INSERT OR REPLACE INTO tool_overrides (slug, title_override, description_override, seo_title, seo_description, featured, disabled, sort_order) VALUES (
    'pet-personality-quiz', 'Pet Personality Quiz', 'Answer 10 quick questions about how your dog or cat behaves at home, at play, and around new people. We match the pattern of answers to one of five personality archetypes — Adventurer, Companion, Free Spirit, Entertainer, or Zen Master — with practical training and enrichment tips for each type.',
    'Pet Personality Quiz — Free Pet Tool',
    'Answer 10 quick questions about how your dog or cat behaves at home, at play, and around new people. We match the pattern of answers to one of five personality archetypes — Adventurer, Companion, Free Spirit, Entertainer, or Zen Master — with practical training and enrichment tips for each type.', 1, 0, 164
