INSERT OR REPLACE INTO tool_overrides (slug, title_override, description_override, seo_title, seo_description, featured, disabled, sort_order) VALUES (
    'which-breed-suits-me', 'Which Breed Suits Me? Quiz', 'Tell us your activity level, home size, grooming tolerance, and household setup — we score 13+ popular dog and cat breeds against your profile and return the five most likely to fit. A starting point before you meet individual animals at a shelter or breeder.',
    'Which Breed Suits Me? Quiz — Free Pet Tool',
