INSERT OR REPLACE INTO tool_overrides (slug, title_override, description_override, seo_title, seo_description, featured, disabled, sort_order) VALUES (
    'pet-compatibility-test', 'Pet Compatibility Test', 'Enter the species, age, temperament, sex, and neuter status of both pets and get a 0–100 compatibility score with a clear recommendation. Helpful when you''re thinking about adding a second pet or introducing rescues to a resident animal.',
