INSERT OR REPLACE INTO tool_overrides (slug, title_override, description_override, seo_title, seo_description, featured, disabled, sort_order) VALUES (
    'human-to-pet-age', 'Human Age → Pet Age (Reverse)', 'Enter your human age and we run the standard pet-aging table in reverse to tell you how old you''d be as a small, medium, or large dog — or as a cat. A fun social-share tool built on the same veterinary-approved curves used in our forward age calculators.',
    'Human Age → Pet Age (Reverse) — Free Pet Tool',
    'Enter your human age and we run the standard pet-aging table in reverse to tell you how old you''d be as a small, medium, or large dog — or as a cat. A fun social-share tool built on the same veterinary-approved curves used in our forward age calculators.', 0, 0, 167
