INSERT OR REPLACE INTO tool_overrides (slug, title_override, description_override, seo_title, seo_description, featured, disabled, sort_order) VALUES (
    'pet-zodiac-birthday-card', 'Pet Zodiac & Birthday Card Generator', 'Enter your pet''s name and birthday to reveal their Western zodiac sign with a fun personality blurb, then print a shareable birthday card. Great for social posts and adoption anniversaries.',
