-- 5. FAQs
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_1', 'How old is a 1-year-old dog in human years?', 'A 1-year-old dog is biologically equivalent to a 15-year-old human adolescent, possessing full sexual maturity, adult teeth, and near-adult skeletal size.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_2', 'Why is the traditional ''1 dog year = 7 human years'' formula incorrect?', 'Dogs mature rapidly in their first two years (reaching roughly 24 human years by age 2) and age at different rates thereafter depending on adult body size.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_3', 'Why do small dog breeds live significantly longer than giant dog breeds?', 'Giant breeds grow at an accelerated rate during puppyhood, causing higher oxidative stress, accelerated cellular aging, and earlier organ and cardiovascular failure.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_4', 'At what age is a dog officially classified as a senior?', 'Giant breeds reach senior status at age 5 to 6, large breeds at age 7 to 8, medium breeds at age 8 to 9, and small toy breeds at age 10 to 11.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_5', 'What was the oldest verified dog in recorded history?', 'An Australian Cattle Dog named Bluey lived to the verified age of 29 years and 5 months (1910–1939), working livestock for nearly two decades.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_6', 'What are the early subtle signs of aging in senior dogs?', 'Slowing down on stairs, cloudy bluish eye lenses (nuclear sclerosis), grey muzzle hair, stiffness rising in the morning, and reduced hearing.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_7', 'How often should a senior dog visit the veterinarian?', 'Senior dogs should undergo comprehensive wellness examinations every 6 months, including blood chemistry panels (BUN, creatinine, ALT), blood pressure checks, and urinalysis.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_8', 'What is Canine Cognitive Dysfunction (CDS / dog dementia)?', 'A neurodegenerative brain disorder in senior dogs causing disorientation, getting stuck behind doors, nighttime pacing/howling, and house-training regression.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_9', 'Can diet and supplements extend a senior dog''s life?', 'Yes. Diets enriched with omega-3 fatty acids (EPA/DHA), antioxidants, glucosamine, and controlled high-quality protein protect joints, kidneys, and cognitive brain function.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-age-calculator_10', 'Why does dental disease shorten a dog''s lifespan?', 'Periodontal bacteria enter the bloodstream through inflamed gums, causing chronic microscopic infections that damage heart valves (endocardiosis), liver, and kidneys.', 'dogs', 'tool', 'dog-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_11', 'How many cups of food should I feed my dog per day?', 'Cup portions depend on your dog''s weight, activity level, and the caloric density (kcal/cup) of the specific food brand. Use the exact daily MER calorie formula rather than generic bag charts.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_12', 'Why are the feeding guidelines on dog food bags often too high?', 'Bag guidelines provide broad ranges for entire weight brackets and often overestimate caloric needs by 20% to 30%, which easily leads to chronic weight gain in indoor pets.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_13', 'Why do veterinarians recommend weighing dog food in grams?', 'Volume measuring cups vary widely based on kibble shape and packing. A digital gram scale delivers 100% consistent portion control every day.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_14', 'How many calories can come from training treats each day?', 'Treats must never exceed 10% of your dog''s total daily caloric allowance (MER). The remaining 90% must come from a complete and balanced AAFCO-compliant diet.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_15', 'How many times a day should an adult dog be fed?', 'Adult dogs thrive on 2 scheduled meals per day (morning and evening). Splitting meals stabilizes blood sugar, aids digestion, and reduces the risk of bloat (GDV).', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_16', 'Why is free-feeding (leaving food in the bowl all day) bad for dogs?', 'Free-feeding leads to overeating and obesity, makes it impossible to monitor sudden appetite drops, and increases food spoilage and bacterial contamination.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_17', 'How do I safely transition my dog to a new food?', 'Transition over 7 to 10 days: 75% old/25% new for 3 days, 50/50 for 3 days, 25% old/75% new for 3 days, then 100% new food to prevent acute diarrhea and vomiting.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_18', 'What is the difference between large breed puppy food and regular puppy food?', 'Large breed puppy formulations have strictly controlled calcium, phosphorus, and lower fat energy to prevent rapid bone growth that causes hip dysplasia and OCD.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_19', 'Can dogs eat human vegetables as healthy low-calorie snacks?', 'Yes! Raw carrots, green beans, cucumber slices, and plain canned pumpkin are nutrient-dense, fiber-rich, and virtually calorie-free.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-food-calculator_20', 'What toxic human foods must NEVER be fed to dogs?', 'Chocolate, xylitol (birch sweetener), grapes, raisins, onions, garlic, macadamia nuts, avocado pits, and raw bread dough.', 'dogs', 'tool', 'dog-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_21', 'How much water should a dog drink per day?', 'A healthy dog should drink approximately 1 fluid ounce of water per pound of body weight daily (50 to 60 mL per kg). A 50 lb dog requires roughly 50 oz (approx. 6 cups) of fresh water daily.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_22', 'What does it mean if my dog is suddenly drinking excessive water (polydipsia)?', 'Sudden excessive thirst is a major red-flag symptom of serious medical diseases: Diabetes Mellitus, Chronic Kidney Disease, Cushing''s Disease, or Pyometra (uterine infection).', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_23', 'How do I perform a skin turgor test to check if my dog is dehydrated?', 'Gently lift the loose skin over your dog''s shoulder blades and release. In a hydrated dog, it snaps back instantly. If it stays tented for 2+ seconds, your dog is dehydrated.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_24', 'What is canine water intoxication (hyponatremia)?', 'When dogs ingest excessive water while swimming or biting hoses, diluting blood sodium levels and causing staggering, vomiting, dilated pupils, seizures, and brain swelling.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_25', 'Why do dogs drink significantly more water on dry kibble vs. wet food?', 'Dry kibble contains only 10% moisture, requiring the dog to drink all its water from bowls. Canned wet food contains 75% to 80% water, providing built-in hydration.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_26', 'How often should a dog''s water bowl be cleaned and refilled?', 'Rinse and refill water bowls daily with fresh cool water, and wash bowls with soap or in a dishwasher daily to remove slimy bacterial biofilm.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_27', 'What material is best for dog water bowls?', 'Heavy non-tip stainless steel or lead-free ceramic bowls are best. Plastic bowls scratch easily, harboring bacteria that cause chin acne and bad odors.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_28', 'How much water should I bring on a hike with my dog?', 'Bring at least 1 quart (32 oz) of water per hour of moderate hiking for a medium-to-large dog, carrying a portable collapsible silicone bowl.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_29', 'Can dogs drink from natural streams, rivers, or puddles?', 'Avoid letting dogs drink stagnant water or puddles! Wild water sources carry dangerous pathogens: Giardia, Coccidia, blue-green algae toxins, and Leptospirosis bacteria.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-water-calculator_30', 'How do I encourage a sick or reluctant dog to drink water?', 'Add a splash of low-sodium chicken or beef bone broth (onion/garlic free) to their water bowl, offer ice cubes, or switch temporarily to wet food.', 'dogs', 'tool', 'dog-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_31', 'How many calories does an average adult dog need per day?', 'A typical 50 lb (22.7 kg) neutered adult dog with moderate activity requires approximately 1,200 to 1,350 calories (kcal) per day to maintain an ideal body condition.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_32', 'How do veterinarians calculate exact daily calorie needs (MER)?', 'Veterinarians calculate the Resting Energy Requirement (RER = 70 × kg^0.75) and multiply by a life-stage factor (e.g., 1.6 for neutered dogs) to determine exact daily kcal.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_33', 'Why do neutered dogs require fewer calories than intact dogs?', 'Spaying and neutering reduces resting metabolic rate by 20% to 30% while increasing appetite. Food portions must be reduced by 20% post-surgery to prevent obesity.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_34', 'How much weight can a dog safely lose per week?', 'A safe, healthy rate of weight loss is 1% to 2% of total body weight per week (roughly 0.5 to 1.0 lb per week for a 50 lb dog).', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_35', 'How many calories are in standard dog training treats?', 'Commercial crunchy biscuits contain 20 to 40 kcal each, while soft training treats contain 2 to 5 kcal. Treats must never exceed 10% of total daily calories.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_36', 'How do I calculate calories for an overweight dog on a diet?', 'Calculate the RER using your dog''s *ideal target weight* (not current heavy weight) and multiply by 1.0 to achieve steady, safe fat reduction.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_37', 'Why does maintaining an ideal weight extend a dog''s lifespan?', 'Landmark lifelong studies by Purina and veterinary universities prove that dogs kept at an ideal lean body weight live an average of 1.8 to 2.5 years longer.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_38', 'How do cold winter temperatures affect a dog''s calorie needs?', 'Outdoor dogs in freezing winter climates burn significant calories maintaining body heat, requiring 20% to 50% more calories during sub-freezing months.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_39', 'Can high-fiber foods help an overweight dog feel full?', 'Yes! High-fiber diets (or adding plain canned pumpkin or green beans) increase gastric fullness and satiety without adding excess calories.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-calorie-calculator_40', 'Why is measuring dog food with a gram scale better than cups?', 'Volume measuring cups can vary by up to 25% due to kibble packing. A digital gram scale guarantees exact caloric consistency every single day.', 'dogs', 'tool', 'dog-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_41', 'What is an ideal Body Condition Score (BCS) for a dog?', 'A score of 4 to 5 out of 9 is ideal. Ribs are easily felt without excess fat covering, an obvious hourglass waist is visible from above, and an abdominal tuck is seen from the side.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_42', 'How much excess body fat does each point above BCS 5 represent?', 'Each single number above BCS 5 represents approximately 10% to 15% excess body weight (e.g., a BCS 7 dog is roughly 20% to 30% overweight).', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_43', 'How does maintaining a lean body condition extend a dog''s life?', 'Landmark lifelong studies prove that dogs maintained at an ideal lean BCS live an average of 1.8 to 2.5 years longer and develop arthritis and chronic diseases years later.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_44', 'How do I perform the ''knuckle test'' on my dog''s ribs?', 'Feel the back of your flat hand: your dog''s ribs should feel just like that (easily palpable under light pressure). If it feels like your fleshy palm, your dog is overweight.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_45', 'What serious medical conditions are caused by canine obesity?', 'Cranial cruciate ligament (CCL) knee tears, severe osteoarthritis, respiratory collapse, high blood pressure, pancreatitis, and increased anesthesia risks.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_46', 'Why is it harder to visually assess body condition in fluffy dog breeds?', 'Dense coats (like Golden Retrievers or Poodles) hide visual waistlines. In long-haired dogs, hands-on physical palpation of the ribs and spine is essential.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_47', 'How often should pet owners evaluate their dog''s Body Condition Score?', 'Check your dog''s BCS monthly by performing the hands-on rib sweep test and looking at their top-down profile to catch weight trends early.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_48', 'Why are neutered dogs more prone to weight gain?', 'Sterilization removes gonadal sex hormones, lowering resting metabolic rate by 20% to 30% while increasing appetite. Food portions must be adjusted downward post-surgery.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_49', 'What is the difference between a 5-point and 9-point BCS scale?', 'The 9-point scale is more precise: a 3 on a 5-point scale equals a 4–5 on a 9-point scale, allowing veterinarians to detect subtle weight changes.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bmi-calculator_50', 'Can exercise alone make an obese dog lose weight?', 'No. Weight loss is 80% diet and 20% exercise. Caloric restriction is mandatory because intense exercise can damage the joints of an obese dog.', 'dogs', 'tool', 'dog-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_51', 'How can I estimate my puppy''s adult weight?', 'For medium breeds, multiply their weight at 16 weeks (4 months) by 2. For small breeds, double their weight at 12 weeks. Giant breeds require specialized multi-factor growth curve charts.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_52', 'At what age do puppies stop growing physically?', 'Small breeds finish growing at 9 to 10 months, medium breeds at 12 months, large breeds at 14 to 16 months, and giant breeds (Mastiffs, Danes) continue filling out until 18 to 24 months.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_53', 'Why is rapid growth dangerous for large and giant breed puppies?', 'Rapid weight gain stresses soft developing cartilage, causing developmental orthopedic diseases: hip dysplasia, elbow dysplasia, and osteochondritis dissecans (OCD).', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_54', 'How much weight should a puppy gain each week?', 'Small puppies gain a few ounces weekly; large breed puppies gain 1.5 to 2.5 lbs per week during peak growth (months 2 through 6).', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_55', 'When should a puppy switch from puppy food to adult food?', 'Small/medium breeds transition to adult food at 10 to 12 months. Large/giant breeds should stay on large-breed growth food until 14 to 18 months under veterinary guidance.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_56', 'Can paw size accurately predict how big a puppy will get?', 'Paw size gives a general clue (large knobby joints indicate significant growth potential), but bone thickness and maternal/paternal genetics are far more accurate.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_57', 'Why is calcium supplementation dangerous for growing large breed puppies?', 'Young puppies cannot regulate dietary calcium absorption. Excess calcium causes skeletal malformations, bone spurs, and severe joint deformities.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_58', 'What is panosteitis (''growing pains'') in young dogs?', 'An inflammatory bone disease causing sudden shifting lameness in rapidly growing large-breed puppies (ages 5 to 14 months), requiring veterinary pain management.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_59', 'How do I know if my growing puppy is overweight?', 'Perform the rib check: you should easily feel your puppy''s ribs under a light layer of baby fat. If you must press firmly to feel ribs, reduce food portions.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-weight-calculator_60', 'What should I do if a puppy suddenly stops gaining weight?', 'Sudden growth plateaus indicate internal parasites (roundworms, Giardia), systemic infection, or malabsorption. Schedule an immediate veterinary fecal exam.', 'dogs', 'tool', 'dog-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_61', 'How long is a dog pregnant (gestation period)?', 'Canine gestation lasts an average of 63 days (approx. 9 weeks), with a normal safe range of 58 to 68 days calculated from the date of ovulation or mating.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_62', 'When can a veterinarian confirm dog pregnancy via ultrasound?', 'Ultrasound can reliably detect gestational sacs and beating fetal hearts starting at 25 to 30 days post-breeding.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_63', 'Why should calcium supplements NEVER be given to pregnant dogs?', 'Supplementing calcium during pregnancy suppresses the parathyroid gland, preventing the mother from mobilizing bone calcium during lactation, causing fatal Eclampsia (Milk Fever).', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_64', 'When should an X-ray be taken to count puppies?', 'Take an abdominal X-ray after Day 55 of pregnancy when fetal skeletons are fully calcified, allowing an exact count of skulls and spines to prepare for whelping.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_65', 'What is the pre-whelping temperature drop?', 'A pregnant female''s rectal body temperature drops from normal (100–101.5°F) down below 98.5°F (36.9°C) approximately 12 to 24 hours before active labor begins.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_66', 'When should a pregnant dog''s food intake be increased?', 'Increase food intake starting at Week 6 (Day 42) by transitioning to high-protein, high-calorie puppy food, increasing volume by 30% to 50% through lactation.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_67', 'What are the early physical signs of dog pregnancy?', 'Enlarged pink nipples around Day 25–30, slight morning sickness around Week 3, followed by a visibly expanding abdomen by Week 5.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_68', 'What are the emergency signs of difficult labor (dystocia) in dogs?', 'Strong active contractions for > 30 minutes with no puppy born, > 2 hours between puppies, green discharge before the first birth, or maternal collapse. Call an ER vet.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_69', 'What is uteroverdin (green discharge) and when is it dangerous?', 'Uteroverdin is a dark green pigment from detached placenta. If seen *before* the first puppy is born, it indicates premature placental detachment and fetal hypoxia.', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-pregnancy-calculator_70', 'How many puppies does an average dog have?', 'Litter sizes range from 1 to 3 puppies in toy breeds (Chihuahuas) to 6 to 10 puppies in large breeds (Labradors), and 8 to 14+ in giant breeds (Mastiffs).', 'dogs', 'tool', 'dog-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_71', 'What vaccines are legally mandatory for dogs?', 'Rabies vaccination is required by law in almost all states and municipalities due to its 100% fatal zoonotic transmission to humans.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_72', 'Why do puppies need 3 to 4 booster shots for Distemper and Parvo?', 'Maternal antibodies from mother''s milk neutralize vaccines at unpredictable rates between 6 and 16 weeks. Staggered boosters ensure the puppy develops active immunity the moment maternal antibodies drop.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_73', 'What is the DAPP / DHPP 5-in-1 combination vaccine for dogs?', 'It protects against Canine Distemper, Adenovirus-1 (Infectious Hepatitis), Adenovirus-2 (respiratory), Parvovirus, and Parainfluenza in a single injection.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_74', 'How long is a rabies vaccine certificate valid?', 'The first rabies vaccine given at 12–16 weeks is valid for 1 year. All subsequent booster shots are certified for 3 full years under standard veterinary vaccine formulations.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_75', 'Why is the Leptospirosis vaccine critical for dogs?', 'Leptospirosis is a bacterial infection spread through wildlife urine in puddles and soil. It causes fatal kidney/liver failure and is zoonotic (can infect humans).', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_76', 'How often should an adult dog receive vaccine boosters?', 'Under modern AAHA guidelines, core DAPP and Rabies vaccines are boosted every 3 years, while non-core lifestyle vaccines (Lepto, Bordetella, Flu) require annual boosters.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_77', 'What is a vaccine antibody titer test?', 'A blood test measuring circulating protective antibodies against Parvovirus and Distemper. If titers are positive, revaccination can be safely deferred.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_78', 'Can my puppy go on public walks before finishing all vaccine rounds?', 'Keep puppies in private fenced yards until 1 to 2 weeks after their final 16-week vaccine round to avoid lethal Parvovirus contaminated in public soil and dog parks.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_79', 'What are normal mild side effects after dog vaccinations?', 'Mild tiredness, slight soreness at the injection site, and a reduced appetite for 24 to 48 hours are normal immune activation responses.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-vaccination-schedule_80', 'What are the emergency signs of an allergic vaccine reaction?', 'Facial swelling, hives, vomiting, diarrhea, pale gums, and difficulty breathing within 30 minutes of vaccination require immediate emergency veterinary epinephrine.', 'dogs', 'tool', 'dog-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_81', 'How much daily walking exercise does an adult dog need?', 'Most healthy adult dogs need 30 to 60 minutes of daily walking. High-energy working breeds (Border Collies, Huskies) require 60 to 90+ minutes of combined physical and mental exercise.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_82', 'What is the ''5-minute rule'' for puppy walking exercise?', 'Walk puppies for a maximum of 5 minutes per month of age, up to twice daily (e.g., a 4-month-old puppy walks for max 20 minutes per session) to protect developing growth plates.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_83', 'Why is forced jogging on pavement dangerous for young puppies?', 'Repetitive impact on hard concrete damages open cartilaginous growth plates before 12–18 months, causing permanent skeletal deformities and early hip/elbow arthritis.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_84', 'What is a ''sniffari'' walk and why is it beneficial?', 'A sniffari is a relaxed walk on a long leash where the dog dictates the pace and sniffs freely. Sniffing stimulates the olfactory cortex, burning mental energy and lowering stress hormones.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_85', 'How do I know if my dog is overtired from walking?', 'Signs include lagging behind, panting heavily with a wide flattened tongue, sitting down and refusing to move, and stumbling. Stop and rest in the shade with water.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_86', 'How does hot weather affect dog walking schedules?', 'Walk during cool early morning or late evening hours. Test pavement with the 7-Second Hand Test: if asphalt is too hot for your bare hand, it will burn your dog''s paws.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_87', 'Can senior dogs with arthritis still go on daily walks?', 'YES! Short, gentle 10- to 15-minute walks on soft grass keep arthritic joints lubricated and maintain muscle mass without causing inflammatory flare-ups.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_88', 'Why do brachycephalic (flat-faced) dogs require shorter walks?', 'Bulldogs and Pugs have compressed upper airways (BOAS) that restrict oxygen intake and prevent efficient panting cooling, putting them at high risk for rapid heat exhaustion.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_89', 'Is a harness better than a collar for walking dogs?', 'A front-clip Y-shaped harness distributes pulling pressure safely across the chest and ribcage, preventing tracheal damage, neck disc herniation, and coughing caused by collar pulling.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-walking-calculator_90', 'How many miles can a fit adult dog walk in a day?', 'A fit, conditioned medium-to-large adult dog can comfortably hike 5 to 10 miles on natural dirt trails with proper hydration and rest breaks.', 'dogs', 'tool', 'dog-walking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_91', 'How much does a dog cost over its entire lifetime?', 'The average lifetime cost ranges from $18,000 to $35,000 for small dogs, $25,000 to $45,000 for medium dogs, and $35,000 to $75,000+ for large and giant dog breeds over a 12 to 14-year lifespan.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_92', 'What is the most expensive year of dog ownership?', 'Year 1 is the most expensive ($2,000–$4,500) due to initial spay/neuter surgery, complete puppy vaccine series, microchipping, crate, obedience classes, and supplies.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_93', 'How much should I budget monthly for a single medium dog?', 'A realistic budget is $120 to $250 per month, covering complete food, monthly heartworm/flea preventatives, routine grooming, toys, and veterinary savings.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_94', 'Why are giant dog breeds significantly more expensive to maintain?', 'Giant breeds (Great Danes, Mastiffs) consume triple the food volume, require higher prescription medication dosages based on weight, and suffer higher rates of orthopedic joint issues.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_95', 'Is pet insurance financially worth the monthly premium for dogs?', 'Yes, especially for emergency accidents and chronic hereditary illnesses (cancer, cruciate ligament tears, allergies) where emergency surgery bills exceed $5,000–$8,000.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_96', 'What routine veterinary procedures are most commonly overlooked in budgets?', 'Annual dental cleanings under anesthesia ($500–$1,200) and comprehensive senior wellness blood chemistry profiles ($200–$400) are the most frequently overlooked costs.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_97', 'How much does emergency veterinary surgery typically cost for a dog?', 'Emergency surgical interventions (intestinal foreign body removal, bloat surgery, hit-by-car trauma, TPLO knee repair) average $3,500 to $9,000+.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_98', 'How can I reduce ongoing dog care expenses safely?', 'Buy food in bulk, brush teeth daily to avoid dental surgery, keep dogs at a lean body condition to prevent arthritis, and administer year-round preventatives to avoid costly parasitic diseases.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_99', 'How much does professional dog grooming cost annually?', 'For continuous-growth hair coats (Poodles, Doodles, Shih Tzus), grooming every 6 weeks costs $65–$120 per visit, totaling $600 to $1,200+ annually.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-cost-calculator_100', 'What hidden costs should prospective dog adopters prepare for?', 'Pet deposit/rent surcharges in apartments, boarding or pet-sitting fees during vacations, professional grooming every 6 weeks, and replacing chewed household items during puppyhood.', 'dogs', 'tool', 'dog-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_101', 'What makes a dog name easiest for canines to learn?', 'Names with 1 to 2 crisp syllables starting with hard plosive consonants (P, B, D, K, T) and ending in bright vowel sounds (like ''Kona'', ''Peanut'', or ''Tucker'') are processed fastest by canine auditory systems.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_102', 'Why should I avoid dog names that rhyme with basic commands?', 'Dogs discriminate sound patterns rather than dictionary definitions. A name like ''Bo'' easily confuses with ''No!'', while ''Ray'' sounds like ''Stay'', leading to delayed obedience.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_103', 'Can I rename an older adopted rescue dog?', 'Yes! Dogs adapt to new names within 1 to 2 weeks through positive association. Pair the new name with high-value treats and praise, and they will adopt it seamlessly without confusion.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_104', 'How do I teach my puppy to respond to its new name?', 'Say the name in an upbeat tone. The moment your puppy looks at you, mark with ''Yes!'' and reward with a small treat. Practice 10 repetitions twice daily in low-distraction environments.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_105', 'Why shouldn''t I use my dog''s name when scolding them?', 'Using the name during punishment creates an aversive association. If your dog links its name with anger or fear, it will hesitate or refuse to come when called in emergency situations.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_106', 'What are the most popular dog names worldwide?', 'Consistently top-ranking names include Bella, Luna, Charlie, Max, Bailey, Daisy, Cooper, Milo, Rocky, and Teddy due to their pleasant acoustics and affectionate tone.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_107', 'Should bonded sibling dogs have matching rhyming names?', 'Avoid rhyming pair names like ''Bella & Stella'' or ''Timmy & Tommy''. Because they sound identical across a yard, calling one dog will inadvertently recall both.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_108', 'What is a ''trochaic'' name and why is it recommended?', 'A trochaic name has a stressed first syllable followed by a softer unstressed syllable (like *RHO-da* or *CON-nor*). This natural descending rhythm matches classical mammalian attention cues.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_109', 'How long does it take for a puppy to master name recall?', 'With consistent daily positive reinforcement (5–10 minutes daily), most puppies achieve reliable name recognition within 7 to 14 days.', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-name-generator_110', 'Can a dog have a formal registered name and a different call name?', 'Yes. Pedigreed show dogs have formal registered names (e.g., ''Ch. Whispering Pines Northern Light'') and an everyday short 2-syllable ''call name'' (e.g., ''Kona'').', 'dogs', 'tool', 'dog-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_111', 'How fast should a growing puppy gain weight?', 'Small puppies gain a few ounces per week; large breed puppies gain 1.5 to 2.5 pounds per week during peak growth (months 2 through 6).', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_112', 'At what age do puppies stop growing physically?', 'Small breeds reach full adult size at 9 to 10 months, medium breeds at 12 months, large breeds at 14 to 16 months, and giant breeds (Mastiffs, Danes) continue filling out until 18 to 24 months.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_113', 'How can I predict my puppy''s adult weight at 4 months?', 'For medium breeds, double their weight at 16 weeks (4 months) to estimate adult weight (Weight at 16 weeks × 2 ≈ Adult Weight ± 10%).', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_114', 'At what age do puppies lose their baby teeth and get adult teeth?', 'Puppy deciduous teeth begin falling out at 3.5 to 4 months of age, with all 42 permanent adult teeth fully erupted by 6 months.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_115', 'Why is large breed puppy food essential for dogs over 50 lbs?', 'Large breed puppy food has strictly controlled calcium and lower calories to prevent rapid bone growth that causes hip dysplasia, elbow dysplasia, and OCD joint lesions.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_116', 'What is an epiphyseal growth plate and when does it close?', 'Growth plates are cartilaginous zones at the ends of long bones that add length. They fully calcify and close between 10 and 18 months depending on breed size.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_117', 'Why should young puppies avoid jumping off beds and running on concrete?', 'High-impact jumping and forced running jar open growth plates, causing micro-fractures and permanent angular limb deformities.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_118', 'What should I do if a puppy stops gaining weight for a week?', 'Weight plateaus indicate internal parasites (roundworms, hookworms, Giardia), systemic infection, or malabsorption. Have a vet run a fecal centrifugation test.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_119', 'How many times a day should an 8-week-old puppy be fed?', 'Young puppies (ages 8 to 16 weeks) have small stomachs and should be fed 3 to 4 measured meals daily to maintain stable blood glucose.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-growth-calculator_120', 'When is it safe to switch from puppy food to adult food?', 'Small/medium dogs switch to adult food at 10 to 12 months. Large and giant breeds should stay on large-breed growth food until 14 to 18 months.', 'dogs', 'tool', 'puppy-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_121', 'How accurate is predicting a puppy''s adult weight at 16 weeks?', 'For medium and large dogs, the 16-week (4-month) benchmark is clinically reliable. For most medium breeds, adult weight is approximately double their 16-week weight (± 8%). For toy breeds, doubling weight occurs earlier at 10 to 12 weeks, while giant breeds reach their halfway mark closer to 24 weeks.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_122', 'Do big paws really mean a puppy will be a huge dog?', 'Paw size provides a helpful general indicator of skeletal bone stock and joint width, especially in mixed-breed puppies. Puppies with heavy bone density, broad wrists (carpals), and loose skin typically grow into medium-to-large adults. However, disproportionately large paws occasionally reflect breed-specific traits (such as Basset Hounds or Bulldogs) rather than excessive overall height.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_123', 'When do puppies stop growing in height versus weight?', 'Puppies achieve their final shoulder (wither) height first—typically between 8 to 12 months for small/medium dogs and 12 to 15 months for large dogs. After height growth stops, canines enter the ''filling out'' phase, broadening the chest and gaining lean muscle mass for an additional 3 to 9 months.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_124', 'Why should I avoid rapid growth in large breed puppies?', 'Rapid weight gain stresses immature cartilage and open growth plates before bones have fully mineralized. Research proves that puppies grown at a controlled, lean rate develop significantly lower rates and severity of hip and elbow dysplasia without reducing their ultimate genetic adult size.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_125', 'How does early spaying or neutering affect a puppy''s final adult size?', 'Gonadal hormones (estrogen and testosterone) signal epiphyseal growth plates to calcify and close. Neutering or spaying a dog before growth plates fuse (especially under 6 to 9 months in large breeds) delays plate closure, causing long leg bones to grow slightly longer. This can result in a taller, lankier dog with altered joint angulation.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_126', 'How do male and female dog adult sizes compare?', 'In small and toy breeds, sexual dimorphism is minimal (2% to 4% difference). In medium, large, and giant breeds, intact adult males are typically 8% to 15% heavier and 1 to 2 inches taller than females of the same litter.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_127', 'What should I do if my puppy''s growth suddenly stalls?', 'Sudden growth plateaus or weight loss in puppies warrant veterinary evaluation. Common causes include gastrointestinal parasites (roundworms, Giardia, Coccidia), inadequate caloric density, systemic infections, or liver shunts. Your vet will perform a physical exam and fecal test.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-size-predictor_128', 'When is the right time to transition my puppy to adult dog food?', 'Small and medium breeds can transition to adult maintenance food between 10 and 12 months of age. Large and giant breeds should remain on specialized large-breed puppy formula until 14 to 18 months, when distal long-bone growth plates are confirmed closed.', 'dogs', 'tool', 'dog-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_129', 'What is the average lifespan of a domestic dog?', 'The average canine lifespan is 11 to 13 years across all breeds, ranging from 7–9 years for giant breeds to 14–17+ years for small toy breeds.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_130', 'Why do small dog breeds live significantly longer than giant breeds?', 'Giant dogs experience rapid cellular division and high oxidative stress during puppyhood, accelerating telomere shortening and early organ decline.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_131', 'What dog breeds have the longest life expectancy?', 'Chihuahuas, Toy Poodles, Dachshunds, Australian Cattle Dogs, and Jack Russell Terriers consistently live the longest, frequently reaching 15 to 19 years.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_132', 'Why do spayed and neutered dogs live longer?', 'Sterilized dogs live 14% to 26% longer by eliminating uterine infections (Pyometra), mammary cancer, and testicular cancer while reducing roaming trauma.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_133', 'What is the #1 cause of non-accidental death in adult dogs?', 'Canine cancer (malignant lymphoma, hemangiosarcoma, osteosarcoma) is the leading cause of death in dogs over age 10.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_134', 'How does maintaining a lean body condition extend a dog''s life?', 'Keeping a dog at an ideal lean BCS (4–5) extends their lifespan by an average of 1.8 to 2.5 years compared to overweight dogs.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_135', 'How does dental disease shorten a dog''s life?', 'Severe periodontal disease allows harmful oral bacteria to enter the bloodstream, causing chronic damage to heart valves (mitral valve disease) and kidneys.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_136', 'What was the oldest dog in recorded world history?', 'An Australian Cattle Dog named Bluey lived to the verified Guinness World Record age of 29 years and 5 months (1910–1939).', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_137', 'How often should a senior dog visit the vet?', 'Senior dogs (age 7+ for large breeds, age 10+ for small breeds) should have comprehensive exams and blood chemistry panels every 6 months.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-life-expectancy-calculator_138', 'Can crossbreed / mixed-breed dogs live longer than purebreds?', 'Yes. Mixed-breed dogs often benefit from ''hybrid vigor'' (reduced incidence of specific homozygous recessive genetic diseases), living an average of 1 to 2 years longer.', 'dogs', 'tool', 'dog-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_139', 'What is the 10% treat rule in canine nutrition?', 'Treats and chews must never exceed 10% of your dog''s total daily caloric allowance (MER). For a 1,200 kcal/day dog, the maximum daily treat allowance is 120 calories.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_140', 'How many calories are in a standard 6-inch bully stick?', 'A single 6-inch beef bully stick contains approximately 80 to 100 calories—nearly 10% of a medium dog''s entire daily food budget.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_141', 'How many calories are in a tablespoon of peanut butter?', 'One tablespoon of peanut butter contains approximately 95 to 100 calories and 8 grams of fat. Always verify it is 100% Xylitol-free!', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_142', 'What are the best healthy, low-calorie treats for dogs?', 'Fresh baby carrots (4 kcal), green beans (2 kcal), cucumber slices, apple pieces (no seeds), and plain air-popped popcorn provide great crunch with minimal calories.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_143', 'Can feeding too many treats cause nutritional deficiencies in dogs?', 'Yes. If treats exceed 10% of total daily calories, they dilute the balanced vitamins, protein, and minerals in their complete commercial food.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_144', 'How do I calculate treat calories into my dog''s daily meal plan?', 'Subtract the exact calories fed in treats from your dog''s evening kibble portion to maintain a stable, healthy weight.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_145', 'Are dental chews effective at cleaning dog teeth?', 'Only dental chews carrying the official Veterinary Oral Health Council (VOHC) Seal of Acceptance are clinically proven to reduce plaque and calculus.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_146', 'Can high-fat treats trigger acute Pancreatitis in dogs?', 'YES! High-fat treats (bacon, sausage, cheese, buttery scraps) can trigger acute pancreatitis, causing excruciating abdominal pain, vomiting, and dehydration.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_147', 'What size should dog training treats be?', 'Training treats should be tiny—the size of a green pea (1/4 inch). Small treats can be swallowed instantly without interrupting the training rhythm.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-treat-calorie-calculator_148', 'What human foods are lethal to dogs and must NEVER be given as treats?', 'Chocolate, xylitol (birch sweetener), grapes, raisins, onions, garlic, macadamia nuts, and cooked bones that splinter.', 'dogs', 'tool', 'dog-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_149', 'How often should a Doodle or Poodle mix be professionally groomed?', 'Doodles require professional grooming and haircuts every 4 to 6 weeks, combined with thorough daily line-brushing down to the skin at home to prevent severe matting.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_150', 'Why should double-coated dogs (Huskies, Shepherds) NEVER be shaved in summer?', 'Shaving double coats destroys their natural insulation against heat and sun, causes patchy coat regrowth (post-clipping alopecia), and increases heatstroke risks.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_151', 'What is ''line brushing'' and how is it done properly?', 'Line brushing involves parting the fur with one hand and brushing a small section from the skin outward with a slicker brush, followed by a metal greyhound comb to verify zero hidden mats.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_152', 'How often should a dog''s nails be trimmed?', 'Trim nails every 2 to 4 weeks. If nails click against hard floors when walking, they are overgrown and altering the skeletal alignment of the paw.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_153', 'What are anal glands and do all dogs need them expressed?', 'Anal glands are scent sacs located at the 4 and 8 o''clock positions around the anus. Healthy dogs express them naturally when defecating; only express them if a dog scoots or licks excessively.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_154', 'Why do groomers charge extra for matted dogs?', 'Shaving dense mats requires slow, precision blade work under high-risk conditions to avoid cutting fragile, pulled skin, while dulling expensive grooming clipper blades rapidly.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_155', 'How often should a dog be given a bath?', 'Most dogs need baths every 4 to 8 weeks with a gentle dog shampoo. Bathing too frequently with harsh detergents strips protective natural skin oils, causing dry, itchy skin.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_156', 'What should I do if I accidentally cut the quick and the nail bleeds?', 'Apply styptic blood-stop powder (Kwik-Stop) or plain cornstarch with firm direct finger pressure for 1 to 2 minutes until bleeding stops.', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_157', 'How do I clean my dog''s ears safely?', 'Fill the ear canal with veterinary ear cleaner, massage the base of the ear for 30 seconds until you hear a squishing sound, let the dog shake, and wipe debris with cotton balls (never Q-tips!).', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-grooming-schedule_158', 'What is the difference between hair and fur on dogs?', 'Fur has a shorter growth cycle and sheds heavily (Labradors). Hair has a longer growth cycle, grows continuously, and sheds minimally (Poodles, Doodles).', 'dogs', 'tool', 'dog-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_159', 'How often do female dogs go into heat?', 'Most domestic dogs cycle once every 6 to 8 months (twice per year). Small breeds may cycle every 4 to 5 months, while giant breeds often cycle only once per year.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_160', 'What are the first visible signs that a dog is entering heat?', 'Swelling of the vulva, bloody vaginal discharge, frequent urination, excessive self-grooming, and increased restlessness (the Proestrus phase).', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_161', 'How long does a dog''s complete heat cycle last?', 'The full heat cycle lasts approximately 2 to 4 weeks (average 21 days), split between Proestrus (bloody phase) and Estrus (fertile mating phase).', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_162', 'When is a female dog most fertile during her heat cycle?', 'Peak fertility occurs during Estrus (typically days 9 to 14 after bleeding begins), when progesterone rises and the discharge turns from red to a pale straw/pinkish color.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_163', 'What is ''flagging'' behavior in a female dog?', 'When in standing heat (Estrus), the female deflects her tail to the side and stiffens her hind legs when touched on the lower back, signaling readiness to mate.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_164', 'What is Pyometra and why is it life-threatening?', 'Pyometra is a severe bacterial infection of the uterus occurring 4 to 8 weeks post-heat due to progesterone changes. It is a fatal medical emergency requiring immediate surgical ovariohysterectomy.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_165', 'What is a false pregnancy (pseudopregnancy) in dogs?', 'A hormonal condition 6 to 8 weeks post-heat where a non-pregnant female displays nesting behavior, mothering toys, and lactates milk due to prolactin surges.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_166', 'Can a female dog get pregnant during her very first heat cycle?', 'Yes. Puberty occurs between 6 and 12 months. However, breeding on the first heat is dangerous because the female is not physically or skeletally mature.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_167', 'How do reproductive veterinarians pinpoint exact ovulation timing?', 'By running serial quantitative serum progesterone blood tests (ovulation occurs at 4–10 ng/mL) and performing vaginal cytology exams.', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-heat-cycle-tracker_168', 'How do I manage a female dog in heat at home?', 'Keep her strictly on leash outdoors, use washable dog diapers indoors with frequent changes, and never leave her unattended in a fenced yard (male dogs will jump 6-foot fences).', 'dogs', 'tool', 'dog-heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_169', 'How much exercise does an adult dog need per day?', 'Most dogs need 30 to 60 minutes of daily exercise. High-energy working breeds (Border Collies, Huskies) require 60 to 90+ minutes of combined physical cardio and mental puzzle training.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_170', 'What is mental exercise for dogs and why is it important?', 'Mental exercise includes scent games (nosework), puzzle feeders, and trick training. Mental stimulation burns excess cognitive energy and calms hyperactive dogs faster than physical running.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_171', 'What are the signs that a dog is not getting enough exercise?', 'Destructive chewing, excessive barking, digging in the yard, hyperactivity indoors, jumping on visitors, and weight gain.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_172', 'Can dogs get overtired and hyperactive from too much exercise?', 'YES! Overstimulated dogs enter an overtired state where adrenaline spikes, making them mouthy, jumpy, and unable to settle. Provide quiet crate rest.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_173', 'What are the best indoor exercise games for rainy days?', 'Hide-and-seek with treats, indoor scent tracking, hallway fetch, flirt pole play (controlled), and interactive puzzle toys.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_174', 'What is a flirt pole and how does it exercise dogs?', 'A flirt pole is a long wand with a rope and lure attached. It exercises a dog''s prey drive and impulse control in a small backyard in just 10 to 15 minutes.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_175', 'How much exercise do brachycephalic (flat-faced) breeds need?', 'Bulldogs and Pugs need low-intensity exercise (20–30 minutes of gentle walking in cool weather) to prevent respiratory distress and heatstroke.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_176', 'How does swimming benefit dogs compared to running?', 'Swimming is a zero-impact cardiovascular exercise that builds muscle without placing stress on joints, making it ideal for dogs with arthritis or hip dysplasia.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_177', 'How long should I wait to exercise my dog after eating a meal?', 'Wait at least 1 hour after a meal before strenuous exercise to prevent life-threatening Gastric Dilation-Volvulus (GDV / Bloat) in deep-chested dogs.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-calculator_178', 'What is the best exercise routine for an arthritic senior dog?', 'Multiple short, gentle 10- to 15-minute walks on soft grass keep arthritic joints lubricated without causing post-exercise inflammation.', 'dogs', 'tool', 'dog-exercise-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-needs-calculator_179', 'How much exercise does an adult dog need per day?', 'Most dogs need 30 to 60 minutes of daily exercise. High-energy working breeds (Border Collies, Huskies) require 60 to 90+ minutes of combined physical cardio and mental puzzle training.', 'dogs', 'tool', 'dog-exercise-needs-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-needs-calculator_180', 'What is mental exercise for dogs and why is it important?', 'Mental exercise includes scent games (nosework), puzzle feeders, and trick training. Mental stimulation burns excess cognitive energy and calms hyperactive dogs faster than physical running.', 'dogs', 'tool', 'dog-exercise-needs-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-needs-calculator_181', 'What are the signs that a dog is not getting enough exercise?', 'Destructive chewing, excessive barking, digging in the yard, hyperactivity indoors, jumping on visitors, and weight gain.', 'dogs', 'tool', 'dog-exercise-needs-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-needs-calculator_182', 'Can dogs get overtired and hyperactive from too much exercise?', 'YES! Overstimulated dogs enter an overtired state where adrenaline spikes, making them mouthy, jumpy, and unable to settle. Provide quiet crate rest.', 'dogs', 'tool', 'dog-exercise-needs-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-exercise-needs-calculator_183', 'What are the best indoor exercise games for rainy days?', 'Hide-and-seek with treats, indoor scent tracking, hallway fetch, flirt pole play (controlled), and interactive puzzle toys.', 'dogs', 'tool', 'dog-exercise-needs-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-lifespan-calculator_184', 'What is the average lifespan of a domestic dog?', 'The average canine lifespan is 11 to 13 years across all breeds, ranging from 7–9 years for giant breeds to 14–17+ years for small toy breeds.', 'dogs', 'tool', 'dog-lifespan-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-lifespan-calculator_185', 'Why do small dog breeds live significantly longer than giant breeds?', 'Giant dogs experience rapid cellular division and high oxidative stress during puppyhood, accelerating telomere shortening and early organ decline.', 'dogs', 'tool', 'dog-lifespan-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-lifespan-calculator_186', 'What dog breeds have the longest life expectancy?', 'Chihuahuas, Toy Poodles, Dachshunds, Australian Cattle Dogs, and Jack Russell Terriers consistently live the longest, frequently reaching 15 to 19 years.', 'dogs', 'tool', 'dog-lifespan-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_187', 'Can I use human shampoo or baby shampoo on my dog?', 'No. Human shampoos are formulated for acidic skin (pH 5.5). Dogs have neutral skin (pH 7.0–7.4). Using human shampoo disrupts your dog''s acid mantle, eroding the epidermal lipid barrier and predisposing them to yeast and bacterial infections.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_188', 'How hot should dog bath water be?', 'Always use lukewarm water (around 98°F / 37°C). Hot water dries out canine skin, increases pruritus (itching), and can trigger heat distress in heavy-coated or brachycephalic dogs.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_189', 'Why is it dangerous to let a double-coated dog air dry?', 'Dense undercoats hold damp moisture against warm skin for hours or days. This warm, moist micro-climate fosters rapid bacterial blooms, resulting in painful, oozing hot spots (acute moist dermatitis). Always use a high-velocity dog dryer on cool.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_190', 'How often should I bathe a dog with severe skin allergies?', 'Vets frequently recommend bathing allergic dogs weekly. Bathing acts as mechanical decontamination, removing pollen, dust mites, and mold spores from the fur before they penetrate the epidermal barrier.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_191', 'Does swimming in lakes or the ocean count as a bath?', 'No. Lake water contains algae and bacteria, while ocean saltwater leaves abrasive salt crystals that irritate skin. Always rinse your dog with clean, fresh tap water immediately after swimming.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-bath-frequency-calculator_192', 'What is the 10-minute contact rule for medicated shampoos?', 'Medicated shampoos containing chlorhexidine, ketoconazole, or salicylic acid require at least 10 minutes of active contact time on the skin to kill bacteria and yeast. Rinsing immediately renders the medication ineffective.', 'dogs', 'tool', 'dog-bath-frequency-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_193', 'What is the Rule of 3-3-3 for newly adopted rescue dogs?', 'The Rule of 3-3-3 outlines the recovery phases: 3 days to decompress from shelter stress, 3 weeks to learn your daily household routine, and 3 months to feel fully secure and bonded.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_194', 'What is a Martingale collar and why is it essential for new rescue dogs?', 'A Martingale collar tightens gently when the dog pulls or backs up, completely preventing nervous dogs from slipping backward out of their collar and bolting into traffic.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_195', 'How soon should I introduce a new rescue dog to my existing pets?', 'Never rush introductions on day one. Allow several days of visual separation and scent swapping, followed by neutral outdoor parallel walks on leash before allowing close contact.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_196', 'What veterinary checks are needed immediately after adoption?', 'Schedule an intake wellness exam within 3 to 7 days for microchip registration transfer, fecal parasite screening, heartworm antigen testing, and vaccine verification.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_197', 'Why do rescue dogs sleep so much during their first week home?', 'Animal shelters are loud and stressful. Once in a quiet, safe home, the dog''s adrenaline drops, and they sleep deeply for 14–18 hours daily to recover from chronic sleep deprivation.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_198', 'How do I handle accidents and regression in a newly adopted house-trained dog?', 'Stress and novel territory cause temporary potty regression. Treat the dog like a puppy: take them outside every 2 hours on leash, reward outdoor elimination immediately, and clean accidents with enzymatic cleaners.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_199', 'What supplies should I buy before bringing my new dog home?', 'High-grade food, stainless steel bowls, crate, orthopedic bed, Martingale collar/harness, 6-foot nylon leash, enzymatic cleaner, poop bags, interactive puzzle toys, and grooming brush.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_200', 'How can I prevent separation anxiety in a newly adopted dog?', 'Establish predictable routines, practice short 5- to 10-minute departures from day two, avoid dramatic greetings/goodbyes, and leave long-lasting frozen stuffed KONG toys when departing.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_201', 'Why should I keep visitors and parties away for the first 2 to 3 weeks?', 'Parading a new rescue dog in front of neighbors or hosting parties causes severe sensory overload, increasing fear-induced defensive growling or biting. Keep interactions calm and family-only.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-adoption-checklist_202', 'How do I help a fearful rescue dog build confidence?', 'Give them control over their environment: never force petting, let them approach you at their own pace, toss treats gently onto the floor, and maintain a quiet, predictable daily routine.', 'dogs', 'tool', 'dog-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_203', 'How old is a 1-year-old cat in human years?', 'A 1-year-old cat is biologically equivalent to a 15-year-old human teenager, possessing full adult dentition, adult skeletal size, and sexual maturity.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_204', 'Why is the traditional ''1 cat year = 7 human years'' formula incorrect?', 'Cats mature rapidly in their first two years (reaching roughly 24 human years by age 2) and age more steadily thereafter at roughly 4 human years per calendar year.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_205', 'At what age is a domestic cat officially considered a senior?', 'Under AAFP guidelines, cats are classified as mature at age 7 to 10, senior at age 11 to 14, and geriatric at age 15 and older.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_206', 'What was the oldest domestic cat ever recorded in history?', 'Creme Puff of Austin, Texas lived to the incredible verified Guinness World Record age of 38 years and 3 days (1967–2005).', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_207', 'What are the early subtle signs of aging in senior cats?', 'Reluctance to jump onto high perches, sleeping more, unkempt fur along the spine (due to spinal arthritis), cloudy eye lenses (nuclear sclerosis), and increased vocalization at night.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_208', 'Why do indoor cats live significantly longer than outdoor cats?', 'Indoor cats live an average of 14 to 18+ years, whereas free-roaming outdoor cats average only 3 to 5 years due to vehicle trauma, infectious diseases (FeLV/FIV), and predator attacks.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_209', 'How often should a senior cat visit the veterinarian?', 'Cats aged 11 and older should have comprehensive wellness checkups every 6 months, including blood pressure screening, complete blood count, chemistry panels, and urinalysis.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_210', 'What is Feline Cognitive Dysfunction (cat dementia)?', 'A neurodegenerative condition in senior cats causing disorientation, aimless wandering, excessive nighttime howling, and forgetting litter box locations.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_211', 'Can diet extend a senior cat''s lifespan?', 'Yes. Senior diets enriched with high-digestibility protein, controlled phosphorus (protecting kidneys), omega-3 fatty acids (EPA/DHA), and antioxidants help maintain lean muscle and renal health.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-calculator_212', 'Why do older cats often develop hyperthyroidism?', 'Benign adenomas in the thyroid gland overproduce thyroxine (T4) in senior cats past age 10, causing rapid weight loss despite excessive appetite, rapid heart rate, and high blood pressure.', 'cats', 'tool', 'cat-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_213', 'How many calories does an average 10 lb adult cat need per day?', 'An average neutered 10 lb (4.5 kg) indoor adult cat requires approximately 200 to 220 kcal of complete and balanced food per day to maintain an ideal body condition.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_214', 'Why is wet canned food healthier for cats than dry kibble?', 'Wet food contains 75% to 82% moisture (preventing kidney disease and urinary crystals) and typically provides higher protein and lower carbohydrates matching feline obligate carnivore biology.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_215', 'Why can cats NEVER be fed a vegetarian or vegan diet?', 'Cats are obligate carnivores requiring animal-derived nutrients (taurine, arachidonic acid, Vitamin A, Vitamin B12). Vegan diets cause fatal heart failure (DCM) and permanent blindness.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_216', 'What happens if a cat does not get enough Taurine in its food?', 'Taurine deficiency causes Dilated Cardiomyopathy (fatal heart enlargement), central retinal degeneration (irreversible blindness), and reproductive failure.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_217', 'How many times a day should an adult cat be fed?', 'Cats have small stomachs and naturally hunt 8 to 10 small meals daily. Feeding 3 to 4 measured small meals or using interactive food puzzle feeders is ideal.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_218', 'Why is free-feeding (leaving dry food out all day) harmful to cats?', 'Free-feeding leads to chronic overeating and obesity (affecting >60% of cats), increases carbohydrate intake, and prevents owners from monitoring sudden appetite drops.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_219', 'How do I safely transition my cat to a new food?', 'Transition over 7 to 10 days: 75% old/25% new for 3 days, 50/50 for 3 days, 25% old/75% new for 3 days, then 100% new food to prevent vomiting and diarrhea.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_220', 'Can cats drink cow''s milk as a treat?', 'NO! Most adult cats are lactose intolerant. Ingesting cow''s milk causes painful abdominal cramping, gas, and severe osmotic diarrhea.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_221', 'Why is weighing cat food in grams better than using measuring cups?', 'Dry kibble measuring cups vary by up to 25% due to kibble shape and packing. A digital gram scale provides exact, consistent caloric portions every day.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-food-calculator_222', 'What is an AAFCO nutritional adequacy statement on cat food labels?', 'An AAFCO statement verifies the diet is formulated to meet complete and balanced nutritional profiles for ''Growth/Reproduction'', ''Adult Maintenance'', or ''All Life Stages''.', 'cats', 'tool', 'cat-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_223', 'How much water does a 10 lb cat need to drink per day?', 'A 10 lb (4.5 kg) cat requires approximately 200 to 250 mL (7 to 8.5 fluid ounces, or roughly 1 cup) of total water daily from food and drinking bowls combined.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_224', 'Why do cats on dry food suffer from chronic dehydration?', 'Cats have a low natural thirst drive. When eating dry kibble (10% moisture), cats do not drink enough water to compensate, producing concentrated urine that causes bladder stones and kidney failure.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_225', 'How does feeding wet canned food prevent urinary blockages?', 'Wet food is 78% water. It naturally doubles a cat''s daily fluid intake, diluting the urine so mineral crystals cannot aggregate into life-threatening urethral plugs.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_226', 'Why do cats prefer drinking from running water fountains?', 'Cats instinctively avoid stagnant water (associating still water with bacteria). Circulating fountains oxygenate the water, keep it cool, and stimulate the cat''s natural drinking instinct.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_227', 'What does it mean if an older cat suddenly starts drinking a lot of water?', 'Sudden excessive thirst (polydipsia) is a red-flag symptom of serious medical diseases: Chronic Kidney Disease (CKD), Diabetes Mellitus, or Hyperthyroidism. Seek immediate vet care.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_228', 'How do I perform a skin turgor test to check if my cat is dehydrated?', 'Gently lift the skin over the shoulders and release. In a hydrated cat, it snaps back instantly. If the skin tent remains for 2+ seconds, your cat is dehydrated.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_229', 'Why shouldn''t cat water bowls be placed next to their food bowls?', 'In nature, cats avoid drinking near their prey kill sites to prevent bacterial contamination. Separating food and water bowls across the room increases water consumption.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_230', 'What material is best for cat water bowls?', 'Non-porous stainless steel, heavy ceramic, or glass bowls are best. Plastic bowls scratch easily, harboring bacteria that cause feline chin acne and bad odors.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_231', 'How can I encourage my picky cat to drink more water?', 'Add a splash of low-sodium tuna water or unseasoned bone broth to their bowl, provide multiple wide ceramic dishes, switch to wet food, and install a stainless steel fountain.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-water-calculator_232', 'Why do cats hate when their whiskers touch the sides of a water bowl?', 'Whiskers are packed with sensitive nerve endings (proprioceptors). When whiskers constantly rub against narrow bowl edges, it causes sensory overload (''whisker fatigue''). Use wide, shallow bowls.', 'cats', 'tool', 'cat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_233', 'How many calories should an indoor cat eat per day?', 'A typical 10 lb (4.5 kg) neutered indoor adult cat requires roughly 200 to 220 calories (kcal) per day to maintain a healthy weight.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_234', 'Why do neutered cats require fewer calories than intact cats?', 'Surgical spaying and neutering removes sex hormones, decreasing basal resting metabolic rate by 20% to 30% while increasing appetite. Food portions must be adjusted downward post-surgery.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_235', 'How do veterinarians calculate exact feline calorie needs (RER)?', 'Veterinarians calculate the Resting Energy Requirement (RER = 70 × kg^0.75) and multiply by a life-stage factor (e.g., 1.2 for indoor adult cats) to determine exact daily kcal.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_236', 'Why is rapid crash dieting deadly for overweight cats?', 'Rapid weight loss triggers Hepatic Lipidosis (Fatty Liver Disease), where mobilized fat clogs the liver, causing acute liver failure and jaundice within days.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_237', 'What is a safe rate of weekly weight loss for an overweight cat?', 'Safe, healthy weight loss is 0.5% to 1.5% of total body weight per week (roughly 2 to 4 ounces per week for an overweight 12 lb cat).', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_238', 'How many calories are in standard cat treats?', 'Many commercial crunchy cat treats contain 2 to 4 kcal per piece, while lickable squeeze tubes contain 8 to 15 kcal each. Treats must never exceed 10% of total daily calories.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_239', 'Why is measuring cat food in grams better than using measuring cups?', 'Kibble volume cups can vary by up to 25% depending on how tightly kibbles pack. A digital kitchen scale measuring in grams ensures 100% caloric accuracy every day.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_240', 'How many calories do growing kittens require compared to adults?', 'Young kittens (under 4 months) require 2.5 times more calories per pound of body weight than adult cats to support rapid bone and organ development.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_241', 'Can food puzzle toys help a cat burn calories and lose weight?', 'Yes! Foraging puzzle feeders make cats work for kibble, slowing down ingestion, burning mental energy, and preventing boredom-induced begging.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-calorie-calculator_242', 'What should I do if my cat refuses to eat a new diet food?', 'Never force a cat to fast! If a cat refuses food for 24 to 48 hours, they risk fatty liver disease. Re-introduce their old food and transition very slowly over 2 to 3 weeks.', 'cats', 'tool', 'cat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_243', 'What is an ideal Body Condition Score (BCS) for a domestic cat?', 'A score of 4 to 5 out of 9 is ideal. Ribs are easily felt under a slight layer of fat, a visible waistline is seen from above, and the abdomen tucks up behind the ribs.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_244', 'What is the Feline Body Mass Index (FBMI)?', 'FBMI is a scientific formula developed by veterinary researchers that calculates body fat percentage using rib cage circumference and lower hind leg length (LIM index).', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_245', 'What is the ''primordial pouch'' on a cat''s belly?', 'The primordial pouch is a normal, loose flap of skin on the lower abdomen that protects organs during fights and allows full stride extension. It is not excess fat.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_246', 'How do I know if my cat''s belly is fat or just a primordial pouch?', 'A primordial pouch is soft, loose, and flappy. An obese belly is round, hard, full of dense fat padding, and accompanied by ribs that cannot be felt.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_247', 'What serious medical conditions are caused by feline obesity?', 'Type 2 Diabetes Mellitus, hepatic lipidosis (fatty liver disease), painful osteoarthritis, urinary blockages (FLUTD), and shortened lifespan.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_248', 'How much excess body fat does each point above BCS 5 represent?', 'Each single number above BCS 5 represents approximately 10% to 15% excess body weight (e.g., a BCS 7 cat is 20% to 30% overweight).', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_249', 'Why are domestic indoor cats so prone to obesity?', 'Spaying/neutering lowers metabolic rate by 25%, free-feeding dry food provides excess carbohydrates, and a lack of active predatory hunting exercise leads to positive energy balance.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_250', 'How do I perform the ''knuckle test'' on my cat''s ribs?', 'Feel the back of your flat hand: your cat''s ribs should feel just like that (easily palpable under light pressure). If it feels like your fleshy palm, your cat is overweight.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_251', 'How often should I weigh and score my cat''s body condition?', 'Weigh your cat once a month on a digital baby/pet scale and perform a tactile rib check to catch gradual weight gain before severe obesity develops.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-bmi-calculator_252', 'Can an overweight cat groom itself properly?', 'No. Obese cats cannot reach their perineum or lower back, leading to matted fur along the spine, painful urine scalding, and secondary skin infections.', 'cats', 'tool', 'cat-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_253', 'How much should an 8-week-old kitten weigh?', 'A healthy 8-week-old kitten should weigh approximately 2.0 pounds (800 to 900 grams), which is the standard minimum weight required for safe surgical spay/neuter in shelter programs.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_254', 'What is the average healthy adult weight for a domestic cat?', 'The average adult Domestic Shorthair cat weighs between 8 and 11 pounds (3.6 to 5.0 kg), varying by skeletal frame size and sex.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_255', 'How big do Maine Coon cats get as adults?', 'Maine Coons are the largest domestic cat breed. Adult males typically weigh 15 to 25 lbs (6.8 to 11.3 kg) and females weigh 11 to 15 lbs, taking 3 to 5 years to reach full size.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_256', 'What is the ''pound-a-month'' rule of thumb for growing kittens?', 'A simple veterinary guideline is that growing kittens gain roughly 1 pound per month of life: 1 lb at 1 month, 2 lbs at 2 months, 3 lbs at 3 months, and 4 lbs at 4 months.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_257', 'At what age do domestic cats stop growing?', 'Standard domestic cats reach their full skeletal size around 10 to 12 months of age. Large breeds (Maine Coons, Ragdolls) continue growing until 3 to 4 years of age.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_258', 'Why is regular weight tracking essential for adult cats?', 'Cats are masters at hiding illness. Unexplained weight loss is often the very first clinical sign of chronic kidney disease, hyperthyroidism, diabetes, or cancer.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_259', 'What type of scale is best for weighing cats at home?', 'Use a digital baby/pet scale that measures in exact single grams or tenths of an ounce. Human bathroom scales are too inaccurate to detect subtle feline weight changes.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_260', 'Why are male cats typically larger than female cats?', 'Male cats (toms) exhibit sexual dimorphism, possessing broader skulls, wider jowls (testosterone cheek pads), and 15% to 25% greater muscle mass than females.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_261', 'How much weight should a newborn kitten gain each day?', 'A newborn kitten should gain 10 to 15 grams per day (roughly 100 grams / 3.5 oz per week) for the first 4 weeks of life.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-calculator_262', 'What should I do if a kitten stops gaining weight for 24 hours?', 'Failure to gain weight for 24 hours is a pediatric emergency (Fading Kitten Syndrome). Check body temperature, check for fleas/parasites, and consult a vet immediately.', 'cats', 'tool', 'cat-weight-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_263', 'How long is a domestic cat pregnant (gestation period)?', 'Feline gestation lasts an average of 63 to 65 days (approx. 9 weeks), with a normal safe range of 58 to 70 days from mating.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_264', 'What is ''induced ovulation'' in cats?', 'Female cats do not ovulate automatically. The physical act of mating stimulates nerve receptors in the vagina that trigger an LH hormone surge, causing the ovaries to release eggs 24–48 hours later.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_265', 'What is ''pinking up'' and when does it occur in pregnant cats?', 'Around Day 20 to 25 of pregnancy, the queen''s nipples enlarge, turn bright rosy pink, and lose surrounding hair—the earliest visible physical sign of pregnancy.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_266', 'Can a single litter of kittens have multiple different fathers (superfecundation)?', 'YES! Because queens mate multiple times with different toms while in heat, eggs can be fertilized by different fathers, resulting in kittens with diverse coat colors and genetics in the same litter.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_267', 'When can a veterinarian confirm cat pregnancy via ultrasound?', 'Ultrasound can confirm fetal heartbeats and gestational sacs at 25 to 30 days post-mating, while abdominal palpation can detect grape-like swellings at days 21–28.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_268', 'When should a pregnant cat''s diet be increased?', 'Unlike dogs who only need extra food in late pregnancy, pregnant cats store fat from Day 1. Transition to high-protein kitten food by Week 4, increasing intake to free-choice through lactation.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_269', 'When should an X-ray be taken to count kittens?', 'Take an abdominal X-ray after Day 55 when fetal skeletons are calcified, providing an exact count of kittens to ensure none are left behind in the birth canal during labor.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_270', 'What are the emergency signs of difficult labor (dystocia) in cats?', 'More than 30–60 minutes of hard active straining with no kitten born, > 2 hours between kittens, foul-smelling dark black discharge, or maternal exhaustion. Call an ER vet.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_271', 'How many kittens are in an average feline litter?', 'An average litter contains 4 to 6 kittens, though first-time young queens often have smaller litters of 1 to 3 kittens.', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-pregnancy-calculator_272', 'How soon after giving birth can a mother cat get pregnant again?', 'A queen can go back into heat and become pregnant again as early as 2 to 4 weeks after giving birth, even while actively nursing her current litter!', 'cats', 'tool', 'cat-pregnancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_273', 'What vaccines do indoor-only cats really need?', 'Indoor cats legally require Rabies, and medically require the core FVRCP combination (protecting against Panleukopenia, Rhinotracheitis, and Calicivirus, which humans can carry inside on shoes).', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_274', 'What is the FVRCP combination vaccine for cats?', 'It is the 3-in-1 core vaccine protecting against Feline Viral Rhinotracheitis (Herpesvirus-1), Calicivirus (painful mouth ulcers and respiratory disease), and Panleukopenia (Feline Distemper).', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_275', 'Why do kittens need a series of booster shots every 3 to 4 weeks?', 'Maternal antibodies from mother''s milk neutralize vaccines. Boosters given at 8, 12, and 16 weeks ensure active immunity the moment maternal antibodies decline.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_276', 'What is Feline Injection-Site Sarcoma (FISS)?', 'FISS is a rare, malignant cancer triggered by chronic inflammation from adjuvanted vaccines. Using non-adjuvanted recombinant vaccines (PureVax) and injecting in lower limbs minimizes risk.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_277', 'Why is the Feline Leukemia Virus (FeLV) vaccine recommended for all kittens?', 'The AAFP recommends FeLV vaccination for all kittens under 1 year because young cats are highly susceptible to fatal leukemia virus if they accidentally escape outside.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_278', 'How often do adult cats need vaccine boosters?', 'After the 1-year booster, core FVRCP and Rabies vaccines are administered every 3 years under modern AAFP guidelines, while high-risk outdoor FeLV vaccines are given annually.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_279', 'What are normal mild side effects after cat vaccinations?', 'Mild sleepiness, slight soreness at the injection site, and reduced appetite for 24 to 48 hours are normal, expected immune activation responses.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_280', 'What are the emergency signs of an allergic vaccine reaction in cats?', 'Facial swelling, vomiting, severe diarrhea, hives, difficulty breathing, and sudden collapse within 30 minutes of vaccination require immediate emergency epinephrine.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_281', 'What is the 3-2-1 rule for vaccine lumps in cats?', 'Biopsy any injection-site lump if it persists for >3 months, is >2 cm in diameter, or continues growing 1 month after vaccination to rule out sarcoma.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-vaccination-schedule_282', 'Can a kitten go outside before finishing all vaccine rounds?', 'NO! Keep kittens strictly indoors until 1 to 2 weeks after their final 16-week booster to ensure full immune protection against deadly Panleukopenia and Leukemia.', 'cats', 'tool', 'cat-vaccination-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_283', 'Do domestic cats really know their own names?', 'Yes! Scientific cognitive research proves cats distinguish their specific names from other human words through distinct ear movements, head turns, and vocal responses.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_284', 'What types of names are easiest for cats to hear and learn?', 'Names with 1 to 2 syllables containing high-frequency sibilant sounds (S, SH, CH) and ending in bright vowel sounds like ''ee'' (e.g., ''Milo'', ''Chloe'', ''Sushi'', ''Ziggy'').', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_285', 'How do I train my cat to come when I call its name?', 'Say their name in a cheerful high-pitched voice. When they look at you or approach, click and immediately give a high-value lickable treat. Practice 5 times daily.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_286', 'Why do cats respond better to higher-pitched voices?', 'Cats are biologically tuned to high frequencies (up to 85,000 Hz) to detect rodent prey. High-pitched rising voices signal friendliness and capture feline attention faster.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_287', 'Can I rename an adult rescue cat from a shelter?', 'Yes! Cats adapt to new names within 1 to 2 weeks through positive association. Pair the new name with favorite wet treats and affectionate head scratches.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_288', 'Why shouldn''t I use my cat''s name when punishing them?', 'Using their name during negative events (shouting, giving bitter pills, forcing into carriers) creates an aversive fear association, causing them to hide when called.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_289', 'What are the most popular cat names worldwide?', 'Top international names include Luna, Oliver, Leo, Bella, Milo, Charlie, Lily, Shadow, Cleo, and Simba due to their pleasant acoustics and affectionate tone.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_290', 'Should bonded sibling cats have rhyming names?', 'Avoid rhyming pair names like ''Milo & Shiloh'' or ''Lilly & Milly''. Because they sound identical across a room, calling one cat will confuse both.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_291', 'Why does my cat ignore me even though they know their name?', 'Unlike pack-oriented dogs, cats evaluate social requests independently. If there is no immediate high-value incentive or they feel secure, they may acknowledge you with just a subtle ear flick.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-name-generator_292', 'What are great names inspired by cat coat colors?', 'Black cats: Shadow, Onyx, Midnight, Salem, Raven. Orange cats: Ginger, Marmalade, Oliver, Cheddar. White cats: Snow, Pearl, Casper, Mochi.', 'cats', 'tool', 'cat-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_293', 'How fast should a newborn kitten gain weight?', 'A healthy newborn kitten must gain 10 to 15 grams per day (approx. 100 grams / 3.5 oz per week), weighing roughly 1 pound at 4 weeks and 2 pounds at 8 weeks.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_294', 'What is the ''pound-a-month'' growth rule for kittens?', 'Kittens typically gain 1 pound for every month of age: 1 lb at 1 month, 2 lbs at 2 months, 3 lbs at 3 months, and 4 lbs at 4 months.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_295', 'At what age do kittens lose their baby teeth and get adult teeth?', 'Deciduous baby teeth start falling out around 3.5 to 4 months of age, with all 30 adult permanent teeth fully erupted by 6 months.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_296', 'Why is commercial kitten food necessary until 12 months of age?', 'Kitten formulations provide high protein, extra calcium/phosphorus for dense bone growth, and DHA fatty acids for brain and eye development.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_297', 'When do kittens stop growing and reach full adult size?', 'Standard domestic cats reach adult skeletal size around 10 to 12 months. Large breeds (Maine Coons, Ragdolls) continue growing until 3 to 4 years of age.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_298', 'Why is a digital gram scale essential for monitoring young kittens?', 'Human bathroom scales cannot detect subtle weight drops. A digital kitchen scale measuring in exact single grams catches ''fading kitten'' crises immediately.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_299', 'At what age should kittens be vaccinated and microchipped?', 'Core FVRCP vaccines begin at 6 to 8 weeks and repeat every 3–4 weeks until 16 weeks; microchipping is typically done at 8–12 weeks during spay/neuter.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_300', 'What should I do if an orphaned kitten is not gaining weight?', 'Weight loss is a life-threatening emergency. Warm the kitten to 97°F–100°F first, administer oral dextrose/Karo syrup for hypoglycemia, and bottle-feed warm KMR replacer.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_301', 'When do kittens transition from blue eyes to their permanent eye color?', 'All kittens are born with blue eyes. Permanent adult eye color (green, gold, copper) begins emerging around 6 to 7 weeks of age.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_kitten-growth-calculator_302', 'How much sleep does a growing kitten need each day?', 'Growing kittens sleep between 18 and 20 hours per day. Growth hormone is released primarily during deep sleep cycles.', 'cats', 'tool', 'kitten-growth-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_303', 'How much does it cost to own a cat over its entire lifetime?', 'The average lifetime cost of a healthy domestic cat ranges from $16,000 to $32,000+ over a 15 to 18-year lifespan, covering food, litter, veterinary care, and emergency funds.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_304', 'What is the most expensive year of cat ownership?', 'Year 1 is the most expensive ($1,000–$2,200) due to initial adoption fees, spay/neuter surgery, complete kitten vaccines, microchipping, litter boxes, scratching trees, and supplies.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_305', 'How much should I budget per month for a single indoor cat?', 'A realistic budget is $80 to $150 per month, covering premium canned/dry food, clumping litter, routine wellness sinking funds, toys, and parasite preventatives.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_306', 'What are the most common unexpected veterinary expenses for cats?', 'Male urinary blockage hospitalization ($2,000–$5,000), dental extractions for resorptive lesions ($600–$1,500), and senior kidney/diabetes management ($100–$250/month).', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_307', 'Is pet insurance financially worth it for indoor cats?', 'Yes. Indoor cats frequently ingest linear foreign bodies (hair ties, string) or develop costly chronic diseases (Feline Asthma, Diabetes, Chronic Kidney Disease).', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_308', 'How much does cat litter cost per year?', 'Quality clumping clay or natural plant litter costs between $200 and $400 per year per cat, depending on substrate type and box depth.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_309', 'What hidden costs should prospective cat adopters prepare for?', 'Apartment pet deposits/rent surcharges, replacing scratched furniture, cat-sitter fees during vacations, and specialized senior prescription diets.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_310', 'How can I reduce ongoing cat care expenses safely?', 'Buy food and litter in bulk, brush your cat''s teeth daily to prevent $1,000 dental surgeries, and feed wet food to prevent multi-thousand dollar urinary blockages.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_311', 'Why do veterinary costs increase significantly after a cat turns 10?', 'Senior cats require bi-annual exams, blood chemistry panels, blood pressure checks, arthritis pain management, and prescription renal diets.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-cost-calculator_312', 'How much does it cost to professionally board a cat vs. hire a cat sitter?', 'Cat boarding condos cost $25 to $45 per night, while an in-home professional cat sitter charging 30-minute drop-in visits costs $20 to $35 per visit.', 'cats', 'tool', 'cat-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_313', 'What is the average lifespan of an indoor domestic cat?', 'A healthy indoor cat lives an average of 14 to 18 years, with many well-cared-for cats living into their early 20s.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_314', 'Why do outdoor cats have significantly shorter lifespans?', 'Free-roaming outdoor cats live an average of only 3 to 5 years due to vehicle trauma, predator attacks (coyotes/dogs), rat poison ingestion, and fatal retroviruses (FeLV/FIV).', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_315', 'What cat breeds have the longest life expectancy?', 'Siamese, Burmese, Balinese, and Domestic Shorthair (mixed-breed) cats consistently live the longest, frequently reaching 16 to 20+ years.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_316', 'Why do spayed and neutered cats live significantly longer?', 'Sterilized cats live 39% to 62% longer by eliminating fatal reproductive cancers (mammary tumors, ovarian cancer, testicular cancer) and reducing aggressive roaming.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_317', 'What is the #1 cause of death in senior domestic cats?', 'Chronic Kidney Disease (CKD) and feline cancers (like malignant lymphoma) are the leading natural causes of mortality in geriatric cats.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_318', 'How does dental disease shorten a cat''s life?', 'Severe periodontal disease allows harmful oral bacteria to enter the bloodstream, causing chronic micro-abscesses and damage to heart valves and kidneys.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_319', 'Can regular veterinary checkups extend my cat''s life?', 'Yes! Bi-annual exams and blood panels for cats over age 10 detect kidney disease, hyperthyroidism, and diabetes early when medical management is most effective.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_320', 'What was the oldest cat in world history?', 'Creme Puff of Austin, Texas holds the Guinness World Record, living to the extraordinary verified age of 38 years and 3 days (1967–2005).', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_321', 'How does preventing obesity increase feline lifespan?', 'Maintaining an ideal lean body condition prevents feline diabetes, reduces stress on joints, and lowers systemic inflammation, adding years of healthy life.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-life-expectancy-calculator_322', 'What is a ''Catio'' and how does it promote both safety and longevity?', 'A catio is an escape-proof, fully enclosed outdoor patio that allows cats to enjoy fresh air, sun, and bird-watching without any exposure to cars or predators.', 'cats', 'tool', 'cat-life-expectancy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_323', 'How many pounds of cat litter does one cat use per month?', 'A single adult cat uses approximately 15 to 20 pounds of clumping clay litter, 10 to 14 pounds of natural plant litter, or 6 to 8 pounds of silica crystal litter per month.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_324', 'How deep should the cat litter be in the box?', 'Maintain a depth of 2 to 3 inches (5 to 7.5 cm). This depth allows natural digging and burying while preventing liquid urine from reaching and sticking to the bottom plastic.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_325', 'What type of litter do cats naturally prefer?', 'Scientific behavioral preference trials show cats overwhelmingly prefer unscented, soft, fine-grained clumping clay that mimics natural desert sand.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_326', 'Why should scented cat litters be avoided?', 'Cats have 200 million olfactory scent receptors. Heavy artificial perfumes (lavender, citrus) overwhelm their sense of smell, triggering litter box avoidance.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_327', 'How often should clumping litter boxes be scooped and washed?', 'Scoop solid waste and urine clumps 1 to 2 times daily. Completely dump, scrub with unscented soap/hot water, and refill with fresh litter every 3 to 4 weeks.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_328', 'Why is sodium bentonite clay litter unsafe for young kittens under 8 weeks?', 'Young kittens explore by mouthing litter. Ingested clumping clay expands in the stomach and intestines, forming fatal gastrointestinal blockages. Use non-clumping paper pellets for kittens.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_329', 'What are the benefits of natural wood pellet or corn litters?', 'Plant-based litters are renewable, biodegradable, generate minimal silica dust, and are 100% compostable (for ornamental gardens, never edible crops).', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_330', 'How many litter boxes do I need for 2 cats?', 'Follow the N+1 Rule: provide 3 litter boxes for 2 cats, placed in separate locations so one cat cannot territorially block access to all boxes.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_331', 'Why does cat litter get tracked all over the house and how do I stop it?', 'Fine litter sticks to paw hair. Place large, textured silicone or mesh litter-trapping mats outside box exits and trim excess paw hair in long-haired cats.', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-calculator_332', 'Can used cat litter be flushed down the toilet?', 'NEVER flush cat litter or cat feces down the toilet! Cat feces can carry Toxoplasma gondii parasites, which survive wastewater treatment and kill marine wildlife (like sea otters).', 'cats', 'tool', 'cat-litter-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_333', 'What is the 10% treat rule in feline nutrition?', 'Treats must never exceed 10% of your cat''s total daily caloric allowance (MER). For a standard 200 kcal/day cat, the maximum daily treat allowance is just 20 calories.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_334', 'How many calories are in lickable squeeze treats (Churu)?', 'Most commercial lickable squeeze puree tubes contain between 8 and 15 calories each, meaning a single tube uses up half or more of a cat''s daily treat allowance.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_335', 'Why is human cheese bad for cats?', 'A single 1-ounce cube of cheddar cheese contains 115 calories—over 50% of an adult cat''s entire daily caloric requirement—and contains lactose that triggers severe diarrhea.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_336', 'What are the best healthy, low-calorie treats for cats?', 'Single-ingredient freeze-dried meats (freeze-dried chicken breast, wild salmon, or chicken liver) provide pure protein and intense aroma with minimal calories and zero fillers.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_337', 'Can treats cause my cat to become deficient in essential vitamins?', 'Yes. If treats exceed 10% of total daily calories, they dilute the balanced vitamins, taurine, and minerals in their complete commercial food, leading to nutritional deficiencies.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_338', 'How do I calculate treat calories into my cat''s daily meal plan?', 'Subtract the exact calories fed in treats from your cat''s daily kibble or wet food portion to maintain a stable, healthy weight.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_339', 'Are crunchy dental treats effective at cleaning teeth?', 'Only dental treats with the official Veterinary Oral Health Council (VOHC) Seal of Acceptance are clinically proven to reduce plaque and tartar.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_340', 'Can I give cooked plain chicken or tuna as a cat treat?', 'Yes, small thumbnail-sized pieces of unseasoned boiled chicken or plain water-packed tuna are great high-value rewards, provided they stay within the 10% calorie limit.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_341', 'Why do cats become obsessed with certain commercial treats?', 'Many commercial treats are coated with animal digest—a savory hydrolyzed animal protein spray that produces an intensely appealing aroma to feline olfactory senses.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-treat-calorie-calculator_342', 'Can high-calorie treats trigger pancreatitis in cats?', 'Yes. High-fat treats (bacon, butter, fatty meats) can trigger acute feline pancreatitis, causing severe abdominal pain, lethargy, and vomiting.', 'cats', 'tool', 'cat-treat-calorie-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_343', 'How often should long-haired cats (Persians, Maine Coons) be brushed?', 'Long-haired cats must be brushed DAILY down to the skin using a metal Greyhound comb and slicker brush to prevent painful pelted mats.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_344', 'Why should you NEVER use scissors to cut mats out of a cat''s fur?', 'Feline skin is paper-thin and stretches up inside the mat. Using scissors almost always cuts the cat''s skin, creating severe open wounds requiring surgical stitches.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_345', 'What is a ''Sanitary Trim'' for cats?', 'A sanitary trim is a gentle shaving of the fur around the anus, perineum, and hind legs to prevent feces and urine from sticking to the coat in long-haired or senior cats.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_346', 'Why do older senior cats stop grooming and develop matted fur on their backs?', 'Senior cats suffer from spinal and hip arthritis. Bending to groom their lower back and tail causes joint pain, leading to rapid coat matting and dandruff.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_347', 'How often should a cat''s claws be trimmed?', 'Trim claws every 2 to 3 weeks using specialized cat claw clippers, taking care to cut only the clear tip and avoid the pink, blood-filled quick.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_348', 'Do domestic cats ever need water baths?', 'Most short-haired cats do not need routine baths. However, long-haired breeds, show cats, or cats covered in grease/substances benefit from professional baths every 6 to 8 weeks.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_349', 'What is a ''Lion Cut'' for long-haired cats?', 'A Lion Cut is a professional shave that removes body fur down to a velvet length while leaving fur on the head, mane, boots, and tail puff, eliminating severe matting.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_350', 'How do I prevent my cat from getting stressed during grooming?', 'Keep sessions short (2–3 minutes), brush in preferred areas (cheeks and chin first), pair brushing with lickable squeeze treats, and use Feliway calming pheromones.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_351', 'What is ''stud tail'' in domestic cats?', 'Stud tail (supracaudal gland hyperplasia) is an overproduction of sebaceous oils at the base of the tail, causing greasy, crusty, blackhead-filled skin requiring degreasing shampoos.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-grooming-schedule_352', 'Why does my cat lick its fur until it is bald (psychogenic alopecia)?', 'Obsessive over-grooming leading to bald patches is triggered by skin allergies (fleas/food), chronic joint pain, or severe stress and environmental anxiety.', 'cats', 'tool', 'cat-grooming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_353', 'How much daily active play time does an indoor cat need?', 'Adult cats need a minimum of 20 to 30 minutes of interactive play daily, split into two 10- to 15-minute sessions mimicking natural hunting cycles.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_354', 'Why are laser pointers frustrating for cats if used alone?', 'Laser pointers provide visual chase but zero tactile capture. Without catching a physical object, the cat experiences unfulfilled predatory frustration, leading to aggression.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_355', 'What is the ''Hunt-Catch-Eat-Groom-Sleep'' cycle in cats?', 'The natural feline biological rhythm where active play (hunt/catch) is followed immediately by a meal (eat), prompting relaxed self-grooming and deep restorative sleep.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_356', 'How do I make wand toys act like real prey?', 'Move the toy *away* from the cat, pause behind furniture, flutter feathers like a wounded bird, or drag string along the floor like a creeping mouse.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_357', 'Why does my cat suddenly bite my ankles when I walk past?', 'Unchanneled predatory drive. Your moving feet look like prey to a bored cat. Redirect this energy with scheduled daily interactive wand toy sessions.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_358', 'What toys are best for solo play when owners are away?', 'Kicker toys stuffed with organic catnip, foraging food puzzle boards, motorized motion mice, and ping-pong balls in dry bathtubs.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_359', 'How do I keep an older senior cat active without hurting joints?', 'Use gentle ground-level wand toys, slow-moving ribbon snakes, and scent enrichment (silvervine, valerian root) that encourage low-impact paw swiping.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_360', 'What is the difference between Catnip and Silvervine?', 'Catnip contains nepetalactone, triggering euphoria in ~65% of cats. Silvervine contains actinidine and is effective in over 80% of cats, including catnip non-responders.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_361', 'Why do cats ''bunny kick'' toys with their hind legs?', 'Bunny kicking is an innate predatory killing reflex used by wild felids to disembowel captured prey using the powerful claws of their hind legs.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-play-time-calculator_362', 'Can puzzle feeders replace standard food bowls for play enrichment?', 'YES! Puzzle feeders force cats to think, forage, and manipulate food with their paws, mimicking natural hunting and preventing scarf-and-barf vomiting.', 'cats', 'tool', 'cat-play-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_363', 'What makes a pet name easiest for dogs and cats to learn?', 'Names with 1 to 2 crisp syllables starting with hard plosive consonants (P, B, D, K, T) and ending in bright vowel sounds (like ''Kona'', ''Peanut'', or ''Milo'') are processed fastest by animal auditory systems.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_364', 'Why should I avoid names that rhyme with basic commands?', 'Animals discriminate sound patterns rather than dictionary definitions. A name like ''Bo'' or ''Joe'' easily confuses with ''No!'', while ''Ray'' sounds like ''Stay'', leading to delayed obedience.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_365', 'Can I rename an older adopted rescue dog or cat?', 'Yes! Pets adapt to new names within 1 to 2 weeks through positive association. Pair the new name with high-value treats and praise, and they will adopt it seamlessly without confusion.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_366', 'How do I teach my puppy to respond to its new name?', 'Say the name in an upbeat tone. The moment your puppy looks at you, mark with ''Yes!'' and reward with a small treat. Practice 10 repetitions twice daily in low-distraction environments.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_367', 'Why shouldn''t I use my pet''s name when scolding them?', 'Using the name during punishment creates an aversive association. If your pet links its name with anger or fear, it will hesitate or refuse to come when called in emergency situations.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_368', 'Do cats actually recognize their own names?', 'Yes! Scientific cognitive studies prove domestic cats distinguish their names from other similar-sounding human words through vocal tone and ear movement.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_369', 'What are the most popular classic pet names worldwide?', 'Consistently top-ranking names include Luna, Bella, Charlie, Milo, Max, Bailey, Daisy, Oliver, Leo, and Cooper due to their pleasant acoustics and affectionate tone.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_370', 'Should bonded sibling pairs have matching rhyming names?', 'Avoid rhyming pair names like ''Bella & Stella''. Because they sound identical across a yard, calling one pet will inadvertently recall both, confusing individual training.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_371', 'What is a ''trochaic'' name and why is it recommended?', 'A trochaic name has a stressed first syllable followed by a softer unstressed syllable (like *RHO-da* or *CON-nor*). This natural descending rhythm matches classical mammalian attention cues.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-generator_372', 'How long does it take for a pet to master name recall?', 'With consistent daily positive reinforcement (5–10 minutes daily), most puppies and kittens achieve reliable name recognition within 7 to 14 days.', 'general', 'tool', 'pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_373', 'How much does a dog or cat cost over its entire lifetime?', 'The average lifetime cost ranges from $20,000 to $55,000 for cats and small dogs, and $35,000 to $75,000+ for large and giant dog breeds over a 12 to 15-year lifespan.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_374', 'What is the most expensive year of pet ownership?', 'Year 1 is typically the most expensive ($2,000–$4,500) due to initial spay/neuter surgery, complete puppy/kitten vaccine series, microchipping, training classes, crates, and starter supplies.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_375', 'How much should I budget monthly for a single medium dog?', 'A realistic budget is $120 to $250 per month, covering high-quality food, monthly heartworm/flea preventatives, routine grooming, toys, and routine veterinary sinking funds.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_376', 'Why are giant dog breeds significantly more expensive to maintain?', 'Giant breeds (Great Danes, Mastiffs) consume triple the food volume, require higher prescription medication dosages based on weight, and suffer higher rates of orthopedic joint issues.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_377', 'Is pet insurance financially worth the monthly premium?', 'Yes, especially for emergency accidents and chronic hereditary illnesses (cancer, cruciate ligament tears, allergies) where emergency surgery bills exceed $5,000–$8,000.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_378', 'What routine veterinary procedures are most commonly overlooked in budgets?', 'Annual dental cleanings under anesthesia ($500–$1,200) and comprehensive senior wellness blood chemistry profiles ($200–$400) are the most frequently overlooked costs.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_379', 'How much does emergency veterinary care typically cost?', 'Minor emergency clinic visits cost $300–$800. Major surgical interventions (intestinal foreign body removal, bloat surgery, hit-by-car trauma) average $3,500 to $9,000+.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_380', 'How can I reduce ongoing pet care expenses safely?', 'Buy food in bulk, maintain daily dental brushing to avoid dental surgery, keep pets at a lean body condition to prevent arthritis, and administer year-round preventatives to avoid costly parasitic diseases.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_381', 'How much does it cost to feed a domestic indoor cat per month?', 'Feeding a balanced combination of high-protein wet canned food and premium dry kibble costs approximately $35 to $70 per month per cat.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-cost-calculator_382', 'What hidden costs should prospective pet adopters prepare for?', 'Pet deposit/rent surcharges in apartments, boarding or pet-sitting fees during vacations, professional grooming every 6 weeks, and replacing damaged household items during puppyhood.', 'general', 'tool', 'pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_383', 'What categories should I track in my pet expense budget?', 'Track 5 primary buckets: Food & Treats, Routine Veterinary & Preventatives, Grooming & Hygiene, Toys/Gear/Training, and Emergency Sinking Fund savings.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_384', 'How much should I contribute to a pet emergency fund monthly?', 'Set aside $50 to $100 per pet per month until you reach a dedicated reserve of $2,000 to $4,000 to cover sudden surgical or diagnostic hospitalizations.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_385', 'Why do veterinary expenses spike as pets age past 8 years?', 'Senior pets experience higher rates of chronic diseases (osteoarthritis, chronic kidney disease, dental decay, thyroid disorders) requiring ongoing medications and frequent blood panels.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_386', 'How can tracking food expenses help prevent pet obesity?', 'Tracking monthly food bags reveals whether feeding portions match calorie recommendations, preventing overfeeding and the subsequent high medical costs of diabetic and orthopedic care.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_387', 'What is the monthly cost difference between small and large dogs?', 'A 15 lb dog costs roughly $60–$90/month to feed and medicate, while an 85 lb dog costs $180–$300/month due to higher food mass and weight-tiered prescription dosages.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_388', 'How do subscription auto-ship services save money on pet care?', 'Auto-ship services for food and monthly preventatives typically offer 5% to 15% recurring discounts while ensuring you never run out of critical heartworm medications.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_389', 'What are the common financial pitfalls of multiple pet ownership?', 'Assuming second pets cost only 50% more. While some gear is shared, food, preventatives, dental cleanings, and emergency vet bills double with every additional animal.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_390', 'How much does professional pet grooming cost annually?', 'For high-maintenance hypoallergenic coats (Poodles, Doodles, Shih Tzus), grooming every 6 weeks costs $60–$120 per visit, totaling $500 to $1,000+ annually.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_391', 'Can I use HSA or FSA funds for pet medical expenses?', 'Standard human HSA/FSA accounts cannot be used for pets unless the animal is an officially certified and prescribed Service Animal under ADA guidelines.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-expense-tracker_392', 'What is economic euthanasia and how does budget tracking prevent it?', 'Economic euthanasia occurs when an owner is forced to euthanize a treatable pet due to inability to pay unexpected medical bills. Budgeting and emergency reserves eliminate this tragic crisis.', 'general', 'tool', 'pet-expense-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_393', 'Why are the feeding guidelines on pet food bags often inaccurate?', 'Bag guidelines provide broad generic ranges for entire weight brackets and often overestimate caloric needs by 20% to 30%, which easily leads to chronic weight gain and obesity.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_394', 'How do veterinarians calculate exact daily calorie needs (MER)?', 'Veterinarians calculate the Resting Energy Requirement (RER = 70 × kg^0.75) and multiply by a life-stage factor (e.g., 1.6 for neutered dogs, 1.2 for indoor cats) to determine exact daily kcal.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_395', 'Why is weighing food on a digital gram scale better than using a measuring cup?', 'Volume measuring cups vary by up to 25% depending on how tightly kibbles pack. A digital gram scale delivers 100% consistent portion accuracy every single day.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_396', 'What percentage of a pet''s daily calories can come from treats?', 'Treats must never exceed 10% of total daily caloric intake. The remaining 90% must come from a complete and balanced AAFCO/WSAVA compliant food.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_397', 'How many times a day should an adult dog or cat be fed?', 'Adult dogs thrive on 2 scheduled meals per day (morning and evening). Cats have small stomachs and naturally thrive on 3 to 4 smaller, measured portions or puzzle feeders.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_398', 'Is free-feeding (leaving food out all day) bad for pets?', 'Yes. Free-feeding leads to overeating and obesity, makes it impossible to monitor sudden appetite changes, and increases food spoilage and bacteria in warm environments.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_399', 'How do I safely transition my pet to a new food?', 'Transition over 7 to 10 days: 75% old/25% new for 3 days, 50/50 for 3 days, 25% old/75% new for 3 days, then 100% new food to prevent acute diarrhea and vomiting.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_400', 'Should I feed wet canned food, dry kibble, or both?', 'A combination is ideal. Dry kibble promotes mechanical chewing, while wet canned food provides vital moisture (especially critical for feline kidney and urinary tract health).', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_401', 'How much weight can a pet safely lose per week?', 'Safe weight loss is 1% to 2% of total body weight per week. Faster weight loss in overweight cats can trigger fatal hepatic lipidosis (fatty liver syndrome).', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-feeding-planner_402', 'What are the best low-calorie treats for overweight dogs?', 'Fresh baby carrots, green beans, cucumber slices, and plain air-popped popcorn provide great crunch and fiber with virtually zero calories.', 'general', 'tool', 'pet-feeding-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_403', 'Can I give my dog human Tylenol or Advil for pain?', 'NO! Human pain medications (Tylenol, Advil, Aleve) are extremely toxic. Tylenol is fatal to cats and causes liver failure in dogs; ibuprofen causes perforating stomach ulcers and acute kidney failure.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_404', 'How do I calculate liquid medication volume in mL?', 'Divide the required milligram dose by the concentration of the liquid medication (e.g., a 50 mg dose with a 25 mg/mL liquid requires exactly 2.0 mL).', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_405', 'What should I do if I miss a dose of my pet''s antibiotic?', 'Give the missed dose as soon as you remember. However, if it is almost time for the next scheduled dose, skip the missed dose and resume normal timing. Never give double doses.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_406', 'How do I easily give a pill to a stubborn dog or cat?', 'Use commercial moldable Pill Pockets, a small dab of cream cheese or peanut butter (xylitol-free!), or use an oral pet piller syringe placed gently behind the tongue followed by a water syringe.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_407', 'Can dog medications be given to cats?', 'NEVER give dog medications to cats without explicit veterinary approval. Dog flea treatments containing permethrin cause fatal neurotoxic seizures in cats.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_408', 'Why is it important to weigh a pet before administering medication?', 'Veterinary medications are dosed strictly by milligrams per kilogram (mg/kg). Dosing based on an outdated weight estimate leads to under-dosing failure or severe toxic overdose.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_409', 'What should I do if my pet vomits immediately after taking a pill?', 'Contact your veterinarian. Do not immediately re-administer the medication unless your vet confirms whether the tablet was absorbed or if an alternative administration method is required.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_410', 'Can I crush pills and mix them with my pet''s food?', 'Some pills can be crushed, but extended-release, enteric-coated, or bitter-tasting tablets must never be crushed. Always check with your pharmacist or veterinarian first.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_411', 'Why must pets finish their entire course of antibiotics?', 'Stopping antibiotics early when symptoms improve leaves stronger bacteria alive, causing severe recurrent infections and developing antibiotic-resistant bacterial strains.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-medication-calculator_412', 'What should I do if my pet accidentally consumes human medication?', 'Call your emergency vet or the Pet Poison Helpline (855-764-7661) immediately with the bottle in hand to provide the exact drug name, milligram strength, and ingested amount.', 'general', 'tool', 'pet-medication-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_413', 'How does pet health insurance work?', 'You pay a monthly premium. When your pet is sick or injured, you pay the veterinary bill, submit the invoice to your insurer, and receive reimbursement (typically 70% to 90%) after meeting your annual deductible.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_414', 'What is the best age to enroll a pet in insurance?', 'Enroll during puppyhood or kittenhood (around 8–12 weeks). Insuring early ensures clean medical records with zero excluded pre-existing conditions.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_415', 'Do pet insurance policies cover pre-existing conditions?', 'No pet insurance company covers active pre-existing conditions. However, some insurers cover ''curable'' pre-existing conditions (like ear infections) if symptom-free for 12 to 18 months.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_416', 'What is the difference between Accident-Only and Accident & Illness plans?', 'Accident-Only covers physical trauma (broken bones, lacerations, toxic ingestions). Comprehensive Accident & Illness plans also cover cancer, infections, diabetes, arthritis, and surgeries.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_417', 'Why do pet insurance premiums increase as pets get older?', 'Premiums rise with age because senior pets have statistically higher probabilities of developing expensive chronic illnesses, cancer, and organ failure.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_418', 'What are waiting periods in pet insurance?', 'Waiting periods are initial exclusion windows (typically 14 days for illnesses, 2 days for accidents, and 6 months for cruciate ligament injuries) before coverage becomes active.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_419', 'Is routine wellness (vaccines, flea prevention) covered by standard insurance?', 'Standard accident/illness policies do not cover routine wellness. Many companies offer optional add-on Wellness Riders for an additional monthly fee.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_420', 'How much does the average dog or cat insurance cost per month?', 'Average comprehensive premiums range from $35 to $65/month for dogs and $20 to $35/month for cats, varying by breed, age, and geographic location.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_421', 'What is a bilateral condition exclusion rider?', 'If your pet has a medical issue in a paired body part (like an eye, ear, or knee) before enrolling, many insurers exclude both sides from future coverage.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-insurance-calculator_422', 'Can I use pet insurance at any veterinary clinic in the country?', 'Yes! Unlike human HMOs, pet insurance has no in-network restrictions. You can visit any licensed veterinarian, specialist, or 24/7 emergency hospital worldwide.', 'general', 'tool', 'pet-insurance-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_423', 'What is the Rule of 3-3-3 for adopted rescue pets?', 'The Rule of 3-3-3 outlines the recovery phases of a shelter pet: 3 days to decompress from acute stress, 3 weeks to learn your daily household routine, and 3 months to feel fully secure, bonded, and settled.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_424', 'How should I set up a safe decompression space for a new rescue cat?', 'Confine the cat to a quiet single bedroom with a litter box, scratching post, food/water placed far from the litter box, hiding spots, and a Feliway pheromone diffuser for the first 7–14 days.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_425', 'What is a Martingale collar and why is it essential for new rescue dogs?', 'A Martingale collar tightens gently when the dog pulls or backs up, completely preventing nervous dogs from slipping backward out of their collar and bolting into traffic.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_426', 'How soon should I introduce a new rescue dog to my existing pets?', 'Never rush introductions on day one. Allow several days of visual separation and scent swapping, followed by neutral outdoor parallel walks on leash before allowing close contact.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_427', 'What veterinary checks are needed immediately after adoption?', 'Schedule an intake wellness exam within 3 to 7 days for microchip registration transfer, fecal parasite screening, heartworm antigen testing, and vaccine booster verification.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_428', 'Why do some rescue dogs sleep so much during their first week home?', 'Animal shelters are loud and stressful. Once in a quiet, safe home, the dog''s adrenaline drops, and they sleep deeply for 14–18 hours daily to recover from chronic sleep deprivation.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_429', 'How do I handle accidents and regression in a newly adopted house-trained dog?', 'Stress and novel territory cause temporary potty regression. Treat the dog like a puppy: take them outside every 2 hours on leash, reward outdoor elimination immediately, and clean accidents with enzymatic cleaners.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_430', 'What supplies should I buy before bringing my new pet home?', 'High-grade food, stainless steel bowls, crate, orthopedic bed, Martingale collar/harness, 6-foot nylon leash, enzymatic cleaner, poop bags/litter box, interactive puzzle toys, and grooming brush.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_431', 'How can I prevent separation anxiety in a newly adopted dog?', 'Establish predictable routines, practice short 5- to 10-minute departures from day two, avoid dramatic greetings/goodbyes, and leave long-lasting frozen stuffed KONG toys when departing.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-adoption-checklist_432', 'Why should I keep visitors and parties away for the first 2 to 3 weeks?', 'Parading a new rescue pet in front of neighbors or hosting parties causes severe sensory overload, increasing fear-induced defensive growling or biting. Keep interactions calm and family-only.', 'general', 'tool', 'pet-adoption-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_433', 'How much food and water should be packed in a pet emergency kit?', 'Pack a minimum 7-day supply of canned or dry pet food in airtight containers and 1 gallon of water per pet per day (accounting for drinking and sanitation).', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_434', 'What is the normal body temperature for a dog or cat?', 'Normal companion animal body temperature is 100.0°F to 102.5°F (37.8°C to 39.2°C). A temperature above 104°F indicates dangerous fever or heatstroke; below 99°F indicates hypothermia or shock.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_435', 'What is Vetrap and why is it superior to human adhesive bandages?', 'Vetrap is a cohesive flexible bandage that sticks securely to itself without sticking to pet fur or skin, providing controlled compression over wound dressings without tearing hair.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_436', 'Can I use human hydrogen peroxide to clean pet wounds?', 'NEVER use hydrogen peroxide on open wounds! Peroxide damages healthy granulating tissue cells and delays healing. Use sterile saline eyewash or 2% dilute chlorhexidine solution.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_437', 'How do I make an emergency muzzle for an injured, biting dog?', 'Use a soft 6-foot nylon leash or roll of gauze: loop over the snout, cross underneath the jaw, bring the ends behind the ears, and tie a bow. Never muzzle a vomiting dog or short-nosed brachycephalic breed.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_438', 'What should I do if my pet is hemorrhaging from a deep laceration?', 'Apply direct firm pressure with sterile gauze pads for at least 5 continuous minutes without lifting the pad. Wrap firmly with Vetrap and transport immediately to an emergency clinic.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_439', 'What emergency documents must be in my pet''s go-bag?', 'Rabies certificates, medical history, proof of microchip registration, prescription medication list, veterinarian phone numbers, and printed color photos of you with your pet.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_440', 'How long can prescription pet medications stay in an emergency kit?', 'Rotate prescription medications every 3 months to prevent active ingredients from expiring. Keep a 14-day supply of chronic medications (insulin, seizure drugs, heart meds) on hand.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_441', 'Why is a pet carrier essential for disaster evacuation?', 'In emergency evacuation shelters and vehicles, panicked pets easily bolt. Hard-sided, secure carriers keep cats and small dogs safe from trauma, smoke, and loud chaos.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emergency-kit_442', 'How do I check my pet''s Capillary Refill Time (CRT)?', 'Lift the upper lip and press your thumb firmly against the pink gum for 2 seconds, then release. The white spot should turn pink again in under 2 seconds. A CRT > 2 seconds indicates shock or poor circulation.', 'general', 'tool', 'pet-emergency-kit', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-qr-tag-generator_443', 'How does the smart collar QR code work?', 'When anyone finds your lost pet and scans the QR code with their phone camera, it opens an urgent emergency profile with your phone number, WhatsApp link, critical medical warnings, and a 1-tap button to send you their GPS map location.', 'general', 'tool', 'pet-qr-tag-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-qr-tag-generator_444', 'Do I need to pay a subscription or buy special hardware?', 'No! FurTools Smart QR Tags are 100% free forever. You can print the tag at home, laminate it, or slide it into standard clear collar tag sleeves.', 'general', 'tool', 'pet-qr-tag-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-qr-tag-generator_445', 'Can I update the emergency contact or medical info later?', 'Yes. You can edit the tag anytime from the tool or directly within your Pet Dashboard.', 'general', 'tool', 'pet-qr-tag-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-qr-tag-generator_446', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'general', 'tool', 'pet-qr-tag-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-qr-tag-generator_447', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'general', 'tool', 'pet-qr-tag-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_448', 'Why is a daily routine so important for dogs and cats?', 'Predictable routines lower stress hormones (cortisol), prevent separation anxiety, eliminate house soiling, and provide domestic pets with a psychological sense of safety.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_449', 'How many hours of sleep does a healthy adult dog need daily?', 'Adult dogs naturally sleep between 12 and 14 hours per day, while puppies and senior dogs often sleep 18 to 20 hours daily to support brain and cellular recovery.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_450', 'What is a ''sniffari'' walk and why is it beneficial?', 'A sniffari is a relaxed walk on a long leash where the dog dictates the pace and sniffs freely. Sniffing stimulates the olfactory cortex, burning mental energy and releasing dopamine.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_451', 'How often should I brush my dog or cat''s teeth?', 'Brush teeth daily using pet-safe enzymatic toothpaste. Plaque mineralizes into permanent dental tartar within 48 hours, so brushing 1–2 times a week is insufficient.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_452', 'How much daily active exercise does a high-energy dog breed require?', 'Working and sporting breeds (Border Collies, Belgian Malinois, Labradors) need 60 to 90+ minutes of combined physical cardio and cognitive puzzle training daily.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_453', 'What are the best mental enrichment activities for indoor cats?', 'Window bird-watching perches, vertical climbing cat trees, daily 15-minute wand toy hunting sessions, and food puzzle foraging mats that mimic hunting.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_454', 'How often should a companion pet''s water bowl be washed?', 'Water bowls must be washed daily with hot soapy water or run through a dishwasher to remove the slimy bacterial biofilm (*slime coat*) that causes oral infections.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_455', 'What is the Fear Free veterinary care philosophy?', 'Fear Free is a veterinary approach that uses positive reinforcement, pheromones, gentle handling, and stress-reduction techniques to eliminate fear and anxiety during vet visits.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_456', 'How often should dog nails be trimmed?', 'Trim nails every 2 to 4 weeks. If nails click against hard floors when walking, they are overgrown and altering the skeletal alignment of the paw.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-care-planner_457', 'What is a lick mat and why does it calm pets down?', 'Lick mats hold soft foods (pumpkin, wet food, yogurt). The repetitive licking motion releases calming endorphins in the brain, soothing anxious dogs and cats.', 'general', 'tool', 'pet-care-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_458', 'Why don''t veterinarians use standard human BMI for dogs and cats?', 'Dogs and cats have immense morphological diversity (from Chihuahuas to Great Danes). Standard BMI fails; veterinarians use the tactile WSAVA 9-Point Body Condition Score (BCS) instead.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_459', 'What is an ideal Body Condition Score (BCS) for dogs and cats?', 'A score of BCS 4 to 5 out of 9 is ideal. Ribs are easily felt without excess fat, and an obvious waistline is visible when viewed from above and from the side.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_460', 'How much longer do pets live when kept at a lean body condition?', 'Lifelong landmark research by Purina and veterinary universities proves that dogs kept at an ideal lean BCS live an average of 1.8 to 2.5 years longer than overweight peers.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_461', 'What serious medical conditions are caused by pet obesity?', 'Obesity causes diabetes mellitus (especially in cats), cranial cruciate ligament (CCL) tears, severe osteoarthritis, respiratory collapse, high blood pressure, and shortened lifespan.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_462', 'Why is rapid weight loss dangerous for overweight cats?', 'Starving an overweight cat triggers hepatic lipidosis (fatty liver disease)—a life-threatening crisis where mobilized fat clogs the liver, leading to liver failure within days.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_463', 'How do I perform the ''knuckle test'' to check my pet''s weight?', 'Feel the back of your flat hand: your pet''s ribs should feel just like that (easily palpable under light pressure). If it feels like your fleshy palm, your pet is overweight.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_464', 'Why is a spayed or neutered pet more prone to weight gain?', 'Surgical sterilization decreases resting metabolic rate by 20% to 30% while increasing appetite. Food portions must be reduced by 20% post-neuter to prevent weight gain.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_465', 'What is the difference between a 5-point and 9-point BCS scale?', 'The 9-point scale is more precise: each single point above 5 represents roughly 10% to 15% excess body fat (e.g., BCS 7 represents approximately 20–30% overweight).', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_466', 'How much weight can a dog safely lose per month?', 'A dog can safely lose 1% to 2% of its body weight per week, or roughly 4% to 8% of total body weight per month under veterinary guidance.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-bmi-calculator_467', 'What is a ''primordial pouch'' on a cat''s belly?', 'The primordial pouch is a normal, loose flap of skin on a cat''s lower abdomen that protects internal organs during fights and allows full stride extension. It is not fat.', 'general', 'tool', 'pet-bmi-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_468', 'Why is the ''1 dog year = 7 human years'' rule incorrect?', 'Dogs mature much faster in their first two years (reaching roughly 24 human years by age 2) and age at varying rates thereafter depending on body size and breed genetics.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_469', 'Why do small dog breeds live significantly longer than large giant breeds?', 'Giant breeds grow at a rapid rate during puppyhood, causing higher oxidative stress and accelerated cellular aging, leading to earlier cancer and cardiovascular decline.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_470', 'At what age is a domestic cat considered a senior?', 'Cats are classified as mature at age 7 to 10, senior at age 11 to 14, and geriatric at age 15 and older under international feline veterinary guidelines.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_471', 'At what age is a dog officially considered a senior?', 'Small dogs reach senior status around age 10 to 11, medium dogs at age 8 to 9, and giant breeds (over 90 lbs) at age 5 to 6.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_472', 'What was the oldest verified dog in recorded history?', 'An Australian Cattle Dog named Bluey lived to the extraordinary verified age of 29 years and 5 months (1910–1939), working livestock for nearly two decades.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_473', 'What was the oldest domestic cat in recorded history?', 'A domestic cat named Creme Puff from Austin, Texas lived to the incredible Guinness World Record age of 38 years and 3 days (1967–2005).', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_474', 'What are the common signs of cognitive decline (dementia) in senior pets?', 'Signs of Canine/Feline Cognitive Dysfunction (CDS) include nighttime pacing, getting stuck behind doors, staring blankly at walls, and house-training regression.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_475', 'How often should senior pets see the veterinarian?', 'Senior and geriatric pets should undergo comprehensive wellness exams every 6 months to catch kidney disease, arthritis, and tumors early.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_476', 'Can diet extend a senior pet''s life expectancy?', 'Yes. Diets enriched with omega-3 fatty acids (EPA/DHA), antioxidants, and high-quality digestible proteins protect brain function, kidneys, and joint cartilage.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-birthday-age-calculator_477', 'How does dental disease impact a senior pet''s lifespan?', 'Chronic periodontal disease allows oral bacteria to enter the bloodstream, directly damaging heart valves, kidneys, and the liver, shortening lifespan by years.', 'general', 'tool', 'pet-birthday-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_478', 'What is a USDA Health Certificate (CVI) for pet travel?', 'A Certificate of Veterinary Inspection (CVI) is an official legal document signed by an accredited veterinarian verifying your pet is vaccinated against rabies, free of infectious disease, and fit for travel.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_479', 'Why do veterinarians advise AGAINST sedating pets during air travel?', 'Tranquilizers (like acepromazine) impair a pet''s natural balance and ability to regulate body temperature at high altitudes, increasing the risk of respiratory arrest and fatal cardiovascular collapse.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_480', 'What are the IATA crate size requirements for flying a dog in cargo?', 'The pet must be able to stand erect with its head/ears naturally high without touching the roof (plus 2–3 inches clearance), turn around 360 degrees, and lie down comfortably.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_481', 'Why are French Bulldogs and Pugs banned from flying on many airlines?', 'Brachycephalic (flat-faced) breeds have narrow nostrils and elongated soft palates. The stress and temperature changes in air travel cause severe airway collapse and fatal heatstroke.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_482', 'How far in advance should I prepare for international pet travel?', 'Start 6 to 9 months in advance. Many rabies-free countries (UK, Japan, Australia, Hawaii) require 15-digit ISO microchips, rabies titer blood tests (FAVN), and strict quarantine permits.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_483', 'How do I prevent motion sickness in dogs during car rides?', 'Ask your vet about prescription Cerenia (maropitant citrate), avoid feeding large meals within 3 hours of travel, keep the car cool with fresh airflow, and use a crash-tested seatbelt harness.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_484', 'What should I pack in my pet''s travel bag?', 'Health certificates, 7-day food supply, portable collapsible silicone bowls, bottled water, prescription medications, waste bags, extra leash, and familiar bedding.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_485', 'How often should I stop for bathroom breaks during long road trips?', 'Stop every 2 to 3 hours for dogs to stretch, relieve themselves on leash, and drink fresh water. Never leave pets unattended in parked vehicles.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_486', 'What is a Center for Pet Safety (CPS) certified car harness?', 'CPS is an independent non-profit that crash-tests pet harnesses and crates using dynamic crash test dummies to verify they withstand 30 mph vehicle collisions without snapping.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-travel-checklist_487', 'What type of microchip is required for international travel?', 'An ISO 11784/11785 compliant 15-digit non-encrypted microchip operating at 134.2 kHz is the universal standard accepted by international customs.', 'general', 'tool', 'pet-travel-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_488', 'How much does a pet sitter cost per day?', 'Daily costs range from $50 to $90 for two to three 30-minute drop-in visits, or $75 to $130+ per night for overnight house sitting, depending on location and number of pets.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_489', 'What is the difference between an in-home pet sitter and boarding?', 'An in-home pet sitter stays in your house, keeping pets in their familiar environment with zero disease exposure. Boarding houses pets at an external facility with social play.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_490', 'Why do pet sitters charge extra for holidays?', 'Holidays (Thanksgiving, Christmas, 4th of July) have peak demand and require sitters to give up personal family time, warranting standard 20% to 35% holiday surge rates.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_491', 'What questions should I ask when interviewing a pet sitter?', 'Ask for proof of commercial liability insurance/bonding, pet CPR certification, references, how they handle medical emergencies, and their specific backup sitter plan if they fall ill.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_492', 'How much extra do sitters charge for giving medications?', 'Simple oral pills often have no extra fee ($0–$5), but complex medical procedures (subcutaneous fluid administration, insulin injections) typically incur a $5–$15 surcharge per visit.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_493', 'Should I tip my pet sitter and how much?', 'Tipping 15% to 20% of the total bill is standard etiquette for independent contractors who provide exceptional care, especially during holidays or complex medical sits.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_494', 'How long should a standard pet sitting drop-in visit last?', 'Standard visits last 30 minutes, which includes feeding, fresh water, litter box scooping or dog walking, medication, and playtime.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_495', 'What information should I leave for my pet sitter?', 'Veterinary clinic address, emergency contact numbers, microchip IDs, detailed feeding/medication schedules, wifi info, alarm codes, and a signed Veterinary Medical Authorization Form.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_496', 'Is it safe to use app-based gig pet sitters?', 'App-based platforms offer convenience, but quality varies widely. Always conduct an in-person Meet & Greet, verify independent references, and confirm their background checks.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-sitter-rate-calculator_497', 'What is a Veterinary Medical Authorization Form for sitters?', 'A signed legal document authorizing your sitter to approve emergency veterinary medical treatment and diagnostics up to a specified dollar limit if you cannot be reached.', 'general', 'tool', 'pet-sitter-rate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_498', 'How much does it cost to board a dog per night?', 'Standard commercial dog boarding costs $40 to $65 per night, while luxury suites with webcams and private outdoor yards range from $75 to $120+ per night.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_499', 'What vaccines are required to board a dog at a commercial kennel?', 'Facilities mandate Rabies, DHPP (Distemper/Parvo), Bordetella (kennel cough within 6 months), and the Bivalent Canine Influenza (H3N2/H3N8) vaccine series.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_500', 'Why do dogs sometimes get kennel cough despite being vaccinated?', 'The Bordetella vaccine protects against the primary bacterial strain, but Canine Infectious Respiratory Disease Complex (CIRDC) is caused by multiple evolving viruses (adenovirus, parainfluenza).', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_501', 'What is the difference between dog boarding and in-home pet sitting?', 'Boarding places your dog in a social facility with other dogs. In-home sitting keeps your dog in their own home, eliminating facility stress and infectious disease exposure.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_502', 'How much does it cost to board a cat?', 'Cat boarding in specialized quiet feline condos costs between $25 and $45 per night, keeping cats completely separated from barking dog noise.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_503', 'What should I pack for my dog''s boarding stay?', 'Bring your dog''s regular food pre-portioned in bags, prescription medications in original bottles, a favorite washable blanket, and emergency veterinary contact details.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_504', 'Why do kennels charge extra for holidays?', 'Holidays have high demand and require double staffing to care for fully booked kennels, resulting in standard $10–$25 per night holiday surcharges.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_505', 'Can aggressive or non-social dogs be boarded?', 'Yes, many facilities offer ''Solo / Individual Play'' programs where non-social dogs receive one-on-one staff play sessions without interacting with other dogs.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_506', 'What should I look for when touring a boarding kennel?', 'Check for clean smell (no heavy ammonia), separate HVAC airflow between rooms, secure double-door safety airlocks, mandatory vaccine enforcement, and calm staff handling.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-boarding-cost-estimator_507', 'Why is a dog tired and thirsty after returning home from boarding?', 'Dogs burn high energy in group play and experience sensory excitement. Returning home, they crash from excitement and drink familiar home water in their calm routine.', 'general', 'tool', 'pet-boarding-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_508', 'Does getting a second pet double your monthly expenses?', 'Yes. Food, prescription preventatives, annual vaccines, dental cleanings, and emergency vet bills scale linearly, doubling your core recurring monthly expenses.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_509', 'Where can multi-pet owners save money legally and safely?', 'Buy large bulk bags of food (saving 10–15%), use multi-pet auto-ship discounts, ask veterinarians for multi-pet exam discounts, and brush teeth daily to avoid dental surgery.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_510', 'Why is adopting two puppies at the same time discouraged by behaviorists?', 'Adopting littermates causes ''Littermate Syndrome''—where puppies bond exclusively with each other, fail to bond with humans, and develop severe separation anxiety and dog-on-dog aggression.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_511', 'How much emergency savings is recommended for a 2-pet household?', 'Maintain a dedicated emergency reserve of $3,000 to $5,000 to cover simultaneous veterinary emergencies or diagnostic workups.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_512', 'Do pet insurance companies offer multi-pet discounts?', 'Yes, most major pet insurance companies offer a 5% to 10% multi-pet discount on monthly premiums for each additional pet enrolled on the same policy.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_513', 'How do multi-cat households handle litter box ratios?', 'Follow the N+1 Rule: provide one litter box per cat plus one extra (e.g., 3 boxes for 2 cats) placed in separate locations to prevent territorial resource guarding.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_514', 'What is the senior compounding curve in multi-pet homes?', 'When pets of similar ages reach senior years together, their chronic medical costs (kidney disease, arthritis meds, blood panels) compound simultaneously.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_515', 'Can multiple dogs share the same food bowl?', 'NEVER allow dogs to share food bowls. Free-for-all feeding leads to resource guarding, violent dog fights, overeating in dominant dogs, and malnutrition in submissive dogs.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_516', 'How much does it cost to feed three cats per month?', 'Feeding three adult cats a balanced diet of quality wet canned food and dry kibble costs approximately $90 to $160 per month.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_multi-pet-cost-calculator_517', 'What is the financial impact of pet-sitting for multiple pets?', 'Sitters charge standard base rates plus a $5–$15 surcharge per additional pet per visit or night, increasing vacation pet care costs significantly.', 'general', 'tool', 'multi-pet-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_518', 'Why do puppies and kittens need a series of vaccines every 3 to 4 weeks?', 'Maternal antibodies from mother''s milk neutralize vaccines. Because we cannot predict the exact week maternal immunity fades, booster vaccines are given every 3–4 weeks until 16–20 weeks to ensure active protection.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_519', 'What is the difference between core and non-core pet vaccines?', 'Core vaccines (Rabies, Distemper, Parvovirus, Panleukopenia) are vital for all pets due to severity and transmission. Non-core vaccines (Lyme, Leptospirosis, Bordetella, FeLV) depend on lifestyle and regional risk.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_520', 'How often do adult dogs and cats need vaccine boosters?', 'After the 1-year booster, core vaccines (Rabies, DHPP, FVRCP) are administered every 3 years under modern AAHA/AAFP guidelines, while non-core vaccines (Bordetella, Lepto) require annual boosters.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_521', 'What is a vaccine titer test?', 'A titer test is a blood test that measures circulating antibody levels against specific viruses (Parvovirus, Distemper). If titers are protective, revaccination can be safely deferred.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_522', 'What are normal mild side effects after pet vaccinations?', 'Mild lethargy, slight soreness at the injection site, and mild low-grade fever for 24 to 48 hours are normal immune responses.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_523', 'What are the signs of a dangerous allergic vaccine reaction?', 'Facial swelling, hives, vomiting, diarrhea, pale gums, and difficulty breathing are emergency anaphylactic reactions requiring immediate emergency veterinary intervention.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_524', 'Why is the Leptospirosis vaccine important for dogs?', 'Leptospirosis is a bacterial infection spread through wildlife urine in puddles and soil. It causes fatal kidney/liver failure and is zoonotic (can infect humans).', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_525', 'Why are non-adjuvanted vaccines recommended for cats?', 'Adjuvanted vaccines carry a small risk of triggering Feline Injection-Site Sarcoma (FISS), a malignant tumor. Non-adjuvanted recombinant vaccines provide safe immunity without adjuvants.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_526', 'Can an indoor-only cat skip vaccinations?', 'No. Rabies is required by law in most jurisdictions (bats enter homes), and viruses like Panleukopenia can be brought indoors on human shoes and clothing.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-reminder_527', 'How long after vaccines is a puppy fully protected to go to dog parks?', 'Puppies are not fully protected until 1 to 2 weeks after their final 16-week booster vaccine. Avoid public dog parks and pet stores until this milestone is complete.', 'general', 'tool', 'pet-vaccine-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_528', 'What is the minimum cage size for a single cockatiel?', 'A single cockatiel requires a minimum cage of 24 inches wide by 24 inches deep by 30 inches tall with 1/2-inch to 5/8-inch bar spacing. Wider cages (30+ inches) are strongly recommended so long tail feathers do not fray against cage walls.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_529', 'Why are round bird cages dangerous for parrots and canaries?', 'Round cages lack 90-degree corners that provide birds with a psychological sense of security and navigational reference. Furthermore, the converging bars at the top of round cages create pinch points that trap and break toes, feet, and bands.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_530', 'Why is horizontal cage width more important than vertical height?', 'Birds fly horizontally across territory, not vertically like helicopters. A wide, horizontal cage allows natural flight hops and continuous wing flaps, whereas a tall, narrow tower cage only allows climbing.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_531', 'What bar spacing is safe for budgies and lovebirds?', 'Bar spacing for budgies, lovebirds, and finches must be no greater than 1/2 inch (1.27 cm). Wider bar spacing allows them to push their head through, leading to fatal head entrapment or strangulation.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_532', 'Why is galvanized wire mesh toxic to birds?', 'Galvanized wire is coated with molten zinc. Parrots naturally explore and climb using their beaks; chewing and licking galvanized wire causes acute heavy metal zinc poisoning, leading to vomiting, seizures, kidney failure, and death.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_533', 'How many birds can share a single cage?', 'Enclosure size must scale by 50% to 60% for each additional bird, provided the species is socially compatible. Solitary or territorial parrots should each have their own cage to prevent severe bite wounds and resource guarding.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_534', 'What types of perches should be placed in a bird cage?', 'Provide multiple natural hardwood branches (manzanita, dragonwood, eucalyptus, ribbonwood) of varying diameters and textures. Avoid uniform smooth wooden dowels and sand/concrete perch covers, which cause painful ulcerative bumblefoot (pododermatitis).', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_535', 'How many hours of out-of-cage flight time does a bird need daily?', 'Companion birds require a minimum of 3 to 5 hours of supervised out-of-cage exercise in a bird-proofed room every single day to prevent atherosclerosis and muscle atrophy.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_536', 'What is the best cage material for large cockatoos and macaws?', 'Powder-coated heavy-gauge wrought iron or non-magnetic 304 medical-grade stainless steel with keyed slam-locks is the only material strong enough to withstand large parrot beak forces.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-cage-size-calculator_537', 'Where should a bird''s cage be positioned inside the home?', 'Place the cage against a solid wall in a bright, active family living area (avoiding direct drafty windows and kitchen cooking fumes). Keeping one side against a wall provides psychological security.', 'birds', 'tool', 'bird-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_538', 'Why is an all-seed diet dangerous for pet birds?', 'Seed-only diets are dangerously high in fat (up to 50% fat) and deficient in Vitamin A, calcium, and trace minerals. Over time, all-seed diets cause fatal fatty liver disease (hepatic lipidosis), respiratory infections, and severe arterial atherosclerosis.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_539', 'How do I transition a seed-addicted bird to healthy pellets?', 'Transition gradually over 4 to 8 weeks. Mix 80% seeds with 20% pellets, slowly increasing the pellet ratio while offering warm, softened pellets or mixing pellets with pureed sweet potato. Never starve a bird into switching.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_540', 'Can birds eat spicy chili peppers?', 'Yes! Birds do not possess the mammalian TRPV1 pain receptors for capsaicin, meaning they cannot taste or feel the heat of hot chili peppers. Fresh hot peppers are rich in Vitamin A and make fantastic foraging foods.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_541', 'Why is avocado fatal to birds?', 'Avocado leaves, skin, pit, and flesh contain a fungicidal toxin called persin. In birds, persin causes acute heart muscle necrosis, fluid accumulation in the lungs, and sudden death within 12 to 24 hours.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_542', 'Why do Eclectus parrots require a different diet than other parrots?', 'Eclectus parrots have an exceptionally long digestive tract adapted to digesting wild rainforest vegetation. Synthetic vitamins and artificial colorings in commercial pellets cause neuro-muscular spasms (''toe-tapping'' and ''wing-flipping''). They require a 75%+ fresh raw produce diet.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_543', 'How much fresh water does a parrot need daily?', 'Birds need fresh, clean water available 24/7. Water dishes must be washed and disinfected daily because parrots love dipping pellets and food into their water, creating rapid bacterial growth.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_544', 'Are raw peanuts safe for pet birds?', 'Raw in-shell peanuts carry high risks of Aspergillus mold contamination, which produces carcinogenic aflatoxins that cause fatal respiratory aspergillosis. Only feed human-grade roasted or shelled nuts (walnuts, almonds, pecans).', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_545', 'How much food should a small cockatiel or budgie eat each day?', 'A cockatiel (80–100g) eats approximately 8 to 10 grams of total food daily (about 1.5 to 2 tablespoons), while a budgie (30–40g) eats about 3 to 4 grams daily, with the majority coming from high-potency pellets and fresh greens.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_546', 'Can birds drink fruit juice or milk?', 'Birds cannot digest lactose and should never be given dairy milk. Freshly squeezed 100% pure fruit juice can be a tiny occasional treat, but clean filtered water is the only healthy daily beverage.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-food-calculator_547', 'Why do parrots need bioavailable calcium in their diet?', 'Calcium is critical for skeletal density, muscle contractions, and eggshell formation in females. African Greys are especially prone to hypocalcemia seizures if their diet lacks bioavailable calcium and Vitamin D3.', 'birds', 'tool', 'bird-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_548', 'How many seeds should my pet bird eat per day?', 'For small birds (budgies, cockatiels), seeds should not exceed 1 to 1.5 teaspoons daily. For medium-to-large parrots (Amazons, Greys, Cockatoos), seed should be limited to 1 teaspoon or a few individual nuts as training and foraging rewards. The core daily diet should be 60–70% veterinary pellets and 20–25% fresh vegetable chop.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_549', 'Why are sunflower seeds dangerous when fed as a primary diet?', 'Sunflower seeds are over 45% fat and highly addictive to parrots. A primary sunflower diet leads directly to hepatic lipidosis (fatty liver disease), high cholesterol, arterial plaque (atherosclerosis), and painful fatty tumors called xanthomas.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_550', 'Can budgies and cockatiels survive on an all-pellet diet?', 'While large parrots thrive on 70–80% pellets, small Australian desert granivores like budgies and cockatiels do best on a balanced hybrid: roughly 50–60% pellets, 20–30% quality low-fat seeds or sprouts, and 15–20% fresh dark leafy greens.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_551', 'How do I transition a seed-addicted parrot to a healthy pellet diet?', 'Transition gradually over 4 to 8 weeks. Start by offering pellets first thing in the morning when the bird is hungriest. You can mix pellets with warm pureed sweet potato, moisten pellets with 100% organic fruit juice, or mix 90% seed with 10% pellets, increasing the pellet ratio by 10% each week. Never starve a bird into switching.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_552', 'What is the benefit of sprouting bird seed before feeding?', 'Germinating and sprouting seeds consumes their internal fat reserves while boosting bioavailable vitamins, active digestive enzymes, and chlorophyll. Sprouted seeds retain the familiar texture of seed while offering the nutritional profile of fresh green produce.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_553', 'Which seeds are the healthiest for companion birds?', 'Low-fat, nutrient-rich seeds include white proso millet, canary grass seed, oat groats, hemp seed, chia seed, and milk thistle seed. Safflower and sunflower seeds should be strictly reserved as rare positive-reinforcement training treats.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_554', 'Are tree nuts healthy for large parrots?', 'Yes, in measured quantities. Macaws, in particular, require higher dietary fat and thrive with 2 to 4 raw walnuts, almonds, or macadamia nuts daily. African Greys and Amazons are prone to obesity and should receive only half a walnut or one almond per day.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_555', 'Why do parrots pick through seed bowls and throw out food?', 'Parrots are instinctive selectors; they search for the highest-fat kernels and toss aside lower-calorie seeds. In the wild, this behavior helps disperse forest seeds, but in a cage, it causes severe nutritional imbalances. Providing measured daily portions eliminates this selective feeding.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_556', 'Can seeds cause calcium deficiency in laying female birds?', 'Yes. Seeds have a severely distorted calcium-to-phosphorus ratio (often 1:10, whereas birds require 2:1). An all-seed diet rapidly depletes skeletal calcium, leading to thin eggshells, life-threatening egg binding, and hypocalcemic tetany.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-seed-portion-calculator_557', 'What is the best way to feed seeds for mental enrichment?', 'Avoid standard food dishes. Place seeds in puzzle toys, roll them inside untreated cupcake wrappers, or bury them under clean river pebbles in a foraging tray. Foraging satisfies the parrot''s instinctual need to work for food, preventing boredom-induced screaming and feather picking.', 'birds', 'tool', 'bird-seed-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_558', 'What is the longest-lived companion bird species?', 'Large macaws (Green-Winged, Hyacinth, Blue & Gold) and Cockatoos (Umbrella, Moluccan, Sulphur-Crested) have the longest lifespans, routinely living 50 to 80+ years in captivity with proper veterinary care.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_559', 'Why do birds live longer than mammals of the same size?', 'Birds possess unique cellular anti-aging mechanisms. Their mitochondria produce fewer free radicals, their tissues resist oxidative damage more effectively, and their telomeres degrade at a much slower rate than mammalian cells.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_560', 'What are the leading causes of premature death in pet birds?', 'The top causes of premature death are fatty liver disease and atherosclerosis from all-seed diets, acute toxic inhalation (PTFE Teflon fumes, scented candles, aerosol sprays), and unspotted chronic infections (aspergillosis).', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_561', 'How long do domestic cockatiels and budgies live?', 'With a pellet-and-fresh-vegetable diet, daily exercise, and regular vet care, cockatiels live 15 to 25+ years, while budgerigars average 8 to 15 years.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_562', 'Why is legal estate planning necessary for large parrot owners?', 'Because African Greys, Amazons, Cockatoos, and Macaws live 40 to 80 years, they frequently outlive their owners. Establishing a legal pet trust and naming designated secondary caregivers ensures the bird does not end up in overcrowded rescue shelters.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_563', 'What are the common signs of aging in senior birds?', 'Senior birds (usually 20+ years for medium birds, 40+ years for large parrots) show stiffness in foot joints (osteoarthritis), cataract lens clouding, thinning plumage, decreased vocalizations, and altered grip strength on perches.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_564', 'How can I adapt an enclosure for an elderly, arthritic bird?', 'Install flat padded wooden platforms, wrap natural branches in soft cohesive bandage wrap for grip, lower perches closer to the cage floor, and keep food/water dishes easily accessible without climbing.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_565', 'How often should a companion bird see an avian veterinarian?', 'Young and adult birds should have an annual wellness exam. Senior birds (over 15–20 years depending on species) should see an avian vet every 6 months for blood chemistry and kidney health panels.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_566', 'What was the oldest parrot ever recorded in history?', 'A Major Mitchell''s Cockatoo named ''Cookie'' who lived at Chicago''s Brookfield Zoo is officially recognized by Guinness World Records as the oldest verified parrot, living to the extraordinary age of 83 years.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-lifespan-estimator_567', 'Does full-spectrum lighting extend a pet bird''s lifespan?', 'Yes. Birds need UVB light to synthesize Vitamin D3 for proper calcium absorption and immune regulation. Window glass blocks 100% of natural UVB rays, so avian-specific full-spectrum lighting or outdoor aviary time is essential.', 'birds', 'tool', 'bird-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_568', 'Can pet birds learn to recognize and repeat their own names?', 'Yes! Many bird species—especially African Greys, Amazons, Budgies, Cockatiels, and Indian Ringnecks—learn to recognize their names quickly, and vocal species will often speak their own name as a cheerful flock contact call.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_569', 'Which pet bird species are the best talkers?', 'The Congo African Grey Parrot is widely considered the top vocal learner, capable of learning hundreds of words with context. Yellow-Naped Amazons, Indian Ringnecks, Quaker Parrots, and male Budgerigars are also exceptional talkers.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_570', 'What types of names are easiest for a bird to learn to say?', 'Names with 1 or 2 crisp syllables containing sharp plosive consonants (P, B, T, K, CH) and bright vowels (like ''Pico'', ''Kiwi'', ''Tiki'', or ''Peanut'') are the easiest for birds to articulate.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_571', 'Why do budgies (parakeets) often talk better than large cockatoos?', 'Budgerigars possess a high syrinx vibration frequency and intense flock mimicry drives. In fact, a male budgie named Puck holds the world record with a vocabulary of 1,728 words.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_572', 'How should I teach my parrot to say its name?', 'Repeat the name clearly in an upbeat, enthusiastic tone whenever offering a favorite treat or greeting the bird in the morning. Consistent daily repetition during bonded interactions yields the best results.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_573', 'Can I rename an older adopted rescue parrot?', 'Yes! Parrots adapt readily to new names. Simply use their new name paired with positive reinforcement, head scratches, and favorite treats, and they will adopt it within 2 to 4 weeks.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_574', 'What is ''eye-pinning'' when a bird hears its name?', 'Eye-pinning is the rapid, voluntary contraction and dilation of the pupil. It indicates intense excitement, focus, or interest when your bird hears a familiar voice, word, or stimulus.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_575', 'Why do female cockatiels rarely talk compared to males?', 'Male cockatiels use vocalizations and whistling for courtship displays in the wild, making them much more vocal and prone to mimicry than females, who communicate through quieter body language.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_576', 'What are great names for a pair of bonded lovebirds or conures?', 'Popular bonded pair duos include Mango & Kiwi, Bonnie & Clyde, Sunny & Sky, Pip & Merry, Tiki & Mango, and Romeo & Juliet.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-name-generator_577', 'Do canaries and finches recognize their names?', 'While canaries and finches do not talk, they learn their owner''s voice and name cues through positive associations, chirping back or flying to the front perch when called.', 'birds', 'tool', 'bird-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_578', 'Should I clip my pet bird''s wings?', 'It is a personal and situational decision. Full flight provides essential cardiovascular exercise and mental confidence when the home is bird-proofed. A conservative micro-clip is chosen when uncontrolled ceiling fans, open doors, or pets create extreme flight hazards.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_579', 'Why is clipping only one wing dangerous?', 'Asymmetrical clipping destroys aerodynamic balance. When a one-wing clipped bird tries to fly, it spirals out of control in a violent corkscrew, crashing into walls and shattering its delicate keel bone (sternum).', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_580', 'What is a blood feather and what happens if it is cut?', 'A blood feather is a newly growing feather with an active internal blood vessel (visible as a dark purple/blue shaft). Cutting a blood feather causes profuse bleeding. Apply styptic powder or cornstarch immediately and seek veterinary help.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_581', 'Can a clipped bird still escape outdoors and fly away?', 'YES! A common and tragic mistake is taking a clipped bird outside without a carrier or aviator harness. A sudden gust of wind or startle reflex provides enough lift for a clipped bird to fly hundreds of feet up into trees or get lost.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_582', 'How often do clipped wings need to be re-trimmed?', 'Wings must be re-evaluated every 6 to 10 months. When the bird undergoes its seasonal molt, clipped primary feathers naturally drop out and are replaced by full new flight feathers.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_583', 'Should a young baby bird be clipped before learning to fly?', 'NEVER clip a fledgling bird before it learns to fly. Allowing young birds to fledge and master flight establishes lifelong brain spatial coordination, visual processing, muscle tone, and self-confidence.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_584', 'Does wing clipping hurt the bird?', 'Trimming fully mature flight feathers does not hurt because the feather shafts consist of dead keratin (like human hair or fingernails). However, cutting an immature blood feather is extremely painful and bleeds heavily.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_585', 'What is the Aviator Harness and can it replace wing clipping?', 'The Aviator Harness is an escape-proof, avian-safe body harness with an elastic leash that allows fully flighted parrots to safely enjoy outdoor sunshine and free flight without risk of escaping.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_586', 'Why do severely clipped birds develop feather plucking?', 'Severe wing clips make birds feel helpless, grounded, and vulnerable to perceived predators. The resulting chronic frustration and anxiety frequently trigger psychogenic feather destructive behavior (feather plucking).', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clip-guide_587', 'Who should perform my bird''s first wing clip?', 'Have an avian veterinarian or experienced certified avian technician perform the first clip. They will demonstrate proper towel restraint, identify hidden blood feathers, and ensure safe glide mechanics.', 'birds', 'tool', 'bird-wing-clip-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_588', 'What is the difference between gross volume and net water volume?', 'Gross volume is the theoretical capacity of the empty glass tank based on outer dimensions. Net water volume is the actual liquid water inside after subtracting the thickness of glass, 10–20% displacement from [aquarium substrate](/tools/aquarium-substrate-calculator) and hardscape rocks, and the top 1-inch waterline gap.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_589', 'How much water do substrate and rock decor typically displace?', 'In standard community and planted tanks, substrate and decor displace between 10% and 20% of nominal volume. A 40-gallon tank usually holds approximately 32 to 35 gallons of net water.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_590', 'How do I calculate the total filled weight of my aquarium?', 'Multiply your net gallons of freshwater by 8.34 lbs (or 8.55 lbs for saltwater). Add the dry weight of the glass tank, the weight of your substrate and stones, and the weight of your stand. A 55-gallon tank typically weighs over 600 lbs filled.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_591', 'Why should I leave a water gap below the top rim of the tank?', 'Leaving 1 to 1.5 inches of space below the rim prevents water from splashing over due to filter surface agitation, accommodates fish that jump, and prevents surface overflow when your hands enter the tank during maintenance.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_592', 'Does an external sump filter add to my total water volume?', 'Yes. Water residing in an external sump increases the total system water volume, which dilutes waste and improves water parameter stability. Add your sump''s operating water volume to the display tank''s net volume.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_593', 'How does glass thickness affect internal volume calculations?', 'Tanks with 10mm to 15mm thick glass have smaller internal dimensions than their external measurements suggest. Always measure inside the glass panes for precise gallon calculations.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_594', 'Why is precise net volume critical when administering fish medications?', 'Underdosing medications allows pathogens to develop resistance, while overdosing can cause fatal toxicity to sensitive fish and invertebrates. Using our [Fish Medication Dose Calculator](/tools/fish-medication-dose) with true net volume guarantees safe treatment.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_595', 'How do I convert US liquid gallons to Imperial gallons and liters?', '1 US liquid gallon equals 3.78541 Liters and approximately 0.8327 Imperial gallons. Multiply US gallons by 3.785 to get liters.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_596', 'How do I measure the water volume of a cylinder or half-cylinder aquarium?', 'Use the cylinder formula $\pi \times r^2 \times h \div 231$, where $r$ is the internal radius in inches and $h$ is the water height in inches. For a half-cylinder, divide the result by 2.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-volume-calculator_597', 'How does water volume affect water chemistry stability?', 'Larger water volumes have greater thermal and chemical inertia. Temperature swings, ammonia spikes, and nitrate buildup happen much slower in a 55-gallon tank than in a 5-gallon nano tank.', 'fish', 'tool', 'aquarium-volume-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_598', 'Why is my filter''s actual flow rate so much lower than the GPH rating on the box?', 'Filter manufacturers test flow ratings with an empty canister, no filter media, and zero vertical lift. In real-world operation, coarse mechanical foams, fine polyfloss, porous biological media, biological slime buildup, and 3 to 4 feet of vertical tubing lift reduce actual flow by 30% to 50%. A filter rated at 300 GPH typically pumps 160 to 200 GPH once running.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_599', 'Can aquarium filter flow rate ever be too strong for fish?', 'Yes. Fish with long decorative fins (such as Betta splendens, Fancy Guppies, and Fancy Goldfish) or low-energy benthic animals (like Axolotls) suffer chronic exhaustion, stress-induced immunosuppression, and physical fin tearing if subjected to strong direct currents. For these species, keep turnover at 3× to 4× and diffuse output velocity using a spray bar directed against the glass, lily pipe, or foam baffle.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_600', 'Does high water flow reduce biological filtration efficiency by decreasing contact time?', 'No. Scientific research on biological biofilm kinetics shows that nitrifying bacteria (Nitrosomonas and Nitrospira) assimilate ammonia within milliseconds. Faster flow rates compress the stagnant fluid boundary layer surrounding bacterial colonies, delivering more dissolved ammonia and essential dissolved oxygen (DO) per minute. Contact time is only an issue with slow chemical media like granular activated carbon or ion exchange resins.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_601', 'What is the difference between filter turnover and powerhead/wavemaker circulation?', 'Filter turnover refers strictly to water passing through physical mechanical, biological, and chemical media beds inside a filter. Wavemakers and powerheads provide internal laminar or turbulent circulation within the display tank without passing water through media. High-demand setups like reef tanks and high-tech planted aquascapes combine 5× to 10× filter turnover with 10× to 20× internal circulation.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_602', 'How does vertical head height affect canister and sump pump flow?', 'Head height is the vertical distance from the pump impeller to the aquarium''s top return outlet. Gravity exerts downward hydraulic head pressure on the water column. Every additional foot of elevation decreases flow rate. A typical 4-foot cabinet rise reduces an unpressurized pump''s output by 20% to 35% before accounting for media resistance.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-filter-flow-rate_603', 'How often should filter media be cleaned to prevent flow rate loss?', 'Rinse mechanical pre-filter sponges every 2 to 4 weeks during routine water changes using siphoned tank water (never chlorinated tap water, which destroys beneficial nitrifying bacteria). Replace disposable fine polishing floss monthly, as dense organic detritus restricts pump flow faster than any other media component.', 'fish', 'tool', 'aquarium-filter-flow-rate', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_604', 'Why is the ''one inch of fish per gallon'' rule inaccurate?', 'Fish volume and waste output scale cubically with body weight, not linearly with length. A 10-inch deep-bodied fish produces dozens of times more waste than ten 1-inch slender tetras.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_605', 'What is aquarium bioload and how is it measured?', 'Bioload is the cumulative biological waste (ammonia, feces, uneaten food) produced by all inhabitants relative to the biological filtration capacity and water volume of the aquarium.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_606', 'How does filter turnover rate affect my stocking limit?', 'Filters with higher flow rates and larger biological media surface areas process ammonia faster. We recommend 4× to 6× tank volume per hour for community tanks and 8× to 10× for heavy waste producers.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_607', 'Can adding live aquarium plants increase my safe fish capacity?', 'Yes. Live plants consume toxic ammonia, nitrite, and nitrate as fertilizer and generate dissolved oxygen, effectively expanding your tank''s biological carrying capacity.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_608', 'What are the three vertical swim zones in an aquarium?', 'They are the top zone (e.g., Hatchetfish, Danios), midwater zone (e.g., Tetras, Angelfish), and bottom zone (e.g., Corydoras, Loaches). Stocking species across all three zones minimizes territorial disputes.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_609', 'What are the early warning signs that an aquarium is overstocked?', 'Symptoms include rapidly rising nitrates (>40 ppm weekly), fish gasping at the surface for oxygen, frequent territorial nipping, cloudy water, and persistent trace ammonia or nitrite readings.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_610', 'What is the minimum recommended school size for schooling fish like tetras?', 'Most schooling and shoaling species (Tetras, Rasboras, Corydoras, Barbs) require a minimum group of 6 individuals, with 8 to 12 being ideal to prevent chronic stress and immune suppression.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_611', 'Why does tank footprint matter more than total water volume for stocking?', 'A larger footprint provides more surface area for oxygen exchange and more floor territory for bottom and midwater fish to establish natural swimming boundaries.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_612', 'How quickly should I add new fish to an aquarium?', 'Add fish gradually in small groups (3 to 6 fish at a time) separated by 1 to 2 weeks. This gives nitrifying bacteria time to multiply and handle the increased bioload.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-stocking-calculator_613', 'How do I calculate stocking for aggressive territorial species like African Cichlids?', 'African cichlids are often intentionally moderately crowded with high filtration (8–10× turnover) to disperse individual aggression, accompanied by heavy rockwork hiding caves.', 'fish', 'tool', 'fish-stocking-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_614', 'What is the aquarium nitrogen cycle and why is it essential?', 'It is the biological colonization of beneficial bacteria that convert deadly fish waste (ammonia) into nitrite, and then into less toxic nitrate. Without cycling, fish suffer gill damage and death from ammonia poisoning.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_615', 'How do I perform a fishless cycle using pure ammonia?', 'Dose liquid ammonium chloride to reach 2.0–4.0 ppm ammonia. Test every 2–3 days. Once ammonia drops and nitrites spike and then fall to 0 ppm while nitrates rise, dose 2 ppm ammonia again. If it clears to 0 ppm in 24 hours, the cycle is complete.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_616', 'How long does it take to cycle a new aquarium?', 'A typical fishless cycle takes 3 to 6 weeks. Using established seeded filter media or bottled live nitrifying bacteria can reduce the timeline to 7 to 14 days.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_617', 'Why did my nitrite levels get stuck and refuse to drop?', 'Nitrite-oxidizing bacteria (*Nitrospira*) multiply much slower than ammonia-oxidizers. A nitrite stall can also happen if pH drops below 6.5, if KH is depleted, or if ammonia was dosed too high (>5 ppm).', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_618', 'Can a low pH stall or kill beneficial nitrifying bacteria?', 'Yes. Below pH 6.5, nitrifying bacterial activity declines significantly, and below pH 6.0, biological nitrification halts entirely.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_619', 'What is ''seeded filter media'' and why is it so effective?', 'Seeded media is sponge, ceramic rings, or filter floss taken directly from an established, disease-free aquarium. It introduces billions of active nitrifying bacteria instantly.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_620', 'Do bottled nitrifying bacteria products actually work?', 'High-quality live bacterial cultures containing true aquatic strains (*Nitrospira*) help jumpstart the cycle, provided they have been stored properly and are not expired.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_621', 'Why did my tank water turn cloudy white during the first week of cycling?', 'A milky white haze is a harmless heterotrophic bacterial bloom feeding on free dissolved organics. It will clear on its own within a few days as the ecosystem balances.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_622', 'How do I handle an emergency fish-in cycle if I already added fish?', 'Perform daily 30–50% water changes to keep combined ammonia and nitrite below 0.25–0.50 ppm, dose a water conditioner that temporarily detoxifies ammonia, and add live beneficial bacteria daily.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-cycling-tracker_623', 'Can I rinse my filter media in untreated tap water?', 'Never rinse filter media in chlorinated tap water, as chlorine and chloramines instantly kill nitrifying bacteria. Always rinse media gently in a bucket of siphoned aquarium water.', 'fish', 'tool', 'tank-cycling-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_624', 'How often should I change aquarium water and what percentage?', 'Most healthy community aquariums thrive on a 20% to 30% water change once per week. Heavily stocked tanks or cichlid setups may require 40% to 50% weekly to keep nitrates below 20 ppm.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_625', 'What is ''Old Tank Syndrome'' and why is it dangerous?', 'It occurs when water changes are neglected for months and only evaporated water is topped off. Nitrates and TDS skyrocket while KH drops to zero, crashing the pH. A sudden large water change then causes fatal osmotic shock.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_626', 'Why can''t I just top off water that has evaporated?', 'When water evaporates, only pure H2O leaves the tank; all minerals, salts, nitrates, and dissolved organics remain behind. Topping off concentrates these compounds over time without removing waste.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_627', 'How do I safely dechlorinate new tap water before adding it?', 'Add a quality aquarium water conditioner to the bucket before pouring, or dose for the entire tank volume if refilling directly with a hose, to neutralize chlorine, chloramines, and heavy metals.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_628', 'Will doing a large 50% water change destroy my beneficial bacteria?', 'No. Nitrifying bacteria live primarily attached to the surfaces of your filter media, substrate, and decor—virtually none float free in the water column.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_629', 'How do I match the temperature of new replacement water?', 'Use a digital thermometer to ensure the replacement water is within 1°C to 2°F of your tank water. Large temperature drops cause stress and can trigger parasitic white spot outbreaks.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_630', 'Should I vacuum the entire gravel bed during every water change?', 'Vacuum about one-third to one-half of the open gravel bed during each water change. Rotating sections preserves beneficial micro-organisms while keeping waste levels controlled.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_631', 'Can live aquatic plants eliminate the need for water changes completely?', 'While heavily planted low-stock tanks require fewer water changes, periodic water changes are still necessary to replenish depleted trace minerals and prevent organic acid buildup.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_632', 'How do water changes affect carbonate hardness (KH) and pH stability?', 'Water changes replenish carbonate hardness (KH) consumed by biological filtration, which acts as a chemical buffer to keep your aquarium pH stable.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_water-change-scheduler_633', 'What should I do if my municipal tap water already contains high nitrates?', 'If tap water contains >20 ppm nitrates, consider using an RO/DI (Reverse Osmosis / Deionization) filtration system or remineralized spring water, alongside live nitrate-absorbing plants.', 'fish', 'tool', 'water-change-scheduler', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_634', 'How much food should I feed my aquarium fish each day?', 'Feed an amount your fish can completely consume within 1.5 to 2 minutes, once or twice daily for adults. Uneaten food should not remain on the substrate after feeding.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_635', 'Why is fasting adult aquarium fish for one day a week recommended?', 'Fasting gives the digestive tract time to fully clear, significantly reducing the risk of constipation, bloat, and swim bladder disorders.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_636', 'What is the difference between flake food, pellets, and frozen food?', 'Flakes dissolve quickly and suit surface feeders; pellets maintain nutritional integrity and suit midwater/bottom fish; frozen foods (daphnia, bloodworms) provide natural proteins and roughage.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_637', 'How does overfeeding cause swim bladder disorder in fish?', 'Consuming dry flakes that expand in the stomach causes intestinal impaction, which exerts physical pressure on the adjacent swim bladder organ and impairs buoyancy.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_638', 'How often should baby fish fry be fed compared to adult fish?', 'Fry have tiny stomachs and high metabolic growth rates, requiring 3 to 5 small micro-feedings of infusoria, baby brine shrimp, or powdered fry food every day.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_639', 'How do I make sure bottom-feeders like Corydoras and Plecos get enough food?', 'Use sinking wafers, spirulina tablets, or repashy gel foods and drop them into the tank after turning off the aquarium lights when nocturnal bottom dwellers are most active.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_640', 'How does water temperature affect a fish''s feeding and digestion rate?', 'As cold-blooded animals, a fish''s metabolic rate increases in warmer water, requiring slightly more food, while cooler water slows gastrointestinal transit time.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_641', 'How long can healthy adult fish safely go without food during a vacation?', 'Healthy adult fish can safely go 5 to 7 days without food. For longer absences, use an electronic timed auto-feeder rather than holiday feeding blocks, which foul water.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_642', 'How should I store dry fish food to preserve its vitamin content?', 'Keep dry food sealed in a cool, dark, dry location. Discard opened containers after 3 to 4 months, as exposure to oxygen degrades essential vitamins and fatty acids.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-food-calculator_643', 'What are the best foods to help relieve constipation in constipated fish?', 'Feed blanched, deshelled green peas or live/frozen daphnia. Both act as natural mild laxatives and stimulate gut motility.', 'fish', 'tool', 'fish-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_644', 'How many watts of heater power do I need per gallon of water?', 'As a general rule, use 3 to 5 Watts per gallon for a 5°F to 10°F temperature rise above room temperature. For cold rooms with a 15°F+ temperature difference, use 7 to 9 Watts per gallon.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_645', 'Why is using two smaller heaters safer than using one large heater?', 'Dual heaters provide redundancy. If one heater''s thermostat fails stuck ''ON'', a smaller heater cannot overheat the entire tank. If one fails ''OFF'', the second heater prevents a deadly temperature crash.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_646', 'Where is the best location in the aquarium to position the heater?', 'Mount the heater horizontally or at a 45-degree angle near the filter intake or outflow. Strong water circulation distributes heat evenly and prevents localized hot spots.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_647', 'Why should I use an external temperature controller like an Inkbird?', 'An external digital controller acts as an independent secondary safety shutoff. If the heater''s internal thermostat gets stuck on, the external controller cuts power instantly.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_648', 'Do cold-water fish like goldfish and axolotls need an aquarium heater?', 'No. Cold-water species thrive in unheated water between 60°F and 68°F (15°C–20°C). Installing a heater for axolotls causes severe heat stress and illness.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_649', 'Can modern submersible aquarium heaters be placed completely underwater?', 'Yes, fully submersible heaters are designed to be placed completely underwater. Always ensure the water level never drops below the minimum water line marked on the glass.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_650', 'How long should I wait before plugging in a newly installed heater?', 'Wait 20 to 30 minutes after submersing a new heater before plugging it in. This allows the glass casing and thermostat to acclimate to the water temperature and prevents thermal shock cracking.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_651', 'What should I do if my aquarium heater breaks or cracks underwater?', 'Immediately unplug the heater from the wall outlet before touching the water to prevent electric shock. Then remove the heater and perform a water change.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_652', 'How often should aquarium heaters be proactively replaced?', 'Most aquatic professionals recommend proactively replacing mechanical glass heaters every 2 to 3 years before internal bimetallic thermostat contacts wear out.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-heater-wattage-calculator_653', 'Why does my aquarium water feel warm even when the heater is set correctly?', 'High-output LED lighting, internal water pumps, powerheads, and warm ambient summer room temperatures can add heat to the water column beyond what the heater produces.', 'fish', 'tool', 'aquarium-heater-wattage-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_654', 'What is PAR and why is it more accurate than watts per gallon?', 'PAR (Photosynthetically Active Radiation) measures the actual light energy available for photosynthesis between 400–700nm at the substrate level, unlike watts which only measure electrical power consumption.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_655', 'How many hours per day should I keep aquarium lights turned on?', '6 to 8 hours daily is optimal for planted tanks. Running lights for longer than 8 hours without elevated CO2 and nutrients almost always causes severe algae outbreaks.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_656', 'What is the ''siesta'' lighting method and how does it reduce algae?', 'A siesta schedule runs lights for 3–4 hours in the morning, turns them off for 2–3 hours in the afternoon, and runs for 3–4 hours in the evening. This breaks the algae growth cycle and lets CO2 regenerate.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_657', 'What Kelvin rating is best for planted freshwater aquariums?', 'A 6,500K to 7,500K color temperature mimics natural midday sunlight and provides the optimal balance of red and blue light spectrums needed for plant photosynthesis.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_658', 'Can high light levels harm live plants if CO2 is not injected?', 'Yes. High light accelerates plant metabolic demand for carbon. If dissolved CO2 is depleted, plants starve and leach organics, triggering explosive algae growth on plant leaves.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_659', 'How does tank depth affect the light reaching my substrate plants?', 'Water absorbs and scatters light rapidly. A tall 24-inch aquarium requires significantly higher PAR output to grow low carpeting plants compared to a shallow 12-inch rimless tank.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_660', 'Do non-planted fish-only tanks require specialized lighting?', 'No. Fish-only tanks only need modest lighting for human viewing and fish day/night circadian rhythms. Keeping lighting low in fish-only tanks prevents nuisance algae.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_661', 'Why do red aquatic plants require higher lighting intensity?', 'Red plants produce protective anthocyanin and carotenoid pigments to shield chlorophyll under intense lighting, which creates their deep vibrant red coloration.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_662', 'How can I fix brown diatoms appearing in a new aquarium?', 'Brown diatom algae is normal in new tanks feeding on silicates in fresh substrate and glass. It typically disappears on its own within 4 to 8 weeks as the tank matures.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-lighting-calculator_663', 'What are WRGB LED lights and why are they popular for planted tanks?', 'WRGB fixtures combine dedicated White, Red, Green, and Blue LED diodes, allowing hobbyists to customize color spectrum for vivid plant hues and optimal plant growth.', 'fish', 'tool', 'aquarium-lighting-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_664', 'How much does a complete beginner 20-gallon aquarium setup cost?', 'A realistic budget for a quality 20-gallon freshwater setup with tank, stand, filter, heater, substrate, test kit, conditioner, and initial fish is approximately $350 to $550.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_665', 'What are the recurring monthly expenses of maintaining an aquarium?', 'Monthly recurring expenses typically range from $15 to $35, covering electricity consumption, quality food, water conditioners, and testing supplies.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_666', 'How much electricity does an aquarium consume each month?', 'A standard 20 to 55-gallon tank uses between 15 and 50 kWh per month, which typically costs $3 to $12 depending on local electricity rates and room temperature.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_667', 'Where is it safe to save money when setting up an aquarium?', 'You can safely save by buying used glass tanks, building a solid DIY stand, and using affordable pool filter silica sand as an inert substrate.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_668', 'What aquarium equipment should I never buy cheaply?', 'Never compromise on heaters (cheap units fail and boil tanks), liquid test kits (test strips are inaccurate), and biological filtration.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_669', 'How much extra does a high-tech planted tank cost compared to a basic tank?', 'A high-tech planted tank costs $400 to $800+ more, driven by pressurized CO2 equipment, high-PAR WRGB LED lighting, active aquasoil, and specialized fertilizers.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_670', 'What unexpected emergency expenses should every fishkeeper budget for?', 'Budget for a secondary backup heater, a battery-powered air pump for power outages, a quarantine/hospital tank, and emergency medications ($50–$100 total).', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_671', 'Is buying a used aquarium setup worth the cost savings?', 'Yes, used aquariums can save 50–70% of costs, provided you leak-test the tank outdoors for 24 hours to ensure the silicone seals are intact before bringing it indoors.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_672', 'Why is a 20-gallon tank often cheaper to maintain in the long run than a 5-gallon nano tank?', 'Larger water volumes have greater chemical stability, experiencing fewer sudden fish losses, disease outbreaks, and water quality emergencies than fragile nano aquariums.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-tank-cost-calculator_673', 'How much do water testing kits and water conditioners cost annually?', 'A master liquid test kit ($35) lasts 1 to 2 years, and concentrated dechlorinator ($15) lasts a typical 30-gallon tank for over a year, totaling ~$30–$45 annually.', 'fish', 'tool', 'fish-tank-cost-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_674', 'Do fish actually recognize their owners and respond to names?', 'While fish do not hear airborne names like dogs do, they possess sharp vision and rapidly recognize their owner''s face and feeding gestures, swimming excitedly to the glass.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_675', 'What are the most popular names for male and female Betta fish?', 'Popular male Betta names include Poseidon, Flare, Phoenix, Neptune, and Cobalt. Popular female Betta names include Cleo, Coral, Iris, Opal, and Ruby.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_676', 'How should I name a large school of identical fish like Neon Tetras?', 'Many keepers give schooling groups collective names like ''The Neon Brigade'' or ''The Sparklers'', or name standout individuals by subtle fin or size differences.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_677', 'What are some clever pun names for pet fish?', 'Classic fish puns include Swim Shady, Gill-bert, Finneas, Fishy McFishface, Bait, Guppy Goldberg, and James Pond.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_678', 'Can aquarium fish be trained to perform tricks or target feed?', 'Yes. Bettas and Goldfish can easily be target-trained with positive food reinforcement to swim through hoops, follow feeding wands, and feed at specific stations.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_679', 'What are great mythological names for centerpiece aquarium fish?', 'Top mythological names include Triton, Leviathan, Neptune, Calypso, Athena, Apollo, Hydra, Kraken, and Osiris.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_680', 'How does naming my fish help with routine health monitoring?', 'Assigning names encourages keepers to observe individual fish closely each day, making it easier to catch early signs of illness or fin rot.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_681', 'What are great names for pairs of breeding Angelfish or Cichlids?', 'Popular pair names include Bonnie & Clyde, Romeo & Juliet, Zeus & Hera, Salt & Pepper, and Apollo & Artemis.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_682', 'How do goldfish demonstrate long-term memory in scientific studies?', 'Scientific research proves goldfish retain learned maze routes, color cues, and feeding schedules for at least 5 to 6 months, completely disproving the 3-second myth.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-name-generator_683', 'Can I rename my fish without causing stress?', 'Yes. Since fish respond to visual cues, routines, and lighting rather than vocalized words, you can change their name at any time.', 'fish', 'tool', 'fish-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_684', 'How much hay should my rabbit eat every single day?', 'Your rabbit should consume a loose pile of hay roughly the same size as their own body every 24 hours. By weight, this equals approximately 30 to 35 grams of dry grass hay per pound of body weight. An average 5 lb (2.3 kg) rabbit eats about 150 to 175 grams of hay daily. Hay must be available 24/7 without restriction.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_685', 'Can I feed Alfalfa hay to an adult rabbit?', 'No, healthy adult rabbits over 6 months old should not receive Alfalfa hay. Alfalfa is a legume hay containing dangerously high levels of protein (18%) and calcium (>1.4%). In adult rabbits, excess calcium is excreted through the urinary tract, leading to thick bladder sludge, painful calcium carbonate bladder stones, and chronic renal damage. Stick to grass hays like Timothy, Orchard, or Meadow hay.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_686', 'What should I do if my rabbit stops eating hay for 12 hours?', 'A rabbit that stops eating hay for 12 hours is experiencing a medical emergency known as Gastrointestinal (GI) Stasis. Check for small, dry, or absent poops, loud gurgling or silent belly sounds, and lethargic crouching. Contact an exotic veterinarian immediately. Never wait more than 12 to 24 hours, as GI stasis can quickly become fatal.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_687', 'Why does my rabbit poop in the litter box while eating hay?', 'Rabbits possess an innate biological urge to graze and eliminate at the same time. Placing a clean hay rack directly hanging over their litter tray harnesses this natural behavior, instantly resolving up to 95% of all litter box training issues.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_688', 'What is the difference between 1st, 2nd, and 3rd cut Timothy hay?', '1st cut is harvested in spring; it is crunchy, high in coarse stems and seed heads, and has the highest fiber for dental wear. 2nd cut is harvested mid-summer; it features leafy green foliage with moderate stems, offering the ideal balance of taste and fiber. 3rd cut is harvested in autumn; it is ultra-soft and leafy with almost no stems, making it great for dental-compromised seniors but lower in tooth-grinding resistance.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_689', 'Can rabbits live on pellets alone without hay?', 'Absolutely not. Commercial pellets do not provide the long, intact physical fibers required to stimulate gut motility or grind down continuously growing molars. Rabbits fed a pellet-only diet suffer severe dental disease, fatal GI stasis, and severe obesity.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_690', 'How can I encourage a picky rabbit to eat more hay?', 'Try offering a variety of grass hays (mix 2nd cut Timothy with fragrant Orchard grass, Oat hay, and Meadow hay). Fluff and refresh the hay 2–3 times daily, as rabbits ignore stale, stepped-on hay. You can also mix in safe dried herbs like chamomile, dandelion leaf, or marigold petals.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_691', 'How should I store bulk bales of rabbit hay?', 'Store hay in a dry, dark, well-ventilated location inside cardboard boxes, breathable fabric laundry bags, or wooden crates. Never store fresh hay in sealed plastic bags or airtight plastic totes, as trapped humidity breeds toxic mold and mycotoxins.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_692', 'What are cecotropes and why does my rabbit eat them?', 'Cecotropes are small, glossy, nutrient-rich clusters of fermented bacteria, volatile fatty acids, and B-complex vitamins produced in the rabbit''s cecum. Rabbits instinctively eat them directly from the anus to recycle essential proteins and vitamins. Uneaten, mushy cecotropes on the floor indicate an over-supplemented, high-carb pellet diet.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-calculator_693', 'Is Orchard grass as healthy as Timothy hay for rabbits?', 'Yes. Orchard grass has a virtually identical nutritional profile to 2nd cut Timothy hay (high fiber, low protein, low calcium) but is softer, greener, and produces fewer airborne pollen allergens, making it an excellent choice for allergy-sensitive pet owners.', 'small-pets', 'tool', 'rabbit-hay-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_694', 'How much hay should my rabbit eat every day?', 'A healthy rabbit must eat a pile of loose grass hay at least equal to their own body size every single day. By weight, this represents roughly 30 to 35 grams of hay per pound of body weight (approx. 150g daily for a typical 5-pound rabbit). Hay should be available 24/7 without restriction.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_695', 'Can adult rabbits eat alfalfa hay?', 'No. Alfalfa is a legume, not a grass. It is packed with high protein and elevated calcium. Adult rabbits excrete excess calcium through their urinary tract, which rapidly forms painful, gritty bladder sludge and bladder stones. Only feed grass hays (Timothy, Orchard, Meadow, Oat) to adult rabbits.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_696', 'Why is hay more important than commercial pellets?', 'Pellets are ground up and quickly swallowed without requiring lateral chewing, causing molar spurs. Furthermore, pellets lack the long-strand indigestible fiber needed to stimulate colonic peristalsis. Feeding excessive pellets and too little hay is the primary cause of fatal Gastrointestinal (GI) Stasis.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_697', 'What should I do if my rabbit stops eating hay for 12 hours?', 'This is a life-threatening veterinary emergency known as GI Stasis. Rabbits cannot safely fast; without continuous fiber, the gut halts, gas builds up painfully, and hepatic lipidosis begins within 24 hours. Contact an exotic pet veterinarian immediately.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_698', 'Why does my rabbit eat hay while sitting in the litter box?', 'Rabbits possess a natural biological urge to graze and poop simultaneously. Hanging your rabbit''s hay rack directly above or inside their litter box promotes natural grazing behavior and instantly resolves most litter training problems.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_699', 'What is the difference between 1st, 2nd, and 3rd cut Timothy hay?', '1st cut has the thickest crunchy stems and seed heads, providing maximum dental wear and crude fiber. 2nd cut has leafy green foliage with moderate stems, offering the ideal blend of taste and fiber. 3rd cut is soft and almost stemless, excellent for elderly rabbits with missing teeth but providing less dental wear.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_700', 'How do I store rabbit hay so it doesn''t get moldy?', 'Store hay in a dry, dark, well-ventilated area in cardboard boxes or breathable woven fabric bags. Never seal fresh hay in plastic containers or bags, as trapped humidity breeds lethal Aspergillus and fungal mycotoxins.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_701', 'What are caecotropes and why does my rabbit eat them?', 'Caecotropes are nutrient-dense packets produced in the rabbit''s caecum containing essential amino acids, fatty acids, and B-vitamins. Rabbits ingest them directly from the anus to reabsorb these vital nutrients. Finding uneaten, mushy caecotropes on the floor usually indicates an over-supplemented, high-pellet diet.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_702', 'Is Orchard grass a good alternative if I am allergic to Timothy hay?', 'Yes! Orchard grass matches 2nd cut Timothy hay in nutritional composition (high fiber, low protein, low calcium) but produces significantly less airborne pollen, making it the top recommendation for owners with grass allergies.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-hay-portion-calculator_703', 'How can I encourage a picky rabbit to eat more hay?', 'Refresh hay 2–3 times daily (rabbits ignore stale or stepped-on hay), mix different varieties (Timothy, Orchard, Oat, botanical herbs like dried dandelion or chamomile), and reduce pellet portions so the rabbit is motivated to graze on fibrous hay.', 'small-pets', 'tool', 'rabbit-hay-portion-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_704', 'What is the absolute minimum cage size for a single rabbit?', 'A single standard rabbit needs a minimum unbroken base enclosure of 12 to 16 sq ft (e.g., a 4x4 ft exercise pen) with a height of at least 36 inches, paired with an accessible exercise run of at least 32 sq ft for 4+ hours daily.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_705', 'Why are wire-bottom cages dangerous for rabbits?', 'Rabbits have no protective foot pads on the bottom of their paws—only a thin layer of fur over bone. Wire floors concentrate their body weight onto thin metal wires, wearing away the fur and causing ulcerative pododermatitis (sore hocks), which can progress to deep bone infections.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_706', 'How high can a rabbit jump over an exercise pen?', 'Even small and medium rabbits can easily clear 24- to 30-inch barriers from a standstill. An exercise pen should be at least 36 inches tall for dwarf and standard breeds, and 42 to 48 inches tall for energetic or giant breeds.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_707', 'Can rabbits live 100% free-roam indoors like a cat or dog?', 'Yes! In fact, free-roaming in a bunny-proofed home is considered the gold standard of modern rabbit care. Baseboards, electrical cords, and toxic houseplants must be protected or elevated to ensure safety.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_708', 'How much space does a bonded pair of rabbits require?', 'A bonded pair needs at least 20 to 24 sq ft of base enclosure floor space, plus a 40+ sq ft daily exercise run. They also need duplicate resources (2 litter boxes, 2 hay stations, 2 water bowls) to prevent territorial disputes.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_709', 'Are multi-level cages good for rabbits?', 'Multi-level cages provide bonus enrichment, but upper levels do not replace single-level floor space. Rabbits need wide horizontal ground to run and hop. Ramps must have solid traction and shallow slopes (<30 degrees) to prevent spinal trauma.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_710', 'What is the best flooring to put inside a rabbit pen?', 'The best flooring is solid, non-slip, and chew-resistant: water-resistant vinyl sheet flooring covered with washable, low-pile cotton rugs, fleece blankets, or foam puzzle mats.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_711', 'Can I keep my pet rabbit outdoors in a wooden hutch?', 'Outdoor hutch living is strongly discouraged by modern exotic veterinarians. Outdoor rabbits face extreme risks from temperature extremes, flystrike (maggot infestation), respiratory infections, and predator-induced heart attacks.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_712', 'How many hours of out-of-cage exercise does a rabbit need each day?', 'Rabbits require at least 3 to 5 hours of free-roam exercise daily outside their primary pen, ideally during their natural crepuscular peak activity periods (early morning and dusk).', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-cage-size-calculator_713', 'What hides should I provide inside the rabbit enclosure?', 'Provide at least one hide box per rabbit, plus one extra. Hides should have two separate entry/exit holes so one rabbit cannot corner and trap another during territorial disagreements.', 'small-pets', 'tool', 'rabbit-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_714', 'Why are seed and muesli mix rabbit foods dangerous?', 'Muesli mixes with colorful pieces, dried corn, seeds, and cereal flakes encourage selective feeding. The rabbit eats the sugary, fatty bits and leaves the nutritious fiber behind, causing rapid tooth decay, obesity, cecal dysbiosis, and fatal GI stasis.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_715', 'How many pellets should an adult rabbit eat each day?', 'An adult rabbit of ideal weight needs only 1/8 to 1/4 cup (approximately 25 to 35 grams) of plain, high-fiber Timothy-based pellets per 5 lbs (2.3 kg) of body weight daily. Overfeeding pellets suppresses their appetite for vital grass hay.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_716', 'Why is iceberg lettuce bad for rabbits?', 'Iceberg lettuce consists almost entirely of water with virtually zero nutritional value, and it contains lactucarium, a chemical compound that can trigger severe watery diarrhea and intestinal cramping in rabbits. Choose dark leafy varieties like Romaine or green leaf lettuce instead.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_717', 'How much fresh leafy greens should I feed daily?', 'Feed approximately 1 packed cup of dark leafy greens per 2 lbs of body weight daily. For an average 4 lb rabbit, provide 2 packed cups of mixed greens daily, rotating between at least three safe varieties like Romaine, cilantro, and mint.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_718', 'Are carrots safe for rabbits to eat every day?', 'No. The popular cartoon trope of rabbits eating whole carrots daily is a dangerous myth. Carrots and fruits are very high in natural sugars and starches. They should be restricted to a tiny treat—no more than 1 teaspoon to 1 tablespoon per 2 lbs of body weight occasionally.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_719', 'Why should water be offered in a heavy ceramic bowl instead of a bottle?', 'Rabbits drink substantially more water from an open ceramic bowl than from a sipper bottle. Lapping water from a bowl matches their natural anatomical drinking posture and prevents dehydration. Water bottles often clog, harbor bacterial biofilms, and frustrate thirsty rabbits.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_720', 'How do I transition my rabbit to a new brand of pellets?', 'Transition gradually over 2 to 3 weeks. Mix 75% old food with 25% new food for 5 days, then 50/50 for 5 days, then 25% old and 75% new for 5 days before fully switching. Abrupt dietary shifts shock the cecal microflora and trigger GI stasis.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_721', 'Can rabbits eat fresh grass from the garden or lawn?', 'Yes, provided the grass is 100% free from chemical pesticides, fertilizers, weedkillers, and dog/cat feces. Introduce fresh grass slowly in tiny amounts. Never feed lawnmower clippings, as the heat and blades trigger rapid fermentation that causes fatal bloat.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_722', 'What should I do if my rabbit has soft, sticky poops smeared on their hindquarters?', 'Sticky poops (''poopy butt'') are usually unconsumed cecotropes caused by excess carbohydrates from too many pellets, sugary treats, or a lack of hay. Cut out all treats, reduce pellets to a strict minimum, and feed 100% grass hay until stools normalize.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-food-calculator_723', 'At what age should a young bunny switch from Alfalfa to Timothy pellets?', 'Young rabbits should transition from high-protein Alfalfa-based pellets to low-protein Timothy grass-based pellets between 6 and 7 months of age, when skeletal growth plates fuse and energy requirements stabilize.', 'small-pets', 'tool', 'rabbit-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_724', 'What is the average lifespan of a pet rabbit?', 'With modern indoor veterinary care, high-fiber diets, and spay/neuter surgery, domestic rabbits live an average of 8 to 12 years. Small dwarf breeds frequently reach 12 to 14+ years, while giant breeds average 5 to 8 years.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_725', 'At what age is a rabbit considered a senior?', 'A rabbit is generally considered a senior at 5 to 6 years of age (or 4 years of age for giant breeds like Flemish Giants). At this stage, semi-annual veterinary checkups are recommended to monitor dental and kidney health.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_726', 'Why is spaying or neutering essential for a rabbit''s lifespan?', 'Unspayed female rabbits face an overwhelming 70% to 80% risk of developing fatal uterine adenocarcinoma (uterine cancer) by age 4 to 5. Spaying eliminates this risk completely, while neutering prevents reproductive cancers and reduces territorial aggression and stress.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_727', 'What are the common signs of arthritis in an aging rabbit?', 'Signs of arthritis include reluctance to hop or binky, difficulty grooming the hindquarters (causing messy fur or uncollected cecotropes), missing the litter box due to high lip walls, and developing sore hocks on the heels.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_728', 'How should I adapt the home environment for an elderly rabbit?', 'Provide non-slip memory foam rugs over slick floors, cut down the front entrance of litter boxes to a 2-inch height, keep food and water bowls close to their primary resting area, and offer safe, low-voltage warming pads during cold seasons.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_729', 'Do older rabbits need different food than young adults?', 'Senior rabbits with kidney issues may need low-calcium Orchard grass rather than Timothy hay, and seniors losing weight may need a slight increase in quality pellets or critical care mash. Always consult an exotic vet before altering a senior rabbit''s diet.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_730', 'How often should an older rabbit see an exotic veterinarian?', 'Rabbits aged 5 and older should see an exotic veterinarian every 6 months for a thorough physical exam, oral cavity endoscopy to spot hidden molar spurs, and annual blood chemistry panels.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_731', 'Can senior rabbits develop cataracts?', 'Yes, elderly rabbits can develop cataracts due to age-related lens nuclear sclerosis or Encephalitozoon cuniculi (E. cuniculi) parasitic microsporidian infections. Keep their enclosure layout consistent so visually impaired rabbits can navigate by scent and memory.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_732', 'Why do giant breed rabbits have shorter lifespans than dwarf breeds?', 'Giant breeds experience accelerated cellular growth and carry substantial body mass, which places heavier demands on their cardiovascular system and musculoskeletal frame, predisposing them to earlier cardiac failure and degenerative joint disease.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-age-calculator_733', 'What is the oldest recorded domestic rabbit?', 'According to the Guinness World Records, the oldest verified domestic rabbit was an Australian rabbit named Flopsy, who lived to be 18 years and 10 months old.', 'small-pets', 'tool', 'rabbit-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_734', 'Can rabbits really learn and recognize their own names?', 'Yes! Rabbits are intelligent and have excellent auditory memory. With 1 to 2 weeks of consistent positive reinforcement (associating their name with a fresh herb or head scratch), a rabbit will perk its ears and hop over when called.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_735', 'What kind of names do rabbits learn most easily?', 'Rabbits respond best to short, distinct 1- or 2-syllable names with sharp consonant sounds (like ''Pip'', ''Barnaby'', ''Cleo'', or ''Boba'') spoken in a consistent, cheerful tone of voice.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_736', 'How should I train my rabbit to come when I call its name?', 'Sit on the floor at your rabbit''s level. Say their name clearly, hold out a fragrant piece of cilantro or fresh dill, and reward them immediately when they hop toward you. Practice for 3 to 5 minutes once or twice daily.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_737', 'Should I rename an adopted rescue rabbit?', 'You can easily rename a rescue rabbit! Rabbits adapt quickly to new vocal cues. Simply use their new name paired with positive reinforcement, and they will master it within 1 to 2 weeks.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_738', 'What are popular names for bonded pairs of rabbits?', 'Classic bonded pair names include themed duos like Clover & Bramble, Salt & Pepper, Biscuit & Gravy, Mochi & Boba, Hazel & Fiver, and Bonnie & Clyde.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_739', 'Why do rabbits thump their hind legs?', 'Thumping is a natural wild instinct used to alert the warren to danger. Rabbits thump when frightened by an unfamiliar noise, scent, or shadow, or occasionally to express extreme displeasure or annoyance.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_740', 'What does it mean when a rabbit grinds its teeth gently while being petted?', 'Gentle tooth purring (chattering) while relaxing or being petted is a sign of deep contentment and happiness—the rabbit equivalent of a cat purring. Loud, harsh tooth clicking accompanied by a hunched posture indicates severe abdominal pain.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_741', 'Can I use human food names for my rabbit?', 'Food-inspired names like Mochi, Boba, Peanut, Waffles, and Cinnamon are among the most popular and endearing pet rabbit names worldwide.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_742', 'How do rabbits show affection to their owners?', 'Rabbits show affection by nudging with their nose, running figure-eights around your feet (circling), grooming/licking your hands or clothes, tooth-purring, and flopping down comfortably beside you.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-name-generator_743', 'Do male and female rabbits have different naming personalities?', 'Personality in rabbits is shaped far more by breed, individual temperament, and whether they are spayed/neutered than by biological sex alone. Both neutered males and spayed females can be equally affectionate, playful, and responsive.', 'small-pets', 'tool', 'rabbit-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_744', 'What is the absolute minimum unbroken cage size for a Syrian hamster?', 'The veterinary minimum unbroken floor space for a Syrian hamster is 600 to 800 sq inches (approximately 40-gallon breeder aquarium minimum), with 1,000+ sq inches strongly recommended for active female Syrians.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_745', 'Why do connecting plastic modular cages not count toward floor space?', 'Hamsters need continuous, uninterrupted floor space to build underground burrow networks, forage naturally, and sprint without obstruction. Small modular pods connected by tubes restrict movement, trap carbon dioxide and ammonia, and cause severe territorial stress.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_746', 'How deep should hamster bedding be?', 'Bedding should be at least 8 to 10 inches deep for dwarf hamsters, and 10 to 12+ inches deep for Syrian hamsters. Deep bedding allows hamsters to construct stable underground sleeping burrows and food storage chambers.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_747', 'Why is bar chewing and climbing (''monkey barring'') dangerous?', 'Bar chewing is a stereotypic stress behavior indicating severe boredom and cramped housing. It can break teeth, cause brain micro-trauma, and cause facial abscesses. Climbing cage bars frequently leads to fatal falls and broken limbs.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_748', 'What bedding substrates are safe for hamsters?', 'Safe beddings include unscented, dust-extracted paper bedding (Kaytee Clean & Cozy, Carefresh), aspen shavings, and soft meadow/orchard hay. Never use cedar, pine, scented beddings, or cotton/fluff nesting material (which tangles limbs and causes fatal gut impaction).', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_749', 'Can two hamsters live together in the same cage?', 'No. Syrian hamsters and Chinese hamsters are strictly solitary animals. Housing them together will result in violent territorial fights and fatal injuries. Even dwarf species almost always fight in captivity and should be housed individually.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_750', 'What is a multi-chamber hide and why is it recommended?', 'A multi-chamber hide mimics a natural underground burrow system by offering 2 to 3 connected dark rooms with an open bottom sitting directly on deep bedding. Hamsters use separate rooms for sleeping, storing food hoards, and urinating.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_751', 'How large should a Roborovski hamster''s sand bath be?', 'Roborovskis originate from sandy deserts and need a large sand area covering 25% to 33% of their enclosure floor. Use calcium-free, dye-free reptile sand or sterilized children''s play sand (never dust).', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_752', 'How often should I clean a large hamster enclosure?', 'In a properly sized enclosure (600–1,000+ sq in) with deep bedding, full cleans should be done only every 6 to 8 weeks. Perform daily spot-cleaning of the soiled litter/sand corner to avoid destroying the hamster''s complex tunnel system and scent marks.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-cage-size-calculator_753', 'What are the best budget-friendly large hamster enclosures?', 'Excellent budget-friendly options include DIY bin cages made from 50-gallon heavy-duty storage totes (with wire mesh lids installed), used 40–75 gallon glass fish tanks from classified ads, or modified IKEA Pax/Linnmon flatpack furniture.', 'small-pets', 'tool', 'hamster-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_754', 'Why is scatter feeding better than feeding from a food bowl?', 'Scatter feeding—sprinkling the seed mix across the surface of the bedding—mimics natural wild foraging behavior. It provides mental stimulation, encourages exercise, and prevents boredom and stereotypic bar-chewing.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_755', 'Why are dwarf hamsters prone to diabetes?', 'Campbell''s and Winter White dwarf hamsters possess genetic variations that impair insulin regulation. Feeding them sugary treats, dried fruits, honey-dipped seed bars, corn, or peas frequently triggers rapid Type-2 diabetes and early mortality.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_756', 'How many mealworms should I feed my hamster each week?', 'Feed 3 to 5 dried or live mealworms per week for a Syrian hamster, and 2 to 3 small mealworms or crickets for dwarf hamsters to fulfill their omnivorous animal protein requirement.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_757', 'Why does my hamster empty their food bowl instantly?', 'Hamsters have deep cheek pouches extending to their shoulders. In the wild, they pouch and carry all available food straight to their underground cache. An empty bowl does not mean they ate everything; check their burrow hoard before adding more food.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_758', 'Can hamsters eat citrus fruits or onions?', 'No. Never feed citrus fruits (oranges, lemons, grapefruits), onions, garlic, leeks, chives, raw kidney beans, apple seeds, or raw potatoes. Citrus acid causes painful stomach ulcers, and allium vegetables destroy red blood cells.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_759', 'How often should I clean out my hamster''s food hoard?', 'Inspect their hoard during weekly spot-cleans. Remove perishable fresh vegetables immediately to prevent mold. Leave dry seed caches intact and replace any removed spoiled food with a small pinch of fresh seeds to prevent stress.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_760', 'Are sunflower seeds and peanuts healthy for hamsters?', 'Sunflower seeds and peanuts are high in fat and should be used strictly as hand-fed training treats rather than a primary food base. Excess fatty nuts lead to obesity and arterial disease.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_761', 'What fresh herbs are safe for hamsters to eat?', 'Safe fresh and dried herbs include dandelion leaves, parsley, cilantro, basil, chamomile flowers, marigold (calendula) petals, and mint in small amounts.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_762', 'Can hamsters drink milk or eat cheese?', 'Hamsters are lactose intolerant after weaning. Commercial cow''s milk causes severe diarrhea. A tiny crumb of low-lactose hard cheese (like mild cheddar) can be an occasional treat, but insect protein is far healthier.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-food-calculator_763', 'Do hamsters need mineral licks or salt wheels?', 'No. Salt licks and mineral blocks are unnecessary and dangerous for hamsters. A balanced seed and pellet diet provides all required minerals, and excess salt causes kidney damage and severe dehydration.', 'small-pets', 'tool', 'hamster-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_764', 'Why can''t guinea pigs produce their own Vitamin C?', 'Guinea pigs lack the active L-gulonolactone oxidase (GULO) liver enzyme due to an evolutionary genetic mutation. Because they cannot synthesize ascorbic acid from glucose, 100% of their daily Vitamin C must come from their diet.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_765', 'What is the best daily natural source of Vitamin C for a guinea pig?', 'Fresh yellow and red bell peppers are the best natural sources. They contain nearly 200 mg of Vitamin C per 100 grams, are low in calcium and sugar, and a single medium slice daily satisfies an adult guinea pig''s full requirement.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_766', 'Why should I never put Vitamin C drops in their water bottle?', 'Vitamin C oxidizes rapidly in light and air, losing over half its potency within hours. Additionally, it alters the water''s taste, causing many guinea pigs to stop drinking, leading to rapid, life-threatening dehydration.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_767', 'What are the earliest warning signs of scurvy (Vitamin C deficiency)?', 'Early signs include a dull, puffed-up coat, subtle weight loss, hopping stiffly with the hind legs, swollen or tender foot joints, bleeding gums, and crying out when picked up.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_768', 'Can a guinea pig overdose on Vitamin C?', 'Vitamin C is water-soluble, meaning moderate excesses are safely excreted in urine. However, extreme chronic overdosing (>100 mg/day for months in healthy adults) can contribute to the formation of calcium oxalate bladder stones and pseudo-scurvy.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_769', 'How much Vitamin C does a sick or pregnant guinea pig need?', 'Pregnant sows, nursing mothers, and guinea pigs recovering from illness or surgery need 35 to 50 mg (and up to 100 mg under veterinary care for active scurvy) of Vitamin C daily.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_770', 'Do guinea pig pellets lose their Vitamin C over time?', 'Yes. Even pellets with stabilized Vitamin C lose significant nutritional value after 90 days once the bag is opened and exposed to air and humidity. Always check manufacturing dates and store pellets sealed in a cool, dark container.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_771', 'Can I feed oranges to my guinea pig for Vitamin C?', 'Oranges contain Vitamin C, but they are very high in citric acid and natural sugars, which can cause painful lip sores (cheilitis) and digestive upset. Bell peppers are far safer and contain more Vitamin C.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_772', 'Are chewable Vitamin C tablets safe for guinea pigs?', 'Yes, stabilized 50 mg Vitamin C tablets formulated specifically for small animals (such as Oxbow Natural Science Vitamin C) are highly recommended, safe, and loved by guinea pigs as a daily treat.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-vitamin-c-calculator_773', 'How quickly can a guinea pig recover from scurvy with treatment?', 'With prompt high-dose oral Vitamin C supplementation (50–100 mg/day directly into the mouth) and veterinary pain relief, clinical improvement is often seen within 48 to 96 hours, with full joint recovery taking 1 to 3 weeks.', 'small-pets', 'tool', 'guinea-pig-vitamin-c-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_774', 'Can hamsters and guinea pigs learn their names?', 'Yes! Guinea pigs and hamsters can learn to recognize their names. When you consistently pair their name with a favorite treat (like a bell pepper slice or mealworm), they will perk up and come to the front of their enclosure.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_775', 'What names work best for ferrets?', 'Ferrets respond well to short, energetic names starting with crisp consonants like Bandit, Ziggy, Rascal, Jax, and Pip, which match their playful, inquisitive personalities.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_776', 'How do I choose names for a pair of guinea pigs?', 'Popular strategies include complementary food duos (Peanut & Buttercup, Biscuit & Gravy), nature pairs (Clover & Daisy), or famous fictional companions (Pippin & Merry, Thelma & Louise).', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_777', 'Why do guinea pigs make a loud ''wheeking'' sound?', 'Wheeking is a vocalization guinea pigs use almost exclusively to communicate with their human caregivers. It is an excited greeting expressing anticipation of fresh veggies or hay.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_778', 'Can hedgehogs recognize their owner''s voice and name?', 'African Pygmy Hedgehogs have poor eyesight but acute hearing and scent. With gentle daily handling, they learn to recognize their owner''s specific vocal tone and will uncurl when spoken to calmly.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_779', 'What are cute names for African Pygmy Hedgehogs?', 'Quill- and nature-inspired names like Bramble, Quilliam, Sonic, Sprout, Nutmeg, Prickles, and Pip are classic favorites for hedgehogs.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_780', 'How should I name a colony of sugar gliders?', 'Sugar gliders live in close colonies and suit coordinated group themes, such as celestial names (Nova, Comet, Stella, Orion) or Australian-inspired names (Sydney, Bindi, Roo, Boomer).', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_781', 'Do chinchillas respond to voice training?', 'Chinchillas are intelligent and learn voice cues quickly. They respond well to soft, gentle names like Dusty, Ash, Velvet, and Sterling, especially when offered a rosehip or dust bath.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_782', 'Should I name my pet based on its coat color or personality?', 'Observing your pet''s behavior for 2 to 3 days often reveals their true personality (whether shy, bold, acrobatic, or food-obsessed), leading to a much more meaningful and fitting name.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_small-pet-name-generator_783', 'Is it okay to change the name of an adopted small pet?', 'Yes. Small pets adapt seamlessly to new names through positive reinforcement and positive voice association within 1 to 2 weeks.', 'small-pets', 'tool', 'small-pet-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_784', 'Which hamster species lives the longest?', 'Roborovski dwarf hamsters have the longest natural lifespan among domestic hamsters, averaging 3 to 3.5 years, with some well-cared-for individuals reaching 4 years.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_785', 'Why do domestic hamsters have relatively short lifespans?', 'Hamsters are prey animals with extremely high metabolic rates and rapid heart rates (300–500 bpm). Their evolutionary survival strategy focuses on early sexual maturity and rapid reproduction rather than individual longevity.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_786', 'What are the common signs of aging in a senior hamster?', 'Senior signs (usually appearing after 18 months) include sleeping longer hours, reduced wheel running, slight weight loss, thinning fur, cloudy eyes (cataracts), and moving more slowly.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_787', 'How can I adapt a cage for a geriatric hamster?', 'Lower water bottle spouts and food dishes to ground level, remove high climbing platforms or steep ladders to prevent falls, switch to softer paper bedding, and offer softened food mash if dental wear occurs.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_788', 'What is ''torpor'' in hamsters and how is it different from dying?', 'Torpor is a dangerous hypothermic state triggered when room temperatures drop below 60°F (15°C). The hamster appears limp, cold, and barely breathing. Slowly warm them up in your hands or under a warm towel near a safe heat source; true hibernation does not exist in domestic hamsters.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_789', 'What are the leading causes of death in pet hamsters?', 'Leading causes include heart failure (cardiomyopathy), chronic renal failure, cancer/tumors, diabetes in dwarf species, and Wet Tail (proliferative ileitis) in stressed young Syrian hamsters.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_790', 'Can a hamster live to be 5 years old?', 'While 5-year lifespans are occasionally claimed, they are exceptionally rare. A lifespan of 2 to 3 years is the realistic biological norm for domestic hamsters.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_791', 'How does wheel size affect a hamster''s lifespan?', 'An undersized wheel forces the hamster to run with its spine bent backwards, leading to severe chronic spinal disc compression, arthritis, and nerve damage that severely reduces their quality of life and mobility.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_792', 'Do female hamsters live longer than male hamsters?', 'Lifespans are generally comparable between sexes, although female Syrian hamsters can be more prone to reproductive tract infections (like pyometra) if not monitored carefully.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-lifespan-estimator_793', 'How do I know when it is time to say goodbye to an elderly hamster?', 'Consult an exotic vet when your hamster can no longer eat or drink, has chronic unmanageable pain, exhibits persistent labored breathing, or loses the ability to walk and groom.', 'small-pets', 'tool', 'hamster-lifespan-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_794', 'What is the modern minimum tank size for an adult bearded dragon?', 'The gold standard minimum for an adult bearded dragon is 48 × 24 × 24 inches (120 gallons / 4×2×2 ft) with 8 sq ft of floor area. This allows a proper thermal gradient from 105°F basking down to 75°F cool retreat.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_795', 'Can a baby reptile start in an adult-sized enclosure?', 'Yes, provided the enclosure is filled with dense clutter, fake plants, multiple hides, and easily accessible food and water dishes. In the wild, baby reptiles have unlimited space — they only get stressed in large, empty, barren enclosures.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_796', 'Is PVC, glass, or wooden enclosure better for reptiles?', 'PVC is the best all-around material: it retains heat, holds humidity without warping, is lightweight, and has opaque sides that reduce reptile stress. Glass is great for arid species but loses heat quickly. Wood tables are ideal for tortoises but rot under high humidity.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_797', 'How much space does an adult leopard gecko need?', 'Adult leopard geckos need a minimum of 36 × 18 × 18 inches (40–50 gallon breeder tank) with at least 4.5 sq ft of floor area to accommodate warm, cool, and humid hides plus foraging space.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_798', 'Why do chameleons require all-screen mesh cages?', 'Chameleons have extremely sensitive respiratory systems. Glass tanks trap stagnant, humid air which breeds bacteria and causes fatal upper respiratory infections. Screen cages allow continuous 360-degree air movement.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_799', 'What is the enclosure standard for ball pythons and corn snakes?', 'Modern welfare standards require an enclosure length equal to or greater than the snake''s total body length (e.g. 48 × 24 × 24 inches for a 4 ft snake). The snake must be able to stretch out fully along one wall.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_800', 'Why should tortoises NOT be kept in glass tanks?', 'Tortoises do not understand the concept of transparent glass. They will continuously pace, scrape, and ram against the glass trying to walk through, causing chronic stress and injury. Open-top wooden tortoise tables are recommended.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_801', 'Do arboreal geckos require vertical height over floor space?', 'Yes. Species like Crested Geckos, Gargoyle Geckos, and Day Geckos prioritize vertical climbing height. An adult Crested Gecko requires a minimum of 18 × 18 × 36 inches (or 24 × 18 × 24 inches) with vertical cork branches and canopy vines.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_802', 'How do I calculate enclosure volume in gallons from dimensions?', 'Multiply Length × Width × Height (in inches) and divide the total by 231 cubic inches per US gallon. For example, a 48 × 24 × 24 in tank = 27,648 ÷ 231 ≈ 120 Gallons.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_803', 'How many hides should an enclosure have?', 'Every terrestrial and semi-arboreal reptile enclosure must have a minimum of 3 hides: one on the warm basking side, one on the cool retreat side, and an enclosed humid hide packed with damp sphagnum moss for shedding.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_804', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-enclosure-size-calculator_805', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_806', 'Why is UVB light essential for captive reptiles?', 'UVB radiation (290–320 nm) converts provitamin D3 in the reptile''s skin into active Vitamin D3, which is required for gut calcium absorption. Without UVB, reptiles develop Metabolic Bone Disease (MBD), causing soft bones, tremors, fractures, and death.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_807', 'Does glass or acrylic block UVB radiation?', 'Yes. Standard glass, acrylic, and clear plastics block virtually 100% of UVB rays. Never place a UVB bulb outside a glass window or glass tank top, as your pet will receive zero ultraviolet benefit.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_808', 'How much UVB is blocked by a wire mesh screen top?', 'Standard woven wire mesh tops block 30% to 35% of UVB output, while fine micro-mesh screens can block 45% to 50%. You must position the bulb closer or use a higher output tube (e.g. 10.0 / 12% instead of 5.0 / 6%) when mounting over mesh.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_809', 'What is the Ferguson Zone system?', 'The Ferguson Zone classification groups reptiles by their wild basking habits: Zone 1 (0.0–0.7 UVI, shade dwellers like leopard geckos), Zone 2 (0.7–1.0 UVI, partial sun), Zone 3 (1.0–2.6 UVI, open sun baskers like bearded dragons), and Zone 4 (2.6–8.0 UVI, intense midday baskers like Uromastyx).', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_810', 'Why are T5-HO linear tubes superior to compact/coil bulbs?', 'Linear T5-HO fluorescent tubes provide a wide, uniform, continuous gradient of UVB across the basking zone. Compact/coil screw-in bulbs project a narrow cone of light with dangerous high-UV hotspots in the center and rapid decay within 3–4 months.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_811', 'How often should UVB fluorescent bulbs be replaced?', 'Linear T5-HO bulbs should be replaced every 10–12 months, and older T8 bulbs every 6 months. Even though the bulb still emits visible light, the internal phosphors that generate UVB degrade over time.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_812', 'How do I accurately measure UVB output in my terrarium?', 'The gold standard scientific tool is a Solarmeter Model 6.5R Ultraviolet Index (UVI) Radiometer. It measures biologically active UVB right at your pet''s basking perch.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_813', 'Do nocturnal reptiles like leopard geckos and ball pythons need UVB?', 'While nocturnal species can survive on dietary Vitamin D3 powder alone, peer-reviewed studies show that low-level Ferguson Zone 1 UVB (e.g. Arcadia ShadeDweller) significantly improves immune response, natural circadian rhythm, color pigmentation, and voluntary activity.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_814', 'Can a reptile get a UVB burn or eye damage from a bulb placed too close?', 'Yes. If a high-output UVB tube is mounted closer than the minimum safe distance without adequate shelter, the intense radiation can cause photokeratoconjunctivitis (eye inflammation/blindness) and skin blistering.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_815', 'Should the UVB light cover the entire enclosure?', 'No. The UVB tube should span approximately ½ to ⅔ the length of the enclosure, aligned directly over the warm basking zone. This creates a natural UV gradient, allowing your reptile to retreat into full shade when desired.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_816', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-distance-guide_817', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-uvb-distance-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_818', 'What is the golden rule for feeder insect size?', 'The feeder insect''s length should never be wider than the space between your reptile''s eyes. Feeding insects that are too large can cause choking, regurgitation, gut impaction, or temporary hind-leg paralysis from pressure on the spinal nerve.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_819', 'Why are Dubia Roaches considered superior to crickets?', 'Dubia roaches have a higher meat-to-shell ratio (21.4% protein), lower fat, soft exoskeletons, cannot jump or bite reptiles, are odorless, and have a significantly longer shelf life than crickets.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_820', 'What is gut-loading and why is it mandatory?', 'Gut-loading is the practice of feeding nutritious vegetables (carrots, squash, collard greens) and high-calcium commercial gutload chow to feeder insects for 24–48 hours before offering them to your reptile. Your reptile absorbs whatever is inside the insect''s digestive tract.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_821', 'Why should mealworms and superworms be fed in moderation?', 'Mealworms and superworms have thick exoskeletons made of chitin and higher crude fat content. Young reptiles with small digestive tracts can struggle to break down heavy chitin, leading to digestive impaction.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_822', 'Which feeder insect has the highest natural calcium content?', 'Black Soldier Fly Larvae (sold as NutriGrubs, Calciworms, or Phoenix Worms) have an extraordinary natural calcium-to-phosphorus ratio of 1.5:1, meaning they do not require calcium powder dusting before feeding.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_823', 'How do I choose the right rodent size for my pet snake?', 'Weigh your snake on a digital kitchen scale in grams. For growing juveniles, choose a frozen-thawed mouse or rat weighing 10% to 15% of the snake''s body weight. For adults, choose a prey item weighing 5% to 8% of body weight (roughly equal to the snake''s widest body diameter).', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_824', 'Why should I feed frozen-thawed rodents instead of live prey?', 'Live rodents possess sharp teeth and powerful jaws. A frightened or defensive live rat can inflict severe, disfiguring, or fatal bite wounds on a captive snake within seconds. Frozen-thawed rodents are 100% safe and free of parasites.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_825', 'When are hornworms beneficial for reptiles?', 'Hornworms (Goliath worms) consist of approximately 85% water and have soft bodies with high calcium. They are ideal for boosting hydration in dehydrated reptiles, helping gravid females, and stimulating reluctant eaters.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_826', 'Can I feed wild-caught insects from my garden?', 'Never feed wild insects. Garden insects routinely carry lethal chemical pesticides, herbicides, and internal parasites that can kill captive reptiles.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_827', 'How do I properly thaw and warm frozen rodents for snakes?', 'Thaw the rodent in the refrigerator overnight or sealed in a ziplock bag in cold water for 1–2 hours. Never microwave rodents. Before feeding, submerge the sealed bag in warm water (105–110°F) for 10 minutes so the head reads ~100°F on an infrared thermometer.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_828', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-feeder-size-calculator_829', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-feeder-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_830', 'How often should I feed my snake based on age?', 'Hatchlings and babies eat every 5–7 days; growing juveniles (100–500g) eat every 7–10 days; sub-adults eat every 10–14 days; and mature adults eat every 14–21 days (or 3–4 weeks for large boas and pythons).', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_831', 'Why did my ball python suddenly refuse food?', 'Common causes of food refusal include: opaque ''blue'' shedding phase, enclosure temperature too low (basking spot must be 88–92°F), prey not warmed to body temperature (~100°F), winter seasonal fasting/brumation, or handling too close to feeding time.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_832', 'How long can a healthy adult snake go without eating?', 'A healthy adult snake with good body condition can safely fast for several weeks to months without harm, provided they have clean drinking water and do not lose more than 10% of their body weight.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_833', 'Should I feed my snake inside its enclosure or in a separate tub?', 'Feed your snake inside its main enclosure. Moving a snake to a separate feeding tub causes stress, increases the risk of defensive bites, and handling the snake immediately after eating frequently triggers dangerous regurgitation.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_834', 'How long should I wait before handling my snake after a meal?', 'Wait a strict minimum of 48 hours after feeding before handling your snake. Handling too soon can cause discomfort, stress, and regurgitation of the undigested meal.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_835', 'What should I do if my snake regurgitates its meal?', 'Do NOT attempt to feed again immediately. Regurgitation burns the esophagus with stomach acid. Wait a full 14 days with zero handling and fresh water to allow the digestive lining to heal, then offer a meal half the normal size.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_836', 'Why are rats better than mice for ball pythons?', 'Rats have higher protein content, better bone-to-fat ratios, and come in sizes that grow with the snake. An adult ball python needs 1 small rat rather than having to hunt multiple adult mice, which causes undue feeding stress.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_837', 'What temperature should a thawed feeder rodent be before offering?', 'Warm the rodent''s head to 98–102°F (37–39°C) using warm water in a sealed plastic bag or a hair dryer. Pythons and boas use heat-sensing labial pit organs to target warm prey.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_838', 'Is power-feeding a young snake safe to make it grow faster?', 'No. Power-feeding causes rapid organ growth, severe obesity, hepatic lipidosis (fatty liver disease), and shortens the snake''s natural lifespan by half. A steady, measured growth schedule is far healthier.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_839', 'Can snakes eat fish or eggs?', 'Garter snakes naturally eat whole fish fillets (thiaminase-free) and nightcrawlers. African Egg-Eating Snakes eat fresh quail/finch eggs exclusively. Colubrids like kingsnakes and corn snakes occasionally eat bird eggs, but rodents remain the balanced staple.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_840', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-feeding-schedule_841', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'snake-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_842', 'What is the 10-gallons-per-inch rule for aquatic turtles?', 'The rule states that for every 1 inch of your turtle''s Straight Carapace Length (shell length from front to back, excluding curve), you must provide a minimum of 10 US gallons of swimming water (e.g. an 8-inch adult slider requires an 80–100 gallon tank).', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_843', 'Why do turtle tanks require oversized filtration systems?', 'Turtles produce significantly more solid and dissolved organic waste than fish of equal size. You must use a heavy-duty canister filter rated for 3× to 4× your tank''s actual water volume (e.g. a 75-gallon tank needs a filter rated for 250–300 gallons with high GPH flow).', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_844', 'What are the requirements for a proper turtle basking dock?', 'The basking platform must allow the turtle to climb out of the water and get 100% dry on both its top shell (carapace) and bottom shell (plastron). Complete drying under 90–95°F heat and UVB prevents fungal shell rot and bacterial infections.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_845', 'What water temperature do red-eared sliders and painted turtles need?', 'Adult aquatic turtles thrive in water temperatures between 75°F and 80°F (24–27°C). Hatchlings and juveniles require slightly warmer water around 78°F to 82°F (26–28°C) maintained with a submersible heater with a plastic heater guard.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_846', 'Can you keep two or more turtles in the same tank?', 'Cohabitation is risky. Aquatic turtles are solitary and territorial. While adding 5 gallons per inch of shell accommodates the bioload, cohoused turtles frequently fight, bite legs and tails, and stress each other. Provide multiple basking spots or separate tanks.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_847', 'Are gravel and small stones safe as turtle substrate?', 'Never use small aquarium gravel. Turtles are curious foragers and routinely swallow small gravel, resulting in fatal intestinal impaction and surgery. Use fine river sand, large smooth river rocks (larger than the turtle''s head), or a bare-bottom glass tank.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_848', 'How often should I do water changes in a turtle tank?', 'Perform a 25% to 30% water change weekly using a gravel vacuum siphon to remove bottom debris, and replace with dechlorinated tap water. Test parameters monthly for ammonia (must be 0 ppm), nitrites (0 ppm), and nitrates (<20 ppm).', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_849', 'What is the difference between a turtle tank and a tortoise table?', 'Aquatic turtles (Sliders, Map, Musk) swim in deep water with a dry basking dock. Terrestrial tortoises (Russian, Greek, Sulcata) cannot swim and require open-top wooden tortoise tables with deep digging soil and a shallow soaking dish.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_850', 'Why is a water heater guard essential in turtle aquariums?', 'Turtles can ram heavy glass heaters into tank corners or bite exposed power cords. A durable plastic heater guard protects the glass from shattering and prevents severe contact burns on the turtle''s skin.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_851', 'How fast do baby turtles grow into full adult tank sizes?', 'Most aquatic turtles grow rapidly during their first 2–3 years, reaching 4–6 inches by year two and full adult size (8–12 inches) by year four. Buying an adult-sized 75–120 gallon tank upfront saves hundreds of dollars in intermediate upgrades.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_852', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-tank-calculator_853', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'turtle-tank-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-name-generator_854', 'Can reptiles learn or respond to their names?', 'While reptiles do not recognize names like dogs, many lizards, monitors, and tortoises learn to associate human presence, specific vocal tones, and feeding routines with their caregivers.', 'reptiles', 'tool', 'reptile-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-name-generator_855', 'What are popular themes for naming pet reptiles?', 'Mythology (Loki, Medusa, Draco), gemstone and scale colors (Emerald, Jasper, Onyx), and prehistoric names (Rex, Titan, Yoshi) are among the most popular.', 'reptiles', 'tool', 'reptile-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-name-generator_856', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-name-generator_857', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_858', 'How much hay does a 1,000 lb (450 kg) horse need per day?', 'A 1,000 lb horse requires a minimum of 1.5% to 2.0% of its body weight in dry forage daily, which equals 15 to 20 lbs (6.8 to 9.1 kg) of quality grass hay per day (approx. 3 to 4 standard 5 lb flakes), adjusted upward for cold weather or hard work.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_859', 'Why is feeding large grain meals dangerous for horses?', 'A horse''s stomach holds only 2 to 4 gallons. Feeding more than 5 lbs of grain at once overloads the stomach, pushing undigested starch into the hindgut. In the cecum, starch ferments into lactic acid (hindgut acidosis), releasing endotoxins that trigger fatal laminitis (founder) and severe colic.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_860', 'What is the difference between grass hay (Timothy/Orchard) and legume hay (Alfalfa)?', 'Grass hays (Timothy, Orchard, Coastal Bermuda) provide ideal moderate protein (8–10%), balanced calcium-to-phosphorus ratios, and high fiber for maintenance. Alfalfa is a legume rich in high protein (16–20%) and elevated calcium, making it excellent for working sport horses, lactating mares, and ulcer-prone horses, but too rich for easy keepers.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_861', 'Why do horses develop gastric ulcers when fed twice daily?', 'Unlike humans who secrete stomach acid only when eating, horses secrete hydrochloric acid continuously 24/7. When a horse goes without hay for more than 4 to 6 hours, acid splashes against the unprotected upper stomach lining, causing Equine Gastric Ulcer Syndrome (EGUS).', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_862', 'How many flakes of hay are in a 50 lb bale?', 'A typical two-string 50 lb bale contains between 10 and 12 flakes, with each flake weighing approximately 4 to 5 lbs. However, flake thickness varies widely, so always weigh your hay flakes with a hanging scale.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_863', 'What is a ration balancer and when should it be fed?', 'A ration balancer is a low-calorie, concentrated pellet containing essential amino acids (lysine, methionine), trace minerals (copper, zinc, selenium), and vitamins without excess sugars and starch. It is ideal for ''easy keepers'' who maintain weight on hay alone but lack micronutrients.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_864', 'Can horses eat freshly mowed lawn clippings?', 'NEVER feed lawnmower clippings to horses. Clippings ferment rapidly in warm air, creating toxic heat and gases that cause fatal gas colic, choke from rapid bolting, and lethal botulism from Clostridium bacteria.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_865', 'How do I transition my horse to a new brand of feed or hay?', 'Transition gradually over 10 to 14 days. Mix 75% old feed with 25% new feed for 3–4 days, then 50/50 for 3–4 days, then 25% old and 75% new for 3–4 days before switching completely to avoid shocking hindgut microflora.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_866', 'Why do horses need free-choice plain salt available 24/7?', 'Forage contains virtually zero sodium. Horses require a minimum of 10 to 12 grams of sodium daily for cellular nerve transmission and osmotic thirst drive. Always provide a plain white salt block or add 1–2 tablespoons of loose salt to their feed.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-feed-calculator_867', 'What should I feed a senior horse with poor teeth (wave mouth/smooth mouth)?', 'Senior horses with missing or smooth molars cannot grind long-stem hay. Feed complete soaked senior feeds (which contain built-in digestible fiber), soaked beet pulp shreds, and soaked alfalfa/timothy hay cubes or pellets.', 'horses', 'tool', 'horse-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_868', 'How much water does an average horse drink in 24 hours?', 'An average 1,000 lb (450 kg) horse drinks 8 to 12 gallons (30 to 45 liters) of water daily at resting maintenance in temperate weather, increasing to 15 to 25+ gallons during hot summer weather or intense exercise.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_869', 'Why do horses get impaction colic during cold winter weather?', 'When water freezes or becomes ice-cold (<40°F), horses drink significantly less. Combined with a switch to dry hay (which has only 10% moisture compared to 80% in pasture grass), dry feed gets lodged in the narrow pelvic flexure of the colon, forming a dangerous impaction colic.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_870', 'What is the best water temperature for horses?', 'Horses drink the most water when it is maintained between 45°F and 65°F (7°C to 18°C). Using insulated, heated water buckets or floating de-icers in winter keeps water in this ideal temperature range.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_871', 'How do I perform a skin-pinch test to check for equine dehydration?', 'Pinch a fold of skin on the point of the horse''s shoulder or neck and release it. In a well-hydrated horse, the skin snaps back flat in under 1 second. If the fold lingers for 2 to 4 seconds (skin tenting), the horse is moderately to severely dehydrated.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_872', 'How does equine sweat differ from human sweat?', 'Equine sweat is hypertonic—it contains higher concentrations of sodium, potassium, and chloride than the horse''s own blood serum. This means sweating heavily rapidly depletes critical electrolytes, requiring targeted equine electrolyte supplementation.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_873', 'How can I encourage a horse that refuses to drink while traveling to drink?', 'Add a splash of apple juice or peppermint flavoring to the water bucket, soak their hay, offer warm soaked beet pulp mash, or bring familiar water from your home barn in clean water containers.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_874', 'Should I let a hot, sweaty horse drink water immediately after riding?', 'Yes! The outdated myth that hot horses must not drink water has been thoroughly debunked by veterinary research. Denying a hot horse water delays rehydration. Allow hot horses to drink small, frequent amounts (1–2 gallons every few minutes) of lukewarm water while walking them out.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_875', 'How much water does a lactating broodmare require?', 'A lactating mare producing 3 to 4 gallons of milk daily requires 18 to 25+ gallons (70–95 liters) of fresh water every day to support milk synthesis and prevent dehydration.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_876', 'Are automatic waterers better than traditional buckets?', 'Automatic waterers provide continuous fresh water, but make it impossible to monitor exact daily fluid intake. If using automatic waterers, inspect and clean the bowls daily and check meters to ensure the valves are functioning.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-water-intake-calculator_877', 'When should I give my horse electrolytes instead of plain salt?', 'Give balanced electrolytes during prolonged hard workouts (endurance, cross-country, polo) or extreme heat when the horse is sweating heavily. Always ensure plain fresh water is available alongside electrolyte water.', 'horses', 'tool', 'horse-water-intake-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_878', 'What is the average lifespan of a domestic horse?', 'With modern veterinary dentistry, targeted deworming, and senior nutrition, domestic horses live an average of 25 to 30 years. Ponies frequently reach 35 to 40+ years, while giant draft breeds average 18 to 22 years.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_879', 'At what age is a horse officially considered a senior?', 'Veterinarians generally classify horses aged 15 and older as seniors, and horses aged 20 and older as geriatric, recommending twice-yearly wellness and dental checkups.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_880', 'Why do older horses need their teeth floated more frequently?', 'Equine teeth continuously erupt throughout life. By age 18 to 22, the reserve crowns wear down, creating sharp enamel hooks, step mouth, and wave mouth that lacerate cheeks and prevent thorough hay chewing (''quidding'').', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_881', 'What is Cushing''s Disease (PPID) in senior horses?', 'PPID (Pituitary Pars Intermedia Dysfunction) is an endocrine disorder common in horses over 15. It causes excessive ACTH production, leading to a long curly coat that fails to shed (hypertrichosis), muscle wasting along the topline, chronic laminitis, and immune suppression.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_882', 'How can I tell if a senior horse is having trouble chewing hay?', 'Watch for ''quidding''—spitting out wads of partially chewed, soggy hay balls. Other signs include weight loss, undigested long hay fibers in manure, bad breath, and slow, painful eating.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_883', 'What was the oldest horse ever recorded in history?', 'The oldest verified horse in recorded history was an English barge horse named ''Old Billy'', who was born in 1760 and lived to the extraordinary age of 62 years.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_884', 'Why do ponies live significantly longer than draft horses?', 'Ponies carry less body mass, placing significantly lower mechanical strain on their joints, tendons, and cardiovascular system. Draft horses experience accelerated cellular growth and heavier joint wear.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_885', 'How should the diet of a geriatric horse with missing teeth be modified?', 'Replace long-stem dry hay with soaked complete senior feeds, soaked alfalfa/timothy hay cubes or pellets, and soaked unmolassed beet pulp shreds to ensure adequate calorie and fiber intake without choking.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_886', 'What is the Galvayne''s Groove on a horse''s tooth and how does it determine age?', 'Galvayne''s Groove is a dark longitudinal groove on the upper corner incisor. It appears at the gumline around age 10, reaches halfway down at age 15, extends the full length of the tooth at age 20, and recedes completely by age 30.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-age-calculator_887', 'Can senior horses continue to be ridden and exercised?', 'Yes! Consistent, light to moderate exercise (trail riding, walking, gentle dressage) maintains muscle tone, stimulates joint synovial fluid circulation, and supports mental wellbeing in sound senior horses.', 'horses', 'tool', 'horse-age-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_888', 'What is the ideal Henneke Body Condition Score for a horse?', 'A score of BCS 5 (Moderate) is the universal veterinary ideal for most pleasure and performance horses. Broodmares entering winter can safely be a BCS 6, while racehorses in hard training may sit at a BCS 4.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_889', 'Why is a long winter coat misleading when scoring horse condition?', 'A thick winter hair coat easily hides severe weight loss and prominent ribs visually. True Henneke scoring requires hands-on tactile palpation across all six anatomical reference points.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_890', 'What is a ''cresty neck'' and why is it dangerous?', 'A cresty neck is a thick, hardened accumulation of fat along the upper crest of the neck. It is a major clinical marker of Equine Metabolic Syndrome (EMS) and insulin resistance, placing the horse at extreme risk for fatal pasture laminitis (founder).', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_891', 'How do I help an overweight horse (BCS 7–8) lose weight safely?', 'Eliminate all sweet feeds and grain concentrates. Feed tested low-sugar grass hay (NSC < 10%) at 1.5% of target body weight in slow-feed hay nets, use a grazing muzzle during turnout, add a low-calorie ration balancer for minerals, and increase daily exercise.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_892', 'Why can''t I just starve an obese horse to lose weight quickly?', 'Severe calorie deprivation in equines triggers hyperlipemia—a life-threatening crisis where massive amounts of stored body fat mobilize into the bloodstream, overwhelming the liver and leading to acute liver failure.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_893', 'How do I safely put weight on a thin horse (BCS 2–3)?', 'Have a vet check teeth and fecal egg counts first. Provide unlimited quality grass hay supplemented with alfalfa, add healthy fats (vegetable oil or stabilized rice bran up to 1–2 cups daily), and feed soaked beet pulp without overloading the stomach with grain.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_894', 'What is a ''hay belly'' and does it mean my horse is fat?', 'A hay belly is a distended, dropped lower abdomen caused by the weight of high-fiber, low-protein forage fermenting in the large cecum combined with weak abdominal muscles. A horse can have a large hay belly while having thin ribs and a low BCS score.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_895', 'How often should I evaluate my horse''s Body Condition Score?', 'Score your horse every 30 days. Regular monthly scoring allows you to detect subtle weight trends before severe obesity or emaciation occurs, particularly during seasonal pasture changes.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_896', 'What is the difference between muscle topline and fat deposition?', 'Muscle along the topline feels firm, smooth, and toned across the withers, loin, and croup. Fat feels spongy, soft, or greasy, and creates a distinct gutter crease down the spine or uneven bulging mounds at the tailhead.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-body-condition-score_897', 'What is the Cresty Neck Score (CNS)?', 'The Cresty Neck Score is a specialized 0-to-5 grading system developed specifically to quantify neck fat: 0 is no visual crest, 3 is an enlarged crest with fat filling the hands, and 5 is a massive crest that permanently flops over to one side.', 'horses', 'tool', 'horse-body-condition-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_898', 'Do horses really recognize and learn their own names?', 'Yes! Horses have acute hearing and strong associative learning. When a barn name is consistently paired with positive reinforcement (scratches on the withers, grooming, or treats), horses will perk their ears, turn their heads, and walk to the pasture gate when called.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_899', 'What is the difference between a registered show name and a barn name?', 'A registered show name is an official multi-word title registered with breed organizations (e.g., The Jockey Club or AQHA) reflecting pedigree. A barn name is the practical 1- or 2-syllable nickname used daily around the stable.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_900', 'What are the naming rules for Thoroughbred racehorses?', 'The Jockey Club enforces strict rules: names must not exceed 18 characters (including spaces), cannot duplicate active names, cannot use names of famous racetracks or living people without permission, and cannot be commercially branded.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_901', 'Why do European Warmbloods share the first letter of their sire''s name?', 'Registries like the Hanoverian, Holsteiner, and KWPN traditionally require the foal''s registered name to start with the same initial letter as its sire (or dam in certain dam lines) to track paternal lineage across generations.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_902', 'What types of barn names are easiest for horses to understand?', 'Names with 1 or 2 distinct syllables containing crisp consonant sounds (like ''Bandit'', ''Jasper'', ''Rory'', or ''Bella'') are recognized fastest by equines.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_903', 'Is it bad luck to change a horse''s barn name?', 'While old equestrian superstition suggests changing a horse''s name brings bad luck, horses adapt seamlessly to new barn names within 1 to 2 weeks through positive association.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_904', 'How can I combine a sire and dam name into a creative show name?', 'Take prominent words, syllables, or concepts from both parents. For example, a foal by ''High Brow Cat'' out of ''Autumn Boon'' could be named ''Autumn Cat'' or ''Boon Brow Royalty''.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_905', 'Why do horses respond to specific vocal tones rather than just words?', 'Horses are highly sensitive to pitch, inflection, and emotional cadence. A calm, low, rhythmic tone soothes an anxious horse (''whoa''), while a sharp, energetic rising tone encourages forward motion (''trot'').', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_906', 'What are great names for black or dark bay horses?', 'Classic names for dark equines include Onyx, Midnight, Shadow, Raven, Eclipse, Obsidian, Black Jack, and Knight.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-name-generator_907', 'What are popular names for golden Palomino or Chestnut horses?', 'Popular golden/red names include Butterscotch, Copper, Honey, Sundance, Goldie, Cinnamon, Blaze, Amber, and Nugget.', 'horses', 'tool', 'horse-name-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_908', 'How many square feet of coop space does a chicken need?', 'Standard laying hens require a minimum of 4 square feet of indoor coop floor space per bird, plus 10 square feet per bird in the outdoor run. Heavy dual-purpose breeds (Brahmas, Orpingtons) need 5 to 6 sq ft inside and 15 sq ft outside.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_909', 'Why is hexagonal chicken wire dangerous for chicken coops?', 'Hexagonal chicken wire is weak and easily torn apart by raccoons, dogs, and foxes. Furthermore, rats, weasels, and snakes easily slip through 1-inch mesh. Always use 1/2-inch galvanized hardware cloth.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_910', 'What is an anti-digging predator apron and how do I install it?', 'A predator apron is a barrier of 1/2-inch hardware cloth attached to the bottom of the coop/run that extends 12 to 18 inches horizontally outward along the ground, buried just beneath the grass sod to stop digging foxes and dogs.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_911', 'Why should roosting bars be made of 2x4 wood with the wide side flat?', 'Heavy chickens sleep flat on their footpads rather than curling toes around narrow dowels. A 2x4 with the wide 4-inch side flat allows hens to cover their feet with breast feathers in winter, preventing frostbite and bumblefoot.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_912', 'How much ventilation does a backyard chicken coop require?', 'Provide a minimum of 1 square foot of upper ventilation for every 10 square feet of coop floor space. Vents must be located high above the roosting bars to exhaust warm moisture and ammonia without creating drafty winds on sleeping birds.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_913', 'Why do chickens peck each other bloody in small coops?', 'Overcrowding prevents subordinate hens from retreating from dominant flock members. Frustration and spatial competition quickly escalate into feather pecking, skin tearing, and fatal cloacal cannibalism (vent picking).', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_914', 'How high off the ground should chicken roosting bars be placed?', 'Roosting bars should be installed 2 to 4 feet off the coop floor, and always 12 to 18 inches higher than the nesting boxes. Provide a ladder ramp for heavy breeds so they do not injure leg joints when jumping down.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_915', 'What is the best coop floor bedding material?', 'Kiln-dried, dust-extracted medium pine shavings or chopped hemp bedding are best. Avoid cedar shavings (toxic aromatic plicatic acid damages avian lungs) and fine sawdust (causes respiratory irritation).', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_916', 'Can chickens stay inside the coop all winter?', 'Chickens handle sub-zero cold well if the coop is dry and draft-free. However, they need access to a snow-cleared, covered outdoor run during daylight hours to prevent boredom and coop cabin fever.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-coop-size-calculator_917', 'What latch should I install on coop doors to stop raccoons?', 'Raccoons have dexterous paws capable of opening simple slide latches and hooks. Install two-step predator latches, spring-loaded carabiners, or padlock hasps on all access doors.', 'farm', 'tool', 'chicken-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-egg-production-tracker_918', 'Why did my hen stop laying?', 'Molt, decreased daylight, stress, or age. Two-year-olds slow noticeably.', 'farm', 'tool', 'chicken-egg-production-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-egg-production-tracker_919', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'farm', 'tool', 'chicken-egg-production-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-egg-production-tracker_920', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'farm', 'tool', 'chicken-egg-production-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_921', 'How much hay does an adult goat eat per day?', 'An adult goat eats approximately 3% to 4% of its body weight in dry hay daily. For a 150 lb goat, this equals 4.5 to 6 lbs (2.0 to 2.7 kg) of quality grass or alfalfa hay per day (about 1 to 1.5 standard flakes).', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_922', 'Why should grain NEVER be fed to castrated male goats (wethers)?', 'Grain is high in phosphorus, which causes urinary calculi (bladder stones). In male goats, stones get trapped in the narrow urethral process, blocking urination and causing fatal bladder rupture (''water belly''). Wethers should eat forage only.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_923', 'Why is copper essential for goats but lethal to sheep?', 'Goats require high levels of copper (10–80 ppm) for melanin pigment synthesis, nervous system health, and parasite resistance. Sheep cannot excrete copper efficiently and suffer fatal copper toxicity from goat feed.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_924', 'What is goat bloat and how is it treated?', 'Bloat is an emergency accumulation of gas or frothy foam in the rumen caused by gorging on lush clover, wet alfalfa, or stolen grain. Treat mild cases with drenching vegetable oil or Therabloat and call a vet immediately.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_925', 'What is the difference between grass hay and alfalfa for goats?', 'Grass hay (Timothy, Orchard) provides moderate protein (8–10%) and balanced minerals, making it ideal for wethers and dry does. Alfalfa is a legume high in protein (16–20%) and calcium, essential for lactating dairy does.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_926', 'Can goats eat garden weeds and poison ivy?', 'Yes! Goats are natural browsers that love eating woody brush, brambles, nettles, blackberry thorns, and poison ivy (they are immune to urushiol). However, ornamental plants like azaleas, rhododendrons, and yew are deadly toxic.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_927', 'How much grain does a milking dairy goat need daily?', 'Feed roughly 0.5 lbs of 16% dairy ration for every 3 lbs (approx. 1.5 quarts) of milk the doe produces daily, split into morning and evening milking stanchion feedings.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_928', 'Why should goats have loose minerals instead of mineral blocks?', 'Goats have soft, sensitive tongues designed for browsing leaves. They cannot lick hard cattle mineral blocks effectively to get enough copper and selenium. Always offer loose, weather-protected goat minerals.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_929', 'What is enterotoxemia (overeating disease) in goats?', 'Enterotoxemia is a fatal poisoning caused by Clostridium perfringens type C and D bacteria proliferating in the gut when goats overeat grain or lush forage. Vaccinate all goats annually with the CDT vaccine to prevent it.', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-feed-calculator_930', 'Why do goats need baking soda (sodium bicarbonate)?', 'Free-choice baking soda acts as a natural rumen antacid. If a goat experiences mild rumen acidosis from dietary changes, it will voluntarily consume baking soda to buffer its rumen pH back to safe levels (6.2–6.8).', 'farm', 'tool', 'goat-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_931', 'How deep does a backyard duck pond need to be?', 'A duck pond should be 18 to 24 inches (45 to 60 cm) deep. This depth allows ducks to dive, barrel-roll, fully submerge their heads to clean their nares, and mate naturally with buoyancy.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_932', 'Why do standard aquarium and pool filters fail in duck ponds?', 'Ducks produce massive amounts of high-nitrogen waste, shed waterproof down feathers, and shovel pounds of mud into the water. Standard pool cartridges and sponge filters clog completely within 24 to 48 hours.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_933', 'How often should a non-filtered duck pool be drained and refilled?', 'A standard plastic stock tank or kiddie pool shared by 4 to 6 ducks must be drained, scrubbed, and refilled every 1 to 2 days to prevent dangerous bacterial blooms and foul odors.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_934', 'Can young ducklings swim in a deep duck pond?', 'NO! Ducklings under 4 to 5 weeks old raised in a brooder do not have waterproof oil glands and lack insulating adult feathers. In deep water, their down saturates, causing rapid hypothermia, exhaustion, and drowning. Provide shallow 1-inch water only.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_935', 'How do I build an easy drain system for a duck stock tank?', 'Drill a hole in the bottom sidewall of a 100-gallon stock tank, install a 2-inch PVC bulkhead fitting with a commercial ball valve, and connect a 2-inch flexible hose to drain wastewater directly into garden beds.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_936', 'What is ''wet feather'' in ducks?', 'Wet feather is a condition where a duck''s feathers lose waterproofing due to a clogged preen gland, dirty water, or external parasites, causing water to soak directly to the skin and making the duck waterlogged and chilled.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_937', 'Why is duck pond wastewater so beneficial for vegetable gardens?', 'Duck pond water contains dissolved organic manure, nitrogen, phosphorus, potassium, and beneficial microbes, making it an exceptional organic liquid fertilizer for heavy-feeding garden crops (tomatoes, corn, squash).', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_938', 'How do I prevent duck pond banks from turning into a mud pit?', 'Surround the perimeter of the pond with 3 to 4 feet of washed river rock, concrete pavers, or gravel over geotextile landscape fabric to stop ducks from drilling holes with their bills in bare soil.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_939', 'Do ducks need a pond to lay eggs?', 'Ducks do not strictly require a swimming pond to lay eggs, but they must have deep water buckets (at least 6–8 inches deep) to submerge their entire heads daily to prevent eye infections and clear feed from their bills.', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-pond-size-calculator_940', 'What plants are safe to grow around a duck pond?', 'Safe, duck-friendly plants include water irises, cattails, rushes, duckweed, water lettuce, and hostas (ducks will eagerly eat duckweed and water lettuce as nutrient-rich green snacks).', 'farm', 'tool', 'duck-pond-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_941', 'Why is chocolate toxic to dogs?', 'Chocolate contains theobromine and caffeine (methylxanthines), which dogs metabolize very slowly. These compounds stimulate the central nervous system and heart, causing tremors, seizures, and heart failure.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_942', 'Which type of chocolate is the most dangerous for dogs?', 'Dry cocoa powder and unsweetened baker''s chocolate are the most dangerous, containing 8 to 15 times more theobromine per ounce than milk chocolate.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_943', 'How much milk chocolate is toxic to a 20 lb dog?', 'Ingesting as little as 4 to 6 ounces of milk chocolate can trigger moderate toxicity (vomiting, rapid heart rate) in a 20 lb dog, while less than 1 ounce of baker''s chocolate is toxic.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_944', 'What are the clinical symptoms of chocolate poisoning in dogs?', 'Symptoms appear within 6 to 12 hours: excessive thirst, panting, restlessness, vomiting, diarrhea, rapid heart rate (tachycardia), muscle tremors, seizures, and collapse.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_945', 'Is white chocolate toxic to dogs?', 'White chocolate contains virtually zero theobromine and will not cause methylxanthine poisoning. However, its high fat and sugar content can trigger severe, painful Pancreatitis.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_946', 'What should I do immediately if my dog eats chocolate?', 'Calculate the ingested amount and chocolate type, and call your veterinarian or the Pet Poison Helpline (855-764-7661) immediately. Do NOT wait for symptoms to appear!', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_947', 'Should I induce vomiting at home with hydrogen peroxide?', 'Never induce vomiting without veterinary instruction. Hydrogen peroxide can cause severe hemorrhagic gastritis. Taking your dog to an ER vet for IV apomorphine is safer and far more effective.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_948', 'How do veterinarians treat chocolate poisoning?', 'Veterinarians induce vomiting with IV apomorphine, administer activated charcoal to absorb toxins, place IV fluid lines to flush kidneys, and administer heart medications to control arrhythmias.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_949', 'Why do chocolate wrappers pose an additional danger?', 'Swallowed foil, cellophane, and plastic wrappers can clump together in the stomach or intestines, causing a mechanical intestinal obstruction requiring emergency surgery.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-chocolate-toxicity-calculator_950', 'Can a dog die from eating chocolate?', 'Yes. Severe chocolate toxicity causes cardiac arrhythmias, hyperthermia, and status epilepticus seizures leading to death if left untreated.', 'dogs', 'tool', 'dog-chocolate-toxicity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_951', 'What is the correct Benadryl (diphenhydramine) dosage for dogs?', 'The standard safe veterinary dosage is 1 mg per pound of body weight (2 to 4 mg/kg), given orally every 8 hours as needed (e.g., a 25 lb dog takes one 25 mg tablet).', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_952', 'What is Benadryl used for in dogs?', 'It treats acute insect stings (bee/wasp), allergic reactions (facial swelling, hives), vaccine reactions, seasonal itching, and mild car travel anxiety/motion sickness.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_953', 'Why is ''Benadryl-D'' (with decongestants) lethal to dogs?', 'Benadryl-D contains pseudoephedrine or phenylephrine, which causes fatal cardiovascular stimulation, extreme hypertension, seizures, and cardiac arrest in dogs.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_954', 'Can I give my dog liquid children''s Benadryl?', 'Check the ingredients carefully! Many liquid formulas contain Xylitol (birch bark sweetener) or alcohol, both of which are toxic and cause fatal liver failure in dogs.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_955', 'What are common side effects of Benadryl in dogs?', 'Mild drowsiness/sedation, dry mouth, slight urinary retention, and occasional mild stomach upset. Rarely, some dogs experience paradoxical agitation or excitability.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_956', 'How long does it take for Benadryl to start working?', 'Oral tablets take approximately 30 to 60 minutes to take effect, with peak antihistamine benefits lasting for 6 to 8 hours.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_957', 'When is Benadryl NOT enough for an allergic reaction?', 'If your dog experiences swelling around the throat, difficulty breathing, blue/pale gums, vomiting, or collapse, Benadryl is insufficient—seek immediate emergency vet care for IV steroids and epinephrine.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_958', 'Can I give Benadryl to a dog with glaucoma or heart disease?', 'Consult your vet first. Antihistamines can increase intraocular pressure in glaucoma patients and elevate heart rates in dogs with cardiovascular disease.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_959', 'Can Benadryl cure chronic allergic itching (atopic dermatitis) in dogs?', 'Benadryl is weak against chronic skin allergies because dog skin inflammation is driven by interleukin cytokines (IL-31) rather than histamine. Modern therapies like Apoquel or Cytopoint are far more effective.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-benadryl-dose-calculator_960', 'Can I give Benadryl to my pregnant or nursing dog?', 'Diphenhydramine crosses the placental barrier and enters mother''s milk. Consult a veterinary theriogenologist before administering to breeding females.', 'dogs', 'tool', 'dog-benadryl-dose-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_961', 'How is canine dehydration calculated clinically?', 'Dehydration deficit (mL) = Body Weight (kg) × (Dehydration % / 100) × 1000. For example, a 10 kg dog with 5% dehydration has a fluid deficit of 10 × 0.05 × 1000 = 500 mL.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_962', 'What is the standard maintenance fluid rate for dogs?', 'The standard canine maintenance fluid guideline is 60 mL/kg/day (approximately 2.5 mL/kg/hr), though individual requirements may vary by age, breed, and physical condition.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_963', 'What signs indicate fluid overload in recovering dogs?', 'Watch for serous nasal discharge, coughing, tachypnea (increased respiratory rate), pulmonary crackles, chemosis (swelling of the conjunctiva), restlessness, and rapid unexplained weight gain. Discontinue or reduce fluids immediately and alert the attending veterinarian.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_964', 'What is normal post-operative urine output for a dog?', 'Normal canine urine production on IV fluid support should be between 1.0 and 2.0 mL/kg/hour. Oliguria (< 1 mL/kg/hr) or anuria warrants prompt veterinary evaluation of renal perfusion and catheter patency.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_965', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_canine-fluid-therapy-calculator_966', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'dogs', 'tool', 'canine-fluid-therapy-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_967', 'What is the N+1 rule for cat litter boxes?', 'You must provide one litter box for every cat in your home, plus one extra (e.g., 3 boxes for 2 cats, 4 boxes for 3 cats) to prevent territorial conflict and eliminate accidents.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_968', 'Why shouldn''t multiple litter boxes be placed side-by-side?', 'Cats view side-by-side boxes as a single giant box. A single cat can guard that one location, preventing other cats from accessing a bathroom.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_969', 'How big should a cat''s litter box be?', 'The litter box must be at least 1.5 times the length of the cat from its nose to the base of its tail, allowing full 360-degree turning and comfortable digging.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_970', 'Why do cats prefer open, uncovered litter boxes?', 'Open boxes allow cats to see approaching threats, prevent foul ammonia odors from being trapped, and eliminate claustrophobia in larger cats.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_971', 'How often should litter boxes be scooped?', 'Scoop solid waste and urine clumps a minimum of 1 to 2 times daily. Clean boxes encourage consistent use and prevent inappropriate elimination on rugs.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_972', 'Where is the worst place to put a cat litter box?', 'Never put boxes next to loud appliances (washing machines/furnaces) that startle cats, or near food and water bowls (cats refuse to eliminate near feeding sites).', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_973', 'What adjustments should be made for an arthritic senior cat''s litter box?', 'Provide low-entry boxes (2 to 3 inches high) or cut an entryway into a storage bin so stiff senior cats can walk in without jumping over high plastic sides.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_974', 'What is Feline Idiopathic Cystitis (FIC) and how is it related to litter boxes?', 'FIC is painful bladder inflammation triggered by stress. Dirty boxes, box competition, or loud locations trigger acute bladder spasms and bloody urination.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_975', 'How do I stop my cat from peeing right outside the litter box?', 'Check for medical pain (UTI/arthritis), ensure the box is large enough, switch to unscented clumping clay litter, scoop daily, and remove any hoods.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-litter-box-count-calculator_976', 'How often should the entire litter box be dumped and scrubbed?', 'Completely empty, wash with hot water and unscented dish soap, and refill with fresh litter every 3 to 4 weeks to eliminate microscopic bacteria embedded in plastic.', 'cats', 'tool', 'cat-litter-box-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_977', 'Does a microchip have GPS tracking to locate my lost pet?', 'NO. A microchip is not a GPS tracker. It is a passive RFID chip that displays a unique 15-digit ID number when scanned by a vet or shelter scanner.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_978', 'What is the AAHA Universal Pet Microchip Lookup tool?', 'It is an online clearinghouse (petmicrochiplookup.org) where shelters and vets enter a scanned microchip number to find which registry database holds the owner''s contact info.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_979', 'How is a microchip implanted in a dog or cat?', 'A veterinarian injects the microchip subcutaneously between the shoulder blades using a sterile pre-loaded syringe. It takes seconds and feels like a routine vaccine injection.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_980', 'Does microchipping require anesthesia?', 'No anesthesia is required. Microchips can be implanted during a routine office visit, though many owners choose to have it done during spay/neuter surgery.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_981', 'What should I do if I move or change my phone number?', 'Log into your microchip registry account (HomeAgain, 24Petwatch, AKC Reunite) immediately and update your phone number, email, and home address.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_982', 'Can a microchip move or migrate inside a pet''s body?', 'Yes, microchips occasionally migrate under the skin toward the shoulder or chest. Have your veterinarian scan your pet''s entire body at every annual exam to verify chip location.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_983', 'What is an ISO-compliant 15-digit microchip?', 'ISO 11784/11785 is the global 134.2 kHz standard microchip required for international travel and recognized by universal scanners worldwide.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_984', 'Do microchips ever need battery replacements?', 'No. Microchips have no internal battery or moving parts. They remain dormant until energized by the radio waves of a handheld scanner, lasting for the pet''s entire life.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_985', 'Can someone steal my pet and reprogram the microchip?', 'No. The 15-digit ID number is permanently encoded in the microchip glass during manufacturing and cannot be altered. Legitimate registries require proof of ownership transfer.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-microchip-checklist_986', 'Why should my pet wear collar tags if they are already microchipped?', 'Collar tags allow a neighbor who finds your pet to call you immediately without needing to drive to a vet clinic or shelter to scan for a microchip.', 'general', 'tool', 'pet-microchip-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_987', 'Why does the grief of losing a pet often feel as intense as losing a human?', 'Pets provide unconditional love, constant physical companionship, and structured daily routines without human conflict, making their absence deeply disorienting.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_988', 'What is ''disenfranchised grief'' in pet loss?', 'Disenfranchised grief occurs when society fails to fully recognize or validate the depth of pet bereavement, leaving grieving pet owners feeling isolated or misunderstood.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_989', 'How do I know when it is the right time for humane euthanasia?', 'Veterinarians use the HHHHHMM Quality of Life scale (Hurt, Hunger, Hydration, Hygiene, Happiness, Mobility, More Good Days than Bad). When bad days outnumber good days, euthanasia prevents suffering.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_990', 'How can I help my surviving pets who are grieving the loss of their companion?', 'Maintain strict daily feeding and walking routines, provide extra gentle affection, and allow surviving pets to sniff the deceased pet''s body briefly to understand their absence.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_991', 'What are meaningful ways to memorialize a beloved pet?', 'Frame clay paw prints, create a memorial shadowbox with collar tags, plant a memorial tree, compile a photo album, or commission custom pet portrait art.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_992', 'How should I talk to young children about pet death?', 'Use clear, honest, compassionate language (e.g., ''he died peacefully''). Avoid confusing euphemisms like ''put to sleep'' or ''went to a farm'', which make children fear going to sleep.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_993', 'What is the Rainbow Bridge poem?', 'The Rainbow Bridge is a beloved prose poem written in the 1980s describing a peaceful, sunny meadow where departed pets are restored to youth and health, waiting to reunite with their owners.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_994', 'How long does normal pet bereavement last?', 'Grief has no fixed timeline. Acute grief typically softens over 2 to 6 months into comforting memories, though milestone days may trigger emotional waves for years.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_995', 'Is it normal to feel guilty after choosing euthanasia?', 'Yes. Guilt is a universal grief reaction where owners second-guess timing. Choosing euthanasia is the ultimate act of selfless compassion to relieve unmanageable pain.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-loss-memorial-generator_996', 'Where can I find free pet loss support groups and hotlines?', 'The Association for Pet Loss and Bereavement (aplb.org) and veterinary university hotlines (like Tufts and Cornell Pet Loss Hotlines) offer free counseling and support groups.', 'general', 'tool', 'pet-loss-memorial-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_997', 'What is a pet''s carbon pawprint?', 'A carbon pawprint measures the total greenhouse gas emissions (CO2e), land usage, and water consumption associated with raising, feeding, and caring for a companion animal.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_998', 'Why does pet food have a significant environmental impact?', 'Pet food relies heavily on animal-derived meat proteins (beef, poultry, lamb). Livestock agriculture requires vast land, water, and fossil fuel resources, generating methane and carbon emissions.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_999', 'Can dogs eat sustainable insect protein?', 'Yes! Black Soldier Fly Larvae (BSFL) protein is AAFCO-approved, hypoallergenic, rich in essential amino acids, and requires 90% less land and water than beef.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1000', 'Can cats be fed a vegetarian or vegan diet?', 'NO! Cats are obligate carnivores with mandatory biological requirements for animal-derived taurine, arachidonic acid, and preformed Vitamin A. Vegan diets cause fatal feline cardiomyopathy and blindness.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1001', 'What is the most environmentally friendly cat litter?', 'Natural plant-based litters made from sustainably harvested wood pellets, compressed wheat, recycled paper, or walnut shells are renewable, biodegradable, and avoid strip-mined sodium bentonite clay.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1002', 'Are all ''biodegradable'' dog poop bags truly eco-friendly?', 'No. Look for certified ASTM D6400 or EN 13432 compostable bags made from cornstarch (PLA). Bags labelled ''oxo-biodegradable'' simply break down into dangerous microplastics.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1003', 'How can I reduce my dog''s environmental footprint without harming their health?', 'Avoid overfeeding, choose poultry or sustainable fish over beef, use certified compostable poop bags, buy durable recycled gear, and spay/neuter to prevent pet overpopulation.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1004', 'Why does preventing pet obesity help the environment?', 'Overfeeding pets consumes excess agricultural resources unnecessarily. Keeping pets lean reduces agricultural demand and lowers lifetime medical manufacturing footprints.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1005', 'Should dog poop be flushed down the toilet?', 'Dog waste can be flushed if your municipal sewer allows it, but NEVER flush cat feces! Cat waste contains Toxoplasma gondii parasites, which survive municipal sewage treatment and kill marine wildlife (sea otters).', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-carbon-pawprint-calculator_1006', 'What is the Pet Sustainability Coalition (PSC)?', 'PSC (petsustainability.org) is an international non-profit industry organization that certifies pet companies meeting rigorous environmental, ethical supply chain, and sustainable packaging standards.', 'general', 'tool', 'pet-carbon-pawprint-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1007', 'How many poop bags does a dog use in a year?', 'A single dog using 2 to 3 bags per day consumes approximately 730 to 1,100 poop bags per year (roughly 60 to 90 bags per month).', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1008', 'Why is leaving dog poop on the grass harmful to the environment?', 'Dog waste is classified by the EPA as a hazardous pollutant. Rain washes millions of fecal bacteria and parasites from dog feces into local stormwater, contaminating urban waterways and lakes.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1009', 'What is the difference between ''biodegradable'' and ''certified compostable'' poop bags?', 'Biodegradable bags often just break down into microplastics. Certified compostable bags (ASTM D6400 / EN 13432 made from plant cornstarch) break down completely into organic humus within 90–180 days.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1010', 'Can dog feces be used as garden fertilizer for vegetables?', 'NEVER use dog waste on edible food crops! Dog feces contain dangerous zoonotic parasites (roundworms, hookworms, Salmonella) that survive in soil and can infect humans.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1011', 'How many times a day should a healthy adult dog poop?', 'A healthy adult dog on a quality balanced diet typically defecates 1 to 3 times daily, usually 20 to 30 minutes after eating a meal (the gastrocolic reflex).', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1012', 'What dangerous parasites are found in uncollected dog poop?', 'Roundworms (*Toxocara canis*), hookworms (*Ancylostoma*), whipworms, *Giardia*, *Coccidia*, and *Cryptosporidium*.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1013', 'Why do dogs on raw food diets produce smaller, chalky white poop?', 'Raw diets contain high levels of crushed bone (calcium carbonate) and high-digestibility meat protein, resulting in denser, chalkier stools that turn white in sunlight.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1014', 'Can dog poop bags be flushed down the toilet?', 'Only specialized flushable PVA (polyvinyl alcohol) bags can be flushed. Standard or compostable bags will clog plumbing and septic systems.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1015', 'How do I safely dispose of dog waste at home?', 'Bag waste and place it in your municipal outdoor trash bin, or install a dedicated in-ground mini septic pet waste digester (like Doggie Dooley) in your yard.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-poop-bag-calculator_1016', 'What causes a sudden increase in the volume of a dog''s stool?', 'Low-quality commercial foods packed with indigestible filler grains (corn, wheat bran, soy hulls) pass straight through the gut, producing massive daily stool volume.', 'dogs', 'tool', 'dog-poop-bag-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1017', 'How do I choose the correct crate size for my dog?', 'Measure your dog from nose tip to base of tail and add 2 to 4 inches for length; measure from floor to top of ears and add 2 to 4 inches for height. The dog must stand, turn, and lie flat comfortably.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1018', 'Why should a puppy''s crate NOT be too big during potty training?', 'If a crate is too large, the puppy will pee in one corner and sleep in the other dry corner. Use an adjustable divider panel to keep the space just large enough to sleep in.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1019', 'What is the maximum time a dog should stay in a crate during the day?', 'Adult dogs should never be crated for more than 4 to 6 continuous hours during the day. Young puppies can only hold their bladders for hours equal to their age in months (max 3–4 hrs).', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1020', 'Which type of crate is best: wire, plastic, or furniture-style?', 'Wire crates offer great airflow and folding portability; plastic airline crates provide secure den-like darkness and crash safety; wooden furniture crates blend into living room decor.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1021', 'How do I stop my puppy from crying in the crate at night?', 'Place the crate right next to your bed during the first week, cover it with a light breathable sheet, provide a warm heartbeat plush toy (Snuggle Puppy), and ensure the puppy emptied its bladder first.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1022', 'Should a dog wear a collar while inside a crate?', 'NEVER leave standard flat collars or choke chains on a crated dog! Collar tags can catch on wire mesh bars, causing fatal strangulation. Use a breakaway collar or remove collars entirely.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1023', 'How do I introduce a fearful adult dog to a crate?', 'Leave the door permanently propped open, feed all delicious meals inside the crate, toss high-value treats into the back, and never force or shove the dog inside.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1024', 'Can crating cure destructive separation anxiety?', 'No! Crating a dog with severe separation anxiety can cause panic, where the dog violently bites wire bars, breaks teeth, and shreds claws. Separation anxiety requires systematic desensitization.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1025', 'What bedding is safe for a puppy that chews everything in the crate?', 'Avoid fluffy fiber-filled beds that can be ripped open and swallowed (causing intestinal blockages). Use heavy-duty chew-proof ballistic nylon pads (like K9 Ballistics) or thick rubber mats.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-size-calculator_1026', 'Where is the best location in the house to place a dog crate?', 'Place the crate in a quiet corner of a frequently used family room (like the living room or bedroom) so the dog feels included in family life rather than isolated in a dark basement.', 'dogs', 'tool', 'dog-crate-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1027', 'How do I measure my dog''s neck for a collar?', 'Use a flexible cloth tape measure around the middle of your dog''s neck (where the collar naturally sits) and add 2 inches to ensure a comfortable fit.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1028', 'What is the ''two-finger rule'' for dog collar tightness?', 'You should be able to slide two flat fingers comfortably between the collar and your dog''s neck. If you can fit three or more, it''s too loose; if you can''t fit two, it''s too tight.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1029', 'What is a Martingale collar and when should it be used?', 'A Martingale collar tightens to a set limit when the leash is pulled, preventing dogs with narrow heads (Greyhounds) or fearful rescue dogs from backing out of their collar.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1030', 'Why should small dogs (Chihuahuas, Yorkies) wear a harness instead of a collar for walks?', 'Toy breeds have fragile, soft tracheal rings. Pulling on a neck collar easily crushes the windpipe, causing chronic coughing and permanent Tracheal Collapse.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1031', 'How often should I check the collar fit on a growing puppy?', 'Check your puppy''s collar fit weekly! Puppies grow rapidly, and tight collars can become painfully embedded in the skin within weeks if not adjusted.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1032', 'What is a breakaway collar for dogs?', 'A breakaway collar unlatches automatically under high pressure if caught on a fence post or another dog''s jaw during play, preventing accidental strangulation.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1033', 'Why are prong and choke chain collars discouraged by veterinary behaviorists?', 'They apply concentrated force to the thyroid gland, larynx, and cervical spine, increasing fear, aggression, and intraocular eye pressure.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1034', 'What width collar should I choose for a large dog?', 'Large and giant dogs (Labradors, Mastiffs) should wear wider 1.5- to 2.0-inch collars. Wider collars distribute pulling force across a larger surface area, protecting the neck.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1035', 'What information must be included on a dog''s ID collar tag?', 'Your dog''s name, two current phone numbers with area codes, ''Reward if found'', and ''Microchipped'' to ensure immediate contact if your dog is lost.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-collar-size-calculator_1036', 'Can a dog sleep wearing its collar?', 'Yes, provided the collar fits properly with the two-finger rule. However, remove collars when dogs are left inside wire crates to prevent snagging on bars.', 'dogs', 'tool', 'dog-collar-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1037', 'How often should I clean my dog''s ears?', 'Dogs with floppy ears (Spaniels, Retrievers) need cleaning every 1 to 2 weeks and after every swim. Dogs with erect prick ears (Huskies) typically need cleaning once a month.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1038', 'Why should I NEVER use Q-tips inside my dog''s ears?', 'Q-tips push wax and bacteria deeper into the horizontal canal against the eardrum, and an unexpected head shake can puncture the delicate tympanic membrane.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1039', 'What are the clinical signs of an ear infection (Otitis Externa) in dogs?', 'Head shaking, scratching at the ears, foul odor, dark brown or yellow discharge, red inflamed skin, and whining when the ears are touched.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1040', 'What is the proper method for cleaning a dog''s ears?', 'Fill the canal with veterinary ear cleaner, massage the base of the ear for 30 seconds until it squishes, let the dog shake its head, and wipe the loose wax with cotton balls.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1041', 'Why do floppy-eared dogs get significantly more ear infections?', 'Heavy ear flaps trap moisture, reduce airflow, and increase canal heat, creating the perfect warm, dark incubator for yeast and bacterial proliferation.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1042', 'Can I use hydrogen peroxide or vinegar to clean my dog''s ears?', 'NEVER use hydrogen peroxide or alcohol! Peroxide leaves residual water in the canal, and both substances cause excruciating chemical burns on inflamed ear skin.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1043', 'What should I do after my dog goes swimming?', 'Flush ears immediately with a veterinary drying ear cleanser containing astringents (like salicylic acid) to evaporate trapped pool or lake water.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1044', 'What causes dark coffee-ground-like wax in a dog''s ears?', 'Coffee-ground debris is a classic symptom of microscopic Ear Mites (*Otodectes cynotis*) or severe secondary *Malassezia* yeast infections requiring veterinary cytology.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1045', 'What is an aural hematoma?', 'When violent head shaking ruptures blood vessels inside the ear flap, causing the ear to swell up like a thick water balloon, requiring veterinary surgical drainage.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-ear-cleaning-schedule_1046', 'Should ear hair be plucked from Poodles and Doodles?', 'Plucking ear hair is controversial. Only pluck if recommended by your vet, as aggressive plucking can cause micro-tears and inflammatory infections in healthy canals.', 'dogs', 'tool', 'dog-ear-cleaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1047', 'How often should I brush my dog''s teeth?', 'Daily brushing is the veterinary gold standard. Brushing at least 3 to 4 times per week is mandatory to disrupt soft plaque biofilms before they mineralize into hard tartar.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1048', 'Can I use human toothpaste for my dog?', 'NEVER use human toothpaste! Human toothpaste contains fluoride (toxic to dog kidneys) and Xylitol (a sweetener that causes fatal liver failure and hypoglycemia in dogs).', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1049', 'What is the VOHC Seal of Acceptance on dog dental products?', 'The Veterinary Oral Health Council (VOHC) awards its official seal only to dental chews, treats, and water additives that have proven in clinical trials to reduce plaque and tartar.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1050', 'Why is ''Anesthesia-Free Dental Cleaning'' dangerous for dogs?', 'Cosmetic scaling on an awake dog only scrapes visible tartar off the crown, failing to clean 80% of dental disease beneath the gumline while risking jaw fractures and inhaled bacteria.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1051', 'What are the early signs of dental disease in dogs?', 'Persistent bad breath (halitosis), red swollen gums, yellow-brown tartar along the gumline, dropped food while eating, and chewing on only one side of the mouth.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1052', 'How does dental disease damage a dog''s internal organs?', 'Oral bacteria enter the bloodstream through inflamed, bleeding gums, causing microscopic infections and permanent damage to heart valves (endocardiosis) and kidneys.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1053', 'How do enzymatic pet toothpastes work?', 'Enzymatic toothpastes contain natural enzymes (glucose oxidase, lactoperoxidase) that break down food residues and produce natural antibacterial action even if the dog swallows it.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1054', 'How often do dogs need professional dental cleaning under anesthesia?', 'Most dogs benefit from an annual professional ultrasonic scaling and polishing starting around age 3 to 4 (small breeds may need cleanings every 6–12 months).', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1055', 'Are hard bones (antlers, hooves, nylon bones) safe for dog teeth?', 'Antlers, cow hooves, and hard nylon bones frequently cause fractured carnassial teeth (the large upper chewing molars), requiring expensive surgical tooth extractions.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-dental-care-schedule_1056', 'What is the best way to train a puppy to accept toothbrushing?', 'Start slowly: let them lick tasty poultry-flavored enzymatic toothpaste from your finger for a week, introduce a soft finger brush, and praise generously after each 10-second session.', 'dogs', 'tool', 'dog-dental-care-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1057', 'How often is it normal for a cat to throw up a hairball?', 'Passing a hairball once every 1 to 2 months is normal. Vomiting hairballs weekly is a clinical sign of underlying gastrointestinal motility disease (IBD) or skin allergies.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1058', 'Why are hairballs shaped like cylinders or cigars instead of balls?', 'As the hairball is regurgitated through the narrow, tubular esophagus, peristaltic contractions compress the mass into an elongated cylindrical shape.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1059', 'How can I prevent my cat from getting frequent hairballs?', 'Brush your cat daily with a metal Greyhound comb to remove dead fur, feed high-moisture wet food, add 1/2 tsp of plain pumpkin fiber, and use hairball lubricant pastes.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1060', 'What are the emergency signs of a blocked hairball intestinal obstruction?', 'Repeated non-productive dry retching, total loss of appetite, lethargy, distended painful belly, and vomiting water immediately after drinking. Seek ER care.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1061', 'How do hairball control cat foods work?', 'Hairball control diets contain specialized high insoluble fiber blends (beet pulp, cellulose) that sweep hair continuously through the gut into the litter box.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1062', 'What is the difference between vomiting a hairball and feline asthma coughing?', 'Asthma coughing looks similar: the cat crouches low to the ground with neck extended, making a dry hacking sound, but produces NO vomit or hairball at the end.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1063', 'Can petroleum-based hairball gels (Laxatone) help?', 'Yes. Malt-flavored petroleum pastes lubricate the stomach contents, helping hair slide smoothly through the pyloric sphincter into the intestines.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1064', 'Why do long-haired cat breeds (Persians, Maine Coons) get more hairballs?', 'Long-haired cats swallow significantly greater volumes and lengths of fur during daily grooming, which easily knots and mats inside the stomach.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1065', 'Can eating fresh cat grass help with hairballs?', 'Yes! Fresh wheatgrass or oat grass provides natural fiber, stimulating mild natural emesis to clear hair or providing roughage to move hair through the intestines.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-hairball-risk-calculator_1066', 'Why does chronic flea allergy increase hairball frequency?', 'Flea bites cause intense skin itching, forcing the cat to lick and nibble obsessively, ingesting 3 to 5 times more hair than normal.', 'cats', 'tool', 'cat-hairball-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1067', 'Why do cats need to scratch furniture and posts?', 'Scratching sheds dead outer claw husks, stretches shoulder and spinal muscles, and deposits territorial scent markers from interdigital paw glands.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1068', 'Why do so many cats ignore cheap commercial scratching posts?', 'Most cheap posts are too short (cats cannot achieve a full standing stretch) or have wobbly bases. If a post wobbles when a cat leans on it, they will never use it again.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1069', 'How tall should a vertical cat scratching post be?', 'A scratching post should be at least 32 to 36 inches (80 to 90 cm) tall so an adult cat can reach upward to full length and stretch its spine.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1070', 'What scratching material is best for cats?', 'Natural woven sisal fabric or heavy sisal rope is the gold standard. Sisal provides satisfying resistance and shreds cleanly without catching or injuring claws.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1071', 'Why should you NEVER buy a scratching post covered in carpet?', 'Carpet-covered posts teach cats that scratching carpet is acceptable, encouraging them to destroy your expensive household rugs and stairs.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1072', 'Where is the best location to place a scratching post in the house?', 'Place posts in prominent social areas: next to sleeping spots (cats stretch immediately upon waking), near doorways, and beside sofa corners they want to scratch.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1073', 'Do some cats prefer horizontal scratching over vertical posts?', 'Yes! Many cats prefer horizontal scratchers. Provide flat or slanted corrugated cardboard scratchers on the floor alongside vertical posts.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1074', 'How do I train my cat to stop scratching my sofa?', 'Place a tall sisal post directly in front of the sofa corner, apply double-sided sticky tape (Sticky Paws) to the sofa, and rub catnip or silvervine on the new post.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1075', 'Why is declawing (onychectomy) cruel and banned by veterinarians?', 'Declawing is NOT a nail trim; it is surgical amputation of the last bone of each toe (like amputating human fingertips), causing chronic pain, arthritis, and biting.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-scratching-post-selector_1076', 'How often should cardboard scratchers be replaced?', 'Replace cardboard scratchers every 3 to 6 months once the core corrugation is shredded smooth and no longer provides claw resistance.', 'cats', 'tool', 'cat-scratching-post-selector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1077', 'What is the best type of cat carrier for vet visits?', 'A hard-sided top-loading carrier or a carrier with a completely removable top half (clamshell design) that allows the vet to examine the cat while resting in the bottom.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1078', 'How big should a cat carrier be?', 'The carrier should be approximately 1.5 times the length of your cat, allowing them to comfortably enter, stand up, turn around 360 degrees, and lie down flat.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1079', 'Why do cats panic when they see their cat carrier?', 'Cats associate the carrier exclusively with scary car rides and vet visits. Leaving the carrier out in your living room year-round with treats makes it a safe daily nap den.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1080', 'How do I get an unwilling, stressed cat into a carrier?', 'Stand a top-loading carrier vertically on end, wrap your cat snugly in a towel (''kitty burrito''), and lower them gently hind-feet first into the top opening.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1081', 'Can two bonded cats share the same carrier during travel?', 'No! Travel stress triggers ''non-recognition aggression''. A frightened cat may violently attack its bonded sibling inside a confined carrier. Always use separate carriers.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1082', 'How should a cat carrier be secured inside a car?', 'Place the carrier on the floor behind the front seats (the safest spot in a crash), or thread the car seatbelt securely through the carrier''s designated seatbelt loops.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1083', 'What is Feliway spray and how does it help carrier travel?', 'Feliway Classic is a synthetic feline facial pheromone. Spraying it inside the carrier 15 minutes before travel provides calming chemical signals that reduce travel panic.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1084', 'Why should a towel or blanket be draped over the carrier during transit?', 'Covering the carrier blocks visual motion sickness triggers, unfamiliar barking dogs, and bright headlights, making the cat feel hidden and secure.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1085', 'What are the IATA requirements for flying with a cat in an airline cabin?', 'The carrier must be soft-sided, leak-proof, ventilated on 3 sides, and fit completely underneath the airplane seat in front of you (typically max 18x11x11 inches).', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-carrier-size-calculator_1086', 'What should I put on the bottom of a cat carrier?', 'Place an absorbent puppy pee pad on the bottom covered with a soft, familiar-smelling fleece blanket from home to catch any nervous accidents.', 'cats', 'tool', 'cat-carrier-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1087', 'What is a Catio and why is it beneficial for indoor cats?', 'A catio is an escape-proof, predator-safe outdoor enclosure that lets cats experience natural sunshine, fresh breezes, and bird-watching safely without the dangers of free roaming.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1088', 'How big does a catio need to be for 2 cats?', 'A minimum of 24 to 36 square feet of floor space with multi-tiered vertical shelves (6 to 8 feet tall) provides ample room for two cats to lounge without territorial crowding.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1089', 'What type of wire mesh is safe for building a catio?', 'Use 16-gauge galvanized welded wire mesh with 1/2-inch or 1-inch square openings. Standard window insect screens are too weak and easily torn by cat claws or raccoons.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1090', 'Can outdoor predators like raccoons or coyotes break into a catio?', 'Not if built properly! A secure catio features heavy framing, escape-proof wire mesh on all sides, a solid roof, and an escape-prevention airlock safety door.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1091', 'How do cats enter and exit a catio from the house?', 'Through a cat door installed in a sash window, a wall cat flap, or a specialized sliding glass pet door insert.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1092', 'What safe plants can I put inside my cat''s catio?', 'Fresh oat cat grass, wheatgrass, organic catnip, cat mint (*Nepeta*), silvervine, and pet-safe spider plants.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1093', 'Do cats using a catio still need monthly flea and heartworm preventatives?', 'YES! Mosquitoes (carrying heartworm larvae) and fleas easily penetrate wire mesh. Catio cats must receive year-round veterinary parasite preventatives.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1094', 'Can a catio be built on an apartment balcony?', 'Yes! Custom freestanding balcony catios enclosed in heavy netting or wire panels provide safe outdoor enrichment for apartment cats without drilling into building walls.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1095', 'How do I protect my catio from extreme sun and rain?', 'Install a solid UV-resistant corrugated polycarbonate roof over at least half the catio, along with shaded corner perches and fresh water bowls.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-catio-size-calculator_1096', 'What vertical climbing elements should be included in a catio?', 'Staggered cedar perches, climbing branches, cedar ramps, hammock beds, and high observation perches near the roofline where cats feel most secure.', 'cats', 'tool', 'cat-catio-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1097', 'Why should soap or shampoo never be used on a bird?', 'Soap and commercial shampoos dissolve the delicate natural waterproofing lipids and microscopic barbule hooks of feathers. This destroys their thermal insulation and water-repelling ability, causing skin irritation and severe hypothermia.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1098', 'Why must birds only be bathed in the morning or early afternoon?', 'Feathers take 1 to 3 hours to dry completely. Bathing a bird late in the evening means they go to sleep with damp under-down, drastically lowering their core body temperature and risking fatal respiratory infections.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1099', 'What should I do if my bird is terrified of spray bottles?', 'Never force or corner a bird with a spray bottle. Try alternative methods: a shallow ceramic baking dish on the cage floor, a gentle trickle from a sink faucet, taking them into the bathroom during your shower, or hanging wet kale leaves.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1100', 'How often should African Greys and Cockatoos be bathed?', 'African Greys and Cockatoos produce large amounts of white powder down. They should be misted or bathed 4 to 5 times per week (or daily) to prevent dry, itchy skin and keep their respiratory tract clear of dust.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1101', 'Can I use a human hairdryer to dry my bird after a bath?', 'NEVER use a human hairdryer! Many hairdryers contain non-stick PTFE/Teflon heating coils that emit lethal toxic fumes. Furthermore, the hot focused airflow can severely burn delicate avian skin. Let birds air-dry in a warm room.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1102', 'What water temperature is best for bird baths?', 'Use lukewarm to room-temperature water (approx. 75°F to 85°F / 24°–29°C). Never use hot water (burns skin) or icy cold water (triggers thermal shock).', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1103', 'Why does my bird spread its wings and flap wildly while getting misted?', 'This is the classic ''bathing display''. In nature, wild parrots flare their wings, fluff their feathers, and vocalize excitedly in the rain to allow water to penetrate down to their skin and under-wing flight tracts.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1104', 'How deep should a bath dish be for small birds like finches and budgies?', 'The water depth should never exceed 0.5 to 1 inch (1.2 to 2.5 cm). Deeper water presents an accidental drowning hazard for small passerines and parakeets.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1105', 'Does regular bathing help prevent feather plucking?', 'Yes! Dry, itchy skin and powder accumulation are major physical triggers for feather chewing and plucking. Regular warm baths soothe irritated skin and encourage healthy preening rather than feather destruction.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-bath-frequency-guide_1106', 'How often should finches and canaries have access to a bath?', 'Finches and canaries love water and should have access to a shallow bath dish daily for 20 to 30 minutes, after which the dish should be removed so they do not drink soiled bath water.', 'birds', 'tool', 'bird-bath-frequency-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1107', 'How many hours of free flight exercise does a companion parrot need daily?', 'A companion bird needs a minimum of 3 to 5 hours of active, supervised out-of-cage flight and social foraging time daily to maintain cardiovascular health and prevent feather plucking.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1108', 'What is the biggest indoor hazard for a flighted bird?', 'Ceiling fans are the single most dangerous indoor hazard. Even a fan on low speed can instantly shatter a bird''s skull, wings, or spine. Always verify fans are turned off before opening cages.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1109', 'How do I teach a flighted bird not to fly into glass windows?', 'Hang sheer curtains, close blinds, or apply patterned window decals spaced no more than 2 inches apart. You can also walk your bird to the glass while perched on your finger and gently tap the glass so they perceive the barrier.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1110', 'What is the minimum aviary length for small birds like finches and canaries?', 'Finches and canaries require a minimum horizontal flight cage length of 30 to 36 inches (or a 6-foot flight aviary for a colony) to allow natural horizontal flight hops.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1111', 'Why should perches be placed only at the ends of a flight cage?', 'Placing perches in the middle of a flight cage obstructs the flight path. Keeping perches at the extreme ends leaves the center open, forcing the bird to execute full-speed wing flaps to cross.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1112', 'Why is a double-door system necessary for outdoor aviaries?', 'A double-door security vestibule (safety airlock) ensures that one door is always closed before the other is opened, completely preventing startled birds from escaping into the wild.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1113', 'Can flighted birds live safely in homes with cats and dogs?', 'Predators (cats and dogs) must be completely locked in a separate room during flight sessions. Cat saliva contains Pasteurella multocida bacteria, which is lethal to birds within 24 hours from even a tiny scratch.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1114', 'What flooring is best for an indoor bird flight room?', 'Easy-to-clean, non-porous flooring like tile, hardwood with protective vinyl runner mats, or washable cotton drop cloths are best. Avoid deep-pile carpets that harbor dander and bacterial droppings.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1115', 'How do I train a parrot to fly back to me on command (recall training)?', 'Use positive reinforcement: start across very short distances (1 foot) between perches, give a verbal cue like ''Come!'', and immediately reward successful landings with a high-value pine nut or treat, gradually increasing distance.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-flight-space-calculator_1116', 'Can clipping wings make an aviary unnecessary?', 'No. Clipping wings limits flight, but birds still need spacious living areas to climb, flap, and forage. Flighted birds in spacious rooms remain significantly healthier and happier.', 'birds', 'tool', 'bird-flight-space-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1117', 'Why is weekly toy rotation necessary for parrots?', 'Parrots have high cognitive intelligence and experience rapid habituation (boredom). Leaving the same toys in a cage for months causes birds to ignore them completely, leading to frustration, screaming, and feather plucking. Rotating toys weekly restores excitement.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1118', 'Why are cotton rope toys and plush sleep huts dangerous?', 'Birds chew and swallow fine cotton threads that cannot be broken down in the stomach. These fibers accumulate into a dense knot in the crop or proventriculus, causing fatal gastrointestinal blockages requiring emergency surgery.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1119', 'What are foraging toys and why are they so important?', 'Foraging toys hide food inside puzzles, cardboard boxes, or woven palm pockets, forcing the bird to solve a challenge to eat. In the wild, birds forage 6+ hours daily; foraging toys prevent cage boredom and destructive habits.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1120', 'How many toys should be in a parrot''s cage at once?', 'Display 4 to 6 varied toys at once in a medium cage (or 3–4 in a small cage), ensuring the toys do not clutter horizontal flight space. Store the rest in reserve and swap them every 5 to 7 days.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1121', 'What types of wood are safe for DIY bird toys?', 'Safe woods include untreated pine, balsa, birch, apple wood, pear, manzanita, willow, and untreated bamboo. Never use pressure-treated wood, cedar, cherry, oak, or toxic plywood.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1122', 'Are mirrors safe for single companion birds?', 'No! Mirrors are psychologically damaging for parrots and budgies. The bird believes the reflection is a real mate, regurgitating food continuously, becoming territorial, and developing severe depression when the mirror bird never reciprocates.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1123', 'What metals are toxic on cheap bird toys?', 'Lead and zinc are highly toxic. Avoid galvanized wire, brass clasps, and cheap split rings. Only use 304 stainless steel, nickel-plated quick links, or natural vegetable-tanned leather cords.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1124', 'How do I make free, safe DIY bird toys at home?', 'Use clean, dye-free cardboard egg cartons filled with organic pellets and herbs, unbleached brown paper lunch bags stuffed with hay, paper cupcake liners threaded on sisal twine, and dry pine cones washed in hot vinegar water.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1125', 'Why do parrots love destroying wood and paper toys?', 'Chewing and shredding is a powerful hardwired instinct used in the wild to excavate nesting cavities in dead trees and forage for hidden wood-boring beetle larvae.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-toy-rotation-planner_1126', 'How should I clean and disinfect reusable parrot toys?', 'Scrub toys in a solution of warm water and distilled white vinegar or veterinary F10 disinfectant, rinse thoroughly, and bake wooden toys in an oven at 200°F (93°C) for 20 minutes to kill mold spores and bacteria.', 'birds', 'tool', 'bird-toy-rotation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1127', 'Why is a quarantine tank necessary for every new fish?', 'A quarantine tank prevents new fish from introducing devastating diseases (Ich, Velvet, Flukes, Columnaris) into your main display aquarium, protecting your existing livestock.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1128', 'How long should new fish remain in the quarantine tank?', 'A minimum of 2 to 4 weeks (14 to 30 days) is recommended. This allows sufficient time for parasitic life cycles to complete and visible symptoms to manifest.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1129', 'What equipment do I need to set up a basic quarantine tank?', 'You need a simple 10–20 gallon bare-bottom tank, a seeded sponge filter, a reliable heater, a thermometer, and PVC pipe elbows for hiding places.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1130', 'Why should a quarantine tank have a bare glass bottom without gravel?', 'A bare bottom prevents parasite cysts from embedding in gravel, makes daily waste siphoning easy, and ensures uneaten food is removed before fouling water.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1131', 'What is the ''Quarantine Trio'' preventative medication protocol?', 'It is a standard preventative combination of an antiparasitic (Praziquantel), an antiprotozoal/antibacterial (Metronidazole), and an external parasite remedy used to clear hidden infections.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1132', 'Should I quarantine new live aquarium plants and snails?', 'Yes. Plants and snails can carry microscopic parasite cysts, snail eggs, and hydra into your aquarium. Quarantine plants for 2 weeks or perform an alum dip.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1133', 'How do I keep a quarantine filter cycled when no fish are in it?', 'Keep a spare sponge filter running in your main display tank or sump at all times, and simply transfer it into the quarantine tank whenever new fish arrive.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1134', 'What daily symptoms should I monitor during quarantine?', 'Watch for clamped fins, rapid gill breathing, flashing against glass, white salt-like spots, cloudy eyes, frayed fins, abnormal feces, and poor appetite.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1135', 'What should I do if a fish shows active disease during quarantine?', 'Diagnose the disease, treat with targeted medication, and restart the 14-day quarantine timer only after all symptoms have completely disappeared.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-quarantine-timer_1136', 'How do I disinfect quarantine equipment after treating sick fish?', 'Disinfect equipment with a 10% bleach solution or 3% hydrogen peroxide, rinse thoroughly with fresh water, and allow to air dry completely before next use.', 'fish', 'tool', 'fish-quarantine-timer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1137', 'How many live plants do I need to heavily plant my aquarium from day one?', 'Aim to plant 60% to 80% of your tank''s substrate floor on day one. For a 20-gallon tank, this typically equates to 20–30 stem plants, 3–5 midground pots, and 6–10 carpeting pots.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1138', 'Why is heavy planting on day one the best defense against algae?', 'A high initial plant biomass consumes excess ammonia, phosphorus, and iron immediately, starving opportunistic algae spores before they can colonize the tank.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1139', 'What are the easiest low-light live plants for beginner aquarists?', 'Top beginner species include Anubias, Java Fern, Cryptocoryne wendtii, Java Moss, Amazon Swords, and Vallisneria. All thrive under low light without injected CO2.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1140', 'What is an epiphyte plant and why must its rhizome stay unburied?', 'Epiphytes (Anubias, Java Fern, Bucephalandra) absorb nutrients directly from the water column. Burying their thick horizontal rhizome in substrate suffocates tissue and causes rot.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1141', 'What is the difference between potted, bunched, and tissue-culture plants?', 'Potted plants have developed root systems; bunched stems are loose cuttings held by a lead weight; in-vitro tissue-culture cups are 100% sterile, pest-free, and snail-free.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1142', 'How many pots of carpeting plants do I need to cover my tank floor?', 'One in-vitro tissue-culture cup of Monte Carlo or Dwarf Hairgrass covers approximately 4 to 6 square inches when divided into small dime-sized plugs spaced 1 inch apart.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1143', 'Why do new aquarium plants melt and lose leaves shortly after planting?', 'Most commercial plants are grown emersed (above water) on nurseries. When submerged underwater in your tank, they shed their terrestrial leaves to grow adapted aquatic foliage.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1144', 'Do heavy root-feeding plants like Amazon Swords need root tabs?', 'Yes. Heavy root feeders in inert sand or gravel require nutrient-rich root fertilizer tabs placed 1 to 2 inches beneath their root crown every 2 to 3 months.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1145', 'How do background stem plants help export nitrates from the water?', 'Fast-growing stem plants have high metabolic growth rates and consume large amounts of nitrogen and potassium, lowering nitrate levels naturally.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-plant-count-calculator_1146', 'Can live plants replace mechanical and biological filters completely?', 'In very low-stocked ''Walstad method'' tanks, plants can handle nitrogenous waste, but standard community tanks still require filters for water circulation and mechanical clarity.', 'fish', 'tool', 'aquarium-plant-count-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1147', 'How deep should the substrate bed be in a freshwater aquarium?', 'A general depth of 2 to 2.5 inches (5 to 6.5 cm) is ideal for most planted and community aquariums, providing ample root anchoring without creating deep anaerobic pockets.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1148', 'What is the formula to calculate how many pounds of substrate I need?', 'Multiply Tank Length (in) × Tank Width (in) × Target Depth (in) and divide by 10 to get the estimated substrate weight in pounds.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1149', 'What is the difference between active aquasoil and inert sand or gravel?', 'Inert sand/gravel does not alter water chemistry or contain nutrients. Active aquasoil lowers pH/KH and has a high Cation Exchange Capacity (CEC) that stores plant nutrients.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1150', 'What is Cation Exchange Capacity (CEC) in aquarium substrates?', 'CEC measures the substrate''s ability to hold onto positively charged nutrient ions (like potassium, calcium, magnesium, and iron) from fertilizers and release them to plant roots.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1151', 'Should I rinse aquarium substrate before adding it to the tank?', 'Always rinse inert sand and gravel until the runoff is crystal clear. Never rinse active aquasoil, as rinsing turns the baked clay pellets into muddy slurry.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1152', 'How do I prevent dangerous anaerobic hydrogen sulfide pockets in deep sand?', 'Keep sand depth under 2.5 inches, use fine 1–2mm sand, or keep burrowing Malaysian Trumpet Snails whose digging continuously aerates the substrate bed.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1153', 'Which substrate is safest for soft-bellied bottom fish like Corydoras?', 'Smooth, rounded silica sand or fine pool filter sand is safest. Rough, sharp gravel damages delicate sensory barbels and causes secondary bacterial infections.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1154', 'Why is gravel unsafe for axolotls and large goldfish?', 'Axolotls and goldfish feed by powerful vacuum suction and readily swallow gravel pebbles, leading to fatal gastrointestinal impaction and intestinal blockage.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1155', 'How long does active aquasoil maintain its pH buffering capacity?', 'Active aquasoil typically buffers pH and KH for 18 to 24 months, depending on the hardness and carbonate levels of the replacement tap water used.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-substrate-calculator_1156', 'How do I create a sloping substrate bed that won''t flatten out over time?', 'Use corrugated plastic substrate support dividers or hardscape rocks buried under the substrate to physically retain the slope and prevent sand from sliding forward.', 'fish', 'tool', 'aquarium-substrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1157', 'How many bubbles per second should I start with for my tank size?', 'Start conservatively at 1 bubble per second per 20 gallons of water. Monitor your drop checker after 3 to 4 hours and adjust the needle valve gradually by micro-increments.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1158', 'What is the safe target dissolved CO2 level for planted aquariums?', '25 to 35 ppm of dissolved CO2 is the universal sweet spot for lush plant growth while maintaining a safe margin of respiratory comfort for fish and shrimp.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1159', 'How does a glass drop checker with 4 dKH solution work?', 'CO2 gas outgasses from the tank water into the drop checker''s air bubble and dissolves into the 4 dKH bromothymol blue indicator. It turns lime green at precisely 30 ppm CO2.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1160', 'Why must I never use tank water inside my CO2 drop checker?', 'Tank water contains variable organic acids and fluctuating KH that distort the chemical indicator, giving a completely inaccurate color reading.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1161', 'When should my CO2 solenoid timer turn on and off?', 'Set the solenoid to turn on 1 to 2 hours before your lights turn on, and turn off 1 hour before lights turn off, ensuring 30 ppm saturation throughout the photoperiod.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1162', 'What is ''End-of-Tank Dump'' (EOTD) and how do dual-stage regulators prevent it?', 'When a single-stage cylinder runs low, internal pressure drops can cause the valve to dump remaining gas into the tank. Dual-stage regulators maintain constant output pressure.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1163', 'What are the signs of CO2 poisoning in fish and how do I fix it?', 'Fish gasping at the surface, lethargy, and loss of equilibrium indicate CO2 poisoning. Immediately turn off CO2, maximize surface agitation, and run an emergency air stone.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1164', 'What is the difference between an in-tank ceramic diffuser and an in-line reactor?', 'In-tank ceramic diffusers produce a mist of micro-bubbles inside the display, while in-line reactors attach to canister filter tubing, dissolving 100% of CO2 gas before entering the tank.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1165', 'Can liquid carbon products replace pressurized CO2 gas injection?', 'No. Liquid carbon products (glutaraldehyde) are mild algaecides that supply only a tiny fraction of the carbon delivered by true pressurized CO2 gas systems.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-co2-calculator_1166', 'How long will a 5 lb CO2 cylinder last on a 40-gallon planted tank?', 'A 5 lb pressurized CO2 cylinder running at 2 to 3 bubbles per second typically lasts between 6 and 9 months before requiring a refill.', 'fish', 'tool', 'aquarium-co2-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1167', 'How can I tell if my hamster''s wheel is too small?', 'Watch your hamster run from the side. If their spine curves like a banana with their head and tail arched upwards, the wheel is too small. A properly sized wheel allows the hamster''s back to remain completely straight and flat while running.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1168', 'Why are wire and barred wheels dangerous for hamsters?', 'Wire rungs and mesh tracks trap feet and toes during full-speed running, causing torn nails, dislocated joints, and broken bones. The uneven pressure also wears away foot fur, causing painful bumblefoot (ulcerative pododermatitis).', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1169', 'What wheel size is needed for a full-grown Syrian hamster?', 'A full-grown Syrian hamster needs an 11- to 12-inch (28 to 30 cm) solid-surface wheel. Anything smaller forces spinal hyperextension and causes chronic back pain.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1170', 'Can a wheel be too large for a dwarf hamster?', 'As long as the wheel has smooth, high-quality dual ball bearings, a dwarf hamster can easily push a 10- or 11-inch wheel without difficulty. However, heavy wooden wheels without bearings can be too hard for tiny Roborovskis to start and stop.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1171', 'Are saucer (flying saucer) wheels good for hamsters?', 'Flying saucer wheels can be an occasional enrichment addition, but they should never replace an upright wheel. Running on a saucer forces the hamster''s body to curve sideways unnaturally, causing asymmetric muscle and joint strain.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1172', 'Why does my hamster pee and poop on their wheel?', 'Running stimulates the gastrointestinal tract and bladder. Hamsters also use scent marking to identify their territory. Clean solid plastic wheels regularly with warm water and pet-safe enzymatic cleaner or diluted white vinegar.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1173', 'What are the quietest hamster wheels available?', 'Top-rated ultra-quiet wheels include the Niteangel Super-Silent series, the Exotic Nutrition Silent Runner, and cork-lined wooden wheels like the Rodipet or Trixie cork wheel.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1174', 'Can hamsters use plastic exercise balls to run around the house?', 'No! Veterinary organizations strongly advise against hamster exercise balls. They provide poor ventilation, trap heat and ammonia, disorient hamsters due to warped vision, pinch toes in ventilation slits, and cause intense panic.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1175', 'How many miles does a hamster run on its wheel every night?', 'A healthy young hamster routinely runs between 3 and 6 miles (5 to 9 kilometers) every single night, making a reliable, quiet wheel essential.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hamster-wheel-size-calculator_1176', 'How do I maintain and clean a cork-lined wooden wheel?', 'Coat the cork track with non-toxic, pet-safe waterproof sealant (such as child-safe toy varnish) before use, and wipe it down with a damp cloth and mild vinegar solution during regular cleanings.', 'small-pets', 'tool', 'hamster-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1177', 'What is the best cage on the market for pet ferrets?', 'The Ferret Nation (Model 182) and Critter Nation by Midwest Homes for Pets are universally regarded by exotic veterinarians and rescues as the gold standard, featuring solid trays, wide-opening double doors, 1/2-inch bar spacing, and sturdy all-metal frames.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1178', 'Why is 1/2-inch bar spacing necessary for ferret cages?', 'Ferrets have flexible, compressible skulls and bodies. Cages with 1-inch bar spacing allow smaller females and kits to squeeze through or get their heads wedged between the bars, risking fatal strangulation.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1179', 'How many hours a day should a ferret be out of its cage?', 'Ferrets require a minimum of 4 hours of active, supervised out-of-cage exercise and social interaction daily in a secure, ferret-proofed environment.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1180', 'Can ferrets live in a cage with wire mesh floors?', 'No. Wire floors cause severe foot injuries, catch claws, and lead to painful pododermatitis (ulcerative foot sores). Always use solid plastic or metal pans covered with soft fleece bedding.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1181', 'What is the biggest household hazard for free-roaming ferrets?', 'Soft rubber, silicone, and foam items (shoe insoles, earplugs, remote buttons, rubber toys). Ferrets love chewing soft rubber, which breaks off and causes fatal gastrointestinal foreign body blockages requiring emergency surgery.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1182', 'How many litter boxes should be placed inside a multi-level ferret cage?', 'Place at least one low-entry corner litter box on the bottom level, and ideally a secondary box on the upper tier. Ferrets have a rapid 3- to 4-hour digestive transit and will not travel far to find a litter tray.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1183', 'What bedding is best for inside a ferret cage?', 'Washable fleece hammocks, hanging sleep sacks, and fleece blankets are best. Avoid wood shavings (which cause respiratory irritation) and loose-thread towels (which can catch long toenails).', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1184', 'Can ferrets be housed in glass aquariums or plastic tub cages?', 'Never house ferrets in aquariums or solid plastic tubs. They lack adequate cross-ventilation, trapping ammonia and heat, which leads to severe respiratory infections and heatstroke.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1185', 'How do I prevent multi-tier fall injuries inside a tall ferret cage?', 'Stagger the solid mezzanine shelves so there is no continuous vertical drop, and hang wide fleece hammocks across middle open spaces to act as safety catch nets.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-cage-size-calculator_1186', 'Can two or three ferrets share a double-story cage?', 'Yes! A double-story Ferret Nation (approx. 45 cu ft) easily and comfortably accommodates 2 to 3 bonded ferrets, provided they receive daily out-of-cage exercise.', 'small-pets', 'tool', 'ferret-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1187', 'What is the absolute minimum cage size for two guinea pigs?', 'The minimum single-level floor space for two female guinea pigs is 10.5 sq ft (a 2x4 C&C grid cage, approx. 30x60 inches). For two male boars, 13 sq ft (a 2x5 C&C cage) is the minimum to prevent territorial fighting.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1188', 'Why are pet-store guinea pig cages almost always too small?', 'Most commercial pet-store cages measure only 3 to 5 sq ft, which is less than half the humane minimum. Cramped cages cause bumblefoot, obesity, dirty living conditions, and aggressive fighting.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1189', 'What does C&C cage mean?', 'C&C stands for ''Cubes and Coroplast''. It is a popular modular cage design made from 14-inch wire storage mesh grids snapped together and lined with a durable, waterproof corrugated plastic (Coroplast) sheet.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1190', 'Can guinea pigs share a multi-level ferret or chinchilla cage?', 'No. Guinea pigs have fragile spines and poor depth perception. They cannot climb vertical wire bars or jump between tall shelves. Falls from heights as low as 12 inches can cause fatal spinal fractures.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1191', 'Why do male guinea pigs (boars) need more space than females?', 'Boars exhibit natural dominance and territorial behaviors. Extra space allows each boar to establish its own personal resting territory and prevents resource guarding around food bowls and hides.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1192', 'What kind of bedding is best for a large C&C guinea pig cage?', 'Fleece liners with an absorbent core (washable puppy pads, U-Haul furniture pads, or Zorb fabric) are the gold standard. They wick urine down into the absorbent layer, keeping the surface completely dry and clean.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1193', 'How many hideaways should I put in the cage?', 'Provide at least one hideout per guinea pig, plus one extra. Every hide must have two separate doors/openings so one pig cannot trap another inside.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1194', 'Can a guinea pig live happily alone without a companion?', 'No. Guinea pigs are obligate herd animals. In countries like Switzerland, it is illegal to keep a single guinea pig. Solitary pigs suffer chronic loneliness, depression, and immune decline.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1195', 'How high should the coroplast side walls be in a C&C cage?', 'Coroplast side walls should be 5 to 6 inches tall to contain bedding, stray hay, and fecal pellets while allowing open airflow.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-cage-size-calculator_1196', 'How often should a large fleece-lined guinea pig cage be cleaned?', 'Perform daily spot-cleaning with a hand broom or mini vacuum to remove fecal pellets and stray hay, and wash the full fleece liners every 4 to 7 days.', 'small-pets', 'tool', 'guinea-pig-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1197', 'Why is hanging hay over the litter box the secret to fast training?', 'Rabbits possess an active gastrocolic reflex that stimulates their digestive tract while chewing. Chewing hay naturally triggers bowel and bladder elimination, so placing hay over the litter box ensures they are in the box when nature calls.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1198', 'Can I use regular clumping cat litter for my rabbit?', 'No! Never use clumping clay cat litter. Rabbits frequently nibble on their litter. Clumping clay swells into a solid cement-like mass in the digestive tract, causing fatal gastrointestinal impaction.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1199', 'Why does my rabbit keep peeing on my bed or couch?', 'Beds and couches are high-value soft territory saturated with your human scent. Insecure or hormonal rabbits feel a strong urge to claim and mark these areas with urine. Keep rabbits off beds until they are fully neutered and 100% litter-trained.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1200', 'At what age can a baby bunny be litter trained?', 'Basic training can start around 8 weeks old, but young bunnies have immature sphincter muscle control and will have occasional accidents until they reach 4 to 6 months and are spayed or neutered.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1201', 'Why is spaying or neutering necessary for reliable litter habits?', 'Intact rabbits are driven by hormones to mark territory by spraying urine up walls and scattering territorial poop markers. Spaying/neutering eliminates hormonal marking and makes training fast and reliable.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1202', 'What is the best way to clean up rabbit urine accidents?', 'Use a 50/50 mixture of white distilled vinegar and warm water or an enzymatic pet stain cleaner. Vinegar dissolves calcium carbonate crystals and neutralizes ammonia scents completely.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1203', 'How many litter boxes do I need for a free-roam rabbit?', 'Follow the ''N + 1'' rule: provide one litter box per room the rabbit has access to, plus one extra in their home base pen. Rabbits are territorial and will not travel long distances to find a box.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1204', 'How often should a rabbit litter box be completely cleaned?', 'Empty and wash the litter box with warm water and vinegar every 2 to 4 days, adding fresh paper pellets and clean hay daily.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1205', 'What should I do if an older trained rabbit suddenly stops using the box?', 'Sudden loss of litter habits is a medical red flag. It typically indicates painful arthritis (inability to hop over high box edges), a urinary tract infection (UTI), or bladder sludge. Consult an exotic vet promptly.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-litter-training-guide_1206', 'How do I make a senior-friendly litter box for an arthritic rabbit?', 'Take a standard shallow plastic storage tub and cut down the front lip to a low 2-inch entry threshold, smoothing any rough plastic edges with sandpaper or tape so the rabbit can walk in without jumping.', 'small-pets', 'tool', 'rabbit-litter-training-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1207', 'Where should the hygrometer probe be placed in the enclosure?', 'Place the digital hygrometer sensor on the cool side of the enclosure, approximately 2 to 3 inches above the substrate level. Do not mount it directly under the heat lamp (which causes falsely low readings) or directly against a wet misting nozzle.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1208', 'Why do tropical reptiles need a nighttime humidity spike?', 'In wild tropical habitats, ambient humidity naturally rises to 80–100% after sunset as temperatures drop. Mimicking this with an evening misting cycle prevents respiratory dehydration while allowing the terrarium to dry down during the day to inhibit mold and bacterial growth.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1209', 'How do I safely raise humidity without making the substrate soggy?', 'Pour water directly into the bottom corners of deep moisture-holding substrate (like coconut husk or cypress mulch). This keeps the bottom layer damp to release humidity while leaving the top surface dry, preventing scale rot.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1210', 'What happens if humidity is too low for a ball python or rainbow boa?', 'Low humidity causes dehydration, patchy stuck sheds (dysecdysis), retained eye caps, and dries out the mucus lining of the respiratory tract, making the snake highly vulnerable to bacterial Upper Respiratory Infections (URI).', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1211', 'Can high humidity harm desert species like bearded dragons and Uromastyx?', 'Yes. High humidity (>45–50%) combined with poor airflow in arid enclosures causes severe respiratory infections, fungal blister disease on scales, and lethargy. Keep desert tanks dry with maximum screen ventilation.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1212', 'What is the best way to lower humidity in an enclosure?', 'Increase ventilation by replacing glass lids with mesh, switch to drier substrate like aspen or paper towels, move the water dish from the warm side to the cool side, and use a smaller surface-area water bowl.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1213', 'Is an ultrasonic fogger or an automatic pressure mister better?', 'Automatic misters (like MistKing) spray fine water droplets across plants for drinking and hydration bursts. Ultrasonic foggers create a dense cloud of microscopic vapor ideal for nighttime humidity spikes in high-humidity species like chameleons and dart frogs.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1214', 'How does a humid hide work?', 'A humid hide is an enclosed plastic or resin box packed with damp sphagnum moss with a single entry hole. It creates a local 80%+ microclimate where reptiles can voluntarily retreat to hydrate and loosen shedding skin.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1215', 'Why are analog dial hygrometers unreliable?', 'Analog dial spring hygrometers frequently have errors of ±15% to 25% right out of the box and quickly stick when exposed to moisture. Always use a calibrated digital hygrometer with an external probe.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1216', 'How does bioactive substrate help stabilize enclosure humidity?', 'Bioactive setups combine a drainage layer, moisture-retentive ABG soil mix, live plants, and clean-up crews (isopods/springtails). The soil and plants act as a natural moisture buffer, preventing rapid humidity crashes.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1217', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-humidity-guide_1218', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-humidity-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1219', 'Why must basking temperatures be measured with an infrared temp gun?', 'Standard thermometers only measure air temperature. An infrared thermometer (temp gun) measures the actual contact surface temperature of rocks and branches where your reptile lies. The basking surface is often 10–20°F hotter than surrounding air.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1220', 'Why are heat rocks dangerous for reptiles?', 'Heat rocks concentrate intense heat in small spots without thermostat control. Reptiles lack thermal pain receptors on their bellies and will sit on overheating rocks until they suffer severe, third-degree burns and flesh necrosis.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1221', 'What is the best overhead heat source for basking diurnal reptiles?', 'Halogen flood bulbs (such as PAR30/PAR38) are the gold standard. They emit Infrared-A (short-wave) and Infrared-B radiation that deeply penetrates muscle tissue, perfectly mimicking natural sunlight.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1222', 'What is the difference between a dimming and an on/off thermostat?', 'On/off thermostats cut power completely when target temp is reached, creating constant flashing and temperature swings with light bulbs. Dimming thermostats smoothly adjust the voltage to maintain an exact, stable temperature without flickering.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1223', 'Why is a thermal gradient with a cool side essential?', 'Reptiles cannot internally regulate body temperature. A wide thermal gradient allows them to move between the warm basking zone (to digest meals) and the cool retreat (to prevent heat stroke and dehydration).', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1224', 'What should the nighttime temperature drop be?', 'Most diurnal reptiles benefit from a natural nighttime temperature drop down to 65–72°F (18–22°C). This drop slows their metabolism, promotes deep sleep, and conserves vital energy reserves.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1225', 'When should a Ceramic Heat Emitter (CHE) or Deep Heat Projector (DHP) be used?', 'CHEs and DHPs emit zero visible light, making them ideal for providing supplemental ambient warmth overnight without disrupting your reptile''s 24-hour day/night circadian rhythm.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1226', 'What basking temperature does an adult bearded dragon need?', 'Adult bearded dragons require a basking surface temperature of 100°F to 105°F (38–41°C), while babies and juveniles need 105°F to 110°F (41–43°C) over a broad piece of slate or driftwood.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1227', 'What happens if a reptile is kept without sufficient basking heat?', 'Without proper heat, reptiles cannot produce digestive enzymes. Food rots in the stomach, leading to regurgitation, severe impaction, metabolic bone disease, and suppressed immune function.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1228', 'Why are colored red or blue nighttime bulbs harmful?', 'Reptiles possess advanced color vision with tetrachromatic photoreceptors. Red and blue night bulbs are completely visible to them, causing severe circadian rhythm disruption, stress, and eye damage over time.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1229', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-basking-temp-guide_1230', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-basking-temp-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1231', 'How does a bearded dragon''s diet change as they grow?', 'Babies (0–3 months) eat 80% insects and 20% greens; juveniles (4–11 months) eat 60% insects and 40% greens; sub-adults (12–17 months) eat 40% insects and 60% greens; and full adults (18+ months) eat 80% greens and only 20% insects.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1232', 'What are the best daily staple greens for bearded dragons?', 'Top daily staple greens include Collard greens, Mustard greens, Dandelion greens, Turnip greens, Endive, Escarole, and shredded Butternut squash. Rotate 3–4 greens weekly for optimal nutrition.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1233', 'Which foods are strictly toxic and lethal to bearded dragons?', 'Never feed Avocado (contains persin toxin), Rhubarb (high oxalic acid), Fireflies/Lightning bugs (contain lethal lucibufagins), Wild-caught insects (pesticides/parasites), or Onion/Garlic.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1234', 'Why should spinach, beet greens, and kale be fed sparingly?', 'Spinach, beet greens, and Swiss chard are high in oxalates, which bind to dietary calcium in the gut and prevent its absorption, increasing the risk of Metabolic Bone Disease. Feed only as rare occasional treats.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1235', 'How often should an adult bearded dragon be fed insects?', 'Adult bearded dragons only need live insects 2 times per week (approx 4–6 large dubia roaches or medium superworms per feeding). Daily insect feeding causes obesity, gout, and fatty liver disease in adults.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1236', 'What is the proper supplement dusting schedule for bearded dragons?', 'Dust live insects with Plain Calcium (no D3) 4–5 days per week; Calcium with Vitamin D3 1–2 days per week; and a comprehensive Reptile Multivitamin powder 1 day per week.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1237', 'How can I encourage a picky bearded dragon to eat its salad?', 'Chop greens into bite-sized pieces, mix in colorful yellow squash, top with edible bee pollen powder (beardies love the sweet taste), add a few moving feeder worms on top of the salad, and feed the salad first thing in the morning before offering insects.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1238', 'What size feeder insects should I give to my bearded dragon?', 'The insect must be no longer than the space between your bearded dragon''s eyes. Oversized insects can lodge in the digestive tract, putting pressure on the spinal cord and causing hind-leg paralysis.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1239', 'Do bearded dragons drink water from a bowl?', 'Many bearded dragons do not recognize standing water in a bowl. They obtain the majority of their hydration from moisture-rich fresh greens, gut-loaded insects, and occasional hornworms.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1240', 'Why is iceberg lettuce bad for bearded dragons?', 'Iceberg lettuce consists of 96% water with virtually zero nutritional value. Eating iceberg lettuce causes severe watery diarrhea, dehydration, and nutrient malabsorption.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1241', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bearded-dragon-food-calculator_1242', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'bearded-dragon-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1243', 'How do I measure a horse for a blanket in the United States?', 'Use a soft measuring tape starting at the center of the horse''s chest, run horizontally across the widest point of the shoulder, along the side of the body, to the center of the tail dock. Round up to the nearest even number in inches.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1244', 'What is the difference between US, European, and UK blanket sizes?', 'US sizes measure overall body length in inches (e.g., 76"). European sizes measure along the topline from withers to tail in centimeters (e.g., 145 cm). UK sizes measure overall length in feet and inches (e.g., 6''3").', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1245', 'How do I convert a US blanket size to a European (EU) size?', 'Subtract 22 to 24 inches from the US size and multiply by 2.54. For example, a US size 76" corresponds to approximately a 135–140 cm European back length.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1246', 'When does an unclipped horse actually need a blanket?', 'Healthy unclipped horses rarely need blankets above 20°F (-7°C) if they have shelter and dry hay. Blanketing is necessary only when the horse is exposed to freezing rain (which flattens insulating hair), high winds, is elderly, or has a low BCS (<4).', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1247', 'Why is a wet horse in freezing rain at greater risk than in dry snow?', 'Dry snow sits on top of a horse''s fluffy fur without melting because natural hair traps air. Freezing rain flattens the hair coat, saturating the skin with cold water, destroying thermal insulation, and triggering rapid hypothermia.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1248', 'What happens if a horse is blanketed too heavily (over-blanketing)?', 'Over-blanketed horses sweat underneath the blanket. The trapped sweat saturates the coat, making the horse cold and clammy, while warm, humid moisture trapped against the skin causes fungal infections (''rain rot'' / dermatophilosis).', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1249', 'How tight should belly surcingles and leg straps be?', 'Belly surcingles should have a hand''s width (approx. 4 inches) of clearance below the belly. Leg straps should be crossed through one another and adjusted to have about 4 to 5 inches of slack so the horse cannot catch a foot while rolling.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1250', 'What should I do if a blanket rubs my horse''s shoulders bald?', 'Bald shoulder rubs indicate the blanket is too small, sits too far back, or lacks shoulder gussets. Use a silky Lycra shoulder guard / bib underneath and consider a blanket with a higher neck or deeper gussets.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1251', 'What does blanket ''denier'' mean?', 'Denier (e.g., 600D vs 1200D vs 1680D) measures the yarn thickness and tear resistance of the outer fabric. Higher denier numbers (1200D+) are much more durable against playful pasture mates and tree branches.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-blanket-size-calculator_1252', 'How should waterproof horse blankets be washed and reproofed?', 'Wash in front-loading commercial machines using cold water and specialized non-detergent blanket wash (like Nikwax Rug Wash). Never use standard laundry detergent or fabric softeners, as they destroy the waterproof polyurethane membrane.', 'horses', 'tool', 'horse-blanket-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1253', 'What is the standard minimum stall size for an average horse?', 'The veterinary and industry standard for an average light horse (15.0 to 16.2 hands / 1,000–1,200 lbs) is 12 feet by 12 feet (3.6 × 3.6 meters), providing 144 square feet of floor space.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1254', 'Why is a 10x10 ft stall too small for most standard horses?', 'A 10x10 ft stall is suitable only for ponies under 14.2 hands. Standard horses in 10x10 stalls frequently get ''cast'' (trapped against the wall when rolling), suffer capped hocks from banging walls, and lack room to lie flat in deep REM sleep.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1255', 'What size stall is required for a foaling mare and newborn foal?', 'A foaling stall must be at least 16 feet by 16 feet (or a double stall created by removing a center partition between two 12x12 stalls). This provides safe room for the mare during labor without trapping the newborn foal against walls.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1256', 'How high should the ceiling be in a horse barn?', 'Ceilings must be at least 10 to 12 feet (3.0 to 3.6 meters) high. Low ceilings create extreme danger of traumatic head and poll fractures if a horse startles and rears.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1257', 'What is the best flooring to install inside a horse stall?', 'Well-drained crushed limestone or packed clay base covered with interlocking, heavy-duty 3/4-inch vulcanized rubber mats is the gold standard. Rubber mats reduce bedding costs by 30% and cushion joints.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1258', 'How wide should stall doors and barn aisleways be?', 'Stall doors should be at least 4 feet wide to prevent hip knocks. Main barn aisleways should be 10 to 12 feet wide to allow two horses to pass each other safely.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1259', 'Why is barn ventilation critical for equine respiratory health?', 'Horses have sensitive lungs. Inhaling airborne ammonia from urine and mold spores from hay causes chronic Equine Asthma (heaves / Recurrent Airway Obstruction). Barns must have open ridge vents and eaves allowing continuous fresh air exchange.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1260', 'How deep should stall bedding be?', 'Maintain 4 to 6 inches of clean, dust-extracted kiln-dried pine shavings or straw over rubber mats, banking the bedding slightly higher along the walls to prevent casting.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1261', 'Why is black walnut wood toxic as horse bedding?', 'Shavings containing even 1% to 2% black walnut (Juglans nigra) wood contain the toxin juglone. Inhaling or standing on black walnut shavings causes acute, severe laminitis within 24 to 48 hours.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-stall-size-calculator_1262', 'How many hours of daily pasture turnout does a stalled horse require?', 'Stalled horses require a minimum of 4 to 6+ hours of daily pasture or paddock turnout to maintain intestinal motility, stimulate joint circulation, and prevent behavioral stable vices.', 'horses', 'tool', 'horse-stall-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1263', 'How often does a horse need to see a farrier?', 'Most horses require professional farrier trimming or shoe resets every 4 to 6 weeks for shod horses, and every 6 to 8 weeks for barefoot horses, with intervals shortened during rapid summer growth.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1264', 'Why is waiting 8 to 10 weeks between farrier visits dangerous?', 'As hooves overgrow, the toe grows forward, creating a long lever arm that delays breakover. This places massive mechanical strain on the Deep Digital Flexor Tendon, navicular bone, and suspensory ligaments, leading to chronic lameness.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1265', 'What are the warning signs that a horse is overdue for a trim?', 'Signs include long, pointed toes, chipped or cracked hoof walls, flaring along the quarters, collapsed/underrun heels, loose shoe nails (clinches), or uneven tripping during work.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1266', 'How fast does a horse''s hoof grow?', 'A healthy equine hoof grows approximately 6 to 10 mm (1/4 to 3/8 inch) per month. It takes roughly 9 to 12 months for a complete new hoof capsule to grow down from the coronary band to the toe.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1267', 'What is thrush and how do I treat it?', 'Thrush is a bacterial and fungal infection of the frog sulci, recognized by black discharge, a foul odor, and tissue degradation. Treat by cleaning the hoof thoroughly, applying topical antiseptic thrush treatments, and keeping stalls dry.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1268', 'What nutrients support healthy hoof wall growth?', 'Biotin (20–30 mg daily), zinc, copper, and sulfur-containing amino acids (methionine and lysine) are the scientifically proven micronutrients required for robust keratin synthesis.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1269', 'Can all horses go barefoot without shoes?', 'Many horses thrive barefoot with proper trimming, balanced nutrition, and gradual conditioning. However, horses with thin soles, weak walls, or those competing on abrasive rocky terrain often require shoes or protective hoof boots.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1270', 'What causes cracks in horse hooves (quarter cracks / toe cracks)?', 'Cracks are caused by unaddressed wall flaring, severe concussive trauma on hard ground, unbalanced landing angles, coronet band injuries, or prolonged wet-to-dry environmental cycles.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1271', 'Why does hoof growth speed up in the spring and summer?', 'Warmer ambient temperatures increase peripheral blood circulation to the coronary band, while nutrient-rich green pasture provides natural vitamins and amino acids that stimulate rapid keratin production.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-hoof-trimming-schedule_1272', 'What should I do if my horse loses a shoe in the pasture?', 'Inspect the foot for exposed bent nails, gently remove any dangerous nails with pliers, apply a temporary protective hoof boot or duct tape/vetwrap wrap to prevent wall chipping, and call your farrier.', 'horses', 'tool', 'horse-hoof-trimming-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1273', 'How much feed does an adult laying hen eat per day?', 'An average standard-sized laying hen eats approximately 1/4 pound (110 to 120 grams) of complete layer feed per day. A flock of 8 hens will consume roughly 2 pounds of feed daily (one 50 lb bag lasts about 25 days).', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1274', 'What is the difference between chick starter, grower, and layer feed?', 'Chick starter has high protein (20–22%) and low calcium for rapid organ growth. Grower feed has 16–18% protein for steady muscle development. Layer feed contains 16% protein plus high calcium (3.8–4.2%) to build strong eggshells.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1275', 'Why is layer feed dangerous for young chicks under 18 weeks old?', 'Layer feed contains 4% calcium. Because young chicks cannot excrete excess calcium through egg laying, the mineral crystallizes in their kidneys, causing fatal visceral gout and kidney failure.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1276', 'What is the difference between chicken grit and oyster shell?', 'Granite grit consists of insoluble hard stones that stay in the muscular gizzard to grind up food mechanically. Oyster shell is soluble calcium carbonate that dissolves in stomach acid to provide calcium for eggshells.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1277', 'Why shouldn''t chickens eat unlimited scratch grains and corn?', 'Scratch grains and cracked corn are low in protein (7–8%) and high in fat/starch. Feeding more than 10% scratch dilutes their diet, halts egg laying, and causes fatal Fatty Liver Hemorrhagic Syndrome (FLHS).', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1278', 'Are pellets better than crumbles or mash for adult chickens?', 'Pellets are best for adult hens because they reduce waste (chickens cannot pick out favorite grains) and do not blow away in outdoor feeders. Crumbles are easier for bantams and young pullets.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1279', 'Can backyard chickens eat raw kitchen scraps?', 'Yes, chickens can eat most vegetable and fruit scraps, cooked rice, and oatmeal. However, NEVER feed raw potato skins/green potatoes (solanine), avocado skin/pits (persin), raw dry beans (phytohaemagglutinin), or moldy food.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1280', 'How much water does a chicken drink compared to feed?', 'Chickens drink approximately 2 to 3 times more water by weight than feed consumed. A hen eating 1/4 lb of feed drinks 1 to 2 cups of clean water daily, doubling during summer heatwaves.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1281', 'Why do chickens eat their own eggs and how do I stop it?', 'Egg eating starts when an egg accidentally breaks and hens discover the high-protein interior, or due to severe calcium deficiency. Stop it by collecting eggs 2–3 times daily, using slanted roll-away nesting boxes, and placing ceramic decoy eggs in boxes.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-feed-calculator_1282', 'What are the benefits of feeding fermented chicken feed?', 'Fermenting feed in water for 3 days creates beneficial lactic acid bacteria (probiotics), increases nutrient bioavailability, improves gut microbiome health, and reduces flock feed consumption by 15% to 20%.', 'farm', 'tool', 'chicken-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-water-calculator_1283', 'Do they refuse dirty water?', 'Absolutely — refill twice daily in summer or they''ll cut intake.', 'farm', 'tool', 'goat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-water-calculator_1284', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'farm', 'tool', 'goat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-water-calculator_1285', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'farm', 'tool', 'goat-water-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1286', 'Why is copper toxic to sheep but required for goats and cattle?', 'Sheep lack the metabolic liver enzymes required to excrete excess dietary copper. Copper accumulates in the liver until stress triggers a massive release into the blood, destroying red blood cells (hemolytic crisis), causing dark brown urine, jaundice, and rapid death.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1287', 'How much hay does an adult sheep eat per day?', 'An adult sheep eats approximately 2% to 3% of its body weight in dry matter daily. A 150 lb ewe requires 3.5 to 4.5 lbs (1.6 to 2.0 kg) of quality grass hay per day at maintenance.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1288', 'What is Pregnancy Toxemia (Twin Lamb Disease) in pregnant ewes?', 'Pregnancy Toxemia is a metabolic ketosis occurring in late pregnancy when twin or triplet lambs compress the ewe''s stomach while demanding high energy. Without grain supplementation, the ewe burns fat reserves, producing fatal ketones in the liver.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1289', 'Can sheep live on pasture alone without supplemental hay?', 'Yes! High-quality, well-managed rotational pasture easily satisfies 100% of a sheep''s nutritional needs during spring, summer, and early autumn, requiring supplemental hay only when pastures go dormant in winter.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1290', 'What is the best type of hay for sheep?', 'Good quality grass hay (Timothy, Orchard, Brome) or a 20% grass/alfalfa mix is ideal for maintenance and early pregnancy. Pure alfalfa should be reserved for lactating ewes and growing lambs.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1291', 'How much grain should a lactating ewe nursing twin lambs receive?', 'A lactating ewe nursing twins needs roughly 1.5 to 2.0 lbs of a 16% sheep grain ration daily in addition to free-choice quality hay or pasture to support high milk volume.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1292', 'Can sheep eat goat or horse mineral blocks?', 'NEVER feed goat, cattle, or horse mineral blocks to sheep! These contain high levels of copper added for other species that will kill sheep. Only provide certified loose sheep mineral labelled ''No Added Copper''.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1293', 'What is ''flushing'' ewes before breeding season?', 'Flushing is the practice of increasing the ewe''s dietary energy (feeding 0.5–1 lb grain or moving to lush pasture) 2 to 3 weeks before breeding to stimulate higher ovulation rates and increase twin lamb percentages.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1294', 'Why do sheep need free-choice plain salt available 24/7?', 'Pasture and hay are naturally deficient in sodium. Sheep require 0.25 to 0.5 ounces of salt daily to maintain osmotic balance, nerve function, and adequate fluid intake.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sheep-feed-calculator_1295', 'What is milk fever (hypocalcemia) in sheep?', 'Hypocalcemia occurs in late-pregnant or newly lambed ewes when calcium demand for fetal skeleton formation or milk synthesis outpaces dietary intake, causing muscle tremors, weakness, downer ewes, and coma.', 'farm', 'tool', 'sheep-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1296', 'Why do ducklings need extra Niacin (Vitamin B3) compared to chicks?', 'Ducklings grow much faster than chicks and cannot synthesize niacin efficiently. Without 55–70 mg/kg of niacin, ducklings develop crippling bowed legs, enlarged hock joints, slipped tendons, and permanent lameness.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1297', 'How do I supplement niacin for ducklings on standard chick starter?', 'Add 1 tablespoon of human-grade Brewer''s Yeast or Nutritional Yeast per 1 cup of feed, or dissolve 100 mg of plain (non-flush-free) niacin powder per gallon of drinking water until 10 weeks of age.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1298', 'Why must water always be placed directly next to a duck''s feed dish?', 'Ducks take a mouthful of dry pellets and immediately dip their bills into water to lubricate the feed and clear their nostrils (nares). Without water nearby, dry feed packs into the roof of their mouth, causing fatal choking.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1299', 'Can ducklings eat medicated chick starter feed?', 'Modern medicated chick starter containing Amprolium is generally safe for ducklings if dosed correctly. However, older feed containing zoalene or high coccidiostats can be toxic. Non-medicated waterfowl feed is safest.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1300', 'Why should ducks be fed pellets instead of powdery mash feed?', 'Powdery mash feed mixes with duck saliva into a cement-like paste that clogs duck bills and nostrils. Extruded pellets hold together cleanly when dipped into water.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1301', 'How much feed does an adult laying duck eat per day?', 'An adult laying duck (Pekin, Khaki Campbell) eats approximately 1/3 to 1/2 pound (160 to 190 grams) of feed daily—roughly 40% to 50% more feed than a standard laying chicken.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1302', 'What healthy treats can I feed to backyard ducks?', 'Ducks love chopped romaine lettuce, peas (floating in water), kale, cucumbers, tomatoes, live earthworms, mealworms, and duckweed. Never feed bread, crackers, or popcorn (causes ''angel wing'' wing deformities).', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1303', 'What is ''Angel Wing'' (carpal valgus) in young ducks?', 'Angel Wing is a deformity where the wing joint twists outward away from the body during feather growth. It is caused by feeding excessive high-protein diets (>20% past 3 weeks) or feeding junk bread, causing flight feathers to grow too heavy for the young wing joint.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1304', 'Do laying ducks need crushed oyster shell for calcium?', 'Yes! Laying ducks produce larger eggs with thicker shells than chickens and require free-choice crushed oyster shell in a separate dish to support daily eggshell calcification.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_duck-feed-calculator_1305', 'Can ducks eat chicken layer feed?', 'Adult laying ducks can eat 16% chicken layer pellets if supplemented with oyster shell and fresh greens. However, young growing ducklings must never eat layer feed due to toxic high calcium levels.', 'farm', 'tool', 'duck-feed-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1306', 'How much water should a dog drink per day?', 'A healthy dog should drink approximately 1 ounce of water per pound of body weight daily (50 to 60 mL per kg). A 50 lb dog requires roughly 50 ounces (approx. 6 cups) of water daily.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1307', 'Why do domestic cats have a naturally low thirst drive?', 'Cats evolved from desert ancestors who obtained moisture from prey. Cats rarely drink enough standing water from bowls, which is why feeding high-moisture wet canned food is vital for feline kidney health.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1308', 'How do I perform a skin-pinch test to check for pet dehydration?', 'Gently lift the skin over the shoulders and release it. In a well-hydrated animal, the skin snaps back immediately. If it tents and takes 2+ seconds to flatten, your pet is dehydrated.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1309', 'Why are running water fountains beneficial for cats?', 'Cats instinctively avoid stagnant water (associating it with bacterial contamination). Circulating water fountains oxygenate water and stimulate cats to drink significantly more.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1310', 'What does it mean if my pet is suddenly drinking excessive water (polydipsia)?', 'Sudden excessive thirst is a red-flag symptom of serious underlying conditions: diabetes mellitus, chronic kidney disease, Cushing''s disease, pyometra (uterine infection), or hypercalcemia.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1311', 'Can a dog drink too much water (water intoxication)?', 'Yes! Water intoxication (hyponatremia) occurs when dogs bite water repeatedly while swimming or catching hose water, diluting blood sodium and causing lethargy, vomiting, seizures, and brain swelling.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1312', 'How much moisture is in wet canned food vs. dry kibble?', 'Dry kibble contains only 8% to 10% moisture, whereas wet canned food contains 75% to 82% water, providing built-in hydration for kidneys and bladder.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1313', 'How often should pet water bowls be cleaned and refilled?', 'Rinse and refill water bowls daily with fresh cool water, and wash them with soap or in a dishwasher daily to remove slimy bacterial biofilm.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1314', 'What should I do if my dog or cat refuses to drink water?', 'Add warm water or low-sodium bone broth to their food, transition to wet food, offer ice cubes, or switch to a stainless steel water fountain.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-hydration-calculator_1315', 'Why are stainless steel or ceramic water bowls better than plastic?', 'Plastic bowls scratch easily, harboring bacteria that cause feline chin acne and foul odors. Non-porous stainless steel and ceramic bowls are hygienic and easy to sanitize.', 'general', 'tool', 'pet-hydration-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1316', 'What is the 10% treat rule in companion animal nutrition?', 'Treats and training rewards must never exceed 10% of your pet''s total daily caloric allowance (MER). Exceeding 10% dilutes the balanced nutrition of their main food and leads to obesity.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1317', 'How small should dog training treats be?', 'Training treats should be tiny—the size of a green pea (1/4 inch) or grain of rice for small dogs. Small treats can be swallowed instantly without interrupting the training rhythm.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1318', 'What are high-value vs. low-value training treats?', 'Low-value treats are plain kibble used in quiet homes. High-value treats are pungent, moist foods (cooked chicken, hot dogs, string cheese, liver) used for recall in high-distraction environments.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1319', 'How do I prevent my dog from gaining weight during intensive training?', 'Subtract the calories consumed in training treats from your dog''s evening food bowl, or measure out your dog''s daily kibble in the morning and use a portion of it as training rewards.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1320', 'Are freeze-dried single-ingredient meat treats healthy?', 'Yes! Freeze-dried beef liver, salmon, and chicken hearts contain zero fillers, artificial preservatives, or wheat, offering intense natural aroma and high nutritional value.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1321', 'What human foods make great, safe, low-calorie training treats?', 'Small diced apple pieces (no seeds), raw carrot coins, blueberry halves, unseasoned roasted chicken breast, and low-moisture part-skim mozzarella cheese.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1322', 'Why is peanut butter a popular reward, and what ingredient is deadly in it?', 'Peanut butter is aromatic and high-value. However, NEVER use peanut butter containing Xylitol (Birch Bark extract), an artificial sweetener that causes fatal liver failure and hypoglycemia.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1323', 'What is a ''jackpot'' reward in animal training?', 'A jackpot is delivering 4 to 5 pea-sized high-value treats in rapid succession (one after another) to heavily reinforce an exceptional breakthrough, like a perfect recall away from a running squirrel.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1324', 'Can I use lickable squeeze treats for training?', 'Yes! Squeeze tubes filled with wet food, meat baby food (onion/garlic free), or peanut butter allow rapid, controlled micro-licks without overfeeding solid calories.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_training-treat-planner_1325', 'Why does my dog refuse treats outside the house?', 'If a food-motivated dog refuses high-value treats outdoors, they are over their sensory stress threshold (fear, anxiety, or hyper-arousal). Move further away from the trigger to lower stress.', 'general', 'tool', 'training-treat-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1326', 'Do all dogs naturally know how to swim?', 'NO! While retrievers love water, heavy, short-legged, or flat-faced breeds (Bulldogs, Pugs, Basset Hounds, Dachshunds) sink quickly and can drown without a life jacket.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1327', 'How much exercise is 10 minutes of swimming equivalent to on land?', '10 minutes of continuous vigorous swimming provides cardiovascular and muscular exertion equivalent to approximately 30 to 40 minutes of brisk running on land.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1328', 'What is water intoxication (hyponatremia) in swimming dogs?', 'When dogs swallow excessive water while retrieving toys, diluting blood sodium levels and causing staggering, vomiting, dilated pupils, seizures, and brain swelling.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1329', 'Why should dogs wear a canine life jacket when swimming?', 'A life jacket provides buoyancy when a dog gets tired, keeps their head above choppy water, and features a heavy-duty top handle to lift the dog into boats or onto docks.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1330', 'What are the dangers of swimming in natural lakes and rivers?', 'Lethal Blue-Green Algae (cyanobacteria toxins), waterborne parasites (Giardia, Leptospirosis), sharp submerged fishing hooks, and fast river currents.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1331', 'What is ''limber tail'' (swimmer''s tail) in dogs?', 'Acute caudal myopathy caused by muscle strain and cold water at the base of the tail, causing the tail to hang limp and painful for several days after swimming.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1332', 'How do I care for my dog''s ears after swimming?', 'Flush ears immediately with a veterinary drying ear cleanser to evaporate trapped water and prevent painful yeast and bacterial ear infections.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1333', 'Is chlorinated pool water safe for dogs to swim in?', 'Properly balanced pool water is generally safe for swimming, but do not let your dog drink pool water (chlorine causes stomach upset), and rinse their coat with fresh water afterward.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1334', 'How do I introduce a hesitant dog to swimming for the first time?', 'Fit them with a life jacket, walk into a zero-depth calm shoreline on leash, reward with favorite treats, and let them paddle at their own pace without pushing or throwing them in.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-swim-time-calculator_1335', 'Why is hydrotherapy beneficial for dogs with arthritis or hip dysplasia?', 'Water buoyancy supports body weight, allowing dogs to build muscle and flex stiff joints with zero impact on painful arthritic cartilage.', 'dogs', 'tool', 'dog-swim-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1336', 'What is the safest way for a dog to ride in a car?', 'Inside a crash-tested travel crate strapped to cargo tie-downs, or secured in the backseat wearing a Center for Pet Safety (CPS) certified crash-tested safety harness.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1337', 'Why should dogs NEVER ride in the front passenger seat?', 'In a collision, passenger-side airbags deploy at 200 mph with explosive force, causing catastrophic head trauma, broken ribs, and death to a dog sitting in the front seat.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1338', 'Why shouldn''t dogs stick their heads out of open car windows?', 'High-speed road gravel and insects cause severe corneal eye ulcers and blindness, while unexpected turns or sudden braking can cause dogs to fall out into highway traffic.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1339', 'What causes motion sickness in dogs and how do I prevent it?', 'Immature inner ear vestibular systems in young dogs cause nausea. Prevent it with forward-facing restraints, cracking windows for fresh air, withholding food 3 hours before travel, and vet-prescribed Cerenia.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1340', 'How often should I stop for bathroom and water breaks on a road trip?', 'Stop every 2 to 3 hours at safe rest areas to let your dog stretch, drink fresh water from a travel bowl, and take a bathroom break on a secure leash.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1341', 'How fast does a parked car become dangerously hot for a dog?', 'On an 75°F (24°C) day, the temperature inside a car reaches 100°F in just 10 minutes and 120°F in 30 minutes, even with windows cracked, causing fatal heatstroke.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1342', 'What is the Center for Pet Safety (CPS) certification?', 'An independent non-profit scientific organization that rigorously crash-tests pet harnesses, crates, and carriers using dynamic crash-test dog dummies.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1343', 'Can I give my dog Benadryl for car anxiety or motion sickness?', 'Benadryl provides mild sedation, but prescription anti-nausea medications (like Cerenia / maropitant citrate) are far more effective for true motion sickness.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1344', 'What travel supplies should I pack in a dog car road trip kit?', 'Vaccination/Rabies records, fresh water jugs, collapsible silicone bowls, 6-foot leash, poop bags, first aid kit, extra food, calming spray, and a pet seat cover.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-car-travel-planner_1345', 'What should I do if my dog panics during car rides?', 'Practice gradual counter-conditioning: feed high-value meals in a parked car for a week, then take 1-minute trips around the block, slowly building up positive associations.', 'dogs', 'tool', 'dog-car-travel-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1346', 'How long should a visit to the dog park last?', 'Limit visits to 30 to 45 minutes. After 45 minutes, dogs become physically tired and overstimulated, significantly increasing the risk of irritability and fights.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1347', 'What are the signs of healthy dog play vs. bullying?', 'Healthy play features reciprocal role reversals (taking turns chasing/pinning), loose bouncy body language, and play bows. Bullying involves relentless pinning, cornering, and tail-tucked fleeing.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1348', 'Why should small dogs NEVER play in the large dog park area?', 'A running small dog can trigger ''predatory drift'' in high-drive large breeds, causing the large dog to treat the small dog as prey with fatal consequences.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1349', 'What vaccines are required before visiting a dog park?', 'Core DAPP, Rabies, Bordetella (kennel cough), Bivalent Canine Influenza, and Leptospirosis, along with active monthly flea, tick, and heartworm preventatives.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1350', 'How do I safely break up a dog fight at a dog park?', 'NEVER reach for their collars with your bare hands! Use the ''wheelbarrow method'' (grab the aggressor''s hind legs and pull backward), dump water, or place a physical barrier (chair/board) between them.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1351', 'Why shouldn''t I bring food or favorite toys into a dog park?', 'High-value treats and tennis balls trigger intense resource guarding and possessive aggression among unfamiliar dogs.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1352', 'What should I do if another dog is harassing or mounting my dog?', 'Do not wait for a fight. Calmly step in, block the other dog with your body, recall your dog, and leave the park to de-escalate the situation.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1353', 'Are dog parks suitable for every dog?', 'NO! Many adult dogs are dog-selective or dog-intolerant, preferring structured 1-on-1 playdates with familiar dog friends rather than chaotic public dog parks.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1354', 'Can young puppies under 4 months visit dog parks?', 'NO! Young puppies lack full vaccination immunity against lethal Parvovirus and can be traumatized by overbearing adult dogs during their critical fear imprint stage.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-park-visit-tracker_1355', 'Why should I keep moving around the dog park rather than standing still?', 'Walking around keeps the energy flowing and prevents dogs from crowding into stationary pack huddles where territorial scuffles commonly erupt.', 'dogs', 'tool', 'dog-park-visit-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1356', 'How long does it typically take to crate train a puppy?', 'With consistent, positive daily conditioning, most puppies become fully comfortable sleeping in their crate within 1 to 2 weeks.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1357', 'How long can a puppy hold its bladder inside a crate?', 'A general rule of thumb is their age in months plus one hour (e.g., a 2-month-old puppy can hold it for max 2–3 hours during the day).', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1358', 'Why should you NEVER use the crate as a punishment?', 'Using the crate for time-outs creates an aversive fear association. The crate must remain a 100% positive, rewarding den where the dog feels safe and happy.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1359', 'How do I stop my puppy from whining in the crate at night?', 'Keep the crate in your bedroom for the first week, ensure they emptied their bladder, provide a warm heartbeat plush toy (Snuggle Puppy), and avoid rewarding tantrums with attention.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1360', 'What should I put inside a puppy''s crate?', 'A durable chew-proof pad, a safe chew toy (like a rubber KONG stuffed with frozen canned food), and an unwashed t-shirt carrying your familiar scent.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1361', 'Should I let my puppy ''cry it out'' in the crate?', 'Distinguish between minor 5-minute protest whines and genuine panic distress. If a puppy is frantic, biting wire bars, and drooling, let them out—forcing them causes crate phobia.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1362', 'When is it safe to leave a puppy alone in the crate during work hours?', 'Adult dogs can handle 4 to 6 hours, but young puppies under 4 months require a midday break from a dog walker or pet sitter for bathroom relief.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1363', 'How do I teach my dog a verbal cue to enter the crate?', 'Toss a treat into the crate while saying ''Go to bed!'' The moment they step inside, mark with ''Yes!'' and reward. Practice 10 times daily until they enter on cue.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1364', 'Can adult rescue dogs be crate trained?', 'Yes! Adult dogs can be crate trained by taking a slow, patient approach using open-door meal feeding and high-value treats over 2 to 3 weeks.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-crate-training-schedule_1365', 'Should I remove my dog''s collar when crating?', 'YES! Standard flat collars and tags can easily catch on wire mesh bars, posing a severe strangulation hazard. Always remove collars before crating.', 'dogs', 'tool', 'dog-crate-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1366', 'Why do indoor cats love sitting on window perches?', 'Windows provide vital mental enrichment (''Cat TV''). Watching birds, squirrels, and moving leaves stimulates their predatory visual cortex, reducing indoor boredom and depression.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1367', 'Are suction cup window perches safe for heavy cats?', 'Yes, provided you choose high-grade perches with industrial suction cups and steel support cables rated for 40+ lbs. Clean the glass with alcohol before mounting.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1368', 'How much weight should a reliable cat window perch hold?', 'Look for perches rated to hold at least 30 to 50 pounds (14 to 23 kg). This ensures safety when a running cat leaps forcefully onto the platform.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1369', 'What is redirected aggression caused by window viewing?', 'When an indoor cat sees an outdoor stray cat through the window, gets agitated, and lashes out aggressively at a nearby family member or resident cat.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1370', 'How do I attract birds to my cat''s window perch safely?', 'Hang a bird feeder 10 to 15 feet outside the window. This provides dynamic visual stimulation while keeping birds safe from cat attacks behind the glass.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1371', 'Why does my cat make a weird chattering or chirping noise at birds in the window?', 'Chattering is an instinctual predatory vocalization expressing excitement, hunting frustration, or mimicking the lethal neck-bite reflex used on small prey.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1372', 'How do I keep a window perch warm during freezing winter months?', 'Window glass radiates cold. Place an insulated thermal self-warming fleece bed or plug-in pet heating pad on the perch platform.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1373', 'What are the best mounting options if I don''t trust suction cups?', 'Use a structural sill-mounted perch that clamps securely to the wooden window ledge using adjustable metal brackets without drilling.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1374', 'Can direct sun through window perches cause skin cancer in cats?', 'Yes! White cats and cats with light-colored ears/noses are susceptible to solar dermatitis and Squamous Cell Carcinoma (skin cancer) from excessive UV exposure.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-window-perch-guide_1375', 'How wide should a window perch be for a large cat (like a Maine Coon)?', 'Large breeds need a platform measuring at least 14 inches deep by 24 inches wide to stretch out and sleep comfortably.', 'cats', 'tool', 'cat-window-perch-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1376', 'What is a safe rate of weekly weight loss for an overweight cat?', 'Safe, healthy weight loss is 0.5% to 1.5% of total body weight per week (roughly 2 to 4 ounces per week for an overweight 12 lb cat).', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1377', 'Why is rapid crash dieting fatal to overweight cats?', 'Rapid weight loss mobilizes massive fat to the liver, causing Hepatic Lipidosis (Fatty Liver Disease), leading to acute liver failure, jaundice, and death.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1378', 'How do I calculate my cat''s ideal weight and calorie needs?', 'Work with your vet to determine your cat''s ideal weight based on body frame, then calculate calories using the target formula: 0.8 × (70 × Ideal Weight in kg^0.75).', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1379', 'Why is switching to wet canned food effective for cat weight loss?', 'Wet food is high in protein and water (78% moisture) and low in carbohydrates, keeping cats feeling full on fewer calories than energy-dense dry kibble.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1380', 'What should I do if my cat begs constantly for food while on a diet?', 'Divide their daily food into 4 to 5 small meals, use interactive puzzle feeders, add high-fiber plain canned pumpkin, and distract with interactive playtime.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1381', 'How often should I weigh my cat during a weight loss program?', 'Weigh your cat every 2 weeks on a digital baby scale at the exact same time of day and record weights in a chart.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1382', 'What are prescription veterinary weight loss diets (like Hill''s Metabolic or Royal Canin Satiety)?', 'These diets contain specialized high-protein, high-fiber, and L-carnitine formulations that activate natural metabolism and promote satiety while burning fat.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1383', 'Can feline diabetes be cured through weight loss?', 'YES! Many overweight cats with Type 2 Diabetes go into complete clinical diabetic remission (no longer requiring insulin) once they achieve a lean body weight.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1384', 'How much exercise does an overweight cat need daily?', 'Engage your cat in 15 to 20 minutes of active wand toy play, laser games paired with physical toys, and foraging puzzle games every day.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-weight-loss-planner_1385', 'What should I do if my cat''s weight loss plateaus?', 'If weight stays flat for 4 weeks, reduce daily calories by another 5% to 10% under veterinary guidance and increase interactive play sessions.', 'cats', 'tool', 'cat-weight-loss-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1386', 'How do nutritional needs change when a cat becomes a senior?', 'Cats over age 11 absorb protein and fat less efficiently. They need highly digestible, calorie-dense foods with controlled phosphorus to prevent muscle wasting while protecting kidney health.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1387', 'What is sarcopenia in older senior cats?', 'Sarcopenia is the age-related loss of skeletal muscle mass. Senior cats look bony along their spine and hips despite eating normal food amounts.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1388', 'Why is phosphorus control critical in senior cat foods?', 'Excess dietary phosphorus damages aging kidney nephrons. Feeding diets with controlled, lower phosphorus protects kidneys and slows the progression of Chronic Kidney Disease (CKD).', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1389', 'Why do older cats often lose their sense of smell and stop eating?', 'Olfactory scent receptors decline with age. Warming wet canned food in the microwave for 5 seconds enhances aromas and stimulates a senior cat''s appetite.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1390', 'When should a kitten transition from kitten food to adult food?', 'Transition from high-calorie kitten food to adult maintenance food at 10 to 12 months of age (or earlier at 6–8 months post-spay/neuter under veterinary guidance).', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1391', 'What supplements help senior cats with arthritis joint pain?', 'Omega-3 marine fatty acids (EPA and DHA from wild fish oil), green-lipped mussel, and veterinary joint supplements support cartilage and reduce joint inflammation.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1392', 'Why is wet canned food especially vital for senior cats?', 'Senior cats have declining kidney filtration and low thirst drives. High-moisture wet food supplies the critical fluid required to flush toxins through aging kidneys.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1393', 'Can senior cats eat high-protein diets?', 'YES! Unless a cat has advanced Stage 3 or 4 Chronic Kidney Disease, senior cats need high-quality, easily digestible animal protein to prevent muscle wasting.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1394', 'How many times a day should a senior cat be fed?', 'Senior cats thrive on 3 to 4 smaller, easily digestible warm meals throughout the day rather than two large meals.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-age-adjusted-feeding_1395', 'What are prescription renal diets (like Hill''s k/d or Royal Canin Renal)?', 'Prescription diets formulated with strictly restricted phosphorus, moderate high-quality protein, potassium, and omega-3s, clinically proven to double survival time in cats with kidney disease.', 'cats', 'tool', 'cat-age-adjusted-feeding', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1396', 'How long does a standard bird molt last?', 'A typical full seasonal molt lasts between 6 and 10 weeks. Feathers drop in a symmetrical, sequential pattern so the bird never loses its ability to fly in the wild.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1397', 'Why is my bird so irritable, sleepy, and grumpy during a molt?', 'Molting is physically exhausting. Growing hundreds of new feathers increases metabolic demand by up to 30%, and emerging pin feathers make the skin sensitive and itchy, causing temporary moodiness and grumpiness.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1398', 'What should I do if a growing blood feather breaks and bleeds heavily?', 'Apply styptic powder, cornstarch, or flour directly to the bleeding shaft with firm pressure for 2 minutes. If bleeding continues, take the bird to an avian vet immediately to safely pull the broken feather from the follicle using hemostatic forceps.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1399', 'What extra nutrients does a molting bird need?', 'Offer extra protein rich in sulfur amino acids (egg food, sprouted pulses, hemp seeds), bioavailable calcium, dark leafy greens for Vitamin A, and full-spectrum UVB light for Vitamin D3 synthesis.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1400', 'How can I help my bird with itchy pin feathers on its head and neck?', 'Birds cannot reach their own heads. Provide daily warm water mists to soften the keratin sheaths. If your bird trusts you, gently roll the dry, flaky white tips of mature head sheaths between your fingertips to release the feather.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1401', 'What causes abnormal, year-round continuous molting in indoor birds?', 'Erratic artificial indoor lighting (living room lights on until midnight) disrupts the avian endocrine system and thyroid regulation. Enforce a strict 10 to 12 hours of total uninterrupted dark sleep every night to stabilize the molt cycle.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1402', 'Why do new feathers sometimes grow in discolored or with dark stress bars?', 'Stress bars (transverse translucent lines across feathers) indicate a period of acute nutritional deficiency, severe illness, or extreme stress during the hours that specific feather was forming in the follicle.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1403', 'Do birds molt their wing flight feathers all at once?', 'No. Flight feathers molt symmetrically in matched pairs from the inner primaries outward over several months so the bird remains balanced and flighted at all times.', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1404', 'How many times a year do companion birds molt?', 'Most companion birds undergo one major full molt per year (usually post-breeding in late summer/autumn) and one minor molt (shedding body down feathers in spring).', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-molting-tracker_1405', 'What is French Molt in young budgerigars?', 'French Molt is a viral disease caused by Avian Polyomavirus or Circovirus (PBFD) that causes juvenile tail and primary flight feathers to break or shed abnormally, leaving the bird unable to fly (''creeper budgies'').', 'birds', 'tool', 'bird-molting-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1406', 'How many hours of sleep does a companion parrot need every night?', 'Parrots require 10 to 12 hours of total, uninterrupted dark sleep every single night. Because they originate from equatorial regions, 12 hours of darkness matches their natural biological circadian rhythm.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1407', 'Why does covering the cage with a blanket help a bird sleep?', 'Covering the cage with a breathable blackout cage cover blocks out stimulating artificial lights, prevents shadow-induced panic, and signals to the bird''s pineal gland that it is safe to enter deep restorative REM sleep.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1408', 'What are ''night frights'' in cockatiels and how do I prevent them?', 'Night frights are sudden, violent panic attacks where cockatiels thrash wildly in the dark, often breaking blood feathers or wings. They are triggered by shadows, distant headlights, or small noises. A low-wattage dim nightlight in the room prevents night frights.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1409', 'How does excess daylight trigger chronic egg laying in female birds?', 'Long daylight hours (>14 hours) signal the avian pituitary gland that spring has arrived, triggering massive estrogen production and continuous egg laying. Maintaining 12 to 14 hours of strict dark sleep suppresses this hormonal surge.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1410', 'What is a ''sleep cage'' and when should I use one?', 'A sleep cage is a smaller, simple cage placed in a quiet, dark spare bedroom. It is used when the main living room cage cannot be made quiet and dark by 8:00 PM due to human evening activities.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1411', 'Can sleep deprivation cause my bird to scream and bite?', 'Yes! Sleep deprivation is the #1 behavioral cause of chronic biting, territorial lunging, and screaming in parrots. A well-rested bird that gets 12 hours of quiet sleep is calmer and far more cooperative.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1412', 'Is it okay if my bird takes daytime naps?', 'Yes, healthy birds naturally take short 15- to 30-minute catnaps on one leg with their head tucked into their back feathers during the quiet afternoon hours.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1413', 'What fabric is safest for a bird cage night cover?', 'Use breathable, non-toxic natural cotton or specialized blackout bird cage covers. Avoid synthetic fabrics that trap heat, or loose-weave towels with loops that can catch long toenails.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1414', 'Should the television or radio be left on for a bird at night?', 'No. Parrots are prey animals with acute hearing; flickering TV light and unpredictable background noise keep them in a hyper-vigilant state, preventing deep restorative sleep.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule_1415', 'Can shifting sleep hours affect a bird''s annual molt?', 'Yes. Inconsistent light cycles confuse the avian thyroid and endocrine glands, leading to erratic, continuous out-of-season molting and feather degradation.', 'birds', 'tool', 'bird-sleep-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1416', 'How many hours of sleep does a pet bird need each night?', 'Companion parrots need 10 to 12 hours of continuous, uninterrupted darkness every single night. In equatorial wild habitats, night duration is roughly 12 hours year-round.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1417', 'What causes night frights in cockatiels and how can they be stopped?', 'Night frights are sudden panic thrashing episodes triggered by unfamiliar shadows, micro-vibrations, or small rodent sounds in total darkness. Cockatiels have limited night vision and panic easily. Installing a dim nightlight near the floor and running a gentle white noise air purifier prevents night frights.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1418', 'How does sleep duration affect hormonal behavior in parrots?', 'Long daylight hours (>12–14 hours) stimulate the pituitary gland into releasing luteinizing hormone and follicle-stimulating hormone, simulating spring mating season. Enforcing a strict 12- to 14-hour dark sleep schedule naturally suppresses hormonal outbursts, biting, and egg laying.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1419', 'Is covering a bird''s cage with a blanket enough for sleep?', 'Only if the room is quiet and dark. A covered cage in a brightly lit room with a loud television still experiences ambient noise and light bleed, preventing the bird from achieving restorative deep REM sleep.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1420', 'What is a sleep cage and why do avian vets recommend it?', 'A sleep cage is a smaller, simple cage placed in a dark, quiet, low-traffic bedroom. It allows your bird to go to sleep on schedule (e.g., 7:30 PM) even if your household remains active and noisy in the main living space.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1421', 'Can pet birds take naps during the day?', 'Yes, it is completely normal for birds to take one or two 20- to 45-minute naps during the afternoon, typically tucking one leg up and resting their beak backward into their shoulder feathers.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1422', 'What fabric should be used to cover a bird cage?', 'Use tightly woven, 100% breathable natural cotton or dedicated non-toxic blackout cage covers. Never use synthetic fabrics that trap heat or looped terrycloth towels that can catch and snap toenails.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1423', 'Can sudden loud noises harm a sleeping bird?', 'Loud, sudden sounds trigger intense fight-or-flight panic responses. In a cage, panic thrashing can result in fractured wing bones, torn ceres, and hemorrhage from broken growing blood feathers.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1424', 'Should I leave a night light on for all parrot species?', 'Most parrots sleep best in complete pitch darkness. However, cockatiels, juvenile birds, or birds with a history of nocturnal thrashing benefit significantly from a faint, indirect warm nightlight.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-sleep-schedule-calculator_1425', 'How does irregular sleep affect a bird''s annual molt?', 'Erratic day/night light cycles disrupt the thyroid gland''s photoperiodic signals, resulting in prolonged, asymmetrical molting, retained feather sheaths, and dull, brittle plumage.', 'birds', 'tool', 'bird-sleep-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1426', 'What is the maximum safe nitrate level for freshwater aquariums?', 'Below 20 ppm is the ideal target for general community fish, below 10 ppm for sensitive species like Discus and dwarf cichlids, and below 40 ppm as an absolute upper limit.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1427', 'How do I calculate the water change percentage needed to reduce my nitrates?', 'Use the dilution formula: Target = Current × (1 - Change%) + Tap × Change%. To cut nitrates in half with 0 ppm tap water, perform a 50% water change.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1428', 'Why are high nitrate levels dangerous to fish over the long term?', 'Chronic high nitrates cause immunosuppression, organ damage, stunting in young fish, reduced lifespan, and increased susceptibility to bacterial fin rot.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1429', 'What should I do if my tap water already contains high nitrates?', 'If your tap water contains >10–20 ppm nitrates, install an RO/DI (Reverse Osmosis / Deionization) water filtration system or use live emergent riparian plants like Pothos.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1430', 'Can live floating plants like Duckweed and Frogbit remove nitrates?', 'Yes. Floating plants have unlimited access to atmospheric CO2, enabling rapid metabolic growth that absorbs large amounts of dissolved nitrate and phosphate.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1431', 'What is the difference between toxic nitrite (NO2) and nitrate (NO3)?', 'Nitrite (NO2) binds to fish hemoglobin and prevents oxygen transport, making it deadly at 0.5 ppm. Nitrate (NO3) is the much less toxic end-product, safe up to 20 ppm.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1432', 'Why is 0 ppm nitrate undesirable in a planted aquarium?', 'Aquatic plants require nitrogen as a primary macronutrient for leaf growth and chlorophyll. 0 ppm nitrate causes plant starvation, leaf yellowing, and algae blooms.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1433', 'How do specialized anaerobic filter media reduce nitrates into nitrogen gas?', 'Deep within porous ceramic media or deep sand beds, anoxic bacteria consume the oxygen atoms from nitrate (NO3) molecules, converting them into harmless nitrogen gas (N2).', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1434', 'How often should I test nitrate levels in an established aquarium?', 'Test nitrates once weekly before your scheduled water change to verify that your bioload and maintenance schedule are keeping levels below 20 ppm.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aquarium-nitrate-calculator_1435', 'How do high nitrates trigger blue-green algae (cyanobacteria) or black beard algae?', 'Severe macronutrient imbalances—especially high nitrate combined with organic waste and low flow—trigger opportunistic cyanobacteria and nuisance red brush algae.', 'fish', 'tool', 'aquarium-nitrate-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1436', 'Why must activated carbon and Purigen be removed before adding medication?', 'Activated carbon, Purigen, and chemical filter resins rapidly absorb medication molecules out of the water, neutralizing the treatment before it can cure your fish.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1437', 'Why is calculating net water volume critical to prevent fish medication overdosing?', 'Substrate and rock displace 10–20% of tank volume. Dosing for nominal tank volume instead of true net water volume results in an overdose that can poison sensitive fish.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1438', 'Why is extra aeration and air stones necessary during fish medication treatment?', 'Many medications (especially antibiotics, formalin, and dye treatments) reduce the water''s oxygen-carrying capacity. Auxiliary air stones prevent fish asphyxiation.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1439', 'When should I use medicated food instead of treating the water column?', 'Internal parasites (Hexamita, worms, internal bacteria) are treated much more effectively when medication is bound into food using gelatin or binders, delivering medicine directly to the gut.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1440', 'Will antibiotic treatments kill the beneficial bacteria in my aquarium filter?', 'Broad-spectrum antibiotics can damage nitrifying bacteria. It is always safest to treat sick fish with antibiotics in a dedicated bare-bottom hospital tank.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1441', 'How do I safely dose scaleless fish like Loaches, Catfish, and Corydoras?', 'Scaleless fish absorb chemicals rapidly through their skin. Many medications (like formalin or malachite green) should be dosed at half-strength for these sensitive species.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1442', 'Is aquarium salt (NaCl) safe for live plants and freshwater invertebrates?', 'No. Aquarium salt is toxic to live plants and sensitive invertebrates like snails and shrimp. Use salt baths in a separate container rather than treating the main tank.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1443', 'What should I do after completing a multi-day medication treatment cycle?', 'Perform a 30% to 50% water change, vacuum the substrate, and re-insert fresh activated carbon into the filter to clear all residual chemicals from the water column.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1444', 'Can I mix multiple fish medications together safely?', 'Only combine medications that are explicitly documented as compatible (such as the Quarantine Trio). Mixing random medications can cause lethal chemical toxicity.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-medication-dose_1445', 'How does temperature affect medication efficacy during treatment?', 'Warmer water accelerates parasite life cycles (helping treatments kill them faster), but also lowers dissolved oxygen, reinforcing the need for heavy aeration.', 'fish', 'tool', 'fish-medication-dose', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1446', 'Why should adult rabbits not have unlimited access to pellets?', 'Unlimited pellets cause rabbits to fill up on dense, easy calories, making them refuse coarse grass hay. This leads to rapid obesity, overgrown molar teeth that form painful spurs, and life-threatening gastrointestinal stasis.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1447', 'How many tablespoons of pellets should a 4 lb dwarf rabbit eat daily?', 'A 4 lb adult rabbit needs only 1.5 to 2 level tablespoons (approx. 20 to 25 grams) of high-fiber Timothy pellets per day, alongside unlimited grass hay and fresh greens.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1448', 'What is the difference between Timothy-based and Alfalfa-based pellets?', 'Alfalfa pellets are high in protein (16–18%) and calcium (>1.2%), suitable only for growing kits under 6 months. Timothy pellets are high in fiber (>22%) and low in calcium (<0.8%), making them the safe choice for adult rabbits.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1449', 'Why do rabbits go crazy for pellets if they shouldn''t eat many?', 'Pellets are concentrated, calorie-dense, and easy to chew—the rabbit equivalent of junk food. Rabbits instinctively crave high-calorie foods, which is why owners must strictly measure daily portions.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1450', 'What should the first ingredient on a quality rabbit pellet bag be?', 'The first listed ingredient should always be a grass hay (e.g., Timothy Grass Meal or Orchard Grass Meal), never wheat middlings, soybean meal, or corn flour.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1451', 'Can an adult rabbit live completely healthy without any pellets?', 'Yes. An adult rabbit can thrive on a pellet-free diet consisting of unlimited diverse grass hays and a wide variety of fresh dark leafy greens, provided trace micronutrients and Vitamin D are accounted for.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1452', 'How do I reduce pellets for an overweight rabbit safely?', 'Reduce pellet portions gradually by 10% each week while ensuring unlimited fresh 1st and 2nd cut Timothy hay is always available. Weigh your rabbit weekly to ensure weight loss does not exceed 1% to 2% of body mass per week.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1453', 'Why are colorful muesli mixes harmful to rabbits?', 'Muesli mixes allow selective feeding where rabbits eat only the high-fat, high-sugar pieces (corn, seeds, flakes), causing severe tooth decay, nutritional deficiencies, and fatal cecal dysbiosis.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1454', 'Can I feed rabbit pellets to guinea pigs or vice versa?', 'No. Rabbit pellets lack the high stabilized Vitamin C that guinea pigs require, while guinea pig pellets may contain different mineral ratios not formulated for rabbit digestion.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-pellet-calculator_1455', 'Should pellets be fed in a bowl or used for enrichment?', 'Using daily pellets inside foraging toys, snuffle mats, or puzzle boards provides fantastic mental stimulation and slows down rapid eating.', 'small-pets', 'tool', 'rabbit-pellet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1456', 'Why is weekly weight tracking critical for pet rabbits?', 'Rabbits instinctively hide signs of illness to avoid showing weakness to predators. A digital scale detects subtle 3% to 5% weight loss weeks before physical symptoms (like anorexia or lethargy) become visible, allowing for early, life-saving veterinary intervention.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1457', 'What type of scale is best for weighing a rabbit?', 'A digital kitchen scale or baby scale with a flat platform that measures accurately in 1-gram or 0.1-ounce increments is ideal. Bathroom scales are far too imprecise for small animals.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1458', 'How much weight loss in a rabbit indicates an emergency?', 'A sudden weight loss of greater than 5% of body weight in 7 to 10 days (or any continuous downward trend over 3 consecutive weeks) is a major medical red flag requiring prompt exotic veterinary diagnostics.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1459', 'What is the Body Condition Score (BCS) system for rabbits?', 'BCS is a 1-to-5 tactile scale: 1 is emaciated (sharp spine and hip bones with no fat), 3 is ideal (ribs easily felt under a smooth thin fat layer with no sharp protrusions), and 5 is obese (thick fat deposits, prominent dewlap, ribs impossible to palpate).', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1460', 'Why do rabbits lose weight when their teeth are overgrown?', 'Overgrown molar spurs cause painful cuts and ulcers on the tongue and cheeks. The rabbit slowly reduces coarse hay chewing because it hurts, resulting in steady caloric decline and progressive weight loss.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1461', 'Can seasonal molting cause slight weight fluctuations?', 'Yes. Major seasonal coat sheds can cause temporary metabolic fluctuations of 1% to 2%, but any persistent loss exceeding 3% is abnormal and warrants veterinary attention.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1462', 'What should I do if my senior rabbit is gradually losing muscle mass?', 'Have an exotic veterinarian perform an oral exam, blood chemistry panel (checking BUN, creatinine, ALT), and urinalysis to check for chronic kidney disease, arthritis, or dental issues.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1463', 'Why is rapid weight loss in an obese rabbit dangerous?', 'When an overweight rabbit suddenly stops eating or loses weight too rapidly, mobilized body fat floods the liver, causing hepatic lipidosis (fatty liver disease)—a life-threatening metabolic crisis.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1464', 'How can I safely weigh a nervous or squirmy rabbit?', 'Place your rabbit inside a familiar high-sided cardboard box or pet carrier on the scale, record the combined weight, let the rabbit out, and subtract the empty container''s weight.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_rabbit-weight-tracker_1465', 'How does spaying or neutering affect a rabbit''s weight?', 'Spaying and neutering slightly reduces basal metabolic rate by removing hormonal stress. Monitor weight closely post-surgery and adjust pellet portions down if the rabbit begins gaining excess fat.', 'small-pets', 'tool', 'rabbit-weight-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1466', 'How much fresh food should a guinea pig get every day?', 'Each adult guinea pig should receive approximately 1 packed cup (about 100 grams) of fresh, washed vegetables daily, with sweet bell peppers and low-calcium leafy greens making up the majority.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1467', 'Why do guinea pigs need Timothy hay instead of Alfalfa hay?', 'Alfalfa hay is a legume packed with excess calcium and protein. In adult guinea pigs over 6 months old, high calcium causes thick bladder sludge and painful calcium carbonate bladder stones. Timothy grass hay provides the ideal low-calcium, high-fiber balance.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1468', 'How many pellets should an adult guinea pig eat daily?', 'An adult guinea pig needs only 1/8 cup (approx. 25 grams) of plain, Timothy-based, stabilized Vitamin C pellets per day. Overfeeding pellets causes obesity and reduces vital hay consumption.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1469', 'Can guinea pigs eat celery?', 'Yes, but celery should always be sliced into small 1/4-inch pieces. Long, unbroken celery strings can tangle around teeth or cause esophageal and intestinal blockages.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1470', 'Why is white, powdery residue left behind when guinea pig urine dries?', 'A small amount of white powdery residue is normal excreted calcium carbonate. However, if the residue is thick, gritty like wet sand, or the pig squeaks in pain while urinating, reduce high-calcium veggies immediately and consult an exotic vet for bladder sludge.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1471', 'Can guinea pigs eat commercially sold yogurt drops or seed sticks?', 'No. Guinea pigs are strict herbivores and cannot digest dairy or high-fat seeds. Commercial yogurt drops and honey seed sticks disrupt gut bacteria and can cause fatal cecal dysbiosis.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1472', 'What should I do if my guinea pig stops eating for 12 hours?', 'A guinea pig that stops eating for 12 hours is in a critical medical emergency (GI Stasis). Their digestive tract can shut down rapidly. Keep them warm and take them to an exotic veterinarian immediately for fluid therapy and gut motility medication.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1473', 'How much water does an average guinea pig drink in 24 hours?', 'An average adult guinea pig drinks between 100 and 200 ml of fresh water daily. Pigs fed water-rich fresh greens (like cucumber and romaine) may drink slightly less from their water bottle.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1474', 'Why do guinea pigs eat their own soft poops?', 'Guinea pigs produce specialized soft, nutrient-rich fecal pellets called cecotropes. Eating them directly from the anus (caecotrophy) allows them to digest and absorb synthesized B-vitamins, amino acids, and essential bacterial proteins.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_guinea-pig-food-calculator_1475', 'At what age should a baby guinea pig switch from Alfalfa to Timothy pellets?', 'Young guinea pigs should transition from Alfalfa pellets to adult Timothy-based pellets at 6 months of age, when skeletal bone growth stabilizes.', 'small-pets', 'tool', 'guinea-pig-food-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1476', 'How often do reptiles shed their skin (ecdysis)?', 'Shedding frequency depends on age and growth rate. Hatchlings and babies shed every 2 to 4 weeks; rapidly growing juveniles shed every 4 to 6 weeks; and mature adults shed every 6 to 12 weeks for skin maintenance.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1477', 'What are the 5 biological stages of a reptile shed cycle?', 'Stage 1: Normal vibrant skin. Stage 2: Dull skin (colors fade, belly scales turn pink). Stage 3: Blue/Opaque phase (eyes become milky/cloudy as lymph fluid separates old skin). Stage 4: Cleared phase (eyes turn clear again 24–48h before shedding). Stage 5: Active slough (the reptile rubs its snout and removes the old skin).', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1478', 'Why should you never feed a snake when its eyes are opaque ''blue''?', 'During the blue phase, the milky lymph fluid between the old and new spectacle scales impairs the snake''s vision, making it feel vulnerable and defensive. Offering prey often triggers refusal, defensive strikes, or high-stress regurgitation.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1479', 'Why do leopard geckos and crested geckos eat their shed skin?', 'Keratophagy (eating shed skin) serves two survival purposes: it allows the gecko to recycle valuable proteins, calcium, and nutrients stored in the old epidermal layer, and it erases scent trails that would attract predators in the wild.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1480', 'How do I safely treat a stuck shed (dysecdysis)?', 'Never forcibly yank dry stuck shed, as it tears new delicate scales beneath. Place the reptile in a ventilated plastic tub lined with warm (85°F / 30°C), wet paper towels for 20–30 minutes, then gently massage the loosened skin off using a wet cotton swab.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1481', 'What is a retained eye cap (spectacle) and how is it removed?', 'A retained spectacle occurs when the clear scale over the snake''s eye fails to shed. Increase humidity and provide a humid hide. If it remains stuck after the next cycle, place a drop of sterile saline on the eye to soften it. Never use tweezers directly on the eye.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1482', 'Why is stuck shed dangerous on a lizard''s toes and tail tip?', 'As the reptile grows, layers of unshed skin dry, harden, and shrink into tight constrictive bands. This cuts off arterial blood circulation, leading to avascular necrosis and permanent loss of toes and tail tips.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1483', 'What causes incomplete or patchy shedding in snakes?', 'The #1 cause is low ambient humidity in the enclosure. Other causes include dehydration, lack of rough surfaces (cork bark/rocks) to rub against, external mites, or inadequate Vitamin A in the diet.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1484', 'Should I pull shed skin off my bearded dragon?', 'No. Bearded dragons shed in large separate flakes and patches. Pulling pieces that have not naturally detached can tear live epithelial tissue, cause bleeding, and introduce bacterial skin infections.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1485', 'How does a humid hide prevent shedding problems?', 'A humid hide (plastic container packed with damp sphagnum moss) creates a localized 80%+ microclimate. Your pet can enter voluntarily to soften its outer stratum corneum layer, ensuring an effortless, one-piece shed.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1486', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-shedding-tracker_1487', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-shedding-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1488', 'What is the 1.0x snake length enclosure welfare standard?', 'Modern veterinary and herpetological welfare standards (such as ARAV and UK RSPCA guidelines) require that the length of the vivarium must be at least 1.0× the total body length of the snake, allowing the snake to fully stretch out along the front glass without bending.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1489', 'Why is the old ''Length + Width = Snake Length'' rule outdated?', 'The old ''L + W'' rule forced snakes to stay permanently coiled, leading to spinal kinks, lack of cardiovascular exercise, muscle atrophy, and severe obesity. Modern welfare guidelines mandate full rectilinear stretching room.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1490', 'What is the minimum tank size for an adult Ball Python?', 'An adult ball python (3.5 to 5.0 ft) requires a minimum 48 × 24 × 24 inch (120 gallon / 4×2×2 ft) enclosure with 8 sq ft of floor area and solid PVC construction to maintain 60–75% humidity.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1491', 'Why are solid PVC enclosures better for snakes than glass fish tanks?', 'Glass aquariums with screen mesh tops bleed heat and humidity rapidly. PVC enclosures have excellent thermal insulation, retain moisture without warping, and have opaque side and back walls that make snakes feel secure from predators.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1492', 'Do arboreal and semi-arboreal snakes need vertical height?', 'Yes. Species like Green Tree Pythons, Amazon Tree Boas, Carpet Pythons, and Corn Snakes utilize vertical space heavily. They require tall vivariums (minimum 24 to 48 inches high) with sturdy climbing perches and elevated basking shelves.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1493', 'How deep should the substrate layer be in a snake vivarium?', 'Burrowing and fossorial species (Kenyan Sand Boas, Western Hognoses) require 3 to 5 inches of loose substrate. Semi-terrestrial species (Ball Pythons, Kingsnakes) need a 2 to 3 inch layer of coconut husk, cypress mulch, or aspen.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1494', 'Can an enclosure be too large for a baby snake?', 'An enclosure is never too large, but it can be too empty. In the wild, baby snakes thrive in open nature. In captivity, a large enclosure is completely safe as long as it is densely packed with fake plants, leaf litter, and multiple snug hides.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1495', 'How many hides does a snake need in its tank?', 'Every snake enclosure must have at least 2 identical, snug hides with a single entrance — one placed in the hot basking zone (88–92°F) and one in the cool zone (75–80°F). This prevents the snake from having to choose between feeling secure and thermoregulating.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1496', 'How do I calculate substrate volume in liters for my snake tank?', 'Multiply Tank Length (in) × Tank Width (in) × Desired Depth (in), then divide the cubic inches by 61.02 to convert to Liters. For example, a 48 × 24 in tank with a 2-inch layer requires approximately 38 Liters of substrate.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1497', 'Why are escape-proof locks mandatory on snake enclosures?', 'Snakes are pure muscle and natural escape artists. They will test every seam, sliding door, and screen corner with their snout. Always use sliding glass locks or heavy-duty locking latches on all vivarium doors.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1498', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_snake-tank-size-calculator_1499', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'snake-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1500', 'How much does the average horse owner spend on supplements per year?', 'The average horse owner spends between $600 and $2,400+ per horse annually on supplements, with joint and digestive health supplements representing the largest recurring expenses.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1501', 'How much money can I save by buying equine supplements in bulk?', 'Purchasing large 10kg to 20kg bulk pails instead of small 30-day retail tubs saves between 25% and 35% on the per-serving cost, resulting in $300 to $600+ in annual savings per horse.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1502', 'What is the danger of overlapping multiple equine supplements?', 'Feeding multiple fortified feeds and supplements can cause toxic mineral overdoses. Excessive selenium causes mane/tail loss and hoof sloughing, while inverted calcium-to-phosphorus ratios cause bone demineralization.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1503', 'Do joint supplements really work for horses with arthritis?', 'High-quality joint supplements containing therapeutic levels of Glucosamine (10,000 mg), Chondroitin (2,000–5,000 mg), MSM (10,000 mg), and Hyaluronic Acid show measurable clinical benefits in reducing joint inflammation and stiffness.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1504', 'How long does it take for a hoof supplement (Biotin) to work?', 'Hoof supplements take 6 to 9 months to show visible results. Biotin only affects new hoof wall forming at the coronary band; it takes nearly a year for that new, stronger tissue to grow down to the weight-bearing ground surface.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1505', 'What should I look for on an equine electrolyte label?', 'Ensure the first ingredient is Sodium Chloride, followed by Potassium Chloride. Avoid cheap electrolytes where sugar (dextrose, sucrose) is the primary ingredient.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1506', 'Can a ration balancer replace multiple individual supplements?', 'Yes! A high-quality ration balancer provides concentrated protein, amino acids, vitamins, and trace minerals for about $1.00/day, often eliminating the need for separate multivitamin and coat supplements.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1507', 'Why is natural Vitamin E (d-alpha-tocopherol) better than synthetic?', 'Natural Vitamin E (d-alpha-tocopherol) has up to double the biological activity and cellular absorption rate of synthetic Vitamin E (dl-alpha-tocopherol), making it essential for horses on dry hay diets.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1508', 'How should bulk supplements be stored in the barn?', 'Store supplements in sealed, airtight plastic containers in a cool, dry feed room away from direct sunlight, moisture, and rodents to prevent active ingredients from oxidizing.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-supplement-cost_1509', 'What is the best way to feed powdered supplements to picky horses?', 'Mix powders with a small amount of warm water, unsweetened applesauce, pure pumpkin puree, or a splash of corn oil or wheat germ oil to adhere the powder to pellets.', 'horses', 'tool', 'horse-supplement-cost', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1510', 'How many nesting boxes do I need for my chicken flock?', 'The standard ratio is 1 nesting box for every 4 to 5 laying hens. For example, a flock of 8 to 10 hens requires 2 to 3 nesting boxes. Providing too many boxes encourages hens to sleep and poop inside them.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1511', 'Why should nesting boxes always be mounted lower than roosting bars?', 'Chickens instinctively sleep on the highest point in the coop. If nesting boxes are higher than roosts, hens will sleep inside the boxes overnight, filling the nesting straw with feces and contaminating eggs with bacteria.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1512', 'What are the ideal dimensions for a chicken nesting box?', 'For standard breeds (Rhode Island Reds, Leghorns), boxes should measure 12 inches wide by 12 inches deep by 12 inches high. Heavy breeds (Brahmas, Orpingtons) need 14x14x14 inches, while bantams need 10x10x10 inches.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1513', 'How high off the ground should chicken nesting boxes be mounted?', 'Mount nesting boxes 18 to 24 inches off the coop floor. This keeps boxes away from floor drafts and bedding litter while providing shaded, secure privacy for laying hens.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1514', 'What is a roll-away nesting box and why is it beneficial?', 'A roll-away box features a gently sloped floor (5–7° angle) that rolls freshly laid eggs forward into a protected collection compartment, keeping eggs spotless and completely eliminating egg-eating habits.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1515', 'What is the best nesting material to put inside nest boxes?', 'Clean, kiln-dried medium pine shavings, fresh oat straw, or washable synthetic turf/aspen nesting pads are best. Avoid hay, which molds quickly when damp.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1516', 'Why do all my hens fight over and use the exact same nesting box?', 'Chickens are flock animals that associate a single safe nesting box with successful egg laying. Even with 5 identical boxes, hens will queue up and lay in the same favorite box. This is completely normal behavior.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1517', 'How do I stop hens from laying eggs on the coop floor or in the run?', 'Place ceramic dummy eggs or golf balls in the nesting boxes, ensure boxes are dark and private, block off dark coop floor corners with bricks, and keep hens locked in the coop until mid-morning.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1518', 'How often should nesting box bedding be cleaned and replaced?', 'Inspect boxes daily. Spot-clean soiled shavings immediately and replace all nesting bedding completely once a month (or immediately if an egg breaks) to prevent bacterial growth.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chicken-nesting-box-count_1519', 'Why do chickens prefer dark, shaded nesting boxes?', 'In the wild, hens hide their nests in dense underbrush to protect eggs from aerial and ground predators. Dark, enclosed boxes give hens a psychological feeling of security during vulnerable oviposition.', 'farm', 'tool', 'chicken-nesting-box-count', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1520', 'How much does an average routine vet visit cost?', 'A routine wellness exam typically costs between $55 and $95 for the physical examination, plus $100 to $200 for annual core vaccines, heartworm blood tests, and fecal parasite checks.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1521', 'Why are emergency vet visits significantly more expensive than regular visits?', '24/7 emergency hospitals maintain continuous overnight staffing of licensed doctors, trauma technicians, in-house laboratory analyzers, surgical suites, and intensive care oxygen units.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1522', 'How much does dog or cat dental cleaning cost?', 'Professional dental cleaning under general anesthesia ranges from $450 to $1,400. The cost varies based on pre-anesthetic bloodwork, dental X-rays, and whether tooth extractions are required.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1523', 'What diagnostic tests are included in a senior pet blood panel?', 'A comprehensive senior panel includes a Complete Blood Count (red/white blood cells), Chemistry Profile (liver enzymes, kidney BUN/creatinine, blood glucose), electrolytes, and a complete urinalysis.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1524', 'Can I get a written prescription from my vet to buy medications online?', 'Yes. By law in most jurisdictions, veterinarians must provide a written portable prescription upon request if they have an active, valid Veterinary-Client-Patient Relationship (VCPR).', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1525', 'What should I do if I cannot afford my pet''s emergency surgery bill?', 'Ask about veterinary payment plans (CareCredit, Scratchpay), contact local non-profit animal charities, explore university veterinary teaching hospital funds, or discuss modified palliative treatment options.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1526', 'How often should adult dogs and cats have a veterinary checkup?', 'Healthy adult pets (ages 1–7) need an annual comprehensive physical exam. Senior pets (age 8+) should be examined every 6 months to detect organ decline early.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1527', 'Why does anesthesia increase the cost of dental and surgical procedures?', 'General anesthesia requires pre-operative blood screening, dedicated intravenous catheter fluids, endotracheal intubation, continuous multi-parameter vital sign monitoring (ECG, SpO2, blood pressure), and recovery technician supervision.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1528', 'Are low-cost spay/neuter clinics safe?', 'Yes. High-volume low-cost spay/neuter clinics employ experienced surgeons who perform hundreds of sterilizations monthly, keeping overhead low through non-profit donor subsidies.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vet-visit-cost-estimator_1529', 'What is a Veterinary-Client-Patient Relationship (VCPR)?', 'A VCPR is a legal medical standard requiring a veterinarian to physically examine your pet in person within the past 12 months before prescribing medications or providing specific medical diagnoses.', 'general', 'tool', 'pet-vet-visit-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1530', 'How much does professional dog grooming cost?', 'Costs range from $45 to $65 for small short-haired dogs (Bath & Brush), $65 to $95 for double-coated shedding breeds, and $80 to $140+ for large continuous-growth curly breeds (Doodles, Poodles).', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1531', 'How often should a Doodle or Poodle mix be professionally groomed?', 'Doodles require professional grooming and haircuts every 4 to 6 weeks, combined with thorough daily line-brushing down to the skin at home to prevent severe matting.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1532', 'Why should double-coated dogs (Huskies, Shepherds) NEVER be shaved?', 'Shaving double-coated breeds destroys their natural insulation against heat and cold, causes patchy coat regrowth (post-clipping alopecia), and increases the risk of severe sunburn and heatstroke.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1533', 'What is ''line brushing'' and how is it done properly?', 'Line brushing involves parting the fur with one hand and brushing a small section from the skin outward with a slicker brush, followed by a metal greyhound comb to verify zero hidden mats.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1534', 'Why do groomers charge extra for matted dogs?', 'Shaving dense mats requires slow, precision blade work under high-risk conditions to avoid cutting fragile, pulled skin, while dulling expensive grooming clipper blades rapidly.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1535', 'What are anal glands and do all dogs need them expressed?', 'Anal glands are scent sacs located at the 4 and 8 o''clock positions around the anus. Healthy dogs express them naturally when defecating; only express them if a dog scoots or licks excessively.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1536', 'How often should a dog''s nails be clipped?', 'Nails should be trimmed or ground with a Dremel every 2 to 4 weeks. Nails should not touch the floor when standing erect.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1537', 'Can domestic cats be professionally groomed?', 'Yes. Long-haired cats (Persians, Maine Coons) benefit from professional sanitary trims, de-shedding treatments, or full ''Lion Cuts'' to eliminate painful hairballs and matting.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1538', 'How much should I tip my pet groomer?', 'Tipping 15% to 20% of the total grooming service is standard etiquette for groomers who handle your pet safely, patiently, and compassionately.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-grooming-cost-estimator_1539', 'What is the difference between a mobile groomer and a salon?', 'Mobile groomers bring a customized grooming van directly to your driveway, offering one-on-one cage-free service for an additional $20–$40 convenience premium.', 'general', 'tool', 'pet-grooming-cost-estimator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1540', 'What pet symptoms require immediate 24/7 emergency veterinary care?', 'Difficulty breathing, non-productive retching with bloated belly, male cats unable to urinate, pale white gums, seizures lasting > 3 minutes, sudden back leg paralysis, and severe trauma.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1541', 'Why is a male cat straining in the litter box a medical emergency?', 'Male cats have a narrow urethra that easily plugs with crystals or mucous plugs. An obstructed bladder cannot void toxins, causing fatal potassium toxicity and bladder rupture within 24 to 48 hours.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1542', 'What does gum color reveal about a pet''s health?', 'Bubblegum pink is healthy. White gums indicate blood loss or shock; brick red indicates heatstroke or sepsis; yellow indicates liver disease or anemia; blue/purple indicates severe oxygen deprivation.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1543', 'How do I count my pet''s resting respiratory rate?', 'When your pet is asleep, count the number of times the chest rises and falls in 30 seconds, then multiply by 2. A normal resting rate is 15 to 30 breaths/min. Over 35 breaths/min warrants an urgent vet check.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1544', 'What should I do if my dog is vomiting?', 'A single episode of vomiting with normal energy can be monitored with a 6-hour food rest followed by a bland diet. Repeated vomiting, vomiting with lethargy, or projectile vomiting requires immediate veterinary care.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1545', 'What is GDV (Bloat) in dogs and how do I spot it?', 'Gastric Dilation-Volvulus is a life-threatening twisting of the stomach in deep-chested dogs. Symptoms: unproductive dry heaving, enlarged hard abdomen, restlessness, and excessive drooling.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1546', 'Is a dry, warm nose a sign that a dog is sick?', 'No. A dog''s nose temperature fluctuates naturally with room humidity, sleep, and weather. Use a digital rectal thermometer to accurately check body temperature (normal: 100.0°F to 102.5°F).', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1547', 'What are the early signs of pain in cats?', 'Cats hide pain. Signs include hiding in closets, squinting eyes, unkempt coat, refusing to jump onto furniture, growling when touched, and urinating outside the litter box.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1548', 'What should I do if my pet has a seizure?', 'Stay calm, move sharp furniture away, do NOT put your hands in their mouth (pets cannot swallow their tongues), dim lights, record a video for your vet, and transport to an ER if the seizure lasts > 3 minutes.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-symptom-checker_1549', 'When is diarrhea considered a veterinary emergency?', 'Seek immediate care if diarrhea contains significant dark red blood or black tarry stool (melena), is accompanied by severe lethargy and vomiting, or occurs in an unvaccinated puppy/kitten.', 'general', 'tool', 'pet-symptom-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1550', 'How can I identify an unknown pet pill found on the floor?', 'Examine the pill''s debossed letters/numbers, color, and geometric shape. Match these markings in an FDA drug database or call your veterinary clinic or pharmacy with the exact imprint code.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1551', 'Why are flavored veterinary chewables dangerous if left on counters?', 'Chewable medications are formulated with delicious liver or beef flavors. Dogs view the whole bottle as a treat bag and will ingest dozens of pills at once, causing fatal organ overdoses.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1552', 'Can I give my pet a pill that was prescribed for a human?', 'NEVER administer human medications without explicit veterinary approval. Many human formulations contain toxic inactive sweeteners (like Xylitol) or dangerous dosage strengths.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1553', 'What is the difference between Carprofen (Rimadyl) and human Ibuprofen?', 'Carprofen is an FDA-approved veterinary NSAID with a safe metabolic clearance in dogs. Human Ibuprofen destroys the canine stomach lining and causes acute kidney failure within hours.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1554', 'How should prescription pet medications be stored safely?', 'Store medications in a high, childproof locked cabinet at controlled room temperature (68°–77°F), away from direct sunlight, moisture, and curious jumping pets.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1555', 'Can veterinary medications expire, and are expired pills dangerous?', 'Yes. Expired medications lose chemical potency and efficacy. Liquid antibiotics degrade rapidly, while degraded tetracyclines can cause kidney damage. Dispose of expired drugs properly.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1556', 'What should I do if I accidentally give my dog the cat''s medication?', 'Contact your veterinarian or the Pet Poison Helpline immediately. Dog flea/tick medications containing permethrin are lethal to cats, requiring immediate decontamination.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1557', 'What is Gabapentin used for in dogs and cats?', 'Gabapentin is a versatile veterinary medication used to manage neuropathic nerve pain, manage seizures, and provide gentle sedation for vet visit anxiety in cats and dogs.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1558', 'Why shouldn''t I flush unused pet medications down the toilet?', 'Flushing pharmaceuticals contaminates public water supplies, rivers, and aquatic ecosystems. Use dedicated pharmacy drug take-back boxes or mix crushed pills with used coffee grounds in sealed trash.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-pill-identifier_1559', 'What is Clavamox (Amoxicillin-Clavulanate) prescribed for in pets?', 'Clavamox is a broad-spectrum potentiated antibiotic commonly prescribed to treat bacterial skin infections, urinary tract infections, dental abscesses, and wound infections in dogs and cats.', 'general', 'tool', 'pet-pill-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1560', 'Why is chocolate toxic to dogs and which type is most dangerous?', 'Chocolate contains theobromine and caffeine, which dogs metabolize very slowly. Cocoa powder and dark baker''s chocolate contain the highest theobromine levels, causing tremors, seizures, and heart arrhythmias.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1561', 'Why are all true lilies (Lilium species) fatal to cats?', 'True lilies (Easter, Tiger, Daylilies) contain an unknown water-soluble toxin. Ingestion of a single leaf, petal, or licking pollen off fur causes acute, irreversible kidney failure within 24 to 72 hours.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1562', 'What is Xylitol (Birch Bark extract) and why is it deadly to dogs?', 'Xylitol is an artificial sweetener in sugar-free gum, peanut butter, and baked goods. In dogs, it triggers a massive insulin surge causing severe hypoglycemia (seizures/coma) and acute liver failure.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1563', 'Why are grapes and raisins toxic to dogs?', 'Grapes and raisins contain high concentrations of tartaric acid. In susceptible dogs, even a small handful triggers acute, sudden kidney failure.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1564', 'Should I induce vomiting with hydrogen peroxide if my dog eats poison?', 'Never induce vomiting without calling a vet or poison hotline first. Corrosive chemicals, petroleum products, or foreign objects cause severe esophageal burns or airway choking if vomited back up.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1565', 'What happens if a pet eats anticoagulant rat poison?', 'Anticoagulant rodenticides inhibit Vitamin K1 recycling, halting blood clotting. Pets bleed internally into lungs and abdomen 3 to 7 days after ingestion. Antidote: prescription Vitamin K1 therapy for 30 days.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1566', 'Are onions and garlic dangerous for dogs and cats?', 'Yes. All Allium plants (onions, garlic, leeks, chives) contain N-propyl disulfide, which damages red blood cell hemoglobin, causing hemolytic anemia (Heinz body anemia).', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1567', 'What is the Pet Poison Helpline phone number?', 'The 24/7 Pet Poison Helpline is (855) 764-7661 and the ASPCA Animal Poison Control Center is (888) 426-4435 (consultation fees apply).', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1568', 'Why are essential oil diffusers dangerous around cats?', 'Cats lack the liver enzyme glucuronyl transferase to metabolize concentrated phenols and terpenes. Diffusing tea tree (melaleuca), eucalyptus, or peppermint oils causes respiratory distress and liver failure.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-poison-lookup_1569', 'What is the emergency veterinary treatment for chocolate or toxin ingestion?', 'Veterinarians administer IV apomorphine to safely induce rapid vomiting, followed by activated charcoal with sorbitol to bind remaining toxins in the GI tract, and supportive IV fluids.', 'general', 'tool', 'pet-poison-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1570', 'What vaccines are legally mandatory for dogs and cats?', 'Rabies vaccination is required by law in almost all states and municipalities due to its 100% fatal zoonotic transmission to humans.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1571', 'Why do puppies need 3 to 4 booster shots for Distemper and Parvo?', 'Maternal antibodies from mother''s milk neutralize vaccines at unpredictable rates between 6 and 16 weeks. Staggered boosters ensure the puppy develops active immunity the moment maternal antibodies drop.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1572', 'How long is a rabies vaccine certificate valid?', 'The first rabies vaccine given at 12–16 weeks is valid for 1 year. All subsequent booster shots are certified for 3 full years under standard veterinary vaccine formulations.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1573', 'What is the DAPP / DHPP 5-in-1 combination vaccine for dogs?', 'It protects against Canine Distemper, Adenovirus-1 (Infectious Hepatitis), Adenovirus-2 (respiratory), Parvovirus, and Parainfluenza in a single injection.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1574', 'What is the FVRCP vaccine for cats?', 'It is the core feline vaccine protecting against Feline Viral Rhinotracheitis (Herpesvirus-1), Calicivirus (oral ulcers/respiratory), and Panleukopenia (Feline Distemper).', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1575', 'How often should an adult dog receive the Leptospirosis vaccine?', 'The Leptospirosis vaccine requires an annual booster because bacterial bacterin vaccines stimulate shorter antibody durations than viral modified-live vaccines.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1576', 'What is an antibody titer test?', 'A blood test measuring protective antibodies against Parvovirus and Distemper. If titers are positive, your dog has active immunity and does not need an immediate booster.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1577', 'What are the common mild side effects after pet vaccinations?', 'Mild tiredness, slight soreness at the injection site, and a reduced appetite for 24 hours are normal immune activation responses.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1578', 'Can my puppy go on walks before finishing all vaccine rounds?', 'Keep puppies in private fenced yards until 1 to 2 weeks after their final 16-week vaccine round to avoid lethal Parvovirus contaminated in public soil and dog parks.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-vaccine-schedule-generator_1579', 'What is the Canine Influenza Virus (CIV) vaccine and who needs it?', 'It is a bivalent vaccine protecting against H3N2 and H3N8 flu strains. Highly recommended for dogs frequenting boarding kennels, dog shows, daycare, and grooming facilities.', 'general', 'tool', 'pet-vaccine-schedule-generator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1580', 'How do I find the nearest 24-hour emergency vet clinic?', 'Use online veterinary locators, check your primary vet''s after-hours answering service message, or search for VECCS-accredited 24/7 veterinary specialty centers in your region.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1581', 'Why should I call the emergency vet clinic before driving over?', 'Calling ahead allows the medical team to prepare emergency oxygen, trauma beds, and blood transfusion kits in advance, while confirming they have open ICU capacity.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1582', 'What should I bring with me to an emergency vet visit?', 'Bring your pet securely restrained (in a carrier or on a leash), any ingested poison packaging/bottles, your pet''s medication history, and a valid photo ID and credit card.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1583', 'How does emergency veterinary triage prioritize patients?', 'Emergency clinics see patients based on medical urgency, not arrival time. Pets with respiratory collapse, severe trauma, or active seizures are treated before stable ear infections.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1584', 'How much does an emergency vet examination fee cost?', 'Emergency intake exam fees typically range from $125 to $250, excluding subsequent diagnostic blood tests, radiographs, medications, and hospitalization.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1585', 'What is a VECCS Level 1 Emergency Veterinary Hospital?', 'It is the highest level of emergency accreditation certified by the Veterinary Emergency and Critical Care Society, requiring 24/7 board-certified specialists, ICU ventilators, and advanced imaging.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1586', 'How do I safely transport an injured, biting dog to the emergency clinic?', 'Injured animals bite out of pain. Wrap the dog gently in a thick blanket or towel, support the spine on a flat board or rigid carrier, and avoid placing pressure on the neck or abdomen.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1587', 'Can emergency veterinary clinics perform immediate blood transfusions?', 'Yes. Comprehensive emergency hospitals maintain stored canine and feline packed red blood cells and fresh frozen plasma for trauma and poisonings.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1588', 'What is an urgent care vet clinic vs. an emergency vet hospital?', 'Urgent care clinics treat non-life-threatening illnesses (ear infections, mild lacerations, minor limping) during evenings, whereas emergency hospitals handle major trauma and 24-hour ICU hospitalization.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_emergency-vet-finder_1589', 'What forms of payment do emergency animal hospitals accept?', 'Emergency clinics require payment at the time of service, accepting major credit cards, pet insurance direct pay (Trupanion Express), and medical financing like CareCredit and Scratchpay.', 'general', 'tool', 'emergency-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_local-vet-finder_1590', 'How are clinics verified?', 'Directory listings are verified against state licensing boards and accreditation standards (AAHA, RCVS).', 'general', 'tool', 'local-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_local-vet-finder_1591', 'Can I register my clinic?', 'Yes! Practice managers can click ''Register a Clinic'' to submit their practice details for review.', 'general', 'tool', 'local-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_local-vet-finder_1592', 'Does the search work on mobile?', 'Yes, you can tap to call directly and get turn-by-turn navigation on Google Maps or Apple Maps.', 'general', 'tool', 'local-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_local-vet-finder_1593', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'general', 'tool', 'local-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_local-vet-finder_1594', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'general', 'tool', 'local-vet-finder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1595', 'What is the difference between a CBC and a Chemistry blood panel?', 'A CBC (Complete Blood Count) evaluates blood cells (red blood cells, white blood cells, platelets). A Chemistry panel measures chemicals and enzymes in the serum to evaluate organ function (liver, kidneys, pancreas).', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1596', 'What does high ALT on a dog''s blood test mean?', 'Alanine Aminotransferase (ALT) is an enzyme inside liver cells. Elevated ALT indicates active liver inflammation, cellular damage, toxic ingestion, or liver disease.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1597', 'What is SDMA on a pet''s kidney blood test?', 'Symmetric Dimethylarginine (SDMA) is an advanced biomarker that detects chronic kidney disease when only 25% to 40% of kidney function is lost, years earlier than traditional creatinine.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1598', 'What does a low Hematocrit (HCT) or PCV mean?', 'Low Hematocrit indicates anemia (a shortage of oxygen-carrying red blood cells), caused by blood loss, immune-mediated hemolytic anemia (IMHA), or chronic organ disease.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1599', 'Why does my pet need blood tests before undergoing anesthesia?', 'Pre-anesthetic bloodwork verifies that the liver and kidneys are healthy enough to metabolize and excrete anesthetic drugs safely, identifying hidden risks before surgery.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1600', 'What does elevated Blood Urea Nitrogen (BUN) and Creatinine indicate?', 'Elevated BUN and Creatinine (azotemia) indicate decreased kidney filtration, severe dehydration, or urinary tract obstruction.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1601', 'Why should senior pets get blood tests every 6 to 12 months?', 'Regular blood panels establish a baseline for your pet, allowing early detection of diabetes, thyroid disorders, and kidney disease before symptoms appear.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1602', 'What does high alkaline phosphatase (ALKP / ALP) mean in dogs?', 'Elevated ALP indicates gallbladder/bile duct issues, bone growth, Cushing''s disease (hyperadrenocorticism), or steroid medication effects.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1603', 'How long does it take to get veterinary blood test results?', 'In-house clinic laboratory analyzers deliver results in 15 to 30 minutes. Comprehensive external reference lab panels typically take 24 to 48 hours.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-blood-test-explainer_1604', 'Why does my dog need to fast before a routine blood test?', 'Eating right before a blood draw causes lipemia (fat droplets in the blood) and temporary blood glucose spikes, which interfere with accurate lab optical readings.', 'general', 'tool', 'pet-blood-test-explainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1605', 'What is the C-BARQ test in canine behavior research?', 'C-BARQ (Canine Behavioral Assessment and Research Questionnaire) is a scientifically validated psychometric tool developed at the University of Pennsylvania to assess canine temperament.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1606', 'Can a dog''s fundamental personality change as they grow older?', 'A pet''s core temperament is established during early genetics and the 3–14 week socialization window. While training refines behaviors, baseline fear or drive remains stable throughout life.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1607', 'What is ''biddability'' in dog breeds?', 'Biddability is a dog''s innate desire and focus to work cooperatively with human direction, highly pronounced in herding and retrieving breeds (Border Collies, Golden Retrievers).', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1608', 'How do feline behaviorists measure cat personality?', 'Cat personality is measured along the ''Feline Five'' dimensions: Neuroticism, Extraversion, Dominance, Impulsiveness, and Agreeableness.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1609', 'What causes a dog to develop a fearful or anxious personality?', 'Anxiety results from a combination of maternal genetics, poor early socialization (weeks 3–14), past trauma, and physiological medical imbalances (like thyroid or chronic pain).', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1610', 'How can I help an introverted, shy cat gain confidence?', 'Provide vertical cat trees, predictable feeding routines, quiet hiding tunnels, and daily interactive wand toy play sessions to activate natural hunting confidence.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1611', 'What is ''neophobia'' in companion animals?', 'Neophobia is the innate fear or avoidance of novel objects, unfamiliar sounds, or strange people, common in under-socialized dogs and cats.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1612', 'Are certain dog breeds universally friendly or naturally aggressive?', 'No. Individual genetics, early socialization, and owner handling create vast behavioral diversity within every single breed.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1613', 'How does spaying or neutering affect a pet''s personality?', 'Sterilization reduces hormone-driven behaviors (urine marking, roaming, mounting, female heat cycles), but does not alter core personality, intelligence, or loyalty.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-personality-quiz_1614', 'What is the difference between high drive and hyperactivity in dogs?', 'High drive is an intense focus on completing a task (retrieving, herding) with quick recovery. Hyperactivity is an inability to settle or regulate arousal even in calm environments.', 'general', 'tool', 'pet-personality-quiz', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1615', 'What is the most important factor when choosing a dog breed?', 'Energy level and mental drive compatibility. Match your true daily activity routine to the dog''s exercise requirements rather than choosing based solely on physical appearance.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1616', 'What are the best dog breeds for first-time dog owners?', 'Golden Retrievers, Labrador Retrievers, Cavalier King Charles Spaniels, Poodles, and Greyhounds are known for their biddability, gentle temperament, and adaptable nature.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1617', 'What are the best dog breeds for apartment living?', 'French Bulldogs, Boston Terriers, Cavalier King Charles Spaniels, Pugs, and surprisingly, retired racing Greyhounds (who are gentle, low-energy couch potatoes).', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1618', 'Are hypoallergenic dogs truly 100% allergy-free?', 'No dog is 100% hypoallergenic. Pet allergies are triggered by the Can f 1 protein found in dander, saliva, and urine. Low-shedding breeds (Poodles, Bichons) simply trap dander in their curls.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1619', 'Why are working breeds (like Belgian Malinois) challenging for average families?', 'Bred for high-intensity military and police work, Malinois possess extreme prey drive, bite drive, and boundless energy that turn destructive without professional daily training.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1620', 'What cat breeds are the most affectionate and social?', 'Ragdolls, Maine Coons, Siamese, Burmese, and Sphynx cats are renowned for their dog-like, outgoing, and affectionate personalities.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1621', 'How much exercise does a high-energy dog breed need daily?', 'High-energy breeds (Border Collies, Viszlas, Australian Shepherds) require a minimum of 60 to 90 minutes of vigorous cardiovascular running and cognitive training daily.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1622', 'What dog breeds require the least professional grooming?', 'Short single-coated breeds like Boxers, Dobermans, Beagles, and Weimaraners require only occasional baths and weekly rubber curry comb brushing.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1623', 'Should families with toddlers get a puppy or an adult dog?', 'An adult dog (ages 2–5) with a known gentle history around children is often safer than a nipping, jumpy puppy with razor-sharp puppy teeth.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_which-breed-suits-me_1624', 'What are the longest-living dog breeds?', 'Small toy breeds consistently live the longest: Chihuahuas, Toy Poodles, Dachshunds, Jack Russell Terriers, and Shih Tzus frequently live 14 to 18+ years.', 'general', 'tool', 'which-breed-suits-me', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1625', 'How do I safely introduce a new dog to a resident cat?', 'Start with complete scent swapping for 5 days. Advance to visual contact through a baby gate while feeding treats, and only progress to leashed in-room meetings once both animals are calm.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1626', 'What is ''predatory drift'' in dogs?', 'Predatory drift occurs when a sudden movement, high-pitched squeal, or panic run from a cat or smaller dog triggers a larger dog''s involuntary predatory hunting sequence.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1627', 'Can all dog breeds learn to live peacefully with cats?', 'Many dogs coexist peacefully with cats. However, individual dogs with intense genetic prey drives (some Terriers, Sighthounds, and Huskies) should never be trusted alone with small pets.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1628', 'How do I introduce two unfamiliar adult dogs?', 'Conduct neutral territory parallel walks on leashes 20 feet apart, gradually closing distance as dogs sniff the ground calmly, before allowing brief 3-second butt sniffs.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1629', 'Why is vertical space (cat trees) essential when adding a dog to a cat home?', 'Vertical cat shelves and trees allow cats to navigate rooms safely above the dog''s reach, preventing the cat from feeling cornered or trapped.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1630', 'How do I know if two pets are playing or fighting?', 'Healthy play features loose bouncy body language, role reversals (taking turns chasing), and play bows. Real aggression involves stiff bodies, hard staring, growling, and pinned ears.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1631', 'What is resource guarding and how do I prevent it between pets?', 'Resource guarding is aggressive defense of food, toys, or sleeping spots. Prevent it by feeding pets in separate closed rooms and picking up high-value chew bones.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1632', 'How long does it take for resident cats to accept a new cat?', 'Cat-to-cat integration typically takes 2 to 8 weeks. Rushing introductions triggers territorial spraying and permanent inter-cat aggression.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1633', 'What is the N+1 litter box rule for multi-cat households?', 'Provide one litter box per cat plus one extra (e.g., 3 boxes for 2 cats) placed in distinct separate locations on different floors.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-compatibility-test_1634', 'What should I do if a fight breaks out between two dogs?', 'NEVER grab collars with your bare hands. Use the ''wheelbarrow method'' (grab the hind legs and pull backward), throw a blanket over them, or spray water to break focus.', 'general', 'tool', 'pet-compatibility-test', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1635', 'How old is a 1-year-old dog or cat in human years?', 'A 1-year-old dog or cat is biologically equivalent to approximately a 15-year-old human adolescent, possessing full sexual maturity and adult teeth.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1636', 'Why is the traditional ''multiply by 7'' rule inaccurate?', 'Pets age rapidly in their first two years (reaching roughly 24 human years by age 2) and age more slowly thereafter, following a logarithmic epigenetic curve.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1637', 'How old is a 7-year-old dog in human years?', 'A 7-year-old small dog is roughly 44–47 human years, a medium dog is roughly 47–50, and a giant breed (Great Dane) is equivalent to a 56–62 year-old senior.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1638', 'How do cats age compared to dogs?', 'Cats age identically to small dogs: 15 human years at age 1, 24 at age 2, and then roughly 4 human years for every chronological year thereafter.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1639', 'At what age is a dog officially classified as a senior?', 'Giant breeds are seniors at age 5 to 6, large dogs at age 7 to 8, medium dogs at age 9, and small toy breeds at age 10 to 11.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1640', 'Why do giant dog breeds age so much faster than small dogs?', 'Giant dogs experience rapid cellular division and high oxidative stress during rapid puppy growth, accelerating telomere shortening and early organ decline.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1641', 'What is the longest living cat breed?', 'Siamese, Burmese, and domestic shorthair cats are renowned for longevity, frequently living 16 to 20+ years.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1642', 'What is the longest living dog breed?', 'Chihuahuas, Australian Cattle Dogs, Toy Poodles, and Dachshunds routinely reach 15 to 19 years of age.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1643', 'What is Canine Cognitive Dysfunction (dementia) and when does it begin?', 'Canine dementia is neurodegenerative brain aging causing disorientation, sleep disruption, and anxiety, typically beginning in dogs older than 11 to 12 years.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_human-to-pet-age_1644', 'How can regular veterinary exams extend a senior pet''s lifespan?', 'Bi-annual exams with blood chemistry panels catch chronic kidney disease, hyperthyroidism, arthritis, and heart disease years before irreversible failure occurs.', 'general', 'tool', 'human-to-pet-age', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1645', 'What is a ''Gotcha Day'' for a pet?', 'A Gotcha Day is the annual anniversary celebration of the date an adopted rescue pet was officially brought into their permanent forever home.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1646', 'How do I make a safe, healthy birthday cake for my dog?', 'Mix oat flour, unsweetened applesauce, pure pumpkin puree, an egg, and a tablespoon of xylitol-free peanut butter. Frost with plain Greek yogurt.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1647', 'What ingredients must be strictly avoided in homemade pet treats?', 'Never use chocolate, xylitol sweeteners, macadamia nuts, raisins, grapes, nutmeg, onions, or excessive butter and sugar.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1648', 'Is it safe to let a dog unwrap their own presents?', 'Yes, under direct supervision! Wrapping a toy loosely in plain unbleached paper or cardboard boxes lets dogs use their paws and jaws in natural foraging play.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1649', 'How can I celebrate my cat''s birthday safely?', 'Offer a fresh can of tuna or salmon wet food, introduce an organic catnip or silvervine toy, and set up a new cardboard scratcher or window bird perch.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1650', 'How do I find my pet''s astrological zodiac sign?', 'Match their birth date to the standard astrological calendar (e.g., Aries: Mar 21–Apr 19, Leo: Jul 23–Aug 22) for fun personalized birthday cards.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1651', 'What is the Human Animal Bond Research Institute (HABRI)?', 'HABRI is a non-profit organization that funds scientific research demonstrating the physical and mental health benefits of companion animals on human lives.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1652', 'Are dog bakeries (pupcakes) safe for all dogs?', 'Most commercial dog bakeries use pet-safe ingredients. However, dogs with pancreatitis, diabetes, or food allergies should stick to single-ingredient meat treats.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1653', 'What are fun, low-stress birthday activities for shy pets?', 'Instead of hosting a loud pet party with stranger dogs, take your dog on a quiet solo nature sniffari walk or provide a snuffle mat at home.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-zodiac-birthday-card_1654', 'How should I update my pet''s records on their annual birthday?', 'Use their birthday as an annual reminder to verify microchip phone numbers, weigh your pet, and check that rabies tags and heartworm medications are up to date.', 'general', 'tool', 'pet-zodiac-birthday-card', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1655', 'What are the most popular pet names and their meanings?', 'Luna (Latin for ''Moon''), Bella (Italian for ''Beautiful''), Milo (Germanic for ''Gracious'' or ''Soldier''), Charlie (Germanic for ''Free Man''), and Max (Latin for ''Greatest'').', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1656', 'Why have human names become the most popular choice for pets?', 'In modern society, pets are viewed as core family members (''fur babies'') rather than utility animals, leading owners to choose human names like Charlie, Lucy, and Oliver.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1657', 'What are popular mythological names for strong guardian dogs?', 'Zeus (King of Greek Gods), Thor (Norse God of Thunder), Athena (Goddess of Wisdom), Odin (Norse All-Father), and Apollo (God of Sun and Light).', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1658', 'What makes a good name for a black dog or cat?', 'Shadow, Onyx, Midnight, Luna, Pepper, Raven, Salem, Nyx, and Eclipse are timeless names inspired by dark colors and nighttime imagery.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1659', 'Can a pet''s name influence how strangers perceive them?', 'Yes. Studies show dogs named ''Sweetie'' or ''Teddy'' receive friendlier initial human reactions than dogs named ''Killer'' or ''Fang'', affecting social interactions.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1660', 'What are great nature-inspired pet names?', 'Willow, River, Jasper, Maple, Aspen, Forest, Clover, Hazel, and Meadow offer gentle, earthy acoustics.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1661', 'What is the history behind the classic dog name ''Fido''?', 'Fido comes from the Latin word ''Fidus'', meaning ''faithful'' or ''loyal'', popularized in America after President Abraham Lincoln named his yellow mongrel dog Fido.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1662', 'How do show dog registered names differ from call names?', 'Show dogs have formal registered names including kennel prefixes (e.g., ''Ch. Whispering Pines Northern Light'') and an everyday short ''call name'' (e.g., ''Kona'').', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1663', 'Should I choose a name based on my pet''s breed origin?', 'Selecting names from the breed''s country of origin (e.g., Fritz for a German Shepherd, Pierre for a French Bulldog, Kenji for an Akita) is a fun cultural tribute.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-name-meaning-lookup_1664', 'How do I teach a rescue dog a new name with a special meaning?', 'Say the new name in a cheerful tone, mark eye contact with ''Yes!'', and immediately reward with a treat. Repeat for 10 reps twice daily; pets master new names in 7–10 days.', 'general', 'tool', 'pet-name-meaning-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1665', 'What is included in a standard shelter pet adoption fee?', 'Adoption fees ($50–$350) typically include mandatory spay/neuter surgery, complete core vaccines, microchipping, deworming, and heartworm/FIV/FeLV testing (saving $600–$900 in retail vet costs).', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1666', 'Why do puppies from ethical preservation breeders cost $2,000 to $4,000+?', 'Ethical breeders invest thousands in OFA genetic health testing (hips, elbows, eyes, cardiac), specialized prenatal veterinary care, top-tier nutrition, and puppy socialization programs.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1667', 'What are OFA and CHIC health clearances?', 'OFA (Orthopedic Foundation for Animals) and CHIC clearances are official veterinary certifications proving breeding parent dogs are free of hereditary hip dysplasia, eye disease, and heart defects.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1668', 'What is the lifetime cost difference between adopting and buying a pet?', 'While initial purchase prices differ, lifetime recurring costs (food, vet care, preventatives, grooming over 12–15 years) are nearly identical ($25,000–$60,000+).', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1669', 'What are red flags of a backyard breeder or puppy mill?', 'Refusing to let you see the mother dog, selling puppies under 8 weeks old, having no OFA genetic health test proof, and offering to meet in parking lots.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1670', 'Are shelter dogs more prone to health issues than purebred dogs?', 'Mixed-breed rescue dogs often benefit from ''hybrid vigor'' (lower incidence of specific recessive genetic diseases), though any pet can develop infections or age-related conditions.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1671', 'Can purebred dogs and cats be adopted from rescue shelters?', 'Yes! Approximately 25% of dogs in animal shelters are purebred, and dedicated breed-specific rescue organizations exist for almost every recognized dog and cat breed.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1672', 'What is an adoption home check?', 'Some rescues conduct brief home visits or virtual video tours to verify secure fencing, check pet-proofing, and ensure your home is safe for the adopted animal.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1673', 'Why do some rescue organizations have strict adoption criteria?', 'Rescues strive to prevent adoption returns and protect animal welfare by matching high-energy or reactive dogs with suitable, experienced owners.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_adoption-vs-buying-cost-comparator_1674', 'What hidden veterinary costs can arise with unvetted puppy mill puppies?', 'Parvovirus treatment ($3,000–$6,000), severe internal parasites (Giardia), congenital heart murmurs, and early orthopedic joint surgeries.', 'general', 'tool', 'adoption-vs-buying-cost-comparator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1675', 'How many puppies does an average dog have in a litter?', 'Litter size ranges from 1 to 3 puppies in toy breeds (Chihuahuas) to 6 to 10 puppies in large breeds (Labradors), and 8 to 14+ in giant breeds (Mastiffs).', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1676', 'How many kittens are in an average feline litter?', 'Domestic cats average 4 to 6 kittens per litter, with first-time mothers typically having smaller litters of 2 to 3 kittens.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1677', 'When can an ultrasound confirm pet pregnancy and count puppies?', 'Ultrasound confirms pregnancy and fetal heartbeats at 25 to 30 days post-breeding, but is inaccurate for counting exact litter numbers.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1678', 'When should an X-ray (radiograph) be taken to count puppy skeletons?', 'Take a veterinary X-ray after Day 55 of pregnancy when fetal skeletons are fully calcified, allowing exact counts of skulls and spines before whelping.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1679', 'Why is taking a late-pregnancy X-ray critical for whelping safety?', 'Knowing the exact number of puppies alerts you immediately if a puppy is stuck or retained in the birth canal during labor, preventing fatal uterine infections.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1680', 'What factors influence how many puppies a female dog will have?', 'Maternal body size, breed genetics, mother''s age (peak at 2–4 years), sperm quality, and precise progesterone timing during breeding.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1681', 'What was the largest canine litter ever recorded?', 'The Guinness World Record was set in 2004 by a Neapolitan Mastiff named Tia in the UK, who gave birth to an astonishing 24 puppies.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1682', 'What is ''Singleton Puppy Syndrome''?', 'When only one puppy is born in a litter. Singletons lack sibling competition and bite inhibition practice, requiring specialized early socialization.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1683', 'Does the father''s (sire''s) breed determine the litter size?', 'No. The mother''s breed and uterine capacity determine the number of eggs ovulated and carried; the sire contributes viable sperm and genetic traits.', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-size-predictor_1684', 'At what age does a female dog''s fertility and litter size decline?', 'Fertility and litter size decline sharply after 5 to 6 years of age, accompanied by higher risks of dystocia (difficult labor) and uterine infections (pyometra).', 'general', 'tool', 'litter-size-predictor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1685', 'What is a clicker and why is it better than just saying ''Good boy''?', 'A clicker makes a distinct, consistent, emotionless sound that marks the exact microsecond of success. Human voices vary in tone and take longer to speak, causing delayed reinforcement timing.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1686', 'How do I ''charge'' a new clicker before training?', 'Click and immediately give a small treat. Repeat ''Click-Treat'' 15 to 20 times without asking for any behavior until your pet perks up at the sound, learning that Click = Food.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1687', 'Can I use a verbal marker word instead of a physical clicker?', 'Yes. A crisp, short word like ''Yes!'' or ''Zip!'' works well when your hands are full, though the mechanical clicker provides sharper acoustic precision for new behaviors.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1688', 'What is ''shaping'' in clicker training?', 'Shaping is rewarding successive approximations toward a goal (e.g., teaching a dog to turn off a light switch by rewarding looking at the wall, then approaching, touching, and finally flipping the switch).', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1689', 'Do I have to use the clicker forever once my dog learns a command?', 'No! Once a behavior is reliably mastered on cue, the clicker is retired for that behavior. The clicker is a teaching tool, not a permanent cue.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1690', 'Can cats, birds, and horses be clicker trained?', 'Yes! Operant conditioning works across all animal species. Cats, birds, horses, rabbits, and zoo animals are clicker trained for voluntary veterinary care.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1691', 'What is the biggest mistake beginners make in clicker training?', 'Poor timing—clicking too late (after the dog has already stood up) or clicking and failing to deliver a treat. Every single click is a contract that MUST be followed by a reward.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1692', 'Why is clicker training superior to punishment-based training?', 'Clicker training builds confident, enthusiastic animals who love learning without fear, avoiding the fallout of aggression and anxiety associated with physical corrections.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1693', 'What is ''capturing'' a behavior?', 'Capturing means waiting for your pet to perform a natural behavior (like stretching or sitting) and clicking the moment they do it, attaching a verbal cue afterward.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_clicker-training-planner_1694', 'How long should a clicker training session last?', 'Keep sessions short and fun: 3 to 5 minutes, 2 to 3 times daily. End on a successful, happy repetition to keep motivation high.', 'general', 'tool', 'clicker-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1695', 'How long can an 8-week-old puppy hold its bladder?', 'An 8-week-old (2-month-old) puppy can physically hold its bladder for a maximum of 2 hours during the day. Expect to take them outside every 60 to 90 minutes when awake.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1696', 'What should I do when my puppy has a potty accident in the house?', 'Never rub their nose in it or yell! Interrupt them calmly with an upbeat ''Outside!'', carry them immediately to their outdoor spot, reward if they finish outside, and clean the accident with an enzymatic cleaner.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1697', 'Why do household cleaners with ammonia fail to clean pet urine?', 'Urine naturally breaks down into ammonia. Cleaning with ammonia-based products leaves a scent that smells like urine to the dog, triggering them to re-mark the exact same spot.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1698', 'How does crate training help with house training?', 'Dogs have an innate den instinct not to soil where they sleep. A properly sized crate encourages puppies to hold their bladder until taken outside to eliminate.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1699', 'What is the proper size for a puppy''s crate during potty training?', 'The crate should be just large enough for the puppy to stand erect, turn around completely, and stretch out flat. Use crate divider panels to adjust size as they grow.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1700', 'Why shouldn''t I use puppy pee pads indoors if I want an outdoor-trained dog?', 'Pee pads teach puppies that soft, absorbent indoor surfaces (rugs, carpets, blankets) are acceptable bathrooms, confusing outdoor training and delaying progress.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1701', 'How do I teach my puppy to ring a bell to go outside?', 'Hang a bell at nose height by the door. Tap the bell with a treat or the puppy''s nose right before opening the door every single time. Within 2 weeks, the puppy will ring it independently.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1702', 'What is the gastrocolic reflex in puppies?', 'It is an involuntary physiological reflex where food entering the stomach stimulates digestive contractions in the colon, causing puppies to need to poop 10–20 minutes after eating.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1703', 'How long does complete puppy potty training take?', 'With strict consistency, most puppies achieve solid house training by 4 to 6 months of age, though occasional minor accidents can happen until 8 months.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_potty-training-schedule_1704', 'What should I do if a fully house-trained adult dog starts having indoor accidents?', 'Schedule an immediate veterinary checkup. Sudden indoor accidents in adult pets are frequently caused by urinary tract infections (UTIs), bladder stones, diabetes, or kidney disease.', 'general', 'tool', 'potty-training-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1705', 'How long does the complete crate training process take?', 'A structured timeline takes approximately 2 to 4 weeks, moving gradually from open-door exploration to calm, independent multi-hour stays.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1706', 'What should I do during Week 1 of crate training?', 'Leave the door permanently open, feed all meals in the back of the crate, and toss high-value treats inside so your dog views it as a positive reward zone.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1707', 'How do I know when my dog is ready for the door to be closed?', 'When your dog voluntarily enters the crate to nap or eagerly looks for treats inside without hesitation, you can begin short closed-door sessions.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1708', 'What is the best chew toy to keep a dog calm in the crate?', 'A classic rubber KONG toy stuffed with canned food, peanut butter, or soaked kibble and frozen solid for 4 hours, providing 20 to 30 minutes of soothing licking.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1709', 'What is the difference between crate phobia and separation anxiety?', 'Crate-phobic dogs panic only when locked inside a crate but are calm loose in a room. Dogs with true separation anxiety panic whenever their owner leaves, regardless of crating.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1710', 'How do I handle setbacks if my dog starts barking in the crate again?', 'Take a step back in the timeline: decrease duration criteria, increase the value of frozen treats, and ensure they are thoroughly exercised before crating.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1711', 'Can I leave a puppy in a crate for an entire 8-hour workday?', 'NO! Puppies under 6 months cannot physically hold their bladders for 8 hours. Hire a midday dog walker or set up an exercise pen (x-pen) with puppy pads.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1712', 'Why should greetings and departures be calm and low-key?', 'Emotional, high-pitched hellos and goodbyes heighten anticipation anxiety. Keeping arrivals calm teaches the dog that departures are routine and safe.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1713', 'Should I cover the crate with a blanket or leave it open?', 'Many dogs feel more secure when 3 sides of the crate are covered with a breathable sheet to create a dark den, while others prefer seeing their surroundings.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_crate-training-timeline_1714', 'At what age can a dog be trusted outside the crate when left alone?', 'Most dogs can be gradually tested loose in puppy-proofed rooms around 1.5 to 2 years of age, once adolescence ends and chewing instincts subside.', 'dogs', 'tool', 'crate-training-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1715', 'Why do dogs naturally pull on the leash?', 'Dogs naturally walk faster than humans and possess an ''opposition reflex''—an instinctive mammalian reflex to lean into and pull harder against physical leash tension.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1716', 'What is the ''Be a Tree'' method for stopping leash pulling?', 'The moment the leash becomes tight, stop walking instantly and freeze like a tree. Only resume walking when your dog takes a step back and slackens the leash.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1717', 'What is a front-clip harness and why is it recommended?', 'A front-clip harness connects the leash to the dog''s chest. When the dog pulls, it gently pivots their shoulders back toward you, eliminating forward pulling leverage without neck strain.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1718', 'Where is the correct ''reward zone'' when teaching loose-leash walking?', 'Deliver treats directly next to your hip on the side you want your dog to walk, reinforcing them for staying in that specific target position.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1719', 'Why are retractable (flexi) leashes discouraged by dog trainers?', 'Retractable leashes teach dogs that pulling extends the line, while thin nylon cords can snap, cause severe friction burns, or drop loudly on pavement, terrifying dogs.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1720', 'How long does it take to train a dog to walk politely on a leash?', 'With consistent daily 10-minute training sessions, most dogs show significant improvement within 2 to 4 weeks.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1721', 'What should I do if my dog lunges at other dogs on walks?', 'Your dog is over threshold. Increase distance from the trigger, use high-value treats to play the ''Look at That'' focus game, and avoid tight leash tension.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1722', 'What leash length is ideal for everyday neighborhood walks?', 'A standard 5- to 6-foot fixed-length flat nylon or biothane leash provides optimal control while giving your dog comfortable slack.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1723', 'Should I let my dog stop and sniff during walks?', 'YES! Sniffing stimulates the olfactory brain, lowers heart rate and cortisol, and burns significant mental energy.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_leash-training-progress_1724', 'How do I transition leash training from indoors to outside?', 'Start in your quiet living room, move to your fenced backyard, then your driveway, and finally the sidewalk, adding environmental distractions gradually.', 'dogs', 'tool', 'leash-training-progress', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1725', 'What is the secret to building a 100% reliable dog recall?', 'Pair your recall cue with ultra-high-value rewards (roast chicken, cheese, hot dogs) every single time, and never call your dog for negative events.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1726', 'What is a ''poisoned cue'' in dog training?', 'When a recall word is ruined because the owner called the dog to punish them, give a bath, or clip nails, causing the dog to associate the word with something unpleasant.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1727', 'Why should I never chase my dog if they run away?', 'Chasing a dog triggers their chase-play reflex, making them run faster. Instead, run in the opposite direction, drop to the ground excitedly, or squeak a high-value toy.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1728', 'How do I use a long line to practice recall safely outdoors?', 'Attach a 15- to 30-foot biothane long line. Let your dog wander, call your cue once, gently guide them toward you if needed, and reward with a treat jackpot.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1729', 'Why is a dog whistle effective for emergency recalls?', 'Whistles have high acoustic penetration that cuts through wind and ambient traffic up to 1/2 mile away, delivering a consistent pitch free of human frustration.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1730', 'What should I do if my dog ignores my recall cue?', 'Do not repeat the word over and over! Run the other way, make funny high-pitched noises, or wave a favorite toy to regain focus, then reward when they reach you.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1731', 'How long does it take to train off-leash recall reliability?', 'Building proofed reliability around high distractions (wildlife, other dogs) typically requires 3 to 6 months of systematic long-line practice.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1732', 'Why should I practice ''touch'' or collar-grabs during recall?', 'Always touch your dog''s collar or have them boop your hand before delivering the reward, preventing them from doing a ''drive-by'' grab-and-run.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1733', 'Should I reward my dog if they take a long time to come back?', 'YES! Always reward your dog when they reach you, even if it took longer than expected. Punishing them upon return teaches them that coming to you is unsafe.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_recall-training-tracker_1734', 'What are the best high-value treats for recall practice?', 'Real meat rewards: boiled chicken breast, freeze-dried liver, cut-up hot dogs, real cheddar cheese cubes, or squeeze tubes of liverwurst.', 'dogs', 'tool', 'recall-training-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1735', 'When is the critical socialization window for puppies?', 'The critical window is between 3 and 14 weeks of age. Experiences during this brief window shape your dog''s lifelong confidence and baseline fear responses.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1736', 'Can I socialize my puppy before they finish all their vaccines?', 'YES! The AVSAB confirms behavioral euthanasia is a greater risk than infectious disease. Socialize safely in clean private homes, puppy preschool classes, and carry them in public.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1737', 'What is the ''Rule of 100'' in puppy socialization?', 'The goal of exposing your puppy to 100 novel positive experiences (different people, sounds, textures, hats, umbrellas, surfaces) before 16 weeks of age.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1738', 'What is the difference between positive exposure and ''flooding''?', 'Positive exposure allows the puppy to observe and approach at their own pace paired with treats. Flooding forces a terrified puppy into overwhelming situations, creating severe lifelong phobias.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1739', 'What body language signals show a puppy is overwhelmed or fearful?', 'Yawning, lip licking, tucking the tail, hiding behind your legs, shaking, lifting a front paw, panting, and refusing high-value treats.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1740', 'What sounds should puppies be desensitized to early?', 'Thunderstorms, fireworks, vacuum cleaners, sirens, crying babies, doorbells, and construction traffic (play audio tracks at low volume while feeding meals).', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1741', 'Why are puppy socialization classes essential?', 'Accredited puppy classes provide safe, sanitized play environments with puppies of similar ages, teaching bite inhibition, polite greeting etiquette, and focus around distractions.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1742', 'How do I socialize a puppy to different handling and veterinary exams?', 'Practice gentle daily handling: look inside ears, gently touch paws, open the mouth to see teeth, lift the tail, and hold them in a gentle bear hug paired with treats.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1743', 'Can an older adult dog be socialized?', 'Adult dogs can be rehabilitated and counter-conditioned through patient desensitization, but it requires significantly more time than early puppy socialization.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_socialization-checklist_1744', 'What surfaces should puppies walk on during socialization?', 'Expose them to grass, gravel, concrete, wet sand, metal grates, slick hardwood, crinkly plastic tarps, stairs, and wobbly wobble boards to build tactile confidence.', 'general', 'tool', 'socialization-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1745', 'What is the critical socialization window for puppies?', 'The critical window is between 3 and 14 weeks of age. Experiences during this phase permanently shape a dog''s confidence, stress resilience, and sociability.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1746', 'What is the 8-to-10 week fear imprint period in puppies?', 'A sensitive developmental sub-phase where traumatic experiences (frightening vet visits, dog attacks) can cause lifelong behavioral fear phobias. Keep all experiences positive.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1747', 'When do puppies lose their baby teeth?', 'Deciduous baby teeth start falling out around 3.5 to 4 months of age, with all 42 permanent adult teeth fully erupted by 6 months.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1748', 'What is canine adolescence and when does it occur?', 'Adolescence occurs between 6 and 18 months, characterized by hormonal surges, temporary training regression, increased independence, and higher physical energy.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1749', 'When do puppy ears stand up in prick-eared breeds (like German Shepherds)?', 'Ears typically stand between 4 and 6 months of age, often fluctuating up and down during teething as calcium is mobilized for tooth growth.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1750', 'At what age should a puppy start basic obedience training?', 'Start positive reinforcement training as early as 8 weeks of age with short 3- to 5-minute sessions focusing on name recognition, sit, and crate comfort.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1751', 'When is a puppy considered fully house-trained?', 'Most puppies achieve consistent reliable house-training around 5 to 6 months of age, once full physiological sphincter muscle control is developed.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1752', 'What is the ''Rule of 100'' in puppy socialization?', 'A guideline to safely expose your puppy to 100 positive novel sights, sounds, surfaces, people, and friendly vaccinated dogs before 16 weeks of age.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1753', 'When do male puppies begin lifting their leg to urinate?', 'Leg lifting typically begins around 6 to 9 months of age as testosterone levels rise during sexual maturation.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-milestone-tracker_1754', 'How much sleep does a young puppy need each day?', 'Young puppies need 18 to 20 hours of sleep daily. Overtired puppies become mouthy, hyperactive, and throw behavioral tantrums.', 'dogs', 'tool', 'puppy-milestone-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1755', 'What is the #1 underlying cause of dog aggression?', 'FEAR and anxiety. Most aggressive behaviors (lunging, barking, growling) are defensive attempts to make a perceived scary threat move away.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1756', 'Why should you NEVER punish a dog for growling?', 'A growl is an early warning siren. If you punish the growl, the dog stops growling but remains scared, learning to bite without warning next time.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1757', 'What is the Dunbar Canine Bite Scale?', 'A clinical 6-level scale assessing bite severity and prognosis: Level 1 (air snap), Level 2 (skin contact, no puncture), Level 3 (shallow punctures), Level 4 (deep puncture/crush), Level 5/6 (severe/fatal).', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1758', 'Can physical pain or medical issues cause sudden aggression in pets?', 'YES! Over 70% of sudden behavioral aggression cases involve medical pain: osteoarthritis, dental abscesses, ear infections, or neurological issues. Always rule out pain first.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1759', 'What is resource guarding and how is it managed?', 'Resource guarding is aggressive defense of food, toys, or sleeping spots. Treat it by trading for higher-value rewards, never forcibly snatching items away.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1760', 'What is the difference between a dog trainer and a Veterinary Behaviorist (DACVB)?', 'A DACVB is a licensed veterinarian with 3+ years of residency in behavioral medicine who can diagnose medical causes and prescribe psychotropic medications.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1761', 'What is ''barrier frustration'' or leash reactivity?', 'When dogs bark or lunge on leash because physical restraint prevents them from greeting or escaping a trigger, which is often misinterpreted as pure aggression.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1762', 'Is a basket muzzle a safe tool for aggressive dogs?', 'Yes! A properly fitted basket muzzle allows the dog to pant, drink water, and take treats while ensuring 100% bite safety during behavioral rehabilitation.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1763', 'What is redirected aggression in pets?', 'When an animal is hyper-aroused by a trigger they cannot reach (like a cat seeing a stray cat outside) and suddenly lashes out at a nearby human or pet.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_aggression-risk-assessment_1764', 'Can aggression in dogs be permanently cured?', 'Aggression is managed rather than ''cured''. Through desensitization, counter-conditioning, and management, the risk of bites can be drastically reduced.', 'general', 'tool', 'aggression-risk-assessment', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1765', 'What is true canine separation anxiety?', 'It is a severe panic disorder where a dog experiences intense emotional distress, panic, and physiological fear when left alone or separated from their primary attachment person.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1766', 'Why do dogs with separation anxiety destroy door frames and window blinds?', 'Their destruction is focused entirely on ''exit barriers'' in a frantic, panicked attempt to break out of the house and reunite with their owner.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1767', 'Should I punish my dog when I return home to find destroyed furniture?', 'NEVER punish a dog upon returning! Dogs cannot connect punishment to past actions; punishment only makes them fear your arrival, escalating anxiety.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1768', 'What is sub-threshold systematic desensitization for separation anxiety?', 'A training protocol where you practice leaving for tiny increments of time (starting with 5–30 seconds) that stay below the dog''s panic threshold, gradually building tolerance.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1769', 'Can crate training cure separation anxiety?', 'For dogs with separation anxiety, crates often cause severe confinement panic, resulting in broken teeth and bloody paws from biting crate bars. Free room confinement is often safer.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1770', 'What are departure cues and how do I desensitize them?', 'Departure cues are triggers like picking up keys, putting on shoes, or grabbing a coat. Desensitize them by performing these actions randomly throughout the day without actually leaving.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1771', 'Can medication help a dog with severe separation anxiety?', 'Yes! FDA-approved SSRIs (Reconcile / Fluoxetine) and tricyclic antidepressants (Clomicalm) balance brain serotonin, lowering baseline panic so behavioral training can succeed.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1772', 'Does getting a second dog fix separation anxiety?', 'Rarely. Separation anxiety is usually focused on attachment to human guardians, not loneliness for other dogs. The new dog often adopts the anxious behaviors.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1773', 'Why does my dog refuse delicious treats when left alone?', 'Severe sympathetic nervous system arousal (fight-or-flight) completely shuts down the digestive system and appetite. Refusing high-value food is a clear indicator of panic.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_separation-anxiety-score_1774', 'How long does it take to resolve separation anxiety in dogs?', 'Rehabilitation is a gradual process taking several weeks to months of consistent sub-threshold desensitization, but success rates exceed 85% with structured protocols.', 'general', 'tool', 'separation-anxiety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1775', 'Why is trick training beneficial for all dogs?', 'Trick training provides mental stimulation, builds rear-end core strength, burns excess energy, boosts shy dog confidence, and deepens the human-animal bond.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1776', 'How do I teach my dog to ''Spin'' in a circle?', 'Hold a high-value treat at your dog''s nose, slowly lure their head in a complete 360-degree circle around toward their tail, mark with ''Yes!'' and reward. Add the verbal cue ''Spin''.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1777', 'How do I teach my dog to ''Take a Bow''?', 'Stand beside your dog and lure a treat straight down between their front paws while gently supporting their belly so their hind legs stay upright in a play-bow stretch.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1778', 'What is canine proprioception and how do tricks improve it?', 'Proprioception is the body''s awareness of its limbs in space. Tricks like backing up or pivoting on a platform teach dogs how to control their hind legs independently.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1779', 'How do I teach my dog to play ''Shy'' (put a paw over their face)?', 'Place a tiny piece of gentle painter''s tape or a loose hair scrunchie over their snout. When they lift a paw to brush it off, click and treat, adding the word ''Shy''.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1780', 'Can older senior dogs learn new tricks?', 'Absolutely! ''You can''t teach an old dog new tricks'' is a myth. Gentle trick training keeps senior canine brains sharp and delays cognitive dysfunction.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1781', 'What is an AKC or DMWYD Trick Dog Title?', 'Official titling programs (Novice, Intermediate, Advanced, Performer) through AKC and Do More With Your Dog! where dogs earn official title certificates for performing sets of tricks.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1782', 'How do I teach a dog to ''Weave'' through my walking legs?', 'Step forward with one leg, lure the dog through from behind with a treat, step forward with the other leg and lure through, gradually linking steps into a fluid weave.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1783', 'Can domestic cats learn tricks?', 'Yes! Using clicker training and high-value meat treats, cats easily learn High Five, Sit, Spin, Jump through hoops, and Ring a bell.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_trick-training-library_1784', 'How long should a trick training session be?', 'Keep sessions short, upbeat, and fun—3 to 5 minutes, 2 to 3 times a day. Always end on a successful, high-reward repetition.', 'general', 'tool', 'trick-training-library', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1785', 'How many words can an average companion dog learn?', 'The average companion dog easily understands 150 to 200 words and signals. Exceptionally trained working dogs (like Chaser the Border Collie) have mastered over 1,000 words.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1786', 'What is the biggest mistake people make when giving dog commands?', 'Repeating the command over and over (''Sit, sit, sit, SIT!''). This teaches the dog that the first three words are meaningless noise. Say the cue once, wait 3 seconds, and assist if needed.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1787', 'Do dogs learn hand signals or verbal words faster?', 'Dogs are visual communicators and learn hand signals significantly faster than spoken words. Always present the verbal word 1 second *before* the hand signal to teach both.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1788', 'What is a ''poisoned cue'' in dog training?', 'A poisoned cue is a command that has become associated with punishment, frustration, or inconsistency, causing the dog to hesitate or refuse to respond.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1789', 'What are the top 5 most important safety commands for every dog?', '1. Reliable Emergency Recall (''Come!''), 2. ''Leave It'' (drop toxic food), 3. ''Drop It'' (release objects), 4. ''Stay'' / ''Wait'', and 5. ''Place'' / Settle on a mat.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1790', 'Can dogs understand the names of their individual toys?', 'Yes! Many dogs learn object discrimination (''Fetch Ball'' vs. ''Fetch Frisbee'' vs. ''Fetch Bear'') through associative reward conditioning.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1791', 'Why should everyone in the family use the exact same command words?', 'Inconsistent words confuse dogs. If one person says ''Down'' for lie down while another says ''Down'' to stop jumping, the dog cannot understand the conflicting criteria.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1792', 'What is ''fast-mapping'' in animal cognitive learning?', 'Fast-mapping is the cognitive ability to learn the name of a new object by process of elimination when placed alongside familiar known objects.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1793', 'How do I teach my dog a reliable ''Leave It'' cue?', 'Hold a treat in a closed fist. When the dog stops licking and pulls their nose away, mark with ''Yes!'' and reward with a *different* treat from your other hand. Add the cue ''Leave It''.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_command-vocabulary-builder_1794', 'Why should release cues (like ''Free!'' or ''Break!'') always be taught?', 'A release cue tells the dog that a Stay or Wait command has officially ended, preventing the dog from deciding on their own when to break position.', 'general', 'tool', 'command-vocabulary-builder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1795', 'What is the ABC model in animal behavior tracking?', 'The ABC model analyzes Antecedents (what triggered the behavior), Behavior (the exact physical action), and Consequences (what happened immediately afterward to maintain the behavior).', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1796', 'What is ''trigger stacking'' in dogs?', 'Trigger stacking occurs when multiple minor stressful events accumulate over hours or days without sufficient recovery time, pushing the dog over their stress threshold into explosive reactivity.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1797', 'How long does cortisol remain elevated after a stressful incident?', 'Stress hormones (cortisol and adrenaline) can remain elevated in a dog''s bloodstream for 24 to 72 hours following an acute fearful or reactive event.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1798', 'What is a ''stress threshold'' in animal training?', 'The invisible boundary where a pet transitions from calm thinking (green zone) into emotional fight-or-flight reactivity (red zone) where learning becomes impossible.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1799', 'How does a behavior journal help my veterinarian or behaviorist?', 'A detailed journal provides objective data on trigger frequency, time of day, recovery latency, and environmental patterns, allowing targeted medical and behavioral treatment.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1800', 'What is ''recovery latency'' in animal behavior?', 'Recovery latency is the exact amount of time it takes for your pet to return to a completely relaxed baseline after encountering a stressful trigger.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1801', 'Why is tracking physical exercise and sleep important in behavior?', 'Sleep deprivation (dogs needing 12–14 hours daily) and lack of decompression sniff walks are primary hidden causes of irritability and hyper-reactivity.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1802', 'How do I identify subtle early stress signals before my dog barks?', 'Look for displacement signals: sudden yawning, lip licking, whale eye (showing whites of eyes), stiff body freeze, and closed mouth.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1803', 'Can dietary changes affect pet behavior logs?', 'Yes. Food allergies, gastrointestinal pain, or high-starch diets can cause systemic discomfort, directly elevating irritability and aggression.', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_behavior-journal_1804', 'What is classical counter-conditioning?', 'Changing an animal''s emotional response to a scary trigger by pairing the distant trigger with delicious high-value treats (e.g., Scary dog appears -> Hot dogs rain down).', 'general', 'tool', 'behavior-journal', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1805', 'What is Continuous Reinforcement (CRF) in pet training?', 'CRF means rewarding 100% of correct repetitions (1 click = 1 treat). It is mandatory when first teaching a brand new behavior so the animal understands the criteria.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1806', 'Why should I transition from continuous to variable reinforcement?', 'Variable reinforcement (rewarding randomly like a slot machine) creates high motivation and makes behaviors virtually immune to extinction, so the pet performs without needing food visible.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1807', 'What is the ''Slot Machine'' (Variable Ratio) effect?', 'Unpredictable rewards stimulate dopamine surges in the brain, driving the animal to perform commands faster and more reliably in hopes that the next rep is the winner.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1808', 'What is ''extinction'' in animal behavior?', 'Extinction occurs when a previously reinforced behavior stops receiving rewards entirely, causing the animal to gradually stop offering the behavior.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1809', 'What is an ''extinction burst''?', 'A temporary surge where the animal tries the behavior harder, faster, or louder (e.g., barking louder at a door) before finally giving up. Never reward during an extinction burst!', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1810', 'When should I start fading treats during training?', 'Begin fading continuous treats once your pet performs the behavior with 80% to 90% accuracy in low-distraction environments across 3 consecutive sessions.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1811', 'Can praise or toys replace food in variable reinforcement schedules?', 'Yes! Real-life rewards (throwing a ball, opening a door for a walk, enthusiastic verbal praise, tug play) function as powerful non-food reinforcers.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1812', 'What is a Fixed Ratio (FR) schedule?', 'Rewarding on a predictable count (e.g., rewarding every 3rd sit). Animals often pause after the reward, making Variable Ratio schedules superior for continuous focus.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1813', 'Why does my dog only listen when I have food in my hand?', 'The food was used as a ''bribe'' rather than a true reward. Fade the food out of your hand within 5–10 reps, keeping rewards hidden in a pouch or on a counter until after the marker cue.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reward-schedule-calculator_1814', 'What is Differential Reinforcement in advanced training?', 'Rewarding only the fastest, crispest 20% of responses with high-value jackpot treats, rapidly refining the quality and speed of obedience commands.', 'general', 'tool', 'reward-schedule-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1815', 'Why do dogs bark at the window or fence line?', 'Territorial and alert barking triggered by visual movement outside (mail carriers, passing dogs). When the trigger walks away, the dog believes its barking successfully defended the home.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1816', 'What is ''demand barking'' and how do I stop it?', 'Demand barking occurs when a dog barks to force you to give treats, open doors, or throw a ball. Extinguish it by completely ignoring the bark and rewarding only calm quiet.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1817', 'Why does shouting ''Stop barking!'' fail to work?', 'Shouting sounds like barking to a dog, validating their alarm and escalating arousal. Speak in a calm low voice and redirect them to a quiet replacement behavior.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1818', 'How does frosted window film stop alert barking?', 'Applying static-cling frosted film to the lower 12 inches of windows blocks the dog''s visual line of sight to outdoor sidewalk triggers while preserving natural light.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1819', 'What is the ''Thank You'' protocol for alert barking?', 'Acknowledge the dog''s alert with a calm ''Thank you'', call them to you, and toss treats on the floor (''Find It''), redirecting their brain away from the trigger.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1820', 'Are ultrasonic or shock anti-bark collars safe and effective?', 'Veterinary behaviorists strongly advise against shock collars. Aversive collars suppress barking through pain, increasing underlying fear and frequently triggering redirected aggression.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1821', 'How does physical and mental exercise reduce excessive barking?', 'Bored dogs vocalize to entertain themselves. Providing 45 minutes of physical exercise combined with mental puzzle feeders drastically reduces boredom barking.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1822', 'What causes monotonous barking when a dog is left outside alone?', 'Social isolation frustration. Dogs are pack animals; keeping them isolated in backyards leads to chronic barrier frustration and repetitive barking.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1823', 'How do I teach my dog the ''Quiet'' cue?', 'Allow 1 to 2 alert barks, hold a high-value treat to their nose (dogs cannot bark while sniffing), wait for 3 seconds of silence, mark ''Quiet'', and reward generously.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_barking-log_1824', 'How can I distinguish between alert barking and separation anxiety barking?', 'Separation anxiety barking occurs exclusively when the owner is absent, accompanied by pacing, drooling, destructive exit digging, and rhythmic mourning howls.', 'dogs', 'tool', 'barking-log', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1825', 'What is the N+1 rule for cat litter boxes?', 'You should provide one litter box for every cat in your home, plus one extra (e.g., 3 boxes for 2 cats) placed in separate rooms on different floors to avoid territorial blocking.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1826', 'Why is my cat suddenly peeing outside the litter box?', 'First rule out painful medical conditions (UTI, bladder stones, Feline Idiopathic Cystitis, arthritis). If healthy, assess litter cleanliness, box size, scented litter, or household stress.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1827', 'What type of litter do most domestic cats prefer?', 'Scientific preference trials prove cats overwhelmingly prefer unscented, soft, fine-grained clumping clay litter that mimics natural sandy desert soil.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1828', 'Why are covered (hooded) litter boxes disliked by many cats?', 'Covered boxes trap foul ammonia odors inside, are often too cramped to turn around in, and make cats feel vulnerable to ambushes from other household pets.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1829', 'How big should a cat''s litter box be?', 'The litter box must be at least 1.5 times the length of your cat from nose to the base of the tail, allowing comfortable 360-degree turning and digging.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1830', 'How often should litter boxes be scooped and completely washed?', 'Scoop solid waste 1 to 2 times daily. Empty, scrub with hot water and unscented soap, and refill with fresh litter every 2 to 4 weeks.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1831', 'Why shouldn''t I place the litter box next to the cat''s food and water?', 'In nature, cats never eliminate near their food or clean water sources to avoid bacterial contamination. Place food, water, and litter in completely separate areas.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1832', 'How do I clean cat urine stains so the cat doesn''t pee there again?', 'Use an enzymatic pet urine cleaner (containing live bio-enzymes) to permanently digest uric acid crystals. Standard bleach or ammonia cleaners will fail and attract cats back.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1833', 'How do I litter train a young kitten?', 'Place the kitten in a shallow low-sided litter box immediately after meals and naps. Kittens have natural burying instincts and usually learn within 2 to 3 days.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_litter-training-planner_1834', 'What adjustments should be made for senior arthritic cats?', 'Use low-entry litter boxes (or cut a 2-inch entryway into a shallow plastic storage bin) so stiff senior cats can walk in without painful jumping over high edges.', 'general', 'tool', 'litter-training-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1835', 'How often do female dogs go into heat?', 'Most domestic dogs cycle once every 6 to 8 months (twice per year). Small breeds may cycle every 4 to 5 months, while giant breeds (Basenjis, Mastiffs) often cycle only once per year.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1836', 'What are the first visible signs that a dog is entering heat?', 'Swelling and enlargement of the vulva, bloody vaginal discharge, frequent urination, excessive self-grooming, and increased restlessness (the Proestrus phase).', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1837', 'How long does a dog''s complete heat cycle last?', 'The full heat cycle lasts approximately 2 to 4 weeks (average 21 days), split between Proestrus (bloody phase) and Estrus (fertile mating phase).', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1838', 'When is a female dog most fertile during her heat cycle?', 'Peak fertility occurs during Estrus (typically days 9 to 14 after bleeding begins), when progesterone rises and the discharge turns from red to a pale straw/pinkish color.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1839', 'What is ''flagging'' behavior in a female dog?', 'When in standing heat (Estrus), the female deflects her tail to the side and stiffens her hind legs when touched on the lower back, signaling readiness to mate.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1840', 'What is Pyometra and why is it life-threatening?', 'Pyometra is a severe bacterial infection of the uterus occurring 4 to 8 weeks post-heat due to progesterone changes. It is a fatal medical emergency requiring immediate surgical ovariohysterectomy.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1841', 'How do feline heat cycles differ from dogs?', 'Cats are seasonally polyestrous induced ovulators. They cycle in and out of heat every 2 to 3 weeks in spring/summer, vocalizing loudly until mating triggers ovulation.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1842', 'What is a false pregnancy (pseudopregnancy) in dogs?', 'A hormonal condition 6 to 8 weeks post-heat where a non-pregnant female displays nesting behavior, mothering toys, and lactates milk due to prolactin surges.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1843', 'Can a female dog get pregnant during her very first heat cycle?', 'Yes. Puberty occurs between 6 and 12 months. However, breeding on the first heat is dangerous because the female is not physically or skeletally mature.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heat-cycle-tracker_1844', 'How do reproductive veterinarians pinpoint exact ovulation timing?', 'By running serial quantitative serum progesterone blood tests (ovulation occurs at 4–10 ng/mL) and performing vaginal cytology exams.', 'general', 'tool', 'heat-cycle-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1845', 'How long is a dog or cat pregnant?', 'The average gestation period is 63 days (approx. 9 weeks), with a normal safe range of 58 to 68 days from the date of mating or ovulation.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1846', 'When can a veterinarian confirm pet pregnancy via ultrasound?', 'Ultrasound can reliably detect gestational sacs and beating fetal hearts starting at 25 to 30 days post-breeding.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1847', 'Why should calcium supplements NEVER be given to pregnant dogs?', 'Supplementing calcium during pregnancy suppresses the parathyroid gland, preventing the mother from naturally mobilizing calcium during lactation, triggering fatal Eclampsia (Milk Fever).', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1848', 'When should a pregnant dog''s diet be increased?', 'Increase food intake starting at Week 6 (Day 42) by transitioning to high-protein, high-calorie puppy/growth food, increasing volume by 30% to 50% through lactation.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1849', 'When can an X-ray (radiograph) count puppy/kitten skeletons?', 'Abdominal radiographs should be taken after Day 55 of gestation when fetal bones are fully calcified, providing an exact count of heads and spines.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1850', 'What are early physical signs of dog pregnancy?', 'Enlarged pink nipples (around Day 25–30), slight morning sickness/decreased appetite around Week 3, followed by a visibly expanding abdomen by Week 5.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1851', 'What happens during the first 3 weeks of pet pregnancy?', 'Fertilized eggs travel down the oviducts and implant into the uterine wall around Day 17 to 21, forming zonary placental attachments.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1852', 'How much weight should a pregnant dog gain?', 'A pregnant female typically gains 15% to 25% of her normal pre-breeding body weight by the time of whelping, depending on litter size.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1853', 'Can a pregnant dog continue exercising?', 'Moderate daily leash walking is encouraged throughout pregnancy to maintain muscle tone for labor. Avoid vigorous jumping or strenuous agility after Week 4.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pregnancy-calendar_1854', 'What is the pre-whelping temperature drop?', 'A female dog''s rectal body temperature drops from normal (100–101.5°F) down below 98.5°F (36.9°C) roughly 12 to 24 hours before active labor begins.', 'general', 'tool', 'pregnancy-calendar', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1855', 'What are the critical emergency signs of dystocia (difficult labor)?', 'Hard active contractions for > 30 minutes with no puppy born, > 2 hours between puppies, green discharge before the first birth, or extreme maternal collapse. Seek immediate ER care.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1856', 'Why does a pregnant dog''s temperature drop before labor?', 'A sharp drop in progesterone triggers the body temperature to drop below 98.5°F (36.9°C), signaling that Stage 1 active labor will begin within 12 to 24 hours.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1857', 'What should I do immediately when a puppy or kitten is born?', 'Tear the amniotic sac off the face, suction fluid from the mouth/nose with a bulb syringe, rub vigorously with a warm dry towel until crying, and tie off the umbilical cord.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1858', 'Why is ''swinging'' newborn puppies to clear fluid dangerous?', 'Swinging puppies causes severe whiplash, brain hemorrhaging, and concussions. Use a safe rubber suction bulb and gentle postural drainage instead.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1859', 'How do I safely cut the umbilical cord?', 'Crush the cord with a sterile hemostat 1 inch from the belly, tie with unwaxed dental floss, cut with clean blunt scissors, and dab with 2% chlorhexidine or Betadine.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1860', 'What is uteroverdin (green discharge) and when is it dangerous?', 'Uteroverdin is a dark green pigment from detached placenta. If seen *before* the first puppy is born, it indicates premature placental detachment and fetal hypoxia (emergency!).', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1861', 'How long should it take to deliver a full litter?', 'Delivery typically takes 6 to 18 hours depending on litter size. Puppies are usually born every 30 to 60 minutes, though resting pauses of 1 to 2 hours between pups are normal.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1862', 'What temperature should the whelping box be kept for newborns?', 'Keep the nest area at 85°F to 90°F (29°–32°C) during Week 1 using a heating pad under half the box, because newborns cannot shiver or regulate their own body heat.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1863', 'Why is it vital that newborns nurse within the first 12 hours?', 'Mother''s first milk (colostrum) contains vital maternal antibodies (IgG) that can only be absorbed through the newborn gut lining during the first 12 to 24 hours of life.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_whelping-kittening-checklist_1864', 'What is Eclampsia (Milk Fever) in nursing mothers?', 'A life-threatening sudden drop in blood calcium caused by heavy lactation, causing muscle tremors, stiff gait, panting, seizures, and fever. Requires emergency IV calcium.', 'general', 'tool', 'whelping-kittening-checklist', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1865', 'What is the standard formula for calculating a dog stud fee?', 'The traditional industry benchmark is equal to the full purchase price of one show/working quality puppy from the resulting litter (e.g., $2,000–$3,500).', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1866', 'What is the difference between a cash stud fee and ''Puppy Pick''?', 'The stud owner can choose an upfront cash fee or select the ''First Pick Puppy'' from the litter to retain for their own breeding program or resale.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1867', 'What mandatory OFA health clearances must a stud dog have before breeding?', 'Certified OFA Hip and Elbow dysplasia ratings (after 24 months of age), annual board-certified eye exams (CAER), cardiac clearance, and complete breed-specific DNA disease panels.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1868', 'What is a ''Puppy Guarantee'' clause in a stud contract?', 'A clause guaranteeing a minimum number of live puppies (typically at least 2 live puppies). If the female misses or has a singleton, a free return repeat breeding is provided.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1869', 'What are the different canine breeding methods?', 'Natural mating, fresh side-by-side artificial insemination (AI), Transcervical Insemination (TCI with an endoscope), and surgical artificial insemination using frozen semen.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1870', 'Why is Brucellosis testing mandatory before natural breeding?', '*Brucella canis* is an incurable, highly contagious venereal bacterial disease causing abortion and sterility in dogs (and is zoonotic to humans). Both dogs must test negative within 30 days before mating.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1871', 'How does a semen evaluation affect stud value?', 'A breeding soundness exam verifying high sperm count (> 500 million motile sperm), progressive motility (> 80%), and normal morphology guarantees reproductive fertility.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1872', 'What working or show titles increase a stud dog''s value?', 'Conformation Champion (CH/GCH), Master National Retriever (MH), Schutzhund/IGP titles, Agility Champion (MACH), or working service certifications.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1873', 'Who pays for reproductive veterinary shipping and collection fees?', 'The owner of the female (dam) is responsible for all reproductive veterinary costs: semen collection, chilling, specialized shipping containers, and insemination.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_stud-fee-calculator_1874', 'What age is ideal for a male dog to begin stud service?', 'Male dogs must be at least 24 months old to complete permanent official OFA hip/elbow clearances before being used as active stud sires.', 'dogs', 'tool', 'stud-fee-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1875', 'What is Wright''s Coefficient of Inbreeding (COI)?', 'COI is a mathematical percentage measuring the probability that two alleles at any gene locus are identical by descent from a common ancestor. Lower COI numbers indicate higher genetic diversity.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1876', 'What is a safe target COI for breeding purebred dogs?', 'Veterinary geneticists recommend keeping 10-generation COI below 5% to 6.25% to prevent inbreeding depression and maintain strong immune system health.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1877', 'What is ''inbreeding depression'' in dogs?', 'A biological phenomenon caused by high inbreeding (COI > 12.5%), resulting in reduced puppy litter sizes, higher puppy mortality, weaker immune systems, and shortened lifespan.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1878', 'Why should COI be calculated across 10 generations rather than 5?', 'A 5-generation pedigree only reveals 62 ancestors and misses significant hidden common ancestors in generations 6 through 10, drastically underestimating true inbreeding.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1879', 'What is the ''Popular Sire Effect'' in purebred dog breeding?', 'When one champion male is bred excessively to hundreds of females, flooding the entire global breed gene pool with his hidden recessive genetic disease mutations.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1880', 'How does high inbreeding affect canine longevity?', 'Research across thousands of dogs proves that every 10% increase in COI reduces median canine lifespan by approximately 1.0 to 1.5 years.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1881', 'What is the difference between inbreeding and linebreeding?', 'Linebreeding is simply a mild term for inbreeding (mating related dogs like grandfather to granddaughter). Genetically, both increase homozygosity and reduce genetic diversity.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1882', 'What is an outcross in dog breeding?', 'Mating two dogs within the same breed that share zero common ancestors in the first 5 to 7 generations (COI ≈ 0%), injecting fresh genetic diversity.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1883', 'Can DNA testing calculate a dog''s genomic COI?', 'Yes! Modern genetic panels (like Embark) measure thousands of genetic markers to calculate an exact *Genomic COI*, which is far more precise than written paper pedigrees.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_genetic-diversity-calculator_1884', 'What is the Major Histocompatibility Complex (MHC / DLA) in dogs?', 'A critical cluster of immune system genes that recognizes viruses and bacteria. Low genetic diversity in DLA genes increases susceptibility to autoimmune diseases.', 'dogs', 'tool', 'genetic-diversity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1885', 'How much weight should a newborn puppy gain each day?', 'A healthy puppy should gain 5% to 10% of its birth weight daily, doubling its original birth weight by 7 to 10 days of age.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1886', 'How much weight should a newborn kitten gain each day?', 'Kittens should gain 10 to 15 grams per day (roughly 100 grams / 3.5 oz per week), weighing approximately 1 pound at 4 weeks of age.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1887', 'What should I do if a newborn puppy or kitten is losing weight?', 'Weight loss is a medical emergency. Warm the newborn slowly, check for cleft palate, ensure they are latching onto high-milk teats, or begin supplemental tube feeding with milk replacer.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1888', 'Why is a digital gram scale necessary for weighing newborns?', 'Human bathroom scales are completely inaccurate for tiny newborns. A digital kitchen scale measuring in exact single grams or tenths of an ounce detects subtle weight drops immediately.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1889', 'How often should newborn puppies and kittens be weighed?', 'Weigh newborns twice daily at the exact same times (morning and evening before nursing) for the first 2 weeks of life, logging weights in a chart.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1890', 'What is ''Fading Puppy / Kitten Syndrome''?', 'A rapid, life-threatening failure to thrive during the first 2 weeks characterized by hypothermia, failure to gain weight, continuous crying, lethargy, and rejection by the mother.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1891', 'Why shouldn''t you feed milk to a cold newborn pet?', 'If body temperature drops below 96°F (35.5°C), the stomach and intestines stop peristalsis (gut ileus). Ingested milk ferments in the gut, causing bloating, toxic shock, and death.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1892', 'Can I feed cows'' milk to an orphaned puppy or kitten?', 'NEVER feed cows'' or goats'' milk alone. It lacks essential protein, fat, and taurine, causing severe fatal diarrhea. Use commercial species-specific milk replacers (Esbilac or KMR).', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1893', 'How do I know which newborn is getting the most milk from mom?', 'The rear abdominal and inguinal teats produce significantly more milk than the upper chest teats. Rotate smaller, weaker pups onto the rear teats.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_puppy-kitten-weight-chart_1894', 'At what age does the rapid neonatal growth rate begin to level off?', 'Weight gain accelerates through weaning (4–8 weeks) and stabilizes into a steady adolescent growth curve around 4 to 6 months of age.', 'general', 'tool', 'puppy-kitten-weight-chart', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1895', 'At what age should puppies and kittens start weaning?', 'Weaning begins around 3.5 to 4 weeks of age when deciduous baby teeth erupt and the mother naturally begins stepping away from the litter.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1896', 'How do you make weaning gruel (puppy/kitten mash)?', 'Blend high-protein puppy or kitten food with warm commercial milk replacer (Esbilac or KMR) and warm water until it forms a smooth, warm soupy gruel.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1897', 'How long does the complete weaning process take?', 'Weaning takes approximately 3 to 4 weeks, starting at week 4 and finishing with full independence on solid food by 7 to 8 weeks of age.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1898', 'Why shouldn''t puppies and kittens be separated from mom before 8 weeks?', 'Weeks 5 through 8 are vital for psychological development: mother and siblings teach bite inhibition, emotional frustration tolerance, and canine/feline communication etiquette.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1899', 'What should I do if a puppy or kitten walks in and plays in the gruel?', 'This is completely normal! Let them walk in it and lick their paws. Gently wipe them clean with a warm, damp washcloth and towel dry immediately so they don''t get chilled.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1900', 'How do you dry up the mother''s milk safely during weaning?', 'Gradually increase separation time between mother and pups over weeks 5 to 7. Reducing the mother''s high-calorie lactation food portions gradually reduces milk production.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1901', 'What is acute canine/feline mastitis?', 'Mastitis is a bacterial infection of the mammary glands. Symptoms include hot, hard, painful, purple/red nipples and fever, requiring immediate veterinary antibiotics.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1902', 'How many times a day should weaned puppies and kittens be fed?', 'Weaned puppies and kittens (ages 8 to 16 weeks) have small stomachs and should be fed 3 to 4 measured meals daily.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1903', 'When should clean drinking water be introduced in shallow dishes?', 'Introduce a heavy, non-tip shallow water dish at 4 weeks of age alongside initial weaning gruel so young animals learn to lap water.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_weaning-schedule_1904', 'Why is puppy/kitten food necessary instead of adult food?', 'Puppy and kitten growth foods contain higher protein, essential DHA for brain development, and exact calcium-to-phosphorus ratios to build dense bones and muscle.', 'general', 'tool', 'weaning-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1905', 'When do newborn puppies and kittens open their eyes?', 'Eyes naturally open between 10 and 14 days of age. Never force eyelids open! Let them open naturally to prevent corneal trauma.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1906', 'When do newborn puppies and kittens open their ears and hear?', 'Ear canals open between 14 and 17 days of age, with the startle response to loud noises developing by day 18 to 21.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1907', 'Why do newborn puppies and kittens need their bellies stimulated to pee and poop?', 'Newborns lack voluntary control of elimination reflexes. The mother licks their anogenital region after nursing to stimulate urination and defecation until week 3.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1908', 'How do I stimulate an orphaned newborn to eliminate?', 'Gently rub the genital and anal area with a warm, damp cotton ball or washcloth in a gentle circular motion immediately after every feeding until they pee and poop.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1909', 'At what age do puppies and kittens get their baby teeth?', 'Deciduous baby teeth start erupting around 3 to 4 weeks of age (incisors and canines first), signaling readiness to begin weaning onto soft gruel.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1910', 'What ambient temperature is required for newborn litters?', 'Week 1: 85°F to 90°F (29°–32°C); Week 2: 80°F (26.7°C); Week 3: 75°F (24°C); Week 4+: standard room temperature (70°–72°F).', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1911', 'When do puppies and kittens learn to walk?', 'Newborns crawl on their bellies for the first 2 weeks. They begin uncoordinated standing and walking around 18 to 21 days of age.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1912', 'When should puppies and kittens receive their first deworming?', 'Routine veterinary deworming (for roundworms and hookworms transmitted through maternal milk) begins at 2, 4, 6, and 8 weeks of age.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1913', 'When should puppies and kittens receive their first core vaccines?', 'The first core vaccine (DHPP for puppies, FVRCP for kittens) is administered at 6 to 8 weeks of age.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_newborn-care-timeline_1914', 'What is Early Neurological Stimulation (ENS / Bio Sensor)?', 'A series of 5 gentle tactile exercises performed for 3–5 seconds daily from Days 3 to 16, proven by the US Military to boost cardiovascular performance and stress resilience.', 'general', 'tool', 'newborn-care-timeline', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1915', 'At what body temperature is a dog officially suffering from heatstroke?', 'A rectal body temperature above 104.0°F (40.0°C) indicates hyperthermia; temperatures above 106.0°F (41.1°C) cause irreversible cellular damage and multi-organ failure.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1916', 'Why should you NEVER use ice water or an ice bath on a dog with heatstroke?', 'Ice water constricts surface blood vessels, trapping burning heat inside internal organs, while shivering generates more internal body heat. Use cool, room-temperature tap water.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1917', 'What are the earliest warning signs of heatstroke in dogs?', 'Excessive heavy panting, thick sticky drool, bright brick-red gums, wide glazed eyes, wobbling uncoordinated gait, and vomiting.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1918', 'Why are French Bulldogs, Pugs, and Boxers at extreme risk for heatstroke?', 'Brachycephalic (flat-faced) breeds have narrow nostrils and elongated soft palates (BOAS), preventing sufficient airflow to dissipate heat through panting.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1919', 'How fast does a parked car become dangerously hot for a pet?', 'Even on a mild 70°F (21°C) day with windows cracked, a car''s interior temperature reaches 100°F in under 20 minutes and 115°F in 30 minutes, causing fatal heatstroke.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1920', 'What is the Temperature-Humidity Index (THI) for dog safety?', 'Add the temperature in °F to the relative humidity %. If the sum exceeds 150 (e.g., 85°F + 70% humidity = 155), outdoor exercise is dangerous and should be avoided.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1921', 'How can I check if asphalt pavement is too hot for my dog''s paws?', 'The 7-Second Rule: Press the back of your bare hand firmly against the asphalt for 7 seconds. If it is too hot for your skin, it will burn your dog''s footpads.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1922', 'What is the correct emergency cooling first aid for heatstroke?', 'Pour cool tap water over the body, apply wet towels to groin and armpits, run fans, offer small sips of water, and transport to the nearest ER immediately.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1923', 'At what temperature should emergency cooling be stopped?', 'STOP active cooling when the dog''s rectal temperature drops to 103.0°F (39.4°C) to prevent the dog from crashing into severe hypothermia.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_heatstroke-risk-calculator_1924', 'Can heatstroke cause delayed organ damage days later?', 'Yes. Heatstroke triggers internal clotting (DIC), acute kidney failure, and bacterial sepsis from gut lining breakdown 24 to 72 hours after initial cooling.', 'general', 'tool', 'heatstroke-risk-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1925', 'At what temperature is it too cold to walk a dog outside?', 'Temperatures below 32°F (0°C) pose risks for small, short-coated, or senior dogs. Temperatures below 20°F (-7°C) are dangerous for all pets, warranting brief 5-minute bathroom breaks only.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1926', 'Why is automotive antifreeze (ethylene glycol) deadly to pets?', 'Antifreeze tastes sweet to animals. A single tablespoon causes acute calcium oxalate crystal formation in kidney tubules, resulting in fatal kidney failure within 24 hours.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1927', 'What are the early clinical signs of hypothermia in dogs?', 'Violent shivering, lethargy, stiff slow movements, pale cold gums, and curled body posture. Severe hypothermia causes shivering to stop, stupor, and coma.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1928', 'How do I protect my dog''s paws from chemical ice melts and salt?', 'Put on waterproof dog booties, apply protective paw wax (Musher''s Secret) before walks, and wash/wipe paws with warm water immediately upon returning home.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1929', 'Do dog winter sweaters and jackets really provide medical protection?', 'YES! For short-coated breeds (Boxers, Whippets, Chihuahuas), puppies, and senior arthritic dogs, insulated jackets prevent dangerous drops in core body temperature.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1930', 'What are the common sites for pet frostbite?', 'The extremities with lowest blood flow: ear tips, tail tips, scrotum, and footpads. Frostbitten tissue turns pale gray/blue, cold, hard, and painful when re-warmed.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1931', 'Why shouldn''t you leave outdoor cats without winter shelter?', 'Outdoor and feral cats suffer severe frostbite and hypothermia. Provide insulated outdoor shelters packed with straw (NEVER hay, which molds, or blankets, which freeze).', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1932', 'Why do outdoor cats hide under car hoods in winter?', 'Warm car engines attract cold cats. Always bang loudly on your car hood or honk your horn before starting your vehicle in freezing weather.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1933', 'Why does cold weather worsen pet arthritis pain?', 'Cold temperatures and falling barometric pressure cause joint fluid to thicken and muscle stiffness to increase. Keep arthritic pets warm and consult your vet about joint supplements.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cold-weather-safety-score_1934', 'How should I rewarm a hypothermic pet at home?', 'Wrap them in warm towels straight from the dryer, place warm water bottles wrapped in towels against their chest/groin, and transport immediately to a veterinary clinic.', 'general', 'tool', 'cold-weather-safety-score', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1935', 'What is the ''7-Second Hand Test'' for hot pavement?', 'Press the back of your bare hand firmly against the asphalt for 7 full seconds. If it is too hot for your hand to hold comfortably, it will severely burn your dog''s paw pads.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1936', 'How hot does asphalt get compared to ambient air temperature?', 'When air temperature is 85°F (29°C), dark black asphalt pavement absorbs solar radiation and heats up to 135°F (57°C)—hot enough to burn paws within 60 seconds.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1937', 'What are the clinical symptoms of burned paw pads in dogs?', 'Limping, refusing to walk, licking/chewing paws frantically, bright red or dark blackened pad tissue, blisters, and missing sloughed skin exposing raw pink tissue.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1938', 'What immediate first aid should I provide for burned paw pads?', 'Flush paws immediately with cool (not ice-cold) running water for 10 to 15 minutes, wrap loosely in clean cotton bandages, and take your dog to a veterinarian.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1939', 'Are protective dog booties effective for hot pavement?', 'YES! High-quality breathable dog booties with rugged rubber soles protect delicate pads from scorching asphalt and burning sand during summer walks.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1940', 'How do winter de-icing salts damage dog paws?', 'Traditional rock salts (calcium chloride) generate chemical heat when wet, creating painful chemical burns on paw pads. Ingesting salt during paw-licking causes severe salt toxicosis.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1941', 'What are pet-safe paw balms (like Musher''s Secret)?', 'Natural wax-based balms (beeswax, carnauba) form a semi-permeable protective barrier against snow, ice balls, rough terrain, and chemical de-icers.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1942', 'Do dogs sweat through their paw pads?', 'YES! Dogs have merocrine sweat glands located exclusively in their paw pads. When hot or nervous, dogs leave damp paw prints on clinic exam tables.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1943', 'How do I toughen up my dog''s paw pads for hiking?', 'Gradually build up walking distances on rough natural dirt trails over several weeks, use protective paw balms, and avoid sudden endurance hikes on jagged rocks.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_paw-pad-temperature-checker_1944', 'Why should you never apply butter or oil to a burned paw?', 'Applying butter, oil, or thick petroleum jelly traps residual heat deep inside the damaged dermis, worsening tissue destruction and increasing bacterial infection risks.', 'dogs', 'tool', 'paw-pad-temperature-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1945', 'Why are so many dogs terrified of fireworks?', 'Fireworks combine loud unpredicted acoustic explosions (up to 150+ dB), seismic ground vibrations, sulfuric burning odors, and flashing lights that trigger deep survival panic.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1946', 'Why is the 4th of July the #1 day of the year for lost pets?', 'Terrified dogs panic, jumping over 6-foot fences and breaking through screen doors to escape fireworks noise. Keep pets locked securely indoors with microchips up to date.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1947', 'Why should Acepromazine NEVER be used for fireworks phobia?', 'Acepromazine paralyzes the dog''s body without reducing fear in the brain. The dog is trapped in terror, unable to move, which worsens future noise phobias.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1948', 'What modern veterinary medications are effective for fireworks anxiety?', 'Sileo (dexmedetomidine oromucosal gel), Trazodone, Gabapentin, and fast-acting benzodiazepines relieve panic safely under veterinary prescription.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1949', 'How does a ThunderShirt help an anxious dog?', 'A ThunderShirt applies gentle, constant pressure across the torso (swaddling effect), stimulating the parasympathetic nervous system and releasing calming hormones.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1950', 'What is the best way to soundproof a room for fireworks night?', 'Choose an interior room with no windows (like a basement or walk-in closet), close heavy curtains, run a loud box fan or white noise machine, and play classical music.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1951', 'Should I comfort and hug my dog when they are scared of fireworks?', 'YES! ''Comforting reinforces fear'' is an outdated myth. You cannot reinforce an involuntary emotional fear response. Gentle, calm stroking provides vital comfort.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1952', 'What are Adaptil (DAP) pheromones and do they work?', 'Adaptil mimics the natural calming pheromone released by nursing mother dogs. Diffusers and collars help reduce mild to moderate anxiety in many dogs.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1953', 'When should I give prescription fireworks anxiety medications?', 'Administer medications 1 to 2 hours *before* the fireworks or thunderstorm begins. Giving meds once the dog is already in a full panic state severely reduces efficacy.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fireworks-anxiety-prep_1954', 'How can I desensitize my puppy to firework sounds early?', 'Play firework sound tracks at barely audible volume while feeding delicious meals. Over weeks, gradually increase volume as long as the dog remains happy and eating.', 'general', 'tool', 'fireworks-anxiety-prep', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1955', 'What is the most dangerous Halloween candy for dogs?', 'Sugar-free candies containing Xylitol (causes fatal liver failure and seizures), dark baker''s chocolate (cardiac toxicity), and chocolate-covered raisins (kidney failure).', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1956', 'What should I do if my dog eats a bag of candy with foil wrappers?', 'Call your emergency vet immediately. Ingested cellophane, foil wrappers, and lollipop sticks can form a solid mechanical intestinal blockage requiring surgery.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1957', 'Why do some dogs become aggressive toward people in Halloween costumes?', 'Costumes, masks, and hats distort normal human silhouettes and hide facial expressions, triggering a dog''s natural territorial threat defense.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1958', 'How do I prevent my pet from darting out the front door during trick-or-treating?', 'Set up a safe sanctuary room in a quiet back bedroom with food, water, a frozen KONG, and a white noise machine, keeping the door locked all evening.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1959', 'Are glow sticks and glow jewelry toxic to cats?', 'Glow sticks contain dibutyl phthalate. While rarely fatal, the bitter stinging chemical causes intense profuse drooling, foaming at the mouth, and agitation in cats.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1960', 'Are carved pumpkins and gourds toxic to pets?', 'Raw pumpkin is non-toxic in small amounts, but moldy jack-o''-lanterns harbor mycotoxins that cause neurological tremors, while real candle flames cause burn hazards.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1961', 'Is it safe to dress my pet in a Halloween costume?', 'Only if the costume fits loosely, does not restrict vision, hearing, breathing, or movement, and has no chewable buttons or choking hazards. Never force an anxious pet into clothing.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1962', 'What are the signs of chocolate poisoning in dogs?', 'Restlessness, panting, excessive thirst, vomiting, diarrhea, rapid elevated heart rate, muscle tremors, and seizures appearing 6 to 12 hours post-ingestion.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1963', 'Why are black cats kept indoors around Halloween?', 'To protect them from pranks, cruelty, and vehicle accidents during high-traffic Halloween festivities. Keep all cats securely indoors.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_halloween-safety-checker_1964', 'What should I have on hand on Halloween night for pet safety?', 'The phone numbers for the Pet Poison Helpline (855-764-7661) and your local 24/7 emergency veterinary hospital, with collar ID tags securely on your pet.', 'general', 'tool', 'halloween-safety-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1965', 'Why is Christmas tinsel extremely dangerous for cats?', 'Tinsel is a linear foreign body. If swallowed, it bunches the intestines like an accordion, slicing through the intestinal wall and causing fatal septic peritonitis requiring surgery.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1966', 'What holiday foods cause severe Pancreatitis in dogs?', 'High-fat holiday meats (turkey skin, ham, gravy, bacon, buttery scraps) trigger acute inflammation of the pancreas, causing severe vomiting, abdominal pain, and dehydration.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1967', 'Are Poinsettia plants truly fatal to pets?', 'Poinsettias are mildly irritating (causing drooling and mild vomiting), but are NOT fatal. Real holiday dangers are Mistletoe, Holly, and Lily arrangements in bouquets.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1968', 'Why are true lilies in holiday bouquets deadly to cats?', 'Eating a single leaf or petal, or licking water from a lily vase, causes acute, irreversible kidney failure and death in cats within 24 to 72 hours.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1969', 'Is Christmas tree water toxic to dogs and cats?', 'Yes. Stagnant tree stand water harbors toxic fertilizers, pine sap, mold, and bacteria. Cover the tree base so pets cannot drink from it.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1970', 'What should I do if my pet chews on Christmas tree light cords?', 'Unplug the cord immediately without touching the pet. Electrical shock causes oral burns and life-threatening fluid accumulation in the lungs (pulmonary edema).', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1971', 'Why are glass Christmas ornaments dangerous?', 'Chewing or stepping on fragile glass ornaments causes deep paw lacerations and internal mouth, esophageal, and intestinal punctures if swallowed.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1972', 'Can dogs eat holiday gingerbread cookies?', 'No. Gingerbread contains nutmeg, which contains the toxin myristicin, causing tremors, seizures, and elevated heart rates, along with high sugar and spices.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1973', 'Why is holiday bread dough dangerous if swallowed raw?', 'Yeast bread dough continues fermenting in the warm stomach, expanding to cause severe bloat (GDV) while producing toxic alcohol that causes alcohol poisoning.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_christmas-hazard-lookup_1974', 'How do I pet-proof my Christmas tree?', 'Anchor the tree securely to a wall or ceiling, place fragile ornaments and wires high out of reach, cover the water basin, and avoid tinsel and edible popcorn garlands.', 'general', 'tool', 'christmas-hazard-lookup', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1975', 'How do pet allergies differ from human seasonal allergies?', 'Humans experience respiratory symptoms (sneezing, runny nose). Dogs and cats manifest allergies through intense skin itching, obsessive paw licking, and recurrent ear infections.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1976', 'Why does my dog obsessively lick and chew their paws in spring and autumn?', 'Paws walk directly through grass pollen and environmental allergens. The allergen penetrates the skin barrier, triggering localized inflammation and secondary yeast infections.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1977', 'What is Cytopoint and how does it stop dog itching?', 'Cytopoint is an injectable monoclonal antibody that neutralizes the Interleukin-31 (IL-31) protein responsible for sending the itch signal to the brain, lasting 4 to 8 weeks.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1978', 'What is Apoquel (Oclacitinib)?', 'Apoquel is a daily oral Janus Kinase (JAK) inhibitor tablet that blocks allergic inflammation and itch pathways within 4 hours without the harsh side effects of steroids.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1979', 'Why do white dogs get rusty reddish-brown stains on their paws?', 'Saliva and tears contain porphyrin iron pigments. Obsessive licking deposits porphyrin on white fur, staining it reddish-brown.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1980', 'What is Flea Allergy Dermatitis (FAD)?', 'A hypersensitivity to flea saliva proteins. In allergic pets, a single flea bite triggers days of intense itching, hair loss, and scabbing over the lower back and tail base.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1981', 'How do veterinarians diagnose food allergies vs. environmental allergies?', 'Through a strict 8- to 12-week elimination diet trial using a prescription hydrolyzed protein diet (like Royal Canin HP or Hill''s z/d). Blood allergy tests for food are inaccurate.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1982', 'Can human antihistamines (like Benadryl) help an itchy dog?', 'Diphenhydramine (Benadryl) helps only 15% to 20% of dogs with atopic skin allergies and primarily causes mild drowsiness. Modern JAK inhibitors are vastly superior.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1983', 'How can regular bathing help a dog with environmental pollen allergies?', 'Bathing weekly with cool water and a soothing chlorhexidine or phytosphingosine shampoo physically washes pollen and allergens off the skin and repairs the lipid barrier.', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_allergy-season-tracker_1984', 'What are the common signs of an allergic ear infection in dogs?', 'Head shaking, scratching at ears, redness inside the ear canal, and a dark brown discharge with a sweet, pungent yeasty odor (*Malassezia* yeast overgrowth).', 'general', 'tool', 'allergy-season-tracker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1985', 'How does poor air quality and wildfire smoke affect pets?', 'Fine particulate matter (PM2.5) penetrates deep into the lungs, triggering coughing, watery eyes, nasal discharge, wheezing, lethargy, and severe asthma attacks.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1986', 'What Air Quality Index (AQI) number is dangerous for dogs and cats?', 'An AQI over 100 is risky for pets with asthma, heart disease, or flat faces. An AQI over 150 requires keeping all pets indoors with windows closed and brief bathroom breaks only.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1987', 'Why are companion birds at extreme risk from smoke and air pollution?', 'Birds have highly efficient, delicate respiratory air sacs that absorb airborne toxins rapidly. Wildfire smoke or non-stick Teflon fumes can be fatal to birds within minutes.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1988', 'What are the symptoms of smoke inhalation distress in pets?', 'Frequent coughing, open-mouth breathing in cats, wheezing, blue/pale gums, uncoordinated walking, and refusal to eat. Seek immediate veterinary oxygen therapy.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1989', 'How can I protect my pet''s lungs during wildfire smoke season?', 'Keep windows closed, run a True HEPA air purifier in the house, eliminate outdoor cardio play, wipe paws and fur with damp cloths after quick potty trips, and ensure plenty of fresh water.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1990', 'Do air pollution masks work for dogs?', 'Canine particulate masks exist, but most dogs find them distressing, and they can impair panting thermoregulation. Keeping pets indoors in filtered air is much safer.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1991', 'What is Feline Asthma and how is it triggered by bad air?', 'Feline asthma is chronic lower airway inflammation. Smoke, dust, and incense trigger severe bronchial constriction, causing cats to crouch low and cough repeatedly.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1992', 'Why are brachycephalic (flat-faced) dogs more vulnerable to air pollution?', 'Their pinched nostrils and narrow windpipes restrict airflow, making it extremely difficult to clear particulate matter and leading to rapid respiratory fatigue.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1993', 'Can second-hand tobacco smoke harm companion pets?', 'Yes. Second-hand smoke causes chronic bronchitis in dogs, nasal cancer in long-nosed breeds, and malignant feline lymphoma (as cats groom carcinogens off their fur).', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_air-quality-impact-assessor_1994', 'How do I create a clean-air room for my pets during high-AQI events?', 'Pick an interior room with minimal windows, seal door drafts, run a continuous True HEPA air filter (avoid ozone generators), and provide fresh water and soft bedding.', 'general', 'tool', 'air-quality-impact-assessor', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_1995', 'Do all reptiles need UVB?', 'Even nocturnal and crepuscular species benefit from low-level UVB (Ferguson Zone 1). Peer-reviewed studies show improved bone density, immune function and behaviour across ball pythons, leopard geckos and corn snakes.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_1996', 'How do I know if my UVB bulb still works?', 'The only reliable check is a Solarmeter 6.5. If you don''t own one, replace on schedule regardless of how bright the bulb still looks.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_1997', 'Is a compact / coil UVB enough?', 'Compacts produce a very narrow UV column and often decay in 3-4 months. Linear T5-HO with a reflector is the modern standard for most diurnal species.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_1998', 'Can UVB pass through glass or plastic?', 'No. Standard glass and acrylic block virtually all UVB. Mount the fixture inside the enclosure or over a mesh top.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_1999', 'How close should the bulb be?', 'Depends on percentage and reflector. A 12% T5-HO with reflector reaches Ferguson Zone 3 at ~12 inches; without reflector, ~8 inches. Verify with a Solarmeter.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2000', 'What''s metabolic bone disease?', 'MBD is a calcium/vitamin D deficiency that softens bones, curves the spine and jaw, causes fractures, and is frequently fatal. It''s the #1 preventable disease in captive reptiles — and preventable with correct UVB and calcium.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2001', 'Do I need to supplement calcium if UVB is correct?', 'Yes. Most captive diets are calcium-poor. Dust feeder insects with plain calcium 4-5 days a week and calcium with D3 1-2 days for insectivores.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2002', 'Can I use sunlight instead?', 'Direct outdoor sunlight is ideal — no glass. Provide shade and never leave a reptile unattended in a glass tank in the sun (overheating is fatal within minutes).', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2003', 'What is UVI vs UVB percentage?', 'UVI is the biologically-relevant measure of UVB output at the animal''s basking spot. Percentage (5%, 10%, 12%) is a bulb spec — actual UVI depends on distance and reflector.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2004', 'How long is ''photoperiod''?', 'The hours per day the UVB light is on. Most species do well with 10-12 hours in summer and 8-10 in winter, mimicking natural seasons.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2005', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_reptile-uvb-schedule_2006', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'reptile-uvb-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2007', 'How do I actually measure the temperature?', 'Use a digital infrared temp gun aimed at the actual basking surface. Stick-on and dial thermometers are unreliable — they often read air temp, not the animal''s contact surface.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2008', 'Should heat be off at night?', 'For most desert and temperate species, yes. A nighttime drop is biologically necessary. Only supplement heat if the room drops below the species-specific minimum (usually 60-65°F).', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2009', 'Are heat rocks safe?', 'No. Heat rocks concentrate heat in a small area and routinely cause deep contact burns on reptiles that don''t feel low-grade pain the way mammals do.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2010', 'What produces overhead heat?', 'Halogen flood bulbs (best for basking — bright, radiant, and match natural sunlight), ceramic heat emitters (heat only, good for night), and Deep Heat Projectors (infrared-A/B, mimic sun infrared).', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2011', 'Do I need a thermostat?', 'Yes — always. A pulse-proportional or dimming thermostat prevents fires and lethal temperature spikes. Bulbs and heat mats fail unpredictably.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2012', 'Why does my basking spot show 130°F?', 'Bulb too close, too high wattage, or focused reflector. Raise the fixture or step down wattage until surface reads target range.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2013', 'Is a temperature ''gradient'' the same as one warm side?', 'No — the gradient is a smooth transition. The hot basking spot is small; the warm ambient area is roughly ⅓ of the enclosure; the cool retreat is another ⅓; the middle blends between.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2014', 'How large should the basking spot be?', 'Big enough for the entire animal to lie flat and receive heat on both sides of the body — not just the head.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2015', 'What if the whole room is very cold?', 'Add ambient heat (space heater in the room on its own thermostat) rather than cranking the tank hotter, which cooks the basking spot.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2016', 'How often should I verify temps?', 'Once at setup, then weekly. After any bulb change or seasonal shift, re-verify the same day.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2017', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tank-temperature-gradient-calculator_2018', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'tank-temperature-gradient-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2019', 'Why is clipping only one wing considered dangerous by veterinarians?', 'Clipping only one wing creates severe aerodynamic imbalance. When the bird startles and attempts to fly, it spirals in a violent, uncontrollable spin, crashing head-first into walls or shattering its chest bone on the floor.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2020', 'What is the keel bone and why does severe clipping injure it?', 'The keel is the thin, prominent ridge of the breastbone where flight muscles attach. A severely clipped bird falls like a rock; impacting hard floors splits the skin over the keel, causing severe hemorrhage and bone fractures.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2021', 'What is a blood feather and how do I recognize it?', 'A blood feather is an immature, actively growing feather. It has a thick, dark purple or blue-black shaft filled with pressurized blood vessels. Never cut a blood feather, as it will cause profuse and dangerous bleeding.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2022', 'Can a properly clipped bird still fly outdoors?', 'YES. Even conservatively clipped birds can catch an outdoor thermal updraft or tailwind during a panic startle and be carried hundreds of feet into tall trees or away from home. Never take a bird outside without an Aviator harness or carrier.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2023', 'How many feathers should be trimmed during a conservative clip?', 'Trim only the outer 4 to 6 primary flight feathers on both wings symmetrically. Never touch the secondary flight feathers located closer to the body, as they provide critical braking lift.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2024', 'Why should young fledgling birds not be clipped?', 'Fledglings must learn to fly, turn, land, and build muscle coordination. Clipping a young bird before it learns to fly causes permanent loss of confidence, poor balance, and lifelong clumsiness.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2025', 'How long does it take for clipped feathers to grow back?', 'Clipped feathers will not grow back until the next seasonal molt cycle (typically 6 to 10 months), when the old trimmed shafts naturally fall out and new blood feathers emerge.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2026', 'Does feather clipping hurt the bird?', 'Trimming fully mature, clear-shafted primary feathers does not hurt at all—it is equivalent to trimming human fingernails. However, improper restraint can cause severe stress, and cutting a blood feather is extremely painful.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2027', 'What should I do if a clipped bird crashes and splits its breast?', 'Place the bird in a warm, padded carrier, apply gentle pressure with a clean sterile gauze if bleeding, and transport immediately to an emergency avian veterinarian for wound closure and pain management.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-wing-clipping-guide_2028', 'Can flighted birds live safely in a home without clipping?', 'Yes, millions of birds live full-flighted! It requires dedicated bird-proofing: turning off all ceiling fans, covering large mirrors and windows with decals or curtains, locking away cats/dogs, and closing exterior doors.', 'birds', 'tool', 'bird-wing-clipping-guide', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2029', 'Can ferrets be 100% litter trained like a domestic cat?', 'No. Even the best-trained ferrets typically achieve 75% to 90% reliability. Because ferrets have a 3- to 4-hour digestion transit time and get intensely focused during play, occasional corner accidents are completely normal.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2030', 'Why do ferrets back into corners to poop?', 'Corner-backing is a natural wild survival instinct. Backing into a 90-degree corner protects the ferret''s vulnerable rear and blind spots from predators while eliminating.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2031', 'What litter is safest for ferrets?', 'Recycled paper pellets (such as Yesterday''s News) or compressed wood pellets are safest. Never use clay clumping cat litter, which sticks to paw pads, enters the respiratory tract, and causes fatal intestinal blockages if swallowed.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2032', 'Why does my ferret poop right next to the litter box instead of inside it?', 'This common frustration happens when the box entrance lip is too tall, the box is dirty, or the box is too small to fit the ferret''s entire body comfortably. Ensure all four paws fit inside with a low 1-inch front entry.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2033', 'How do I stop my ferret from digging in the litter box?', 'Ferrets love to dig! Provide a dedicated separate digging box filled with dry long-grain rice, ping-pong balls, or autumn leaves to satisfy their burrowing drive away from the bathroom box.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2034', 'Why do ferrets wake up and immediately need to use the bathroom?', 'Metabolism slows during deep sleep. Upon waking, the gastrocolic reflex stimulates the bowel within 5 to 15 minutes, making morning wake-up the best time for scheduled litter box training.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2035', 'What treats are best for rewarding litter box use in ferrets?', 'High-protein, meat-based rewards work best: a drop of pure salmon oil on your finger, a lick of meat baby food (with zero onions/garlic), or freeze-dried raw chicken hearts.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2036', 'How many litter boxes do I need for a free-roaming ferret?', 'Provide at least one litter box per room, plus additional boxes in any corner your ferret frequently targets. Ferrets will not walk to another room when the urge strikes.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2037', 'Can older rescue ferrets be litter trained?', 'Yes! Older ferrets can be trained using the same cage-confinement, waking routine, and positive reinforcement techniques, usually establishing good habits within 2 to 3 weeks.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_ferret-litter-trainer_2038', 'Why should I use vinegar or enzymatic cleaner instead of bleach on accidents?', 'Bleach and standard soaps leave behind residual organic scent markers, while ammonia cleaners mimic urine chemistry. Enzymatic cleaners and white vinegar break down uric acid crystals completely, preventing repeat accidents.', 'small-pets', 'tool', 'ferret-litter-trainer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2039', 'Why does my turtle never bask?', 'Common causes: dock is wet or slippery, water too cold, dock too high to climb, tank in high-traffic area, or basking bulb too weak. Fix each and observe.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2040', 'What temperature should the basking spot be?', '90-95°F surface temperature for most aquatic turtles. Measure with an infrared gun — not room-temp guesses.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2041', 'Do turtles need UVB if outside daily?', 'Direct outdoor sunlight (not through glass) is the gold standard. Indoor tanks always need UVB.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2042', 'How do I know my water temp?', 'Submersible digital thermometer. Set an aquarium heater with guard to species range.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2043', 'Can turtles overheat while basking?', 'Yes if the cool zone (water or shade) isn''t accessible in one motion. Always provide easy escape from heat.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2044', 'What''s shell rot?', 'Bacterial or fungal infection that eats into the shell. Prevented by daily complete-dry basking and clean water.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2045', 'Do tortoises need to soak?', 'Yes — weekly for adults, several times a week for hatchlings, in shallow warm water (85-90°F) up to the plastron for 15-20 minutes.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2046', 'How big must the dock be?', 'Large enough for the entire turtle to sit completely out of the water. Tiny corner rocks do not qualify.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2047', 'How long can a turtle go without basking?', 'A day or two is not concerning. Weeks without basking cause metabolic and shell disease.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2048', 'Is filtered water necessary?', 'Aquatic turtles are extremely messy. Use a canister filter rated for 2-3× the tank''s actual water volume.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2049', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_turtle-basking-time-calculator_2050', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'turtle-basking-time-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2051', 'How often should goat hooves be trimmed?', 'Most domestic goats need their hooves trimmed every 6 to 8 weeks. Goats on rocky, dry pastures may go 8 to 10 weeks, while goats in damp, muddy areas or fast-growing dairy does need trims every 4 to 6 weeks.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2052', 'What tools are needed to trim goat hooves properly?', 'You need sharp, specialized goat hoof shears (orange-handle serrated shears), a hoof pick to remove dirt, a fine hoof rasp, leather work gloves, and styptic powder in case of accidental nicks.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2053', 'What should I do if I accidentally cut into the quick and the hoof bleeds?', 'Don''t panic! Apply styptic powder (Kwik-Stop) or cornstarch with direct finger pressure for 1 to 2 minutes until bleeding stops. Spray with antiseptic blue lotion (Blu-Kote) and keep the goat on clean, dry bedding.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2054', 'What are the signs of contagious foot rot in goats?', 'Signs include severe limping (goats grazing on their knees), foul-smelling gray discharge between the toes, separation of the hoof wall from the sole, and hot, inflamed foot tissue.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2055', 'How do I treat foot rot and foot scald?', 'Trim away all detached, rotting hoof wall to expose the bacteria to oxygen. Soak the hooves in a 10% Zinc Sulfate or Copper Sulfate footbath for 10–15 minutes, apply topical antiseptic spray, and isolate from muddy areas.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2056', 'How do I know when to stop trimming the goat''s sole?', 'Stop trimming the moment the sole appears flat and level with the hoof walls and you see a faint pinkish tint. Pink indicates you are right above the sensitive blood supply of the corium.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2057', 'Should pregnant does have their hooves trimmed before kidding?', 'Yes! Trim does 4 to 6 weeks before their due date. Do NOT trim does in the final 2 weeks of pregnancy, as physical restraint stress can trigger premature labor.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2058', 'Why do front hooves often grow faster than hind hooves on goats?', 'Goats carry approximately 60% of their total body weight on their front legs, stimulating higher blood circulation to the coronary bands of the front hooves, resulting in faster keratin growth.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2059', 'Can I trim goat hooves without a dedicated trimming stand?', 'Yes. You can back the goat into a corner, hold it against a wall with a halter, or sit smaller goats (like Nigerian Dwarfs) onto their rumps like sheep. However, a trim stanchion makes the job much safer.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_goat-hoof-trim-reminder_2060', 'Does diet affect how fast goat hooves grow?', 'Yes! Diets high in protein and carbohydrates accelerate hoof growth significantly, while high-grain diets increase the risk of subclinical laminitis, causing hoof ridges, soft soles, and wall flaring.', 'farm', 'tool', 'goat-hoof-trim-reminder', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2061', 'Why is a rolling 6-week farrier schedule recommended for shod horses?', 'By 6 weeks, the hoof wall has grown forward by 10–12 mm. This shifts the shoe forward and delays the breakover point, placing high strain on the deep digital flexor tendon and navicular bone. Resetting shoes every 6 weeks maintains correct biomechanical alignment.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2062', 'How do I know my horse is overdue for the farrier?', 'Warning signs include long flared toes, shoes shifting forward under the heels, loose or raised nails (clinches), clicking noises at the walk, tripping, and chipping of the barefoot wall.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2063', 'Why do farrier intervals need to be shorter in the summer?', 'Warm weather and lush pasture stimulate peripheral blood flow and provide vitamins that accelerate hoof growth to 8–10 mm per month, requiring farrier appointments every 4 to 5 weeks instead of 6.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2064', 'What should I do if my horse pulls a shoe and bends the nails?', 'Carefully inspect the foot. If bent nails are still attached, gently straighten and pull them out with pliers to prevent the horse from stepping on a nail. Wrap the foot in vetwrap/duct tape or put on a hoof boot and call your farrier.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2065', 'What is the difference between a shoe reset and a new shoe set?', 'A ''reset'' means the farrier cleans, balances, and nails the horse''s existing shoes back on after trimming. A ''new set'' means the old shoes are worn thin or misshapen and are replaced with brand-new steel or aluminum shoes.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2066', 'How can I prepare my horse for a successful farrier visit?', 'Bring the horse in early so its legs and feet are completely dry and clean of mud. Ensure the horse is well-mannered about lifting all four feet, apply fly spray during summer, and provide a clean, level, well-lit workspace.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2067', 'What is a negative palmar angle and how does a farrier fix it?', 'A negative palmar angle occurs when the coffin bone angles downward toward the heel instead of sloping gently forward, usually due to collapsed heels. Farriers correct this using therapeutic trimming, wedge pads, or specialized bar shoes.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2068', 'Why do horses sometimes get abscesses after being trimmed?', 'Abscesses occur when bacteria enter microscopic fissures in the white line or sole. Sudden wet weather softens the hoof, allowing bacteria inside where it forms a painful pocket of pus requiring soaking and drainage.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2069', 'How much does a standard farrier visit cost?', 'A barefoot trim typically costs $40 to $70 per horse, while a full set of four steel shoes with trim ranges from $120 to $250+ depending on region, discipline, and corrective requirements.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_horse-farrier-schedule_2070', 'Can bad farrier work cause long-term lameness?', 'Yes. Improper trimming that leaves hooves unbalanced (medial-lateral imbalance or long-toe/low-heel) places abnormal torque on joints and ligaments, leading directly to ringbone, sidebone, navicular disease, and chronic arthritis.', 'horses', 'tool', 'horse-farrier-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2071', 'Why is my hygrometer showing 30% when I just misted?', 'Analog dial hygrometers are typically 10-15% off. Buy a digital hygrometer (Govee, Inkbird) and place it at the animal''s height, not at the top of the enclosure.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2072', 'Should humidity be constant?', 'For most species no. Natural humidity cycles — high at night after misting, dropping to a lower daytime baseline — mimic wild conditions and prevent bacterial growth.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2073', 'What causes stuck sheds?', 'Low humidity relative to species need. Provide a humid hide with damp sphagnum moss so the animal can self-regulate.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2074', 'What causes respiratory infection?', 'Constant high humidity with poor ventilation, wet substrate contacting the animal, or cold temperatures. Fix ventilation and heat gradient.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2075', 'How do I raise humidity in a screen enclosure?', 'Cover 30-50% of the top with plexiglass, add a large water bowl over the heat source, use bioactive substrate with live plants, or install an ultrasonic fogger.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2076', 'How do I lower humidity?', 'Increase ventilation, reduce misting, swap to a drier substrate (aspen instead of coco), and lower the water bowl surface area.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2077', 'Can I use an ultrasonic fogger overnight?', 'For amphibians and chameleons, yes. Never for arid or temperate reptiles — cold wet nights cause pneumonia.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2078', 'Bioactive substrate — worth it?', 'For humidity-loving species, absolutely. Live plants, springtails and isopods buffer humidity, break down waste and stabilise the microclimate.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2079', 'Does room humidity matter?', 'Yes. In dry winter climates you may need to add a room humidifier to hit target range without soaking the substrate.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2080', 'Why does humidity spike when I turn heat off?', 'Warm air holds more moisture. As temps drop overnight, relative humidity rises. This is normal and matches natural patterns for most species.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2081', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_vivarium-humidity-calculator_2082', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'vivarium-humidity-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2083', 'How accurate is visual photo breed identification for mixed-breed dogs?', 'AI vision models achieve high accuracy on purebred dogs. However, in mixed-breed dogs with 3+ ancestral breeds, visual identification matches DNA in only 25% of cases due to dominant gene masking.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2084', 'What morphological features does AI analyze to identify dog breeds?', 'AI analyzes cranial skull shape (cephalic index), ear set, muzzle length, coat length/texture, color distribution patterns, tail carriage, and body proportions.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2085', 'How do veterinary canine DNA tests work?', 'Cheek swab DNA tests analyze over 200,000 Single Nucleotide Polymorphism (SNP) genetic markers against reference databases of 350+ recognized dog breeds.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2086', 'Why do so many mixed-breed shelter dogs look like ''Pit Bull'' or ''Lab'' mixes?', 'Short coats, blocky heads, and floppy ears are common dominant traits produced by dozens of diverse breed crosses, frequently leading to inaccurate breed labeling.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2087', 'What is a ''furnishing'' gene in Doodle and Terrier breeds?', 'The RSPO2 gene causes facial furnishings (beards and bushy eyebrows), giving dogs their signature teddy-bear look while reducing shedding.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2088', 'Can AI identify domestic cat breeds from photos?', 'Yes, AI identifies distinct cat breeds (Persian, Siamese, Maine Coon, Bengal). However, 95% of domestic cats are non-pedigreed Domestic Shorthairs or Longhairs.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2089', 'What is ''hybrid vigor'' in mixed-breed companion pets?', 'Hybrid vigor refers to greater genetic diversity in mixed-breed animals, reducing the expression of specific recessive genetic diseases common in inbred purebred lines.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2090', 'How can knowing my dog''s genetic breed mix help their veterinary care?', 'Knowing your dog''s breed mix alerts you to critical breed-specific medical risks, such as the MDR1 drug mutation in herding dogs or hip dysplasia in large breeds.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2091', 'What is the MDR1 gene mutation in herding breeds?', 'A genetic mutation common in Collies and Australian Shepherds causing a defective blood-brain barrier, making common medications (like Ivermectin) fatal.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-breed-identifier_2092', 'What is the best lighting and angle to take a photo for AI breed identification?', 'Take a clear, well-lit photo of your standing pet from side eye-level, capturing the full body profile, head shape, and tail carriage clearly.', 'general', 'tool', 'pet-breed-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2093', 'How do veterinarians estimate a rescue dog''s age by its teeth?', 'Puppy milk teeth erupt by 6–8 weeks; adult teeth arrive between 4 and 6 months. Adult age is estimated by examining incisor tooth wear, tartar accumulation, and gum recession.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2094', 'What is the cloudy blue haze in older dogs'' eyes (Nuclear Sclerosis)?', 'Nuclear sclerosis is a normal, harmless aging change in the lens fibers of dogs older than 7. It looks bluish-grey but does not cause blindness, unlike true cataracts.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2095', 'What is the difference between Nuclear Sclerosis and a Cataract?', 'Nuclear sclerosis allows light to pass through and does not cause blindness. Cataracts are opaque white clouds that block light completely, leading to vision loss.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2096', 'Can dogs develop grey facial muzzles at a young age?', 'Yes! Genetic factors and chronic anxiety can cause dogs to develop premature grey muzzle hair as early as 2 to 4 years of age.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2097', 'How do you estimate a kitten''s age during the first 8 weeks?', 'Kittens gain roughly 100g per week: eyes open at 10–14 days, ears open at 2 weeks, baby teeth erupt at 3–4 weeks, and weight reaches roughly 2 lbs at 8 weeks.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2098', 'What physical changes indicate a senior cat?', 'Senior cats develop cloudy ocular lenses, thinning skin over the spine, reduced grooming (clumpy coat), arthritis stiffness, and yellowing dental tartar.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2099', 'Can dental cleaning make an older dog look younger on age estimates?', 'Yes. Professional dental scaling removes heavy tartar stains, so veterinarians also examine bone wear, muscle mass, and ocular lenses for accuracy.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2100', 'What is sarcopenia in older pets?', 'Sarcopenia is the age-related loss of skeletal muscle mass, commonly seen as prominent spine bones and thinning thigh muscles in geriatric animals.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2101', 'How accurate is AI photo age estimation for pets?', 'AI provides reliable life-stage classifications (Puppy/Kitten, Young Adult, Senior), though exact chronological year estimation requires physical veterinary palpation.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-age-estimator-photo_2102', 'At what age do companion animals stop growing physically?', 'Small dogs reach full skeletal size at 9–12 months, medium dogs at 12–15 months, and giant breeds (Mastiffs, Great Danes) continue filling out until 18–24 months.', 'general', 'tool', 'pet-age-estimator-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2103', 'What is the ''guilty look'' in dogs according to science?', 'Cognitive studies prove the ''guilty look'' (cowering, looking away) is an appeasement display reacting to the owner''s present angry tone, not a moral feeling of guilt for past actions.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2104', 'What does ''Whale Eye'' mean in canine body language?', 'Whale Eye occurs when a dog turns its head away but keeps its eyes fixed on you, exposing the white sclera. It signals extreme stress, fear, and potential defensive biting.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2105', 'Does a wagging tail always mean a dog is happy?', 'NO! A wagging tail simply indicates emotional arousal. A loose, sweeping circular tail wag signals happiness; a stiff, high-held tail vibrating rapidly signals high-stress arousal.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2106', 'How do cats show subtle signs of affection and love?', 'Slow blinking (the ''feline kiss''), head bunting (rubbing facial scent glands on you), purring, holding the tail straight up with a slight question-mark curve, and kneading paws.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2107', 'What does it mean when a dog suddenly lip licks or yawns when not tired?', 'Yawning and rapid nose-licking outside of waking up are displacement appeasement signals indicating the dog is feeling nervous or uncomfortable.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2108', 'What are ''raised hackles'' (piloerection) on a dog''s back?', 'Piloerection is an involuntary sympathetic nervous system reflex (like human goosebumps) caused by sudden adrenaline, indicating surprise, arousal, or fear.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2109', 'How do cats communicate stress through their ears and tails?', 'Flattening ears back against the head (''airplane ears''), rapidly twitching the tip of the tail, and dilated black pupils signal escalating irritation and defensive readiness.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2110', 'What is DogFACS and CatFACS in behavioral science?', 'Facial Action Coding Systems are scientific tools that measure individual micro-movements of animal facial muscles to objectively decode emotional states.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2111', 'Why do dogs roll onto their backs when meeting strangers?', 'Rolling over to expose the belly is often a submissive appeasement signal saying ''I am not a threat, please don''t hurt me'', rather than an invitation for a belly rub.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-emotion-detector_2112', 'What is a ''play bow'' in canine communication?', 'A play bow (front elbows down, rear end high in the air with a wagging tail) is a universal metacommunicative signal that means ''everything that follows is just play''.', 'general', 'tool', 'pet-emotion-detector', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2113', 'What is a ''Hot Spot'' (Acute Moist Dermatitis) on a dog?', 'A hot spot is a rapidly developing, red, moist, oozing, hairless bacterial skin lesion caused by intense self-trauma (scratching/licking) from flea bites, allergies, or wet fur.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2114', 'How do veterinarians treat a hot spot?', 'Clip the surrounding fur to let the skin dry, clean with antiseptic chlorhexidine flush, apply topical antimicrobial/steroid cream, and put on an Elizabethan cone collar to stop licking.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2115', 'Is Ringworm in dogs and cats a real worm?', 'NO! Ringworm is a contagious fungal infection (*Microsporum canis*), not a worm. It causes circular patches of hair loss with scaly crusts and is zoonotic (spreads to humans).', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2116', 'What causes dark, thickened ''elephant skin'' on an itchy dog?', 'Chronic scratching and secondary yeast (*Malassezia*) infections cause hyperpigmentation and lichenification (thickening of the skin into a dark, leathery texture).', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2117', 'What is the difference between Sarcoptic and Demodectic mange?', 'Sarcoptic mange (scabies) is caused by contagious, burrowing mites causing intense, agonizing itching. Demodectic mange is caused by non-contagious follicular mites in young or immune-compromised pets.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2118', 'Why do dogs get skin infections in their facial and tail folds?', 'Skin folds (in French Bulldogs, Pugs, Bulldogs) trap heat, sweat, and moisture, creating an ideal dark breeding ground for yeast and bacterial skin-fold dermatitis (intertrigo).', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2119', 'Can human hydrocortisone cream be used on a dog''s itchy skin?', 'Use cautiously under vet guidance. If the dog licks the cream, ingested steroids can cause hormonal imbalances, and steroids must never be used on open fungal or corneal ulcers.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2120', 'What is Flea Allergy Dermatitis (FAD)?', 'An allergic hypersensitivity to flea saliva where a single flea bite causes severe itching, hair loss, and scabbing over the lower back and base of the tail.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2121', 'How does in-clinic skin cytology work?', 'The veterinarian presses clear tape or a glass slide against the lesion, stains the cells, and views them under a microscope to immediately identify bacteria, yeast, or inflammatory cells.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_skin-condition-analyzer_2122', 'What medicated shampoo ingredients help with bacterial and yeast skin infections?', 'Shampoos combining 2% to 4% Chlorhexidine (antibacterial) and 1% to 2% Ketoconazole or Miconazole (antifungal) are the gold standard for treating microbial dermatitis.', 'general', 'tool', 'skin-condition-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2123', 'What is an ideal Body Condition Score (BCS) on the 9-point scale?', 'A score of 4 to 5 out of 9 is ideal. Ribs are easily felt under a light layer of fat, with a clear hourglass waist visible from above and an abdominal tuck from the side.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2124', 'How much excess body fat does each point above BCS 5 represent?', 'Each single number above 5 represents approximately 10% to 15% excess body fat (e.g., BCS 7 is roughly 20% to 30% overweight).', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2125', 'How does maintaining an ideal BCS extend a dog''s life?', 'Landmark lifelong canine studies prove that keeping dogs at an ideal lean BCS (4–5) extends their lifespan by an average of 1.8 to 2.5 years compared to overweight dogs.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2126', 'What are the two best photo angles for assessing pet body condition?', 'A top-down aerial photo looking straight down at the standing pet''s back, and a side profile photo taken at standing eye-level.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2127', 'Why is it harder to visually assess body condition in long-haired breeds?', 'Dense, fluffy coats mask visual waistlines. In long-haired pets, tactile hands-on palpation of the ribs and spine is essential alongside photos.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2128', 'What medical diseases are directly caused by pet obesity?', 'Type 2 Diabetes (especially in cats), cranial cruciate ligament (CCL) tears, crippling osteoarthritis, high blood pressure, respiratory distress, and hepatic lipidosis.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2129', 'Why shouldn''t overweight cats be put on rapid crash diets?', 'Rapid weight loss in cats triggers Hepatic Lipidosis (Fatty Liver Disease)—a life-threatening crisis where mobilized fat overwhelms the liver, causing liver failure.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2130', 'What is the ''feline primordial pouch'' and is it considered fat?', 'The primordial pouch is a natural, loose flap of skin on a cat''s lower abdomen that provides protection during kicks and allows full stride extension. It is not excess fat.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2131', 'How often should pet owners check their pet''s Body Condition Score?', 'Check your pet''s BCS monthly by performing the rib-palpation test and taking consistent top-down photos to catch subtle weight trends early.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_pet-body-condition-photo_2132', 'How does spaying/neutering impact a pet''s ideal caloric needs?', 'Sterilization decreases resting metabolic rate by 20% to 30%. Food portions must be reduced by 15% to 20% post-surgery to maintain an ideal lean BCS.', 'general', 'tool', 'pet-body-condition-photo', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2133', 'What is an ideal stool score on the 7-point veterinary fecal chart?', 'Score 2 is ideal: firm, segmented, log-shaped stool that holds its form and leaves zero residue when picked up off the grass.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2134', 'What does bright red blood (hematochezia) in dog or cat poop mean?', 'Fresh red blood comes from the lower GI tract (colon or rectum), commonly caused by colitis, stress, hookworms, whipworms, or anal gland inflammation.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2135', 'What does black, tarry stool (melena) indicate?', 'Melena indicates digested blood originating from the stomach or upper small intestine, caused by bleeding stomach ulcers, swallowed blood, or severe toxic ingestion.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2136', 'Why is mucus or jelly-like slime present in my dog''s stool?', 'Mucus is produced by the lining of the large intestine (colon) in response to inflammation (colitis), dietary indiscretion, or Giardia protozoan infection.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2137', 'What causes yellow or mustard-colored diarrhea in pets?', 'Yellow stool indicates rapid gastrointestinal transit time (food rushing through before bile can turn it brown), liver dysfunction, or sudden dietary changes.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2138', 'Why is my dog''s poop white and chalky?', 'White, chalky stool occurs in dogs fed raw diets containing excessive bone calcium, or can indicate severe biliary obstruction where bile is blocked from entering the gut.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2139', 'What are small white rice-like grains in pet feces?', 'Dried proglottid segments of Tapeworms (*Dipylidium caninum*), which are transmitted when pets ingest fleas during grooming. Requires prescription deworming.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2140', 'When is pet diarrhea a medical emergency requiring immediate vet care?', 'Diarrhea containing significant blood or black tar, accompanied by repeated vomiting, severe lethargy, or occurring in an unvaccinated puppy/kitten (Parvovirus risk).', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2141', 'How does a veterinary fecal flotation test work?', 'The lab mixes a stool sample with a high-density zinc sulfate solution, causing microscopic parasite eggs (Giardia, Roundworms, Coccidia) to float to the top onto a glass microscope slide.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_poop-health-analyzer_2142', 'What is the bland diet protocol for mild digestive upset in dogs?', 'Feed 75% boiled white rice and 25% boiled lean skinless chicken breast in small, frequent meals for 2 to 3 days to rest the digestive tract before transitioning back.', 'general', 'tool', 'poop-health-analyzer', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2143', 'How can I tell the difference between a wolf and a large domestic dog (like a Husky)?', 'Wolves have massive heads with no distinct forehead ''stop'', yellow/amber eyes (never blue), narrow chests with legs close together, massive paws, and tails that never curl over their back.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2144', 'How do coyote paw tracks differ from dog tracks?', 'Coyote tracks are narrow, oval, and streamlined (2–2.5 inches) with claws pointing inward in a straight single-file line. Dog tracks are rounder, splayed, and wander erratically.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2145', 'Can domestic dogs mate with wolves and coyotes?', 'YES! All members of the genus *Canis* (dogs, wolves, coyotes) share 78 chromosomes and can interbreed, producing fertile hybrid offspring (Wolfdogs and Coydogs).', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2146', 'What are the behavioral challenges of keeping a wolf hybrid as a pet?', 'Wolf hybrids retain wild neophobia (fear of new things), intense predatory drive toward small pets, extreme escape-artist tendencies (jumping 8-foot fences), and territorial marking.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2147', 'Is the Rabies vaccine legally recognized for wolf hybrids?', 'In many states, the USDA rabies vaccine is not officially approved for wolf hybrids. If a hybrid bites a human, animal control may legally confiscate and euthanize the animal for rabies testing.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2148', 'How big does a wild coyote get?', 'Adult coyotes weigh between 20 and 45 pounds (roughly the size of a Border Collie), appearing larger due to their dense winter coat.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2149', 'Do wild wolves ever have blue eyes?', 'NO! Pure adult wolves only have yellow, amber, or light golden-brown eyes. Blue eyes in a wolf-like animal indicate domestic dog genetics (like Siberian Husky ancestry).', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2150', 'How do coyotes hunt domestic pets in suburban areas?', 'Coyotes are opportunistic predators that easily clear 6-foot fences to snatch small dogs, cats, or pet food left outdoors, especially at dusk and dawn.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2151', 'What is a ''Coyote Roller'' and how does it protect backyards?', 'A Coyote Roller is a spinning aluminum tube mounted on top of a backyard fence that spins freely when a coyote attempts to grip the top, preventing them from climbing over.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_dog-wolf-coyote-identifier_2152', 'Why do wolves walk in a ''single-track'' line in the snow?', 'Wolves have narrow chests, allowing their hind feet to step directly into the prints of their front feet (single-tracking), conserving vital energy in deep winter snow.', 'dogs', 'tool', 'dog-wolf-coyote-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2153', 'Why are almost all Calico and Tortoiseshell cats female?', 'The orange color gene is located exclusively on the X chromosome. Females have two X chromosomes (XX) and can inherit both black and orange genes. Males (XY) can only be orange or black.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2154', 'How rare is a male Calico cat, and are they fertile?', 'Male calico cats are extremely rare (approximately 1 in 3,000), occurring only due to a rare XXY chromosomal mutation (Klinefelter Syndrome). Almost all male calicos are sterile.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2155', 'What is a ''Pointed'' cat coat (like a Siamese)?', 'Pointed cats have a temperature-sensitive enzyme mutation where dark pigment develops only on the colder parts of the body: ears, nose mask, paws, and tail.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2156', 'What are the 4 main types of Tabby cat coat patterns?', 'Mackerel (narrow tiger stripes), Classic (swirled marble/bullseye), Spotted (broken spots like a leopard), and Ticked (individual banded agouti hairs with zero stripes on body).', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2157', 'What is the ''M'' marking on a Tabby cat''s forehead?', 'The ''M'' forehead marking is a distinctive genetic feature of all agouti tabby cats, originating from the wild African ancestor of all domestic cats.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2158', 'What is the difference between a Calico and a Tortoiseshell cat?', 'Tortoiseshell cats have mixed patches of black and orange with zero white fur. Calico cats have distinct patches of black, orange, AND white fur.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2159', 'What is a ''Tuxedo'' cat coat pattern?', 'A tuxedo cat is a solid black cat with piebald white spotting on the chest, paws, belly, and chin, resembling a formal black-and-white dinner suit.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2160', 'Why are some white cats with blue eyes born deaf?', 'The dominant white gene (W) suppresses pigment melanocytes in both the inner ear (causing deafness) and the iris of the eye (producing blue eyes).', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2161', 'What is a ''Dilute'' coat color in cats?', 'A genetic recessive dilution gene (d) lightens dense colors: black dilutes to blue (grey), orange dilutes to cream, and chocolate dilutes to lilac.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_cat-coat-pattern-identifier_2162', 'Does cat coat color or pattern affect personality?', 'While owners report ''tortitude'' (spunky tortoiseshells) or sweet orange cats, scientific research shows personality is determined primarily by individual genetics, socialization, and handling.', 'cats', 'tool', 'cat-coat-pattern-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2163', 'What is the GISS method for bird identification?', 'GISS stands for ''General Impression, Size, and Shape''. It is the scientific method of identifying birds by their overall silhouette, posture, beak shape, tail geometry, and locomotive style before examining fine feather colors.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2164', 'How do I tell the difference between a male and female budgie?', 'Look at the cere (the fleshy band above the beak surrounding the nostrils). Mature male budgies have a royal blue or purple cere, while mature females have a pale blue, chalky white, or rough crusty brown cere during breeding.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2165', 'Is it legal to keep a wild bird found in my garden as a pet?', 'No. Under the Migratory Bird Treaty Act in the US and similar laws worldwide, it is illegal to capture or keep native wild birds. Injured wild birds must be brought to a licensed wildlife rehabilitator.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2166', 'What is the difference between a parakeet and a parrot?', 'All parakeets are parrots! ''Parrot'' is the overarching order (Psittaciformes), while ''parakeet'' is an informal term used for small to medium parrots with slender bodies and long, tapered tail feathers (such as budgies and ringnecks).', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2167', 'How do zygodactyl feet help identify parrots?', 'Zygodactyl feet have two toes facing forward and two toes facing backward. This anatomical feature is characteristic of parrots, toucans, and woodpeckers, allowing them to grasp objects and climb vertically with agility.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2168', 'What is DNA sexing in birds and why is it needed?', 'Many parrot species (such as African Greys, Conures, and Macaws) are monomorphic, meaning males and females look identical externally. DNA sexing uses a drop of blood or molted feather sample to definitively determine biological sex.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2169', 'What are the easiest beginner pet bird species?', 'Budgerigars and cockatiels are widely regarded as the best beginner companion birds due to their gentle nature, manageable size, well-understood nutritional needs, and social personalities.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2170', 'How do I identify whether a green parrot is a Conure or an Amazon?', 'Conures are smaller (70–150g) with long, pointed tail feathers and bare white eye rings. Amazons are much larger (300–500g) with stout, heavy bodies and short, square tails.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2171', 'Why do some birds of the same species have completely different colors?', 'Captive breeding has produced genetic color mutations (like Lutino, Albino, Pied, and Blue) that alter melanin and psittacofulvin pigment distribution in the feathers compared to wild-type plumage.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_bird-species-identifier_2172', 'What should I do if I find a fallen baby bird on the ground?', 'If it is a nearly feathered fledgling hopping on the ground, leave it alone—the parents are feeding it nearby. If it is a naked, helpless nestling, gently place it back into its nest or contact a wildlife rescue center.', 'birds', 'tool', 'bird-species-identifier', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2173', 'How do I distinguish between Ich (White Spot) and Epistylis?', 'Ich spots are uniformly small, flat, like grains of salt, and appear evenly on the body. Epistylis spots are raised, fluffy, variable in size, and often attack the eyes and red sores.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2174', 'What causes Dropsy in fish and is it curable?', 'Dropsy is a symptom of internal kidney failure causing fluid accumulation and pineconing scales. It is difficult to cure, but early treatment in a hospital tank with Epsom salt and antibiotics can help.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2175', 'Why is my fish gasping at the surface of the water?', 'Surface gasping indicates severe oxygen deprivation, caused by toxic ammonia/nitrite burning the gills, high water temperature, or gill fluke parasites.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2176', 'How do I tell the difference between Columnaris and true fungal infection?', 'True fungus (Saprolegnia) looks like fluffy cotton-wool on decaying wounds. Columnaris is a fast-moving bacterial disease creating flat, milky, saddle-shaped lesions on the back and mouth.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2177', 'Why is my fish ''flashing'' and scratching its body against rocks?', 'Flashing is a physical reaction to skin irritation, almost always caused by external parasites (Ich, Velvet, Flukes) or high ammonia levels irritating the slime coat.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2178', 'How does poor water quality cause fin rot in healthy fish?', 'Chronic stress from ammonia or high nitrates breaks down the protective slime coat, allowing ubiquitous environmental bacteria (Aeromonas) to invade fin tissue.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2179', 'What is Swim Bladder Disorder and how do I treat it?', 'It causes floating upside down or sinking. Often caused by digestive constipation pressing on the swim bladder. Fast the fish for 3 days, then feed blanched deshelled peas or daphnia.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2180', 'What are the visible symptoms of Velvet disease (Oodinium)?', 'Velvet presents as a fine golden-yellow or rust-colored dusting across the skin (best seen with a flashlight in the dark), accompanied by rapid breathing and severe lethargy.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2181', 'How do I perform a safe Epsom salt bath for a bloated or dropsy fish?', 'Dissolve 1 to 2 teaspoons of pure Epsom salt (magnesium sulfate) per gallon of tank water in a separate container and soak the fish for 15 to 30 minutes to draw out fluids.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_fish-disease-spot-checker_2182', 'When should I consult an aquatic veterinarian?', 'Consult an aquatic vet when valuable fish exhibit persistent ulcers, unidentifiable rapid mortality, or when over-the-counter medications fail to resolve symptoms within 5 days.', 'fish', 'tool', 'fish-disease-spot-checker', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2183', 'Why can''t I use a big tank for a small tarantula?', 'Oversized enclosures make prey hard to find, so feeding response drops and slings can starve. Scale the home to the spider and rehouse as it grows.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2184', 'How much height is dangerous for a terrestrial species?', 'Anything above about 1.5× the leg span. Heavy-bodied terrestrials that fall even a short distance can suffer a fatal abdominal rupture.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2185', 'Do tarantulas need a water dish?', 'Yes — every species, at every size big enough to safely use one. Dehydration kills tarantulas far faster than hunger.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2186', 'When should I rehouse?', 'Only 7-10 days after a moult when the exoskeleton and fangs have hardened, and only when the current enclosure is clearly outgrown.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2187', 'Is ventilation or humidity more important?', 'Ventilation. Stagnant, wet air causes mould and respiratory problems far more often than low humidity causes harm.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2188', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-enclosure-size-calculator_2189', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'tarantula-enclosure-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2190', 'How long can a tarantula go without food?', 'Healthy adults can fast for months, especially around a moult. Water is the non-negotiable requirement.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2191', 'Can I feed wild-caught insects?', 'It is risky. Wild insects can carry pesticides and parasites. Captive-bred crickets, dubia roaches and mealworms are safer.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2192', 'Should I remove uneaten prey?', 'Yes, within 24 hours. Live crickets can chew a vulnerable moulting tarantula.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2193', 'How do I know pre-moult has started?', 'The abdomen darkens and looks stretched, appetite disappears, and the spider often seals itself into a web mat.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2194', 'Is power-feeding safe?', 'Feeding heavily speeds growth but is widely believed to shorten lifespan. A steady schedule is better.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2195', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tarantula-feeding-schedule_2196', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'tarantula-feeding-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2197', 'What is the minimum wheel size for an African Pygmy Hedgehog?', 'The minimum safe diameter for an adult African Pygmy Hedgehog is 11 to 12 inches (28 to 30 cm), with 12 to 14 inches recommended for larger hedgehogs weighing over 500 grams.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2198', 'Why are wire or mesh wheels lethal to hedgehogs?', 'Hedgehog feet have delicate skin and small toes. Wire rungs and mesh catch toes during full-speed running, causing severe degloving injuries, torn nails, broken legs, and painful bumblefoot infections.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2199', 'What is a ''bucket wheel'' and why is it so popular for hedgehogs?', 'A bucket wheel (such as the Carolina Storm Wheel) is handcrafted from a smooth, food-grade plastic bucket mounted on dual rollerblade ball bearings. It features a wide, flat, solid surface with no center axle, making it virtually silent, ergonomic, and easy to clean.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2200', 'Why do hedgehogs poop while running on their wheel?', 'Running stimulates the gastrointestinal tract and bladder. Because hedgehogs run continuously for miles, they naturally eliminate on the go, making daily wheel washing a standard part of hedgehog care.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2201', 'How far does a healthy hedgehog run each night?', 'A healthy young hedgehog routinely runs between 2 and 5 miles (3 to 8 kilometers) every night, using the wheel for several hours in the dark.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2202', 'What should I do if my hedgehog''s paws get raw or bloody from running?', 'Check the wheel surface for sharp edges or rough seams, ensure the wheel is thoroughly cleaned of dried feces, and temporarily remove the wheel for 24 to 48 hours to let paws heal while consulting an exotic vet.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2203', 'Can hedgehogs use flying saucer style wheels?', 'Large 12-inch saucers can be an occasional enrichment option, but many hedgehogs fly off saucers at high speeds or run with an unnatural sideways spinal bend. A traditional upright 12-inch bucket wheel is much safer.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2204', 'At what age should a baby hedgehog get its first wheel?', 'Introduce a safe, lightweight 11- to 12-inch wheel at 8 to 10 weeks of age, once the hoglet has developed sufficient leg strength and coordination.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2205', 'Why does my hedgehog refuse to run on its wheel?', 'Common reasons include cold cage temperatures (below 72°F/22°C triggers dangerous lethargy or torpor), an undersized or stiff wheel that is hard to push, sore footpads, overgrown toenails, or obesity.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-wheel-size-calculator_2206', 'How do I wash a dirty hedgehog wheel easily?', 'Spray the running track thoroughly with warm water and pet-safe dish soap or white vinegar, let it soak for 5 minutes to soften dried matter, scrub with a brush, rinse, and dry before evening.', 'small-pets', 'tool', 'hedgehog-wheel-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2207', 'What is the best staple food for a pet hedgehog?', 'A high-protein, low-fat commercial cat kibble (30–35% protein, 10–14% fat, with chicken or turkey as the first ingredient) supplemented with live gut-loaded insects is the veterinary-recommended standard.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2208', 'How many tablespoons of kibble should a hedgehog eat each day?', 'An average adult hedgehog needs 1 to 2 level tablespoons (approx. 10 to 15 grams) of dry kibble per day, adjusted based on weekly weigh-ins and wheel activity.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2209', 'Why are live insects essential in a hedgehog''s diet?', 'Insects provide chitin—the natural insoluble fiber found in insect exoskeletons. Chitin promotes healthy digestion, satisfies predatory hunting instincts, and prevents obesity.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2210', 'Why are grapes and raisins toxic to hedgehogs?', 'Grapes and raisins contain an unknown nephrotoxin that causes acute, irreversible renal (kidney) failure in hedgehogs, even in tiny amounts.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2211', 'Can hedgehogs eat cooked chicken or eggs?', 'Yes! A teaspoon of plain boiled unseasoned chicken breast or scrambled egg (cooked with zero oil, butter, or salt) makes a fantastic high-protein treat.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2212', 'Why should whole nuts and seeds never be fed to hedgehogs?', 'Hedgehogs have narrow palates and lack large grinding molars. Hard nuts and seeds easily wedge into the roof of the mouth or get stuck in the trachea and intestines, causing asphyxiation or blockages.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2213', 'How often should I feed mealworms to my hedgehog?', 'Mealworms are very high in fat and low in calcium. Limit mealworms to 3 to 5 worms 2 to 3 times weekly as a training treat, prioritizing Dubia roaches and black soldier fly larvae as healthier staples.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2214', 'Can hedgehogs drink milk?', 'No. Hedgehogs lack the lactase enzyme and cannot digest dairy. Milk, cheese, and yogurt cause painful bloating, cramps, and severe dehydrating diarrhea.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2215', 'How can I tell if my hedgehog is overweight?', 'An overweight hedgehog cannot fully roll into a tight, protective ball with quills enclosing its body. Rolls of fat appear around the armpits and chin, and weight exceeds 550 to 600 grams.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_hedgehog-diet-calculator_2216', 'Why is pure canned pumpkin puree good for hedgehogs?', 'Plain 100% canned pumpkin puree (not spiced pie mix) is high in soluble and insoluble fiber. A half-teaspoon helps regulate bowel movements and relieves mild constipation.', 'small-pets', 'tool', 'hedgehog-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2217', 'What is the absolute ideal water temperature range for an axolotl?', 'The ideal water temperature range is 16°C to 18°C (60°F to 64°F). Temperatures should never exceed 20°C (68°F) for extended periods.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2218', 'What happens to an axolotl if the water temperature exceeds 20°C (68°F)?', 'Temperatures above 20°C induce severe heat stress, suppress the immune system, cause external gill filaments to shrink, and trigger opportunistic bacterial and fungal infections.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2219', 'Do axolotls ever need an aquarium heater?', 'Never. Axolotls are cold-water amphibians. Installing a heater is dangerous and one of the most common causes of accidental axolotl death.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2220', 'How effective are clip-on aquarium cooling fans for axolotl tanks?', 'Evaporative cooling fans blowing across the water surface reliably drop water temperature by 2°C to 4°C (4°F–7°F), provided room humidity is not excessively high.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2221', 'When is it necessary to invest in a compressor-based aquarium chiller?', 'If your home ambient room temperature routinely exceeds 22°C (72°F) during warm summer months, an aquarium chiller is mandatory to keep your axolotl alive.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2222', 'What are the clinical behavioral signs of heat stress in an axolotl?', 'Signs include forward-curled gill stalks, a curled tail tip, floating helplessly at the surface, loss of appetite, excessive white slime coat shedding, and lethargy.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2223', 'How can I cool down an axolotl tank during a summer power outage or heatwave?', 'Float sealed bottles of frozen dechlorinated water in the tank, turn off all tank lights, move the tank to the coolest ground floor or basement, and set up battery-powered fans.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2224', 'Why do axolotl external gill filaments curl forward?', 'Forward-curled gills resembling a candy cane are a primary indicator of acute stress, caused by high water temperature, strong filter flow, or ammonia toxicity.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2225', 'How does warm water affect dissolved oxygen levels in an axolotl tank?', 'Warmer water holds significantly less dissolved oxygen while simultaneously speeding up the axolotl''s metabolism, causing double the respiratory distress.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-temperature-calculator_2226', 'Can I put ice cubes directly into the axolotl aquarium water?', 'Do not add loose tap-water ice cubes, as they contain chlorine and cause sudden localized cold pockets. Always freeze dechlorinated water inside sealed bottles before floating.', 'fish', 'tool', 'axolotl-tank-temperature-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2227', 'What is the absolute minimum tank size for a single adult axolotl?', 'A 20-gallon Long aquarium (30″ × 12″ footprint) is the recommended minimum for one adult axolotl, providing sufficient floor space and waste dilution.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2228', 'Why is tank floor footprint more important than water depth for axolotls?', 'Axolotls are benthic bottom-dwellers that spend their time walking on the substrate. A long, wide tank provides more usable living territory than a tall, narrow tank.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2229', 'Can two or more axolotls be housed together in the same tank?', 'Yes, provided the tank is at least 30 to 40 gallons, all axolotls are the exact same size, and multiple hides are provided. Mismatched sizes lead to cannibalism and limb-nipping.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2230', 'Why is aquarium gravel and small pebbles deadly for axolotls?', 'Axolotls feed by vacuum suction and ingest gravel. Gravel cannot pass through their digestive tract, causing fatal intestinal impaction and blockage.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2231', 'What substrate is safe for young juvenile axolotls?', 'Juveniles under 5 inches (13 cm) should always be kept on a bare-bottom glass tank or large smooth slate tile to completely eliminate any risk of swallowing sand.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2232', 'What type of filtration is best for an axolotl tank without creating strong currents?', 'Dual sponge filters powered by an air pump are ideal. If using a canister or HOB filter, install a spray bar or baffle to eliminate strong water flow.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2233', 'How many hides should be provided per axolotl in an enclosure?', 'Provide at least 1 to 2 dark hides per axolotl (such as terra cotta pots, smooth ceramic caves, or PVC pipe elbows) with no sharp edges.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2234', 'Can axolotls live peacefully with aquarium fish or snails?', 'No. Fish nip at delicate axolotl gills, and axolotls will eat fish (risking choking or impaction). Snails pose severe impaction risks. Axolotls must be in a species-only tank.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2235', 'How often should I perform water changes in an axolotl tank?', 'Perform a 20% to 30% water change weekly in a cycled 20-gallon tank, using a turkey baster daily to spot-clean solid waste pellets immediately.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_axolotl-tank-size-calculator_2236', 'What are the ideal dimensions for a 40-gallon breeder axolotl aquarium?', 'A 40-gallon Breeder tank measures 36″ Long × 18″ Wide × 16″ High, providing an expansive 648 square inches of floor area that comfortably houses 2 adult axolotls.', 'fish', 'tool', 'axolotl-tank-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2237', 'What is Hind-Leg Paralysis (HLP) in sugar gliders?', 'HLP (Metabolic Bone Disease) is a devastating condition caused by calcium deficiency and an inverted Calcium-to-Phosphorus ratio. The body leaches calcium from the bones, causing bone softening, spinal compression, and sudden paralysis of the hind legs.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2238', 'What are the only approved staple diets for sugar gliders?', 'The veterinary-recognized approved diets are HPW (High Protein Wombaroo), BML (Bourbon''s Modified Leadbeater''s), TPG (The Pet Glider), and Critter Love. Never feed an unverified diet of random fruits, baby food, and nuts.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2239', 'Can sugar gliders eat pellet food alone?', 'No. Commercial dry pellets do not provide the moisture, bioavailable nectar proteins, or correct calcium-to-phosphorus ratios gliders need. Pellets should only be a minor dry treat alongside an approved wet staple diet.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2240', 'Why is bee pollen included in sugar glider diets?', 'In the wild, sugar gliders consume large amounts of flower pollen while harvesting nectar. Bee pollen provides essential trace amino acids, enzymes, and B-vitamins that mirror their natural wild diet.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2241', 'What fruits and vegetables have a good 2:1 Calcium-to-Phosphorus ratio?', 'High-calcium produce includes papaya, fresh figs, blackberries, raspberries, bok choy, and collard greens. Avoid high-phosphorus foods like corn, peas, bananas, and grapes in large quantities.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2242', 'Can sugar gliders eat chocolate, garlic, or onions?', 'No. Never feed chocolate, garlic, onions, leeks, avocado, apple seeds, raw nuts, or anything containing artificial sweeteners (xylitol). All of these are highly toxic to gliders.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2243', 'Why should food be offered at dusk?', 'Sugar gliders are strictly nocturnal and sleep during the day. Offering fresh food at dusk ensures they eat fresh, unoxidized food during their peak active foraging hours.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2244', 'How many live insects should a sugar glider eat daily?', 'Offer 2 to 4 gut-loaded live mealworms, crickets, or Dubia roach nymphs per glider per evening as an animal protein and behavioral enrichment supplement.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2245', 'Can sugar gliders drink cow''s milk?', 'No. Sugar gliders are severely lactose intolerant. Never feed cow''s milk. If a recipe calls for dairy, use 100% plain, unsweetened Greek yogurt with active live cultures.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-diet-calculator_2246', 'How much fresh water does a pair of sugar gliders need?', 'Gliders need fresh, filtered, chlorine-free water daily from clean water silos or inverted ball-point bottles. Never add vitamins to their drinking water.', 'small-pets', 'tool', 'sugar-glider-diet-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2247', 'What is the absolute minimum cage size for a pair of sugar gliders?', 'The minimum cage size for two sugar gliders is 24 inches wide by 24 inches deep by 36 inches tall (approx. 12 cubic feet), with taller 48- to 72-inch aviaries strongly recommended for gliding exercise.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2248', 'Why is vertical height more important than floor space for gliders?', 'Sugar gliders are arboreal canopy dwellers. They instinctively climb to the highest available vantage point before leaping and gliding down. Tall aviaries satisfy their vertical climbing and gliding drives.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2249', 'Why is 1/2-inch bar spacing mandatory?', 'Sugar gliders can squeeze through openings larger than 1/2 inch, leading to household escapes or fatal head entrapment between cage bars.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2250', 'Why is galvanized wire dangerous for sugar gliders?', 'Galvanized wire is coated in zinc. Gliders constantly lick cage bars and mark them with scent glands, leading to chronic, fatal heavy metal zinc poisoning. Always use powder-coated or stainless steel cages.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2251', 'Can a sugar glider live alone as a single pet?', 'No. Sugar gliders are colony animals. Keeping a single glider causes severe psychological stress, depression, and self-mutilation (chewing their own tail or skin). They must always be kept in bonded pairs or groups.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2252', 'What exercise wheel is safe for sugar gliders?', 'Use an axle-free, mesh-free wheel designed specifically for gliders (such as the Stealth Wheel or Raptor Wheel). Standard small pet wheels with center axles can snap a glider''s long tail or spine.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2253', 'What fabric is safe for glider sleeping pouches?', 'Anti-pill polar fleece is the only safe fabric. It does not fray into loose threads that can wrap around gliders'' toes and limbs, cutting off circulation.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2254', 'How many sleeping pouches should I provide in the cage?', 'Provide at least 2 to 3 fleece pouches per pair placed high in the cage, washing and rotating them weekly.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2255', 'How do I enrich a sugar glider aviary?', 'Add flexible eucalyptus branches, plastic climbing chains, fleece vines, foraging cups, and hanging bird toys with zero loose cotton ropes.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_sugar-glider-cage-size-calculator_2256', 'Where should the cage be positioned in the home?', 'Place the cage in a quiet, climate-controlled room (70°–80°F / 21°–27°C) away from direct sunlight, drafty windows, and loud television noise, keeping cats and dogs completely out of the room.', 'small-pets', 'tool', 'sugar-glider-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2257', 'Why can''t chinchillas ever be bathed in water?', 'Chinchillas have the densest fur of any land mammal (50–80 hairs per follicle). Water cannot dry out of the dense undercoat, causing severe fungal infections (ringworm), skin rot, and fatal hypothermia.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2258', 'How many times a week should a chinchilla have a dust bath?', 'Provide a dust bath 2 to 3 times per week for 10 to 15 minutes in normal conditions, increasing to 3 to 4 times per week in humid environments.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2259', 'Why shouldn''t the dust bath stay in the cage all the time?', 'If left in the cage, chinchillas will urinate and defecate in the dust, and over-bathe, stripping natural skin oils and causing eye infections (conjunctivitis) and dry, flaky skin.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2260', 'What kind of dust is safe for chinchillas?', 'Use only 100% natural volcanic pumice dust mined specifically for chinchillas (such as Oxbow Poof! or Blue Cloud dust). Never use beach sand, playground sand, or scented powders, which lacerate fur and cause eye damage.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2261', 'How often should I replace the bath dust with fresh dust?', 'Sift out stray droppings after each bath using a fine mesh kitchen strainer. Completely discard and replace the dust with fresh dust every 3 to 4 weeks (or immediately if soiled with urine).', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2262', 'What should I do if my chinchilla''s skin looks dry and flaky?', 'Reduce dust bath frequency to once or twice weekly, ensure room humidity is not excessively dry, and consult an exotic vet if flaking or hair loss continues.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2263', 'Can baby chinchillas (kits) take dust baths?', 'Kits can be introduced to dust baths around 1 to 2 weeks of age under close supervision, but keep sessions short (5 minutes) to avoid eye irritation.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2264', 'What container is best for a chinchilla dust bath?', 'Use an enclosed wooden dust bath box, an oval ceramic bowl, or a high-backed metal/glass container with deep walls to contain airborne dust clouds during vigorous rolling.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2265', 'Why do chinchillas get eye discharge after a dust bath?', 'Microscopic dust particles can occasionally irritate the conjunctiva. If discharge or squinting occurs, rinse the eye with sterile saline and withhold the dust bath for 48 hours. Consult a vet if irritation persists.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-dust-bath-schedule_2266', 'What is the maximum safe room temperature for a chinchilla?', 'Chinchillas cannot sweat and are extremely prone to fatal heatstroke. Room temperatures must **never exceed 72°F (22°C)**, with 60°F to 68°F (15°–20°C) and low humidity being the ideal range.', 'small-pets', 'tool', 'chinchilla-dust-bath-schedule', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2267', 'Why is plastic dangerous inside a chinchilla cage?', 'Chinchillas chew relentlessly on all hard surfaces. Ingested plastic cannot be digested or passed through their narrow intestines, leading to fatal gastrointestinal blockages and intestinal perforation.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2268', 'What is the best cage available for a chinchilla?', 'The Ferret Nation or Critter Nation (Model 182) by Midwest Homes for Pets—fitted with custom metal replacement pans and kiln-dried pine ledges—is the gold standard recommended by chinchilla rescues and veterinarians.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2269', 'How do I prevent fall injuries in a tall chinchilla cage?', 'Stagger wooden jumping ledges and solid mezzanine shelves along the walls so there is never an open vertical drop greater than 18 inches from top to bottom.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2270', 'What types of wood are safe for chinchilla ledges and chews?', 'Safe woods include kiln-dried pine, untreated apple wood, pear, willow, and hazelnut. Never use fresh unseasoned pine, cedar, cherry, plum, or oak (which contain toxic resins, tannins, or cyanide compounds).', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2271', 'Why do chinchillas need marble or granite cooling stones?', 'Chinchillas cannot sweat or pant effectively. Polished granite or marble cooling slabs stay naturally cooler than ambient air, providing an essential surface where chinchillas can press their bellies to dissipate body heat.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2272', 'What exercise wheel is safe for chinchillas?', 'Use an all-metal, 14- to 16-inch solid-surface wheel (such as the Chin-Spin or Silver Surfer). Plastic wheels are chewed and destroyed, and wheels under 14 inches cause severe spinal curvature.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2273', 'What is the maximum safe bar spacing for a chinchilla cage?', 'Bar spacing should be 1/2 inch to 3/4 inch. Spacing of 1 inch or wider allows baby chinchillas and smaller adults to squeeze through or suffer head entrapment.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2274', 'Can chinchillas live in wire mesh floor cages?', 'No. Wire mesh floors trap delicate feet, cause broken legs during high leaps, and cause painful ulcerative pododermatitis (bumblefoot). Always use solid metal or wood floors lined with fleece.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2275', 'What room temperature is dangerous for chinchillas?', 'Temperatures above 72°F (22°C) are dangerous, and temperatures above 75°F (24°C) can cause fatal heatstroke within hours. Reliable air conditioning is a mandatory requirement for chinchilla care.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_chinchilla-cage-size-calculator_2276', 'How often should a chinchilla cage be cleaned?', 'Sweep fecal pellets off wooden ledges daily with a hand brush, and perform a full cleaning of fleece liners and metal pans every 4 to 7 days using warm water and distilled white vinegar.', 'small-pets', 'tool', 'chinchilla-cage-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2277', 'Which tortoises must never hibernate?', 'Tropical and subtropical species including sulcata, leopard, red-footed and yellow-footed tortoises. Cooling them causes pneumonia and death.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2278', 'What is the Jackson ratio?', 'A weight-to-length screening figure. Roughly 0.19-0.24 suggests adequate condition for hibernation; below that, do not proceed without a vet.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2279', 'Why must the gut be empty first?', 'Food left in the gut ferments and rots at low temperatures, causing fatal toxicity. Fasting takes 2-4 weeks depending on size.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2280', 'Is the fridge method safe?', 'Yes, and it is generally safer than a garage or shed because temperature is stable. Use a dedicated fridge, monitor daily, and open the door for air exchange.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2281', 'When should I abort hibernation?', 'If weight loss exceeds about 1% of body weight per month, the tortoise urinates, or it appears awake and active. Warm it up and see a vet.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2282', 'Is this tool free?', 'Yes — every FurTools tool is free forever, no signup required.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_tortoise-hibernation-planner_2283', 'Do you store my inputs?', 'No. Everything runs in your browser and nothing is sent to our servers.', 'reptiles', 'tool', 'tortoise-hibernation-planner', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2284', 'Why must quail coop ceilings be either under 12 inches OR over 6 feet high?', 'Startled quail flush straight upward like rockets. A ceiling between 18 inches and 4 feet allows quail to build enough speed to break their necks on the hard roof. Ceilings must be under 12 inches (padded) or over 6 feet.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2285', 'How many square feet of space does a Coturnix quail need?', 'Coturnix quail require a minimum of 1.0 square foot of floor space per bird in cages or hutches, and 1.5 to 2.0 square feet per bird in ground aviaries with natural brush and hides.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2286', 'What is the correct male-to-female ratio for breeding quail?', 'Keep 1 male for every 4 to 5 hens. Keeping too many males results in violent fighting, territorial scalping, and severe back injuries to over-mated hens.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2287', 'Can pet quail be kept in all-female coveys without males?', 'Yes! All-female coveys are quiet, peaceful, never fight, and lay 250 to 300 delicious, unfertilized table eggs per hen per year starting at just 6 weeks of age.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2288', 'Can quail live inside the same coop as chickens?', 'NO! Chickens bully and kill small quail, and chickens carry Coryza, Mycoplasma, and Blackhead disease (*Histomonas meleagridis*), which are fatal to gamebirds.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2289', 'Do quail need nesting boxes like chickens?', 'No. Quail do not use elevated nesting boxes; they lay their speckled eggs directly on the ground or under small sheltered ground tunnels, cardboard huts, or artificial pine branches.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2290', 'Why is a sandbox / dust bath essential for quail?', 'Quail bathe in dry sand daily to clean oils from their plumage and suffocate external parasites (lice and mites). Provide a shallow wooden or plastic tray filled with clean play sand.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2291', 'What wire mesh is safe for quail cages?', 'Use 1/2-inch or 1/4-inch galvanized welded hardware cloth. Standard chicken wire is too large and allows rats, weasels, and snakes to kill quail and steal eggs.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2292', 'What crude protein percentage do Coturnix quail require?', 'Quail chicks need 24% to 28% protein gamebird/turkey starter. Mature laying quail require 20% to 22% protein gamebird layer pellets to maintain heavy egg output.', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );
INSERT OR REPLACE INTO faqs (id, question, answer, category, scope, scope_ref, sort_order, published) VALUES (
      'faq_quail-coop-size-calculator_2293', 'At what age do Coturnix quail start laying eggs?', 'Coturnix quail mature at lightning speed, laying their first speckled eggs at just 6 to 8 weeks of age (compared to 18–24 weeks for chickens).', 'farm', 'tool', 'quail-coop-size-calculator', 0, 1
    );

