  ) VALUES (
    'food_chocolate', 'chocolate', 'Chocolate', 'Sweets & Treats', 'https://images.unsplash.com/photo-1549007994-cb92caebd54b?auto=format&fit=crop&w=600&q=80',
    '{"dog":"unsafe","cat":"unsafe","bird":"unsafe","rabbit":"unsafe","ferret":"unsafe","horse":"unsafe"}', 'Highly toxic to dogs, cats, birds, and small animals due to theobromine and caffeine.', 'None for companion animals.', 'Theobromine stimulates the central nervous system and cardiac muscles, causing arrhythmias and seizures.',
    'Vomiting, diarrhea, restlessness, panting, hyperthermia, seizures, cardiac arrest.', 'If your pet ingested dark or baker''s chocolate, call animal poison control or your emergency vet immediately.', '["Carob treats","Plain baked pumpkin chips"]', '["xylitol","grapes"]',
    '[{"question":"How much chocolate is fatal for a dog?","answer":"As little as 1 oz of baker''s chocolate can cause severe toxicity in a 20 lb dog."}]', '["chocolate","cocoa","theobromine","candy","dark chocolate"]', 1
  );
INSERT OR REPLACE INTO foods (
    id, slug, name, category, image_url, species_safety, short_answer, benefits, risks, symptoms, vet_advice,
    alternatives, related_food_slugs, faqs, keywords, published
  ) VALUES (
    'food_xylitol', 'xylitol', 'Xylitol (Birch Bark Sweetener)', 'Sweets & Treats', 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=600&q=80',
    '{"dog":"unsafe","cat":"unsafe","bird":"unsafe","rabbit":"unsafe","ferret":"unsafe"}', 'Life-threateningly toxic to canines; causes rapid massive insulin release and acute hepatic necrosis.', 'None.', 'Triggers sudden severe hypoglycemia within 10 to 60 minutes, followed by acute liver failure within 12 to 24 hours.',
    'Vomiting, ataxia (loss of coordination), lethargy, collapse, seizures, coma.', 'Medical emergency. Rush to the veterinary emergency clinic immediately.', '["Natural dog-safe peanut butter (100% roasted peanuts only)"]', '["chocolate","peanut-butter"]',
    '[{"question":"Is xylitol found in human peanut butter?","answer":"Yes, check ingredient labels carefully for xylitol or birch bark extract."}]', '["xylitol","sugar free","gum","birch sugar","peanut butter additive"]', 1
  );
INSERT OR REPLACE INTO foods (
    id, slug, name, category, image_url, species_safety, short_answer, benefits, risks, symptoms, vet_advice,
    alternatives, related_food_slugs, faqs, keywords, published
  ) VALUES (
    'food_grapes_and_raisins', 'grapes-and-raisins', 'Grapes & Raisins', 'Fruits', 'https://images.unsplash.com/photo-1537640538966-79f369143f8f?auto=format&fit=crop&w=600&q=80',
    '{"dog":"unsafe","cat":"unsafe","ferret":"unsafe","rabbit":"moderation","bird":"safe"}', 'Severely toxic to dogs; causes unpredictable acute oliguric renal failure.', 'None for canines or felines.', 'Tartaric acid in grapes damages canine renal tubular epithelial cells.',
    'Vomiting within 6 hours, followed by anorexia, lethargy, decreased urine output, and kidney failure.', 'Immediate decontamination (emesis and activated charcoal) followed by 48-hour IV fluid diuresis is critical.', '["Seedless watermelon","Blueberries","Apple slices (no seeds)"]', '["apples","blueberries"]',
    '[{"question":"Are cooked grapes or baked raisin breads safe?","answer":"No, baking or cooking does not destroy the tartaric acid toxin."}]', '["grapes","raisins","sultanas","currants","wine fruit"]', 1
  );
